  franchise_name,
  collection_name
) as (
values
  ('12 Monkeys', 1995, true, 'R', 'Terry Gilliam', '1996-01-05'::date, '129 min', 'Mystery, Sci-Fi, Thriller', 'Chris Marker, David Webb Peoples, Janet Peoples', 'Bruce Willis, Madeleine Stowe, Brad Pitt', 'James Cole, a prisoner of the state in the year 2035, can earn parole if he agrees to travel back in time and thwart a devastating plague. The virus has wiped out most of the Earth''s population and the remainder live underground because the air is poisonous. Returning to the year 1990, six years before the start of the plague, Cole is soon imprisoned in a psychiatric facility because his warnings sound like mad ravings. There he meets a scientist named Dr. Kathryn Railly and Jeffrey Goines, the mad son of an eminent virologist. Cole is returned by the authorities to the year 2035, and finally ends up at his intended destination in 1996. He kidnaps Dr. Railly in order to enlist her help in his quest. Cole discovers graffiti by an apparent animal rights group called the Army of the Twelve Monkeys, but as he delves into the mystery, he hears voices, loses his bearings, and doubts his own sanity. He must figure out if Goines, who seems to be a raving lunatic, holds the key to the puzzle.', 'https://image.tmdb.org/t/p/w500/gt3iyguaCIw8DpQZI1LIN5TohM2.jpg', null, null),
  ('Thir13en Ghosts', 2001, true, 'R', 'Steve Beck', '2001-10-26'::date, '91 min', 'Fantasy, Horror', 'Robb White, Neal Marshall Stevens, Richard D''Ovidio', 'Tony Shalhoub, Shannon Elizabeth, Embeth Davidtz', 'Arthur and his two children, Kathy and Bobby, inherit his Uncle Cyrus''s estate: a glass house that serves as a prison to 12 ghosts. When the family, accompanied by Bobby''s Nanny and an attorney, enter the house they find themselves trapped inside an evil machine "designed by the devil and powered by the dead" to open the Eye of Hell. Aided by Dennis, a ghost hunter, and his rival Kalina, a ghost rights activist out to set the ghosts free, the group must do what they can to get out of the house alive.', 'https://image.tmdb.org/t/p/w500/6yrrddjIjx0ElCRZp5pTZeqrj3k.jpg', null, null),
  ('2010: The Year We Make Contact', 1984, true, 'PG', 'Peter Hyams', '1984-12-07'::date, '116 min', 'Adventure, Mystery, Sci-Fi', 'Arthur C. Clarke, Peter Hyams', 'Roy Scheider, John Lithgow, Helen Mirren', 'In this sequel to 2001: A Space Odyssey (1968), a joint American-Soviet expedition is sent to Jupiter to discover what went wrong with the U.S.S. Discovery against a backdrop of growing global tensions. Amongst the mysteries the expedition must explain, are the appearance of a huge black monolith in Jupiter''s orbit and the fate of H.A.L.; the Discovery''s A.I. computer. Based on the novel by Arthur C. Clarke.', 'https://image.tmdb.org/t/p/w500/mEWKXuCMv7mFMxXVSTI3v8UOQuq.jpg', null, null),
  ('300', 2006, true, 'R', 'Zack Snyder', '2007-03-09'::date, '117 min', 'Action, Drama', 'Zack Snyder, Kurt Johnstad, Michael B. Gordon', 'Gerard Butler, Lena Headey, David Wenham', 'In the Battle of Thermopylae of 480 BC an alliance of Greek city-states fought the invading Persian army in the mountain pass of Thermopylae. Vastly outnumbered, the Greeks held back the enemy in one of the most famous last stands of history. Persian King Xerxes led a Army of well over 100,000 (Persian king Xerxes before war has about 170,000 army) men to Greece and was confronted by 300 Spartans, 700 Thespians, and 400 Thebans. Xerxes waited for 10 days for King Leonidas to surrender or withdraw but left with no options he pushed forward. After 3 days of battle all the Greeks were killed. The Spartan defeat was not the one expected, as a local shepherd, named Ephialtes, defected to the Persians and informed Xerxes that the separate path through Thermopylae, which the Persians could use to outflank the Greeks, was not as heavily guarded as they thought.', 'https://image.tmdb.org/t/p/w500/h7Lcio0c9ohxPhSZg42eTlKIVVY.jpg', null, null),
  ('A Clockwork Orange', 1971, true, 'R', 'Stanley Kubrick', '1972-02-02'::date, '136 min', 'Crime, Sci-Fi', 'Stanley Kubrick, Anthony Burgess', 'Malcolm McDowell, Patrick Magee, Michael Bates', 'Protagonist Alex DeLarge is an "ultraviolent" youth in futuristic Britain. As with all luck, his eventually runs out and he''s arrested and convicted of murder. While in prison, Alex learns of an experimental program in which convicts are programmed to detest violence. If he goes through the program, his sentence will be reduced and he will be back on the streets sooner than expected. But Alex''s ordeals are far from over once he hits the streets of Britain..', 'https://image.tmdb.org/t/p/w500/4sHeTAp65WrSSuc05nRBKddhBxO.jpg', null, null),
  ('A Knight''s Tale', 2001, true, 'PG-13', 'Brian Helgeland', '2001-05-11'::date, '132 min', 'Action, Adventure, Romance', 'Brian Helgeland', 'Heath Ledger, Mark Addy, Rufus Sewell', 'Inspired by "The Canterbury Tales," as well as the early life of William Marshall (later First Earl of Pembroke), this is the story of William, a young squire with a gift for jousting. After his master dies suddenly, the squire hits the road with his cohorts Roland and Wat. On the journey, they stumble across an unknown writer, Chaucer. William, lacking a proper pedigree, convinces Chaucer to forge genealogy documents that will pass him off as a knight. With his newly-minted history in hand, the young man sets out to prove himself a worthy knight at the country''s jousting competition, and finds romance along the way.', 'https://image.tmdb.org/t/p/w500/srb1XnrlDZHcdpjBKqUu4qAzxKU.jpg', null, null),
  ('A Quiet Place', 2018, true, 'PG-13', 'John Krasinski', '2018-04-06'::date, '90 min', 'Drama, Horror, Sci-Fi', 'Bryan Woods, Scott Beck, John Krasinski', 'Emily Blunt, John Krasinski, Millicent Simmonds', 'In a devastated Earth overrun by invincible predators of a possible extraterrestrial origin, the Abbotts find themselves struggling to survive in the isolation of upstate New York, defined by a new era of utter silence. Indeed, as this new type of invader is attracted to noise, even the slightest of sounds can be deadly; however, it''s been already twelve months since the powerful monsters'' first sightings, and this resilient family still stands strong. Of course, learning the rules of survival in this muted dystopia is essential; nevertheless, now, of all times, an otherwise joyous event puts in jeopardy the already fragile stability. And now, more than ever, the Abbotts must not make a sound.', 'https://image.tmdb.org/t/p/w500/nAU74GmpUk7t5iklEp3bufwDq4n.jpg', null, null),
  ('Pop Skull', 2007, true, 'Not Rated', 'Adam Wingard', '2007-07-06'::date, '86 min', 'Drama, Horror', 'E.L. Katz, Lane Hughes, Adam Wingard', 'Lane Hughes, Brandon Carroll, Maggie Gwin', 'Pop Skull depicts the lonely and disjointed life of Daniel, a young Alabama pill addict, as his efforts to cope with the trials of his day-to-day life collide with the increasing influence of murderous and displaced spirits that inhabit his home.', 'https://image.tmdb.org/t/p/w500/t3pksjsHJAherUhrVO6mSkIcJtZ.jpg', null, null),
  ('Aeon Flux', 2005, true, 'PG-13', 'Karyn Kusama', '2005-12-02'::date, '93 min', 'Action, Adventure, Sci-Fi', 'Phil Hay, Matt Manfredi, Peter Chung', 'Charlize Theron, Frances McDormand, Sophie Okonedo', 'Four hundred years in the future, set in the year 2415, Æon Flux is a mysterious assassin. Four centuries after a virus nearly annihilated the human race, leaving only five million survivors in a utopian city called Bregna. Aeon is struggling to destroy the Goodchild regime led by its namesake, Trevor Goodchild, the ruler of Bregna and a descendant of the man who found a cure for the deadly virus. As instructed by the Handler, Æon is assigned to assassinate Goodchild, but there are deeper secrets to be discovered, and conspiracies to be foiled.', 'https://image.tmdb.org/t/p/w500/5958Nt4QX6aRSUdQnvNw8wqjTJQ.jpg', null, null),
  ('Alien', 1979, true, 'R', 'Ridley Scott', '1979-06-22'::date, '117 min', 'Horror, Sci-Fi', 'Dan O''Bannon, Ronald Shusett', 'Sigourney Weaver, Tom Skerritt, John Hurt', 'In the distant future, the crew of the commercial spaceship Nostromo are on their way home when they pick up a distress call from a distant moon. The crew are under obligation to investigate and the spaceship descends on the moon afterwards. After a rough landing, three crew members leave the spaceship to explore the area on the moon. At the same time as they discover a hive colony of some unknown creature, the ship''s computer deciphers the message to be a warning, not a distress call. When one of the eggs is disturbed, the crew realizes that they are not alone on the spaceship and they must deal with the consequences.', 'https://image.tmdb.org/t/p/w500/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', 'Alien/Predator', null),
  ('Alien vs. Predator', 2004, true, 'PG-13', 'Paul W.S. Anderson', '2004-08-13'::date, '101 min', 'Action, Adventure, Horror', 'Paul W.S. Anderson, Dan O''Bannon, Ronald Shusett', 'Sanaa Lathan, Lance Henriksen, Raoul Bova', 'When a private satellite encounters an unidentified source of heat in Antarctica and it is found to be a pyramid buried deep underground , a search team comprising of top-of-the-line archaeologists and engineers is sent to Antarctica to find out more . Once there , the team comes across signs which indicate that the place is inhabited by an unknown alien species . It is not long before the aliens begin to hunt the team members . At the same time , a trio of coming-of-age Predators have arrived to collect the skulls of the aliens as trophies , and the humans are caught between a deadly battle between the two warring species .', 'https://image.tmdb.org/t/p/w500/ySWu5bCnnmgV1cVacvFnFIhgOjp.jpg', 'Alien/Predator', null),
  ('Alien', 1992, true, 'R', 'David Fincher', '1992-05-22'::date, '114 min', 'Action, Horror, Sci-Fi', 'Dan O''Bannon, Ronald Shusett, Vincent Ward', 'Sigourney Weaver, Charles S. Dutton, Charles Dance', 'Ellen Ripley (Sigourney Weaver) is the only survivor when she crash lands on Fiorina 161, a bleak wasteland inhabited by former inmates of the planet''s maximum security prison. Once again, Ripley must face skepticism and the alien as it hunts down the prisoners and guards. Without weapons or modern technology of any kind, Ripley leads the men into battle against the terrifying creature.', 'https://image.tmdb.org/t/p/w500/r1x5JGpyqZU8PYhbs4UcrO1Xb6x.jpg', 'Alien/Predator', null),
  ('Alien: Covenant', 2017, true, 'R', 'Ridley Scott', '2017-05-19'::date, '122 min', 'Horror, Sci-Fi, Thriller', 'Dan O''Bannon, Ronald Shusett, Jack Paglen', 'Michael Fassbender, Katherine Waterston, Billy Crudup', 'In 2104, almost eleven years after the disastrous expedition to the distant moon, LV-223, in Prometheus (2012), the deep-space colonisation vessel, USCSS Covenant, is on course for the remote planet, Origae-6, with more than 2,000 colonists in cryogenic hibernation to build a new world. Instead, a rogue transmission entices the crew to a nearby habitable planet which resembles Earth. As a result, the unsuspecting crewmembers of the Covenant will have to cope with biological foes beyond human comprehension. Now, what started as a peaceful exploratory mission, will soon turn into a desperate rescue operation in uncharted space. Is there an escape from the treacherous, mysterious planet?', 'https://image.tmdb.org/t/p/w500/zecMELPbU5YMQpC81Z8ImaaXuf9.jpg', 'Alien/Predator', null),
  ('Alien: Resurrection', 1997, true, 'R', 'Jean-Pierre Jeunet', '1997-11-26'::date, '109 min', 'Action, Horror, Sci-Fi', 'Dan O''Bannon, Ronald Shusett, Joss Whedon', 'Sigourney Weaver, Winona Ryder, Dominique Pinon', 'The saga continues 200 years after Ripley sacrificed herself for the sake of humanity. Her erstwhile employers long gone, this time it is the military that resurrects the one-woman killing machine through genetic cloning to extract the alien from within her, but during the process her DNA is fused with the queen and then the aliens escape. Now Ripley must decide where her allegiance lies.', 'https://image.tmdb.org/t/p/w500/9aRDMlU5Zwpysilm0WCWzU2PCFv.jpg', 'Alien/Predator', null),
  ('Aliens', 1986, true, 'R', 'James Cameron', '1986-07-18'::date, '137 min', 'Action, Adventure, Sci-Fi', 'James Cameron, David Giler, Walter Hill', 'Sigourney Weaver, Michael Biehn, Carrie Henn', '57 years after Ellen Ripley had a close encounter with the reptilian alien creature from the first movie, she is called back, this time, to help a group of highly trained colonial marines fight off against the sinister extraterrestrials. But this time, the aliens have taken over a space colony on the moon LV-426. When the colonial marines are called upon to search the deserted space colony, they later find out that they are up against more than what they bargained for. Using specially modified machine guns and enough firepower, it''s either fight or die as the space marines battle against the aliens. As the Marines do their best to defend themselves, Ripley must attempt to protect a young girl who is the sole survivor of the nearly wiped out space colony.', 'https://image.tmdb.org/t/p/w500/r1x5JGpyqZU8PYhbs4UcrO1Xb6x.jpg', 'Alien/Predator', null),
  ('Aliens vs. Predator: Requiem', 2007, true, 'R', 'Colin Strause, Greg Strause', '2007-12-25'::date, '94 min', 'Action, Horror, Sci-Fi', 'Shane Salerno, Dan O''Bannon, Ronald Shusett', 'Reiko Aylesworth, Steven Pasquale, Shareeka Epps', 'No one can escape from the aggressive predatory Xenomorphs, and shortly after the Antarctic bloodshed in AVP: Alien vs. Predator (2004), a crippled Predator ship crash-lands on the dense forest of Gunnison, Colorado. As a result, a vicious Predalien hybrid, along with numerous Stage 1 Xenomorphs, or Face-huggers, scatter in all directions, infecting everyone unfortunate enough to cross their path. Once more, the Earth is a battlefield, as both extraterrestrial species are fighting for supremacy, and the humans become stuck in the middle. Now, the fate of the entire city rests in the hands of Sheriff Eddie Morales, and a handful of residents. Can they ensure the fate of humankind?', 'https://image.tmdb.org/t/p/w500/5iTwPDNtvK6ZZF607BHBbU3HO0B.jpg', 'Alien/Predator', null),
  ('Alita: Battle Angel', 2019, true, 'PG-13', 'Robert Rodriguez', '2019-02-14'::date, '122 min', 'Action, Adventure, Sci-Fi', 'James Cameron, Laeta Kalogridis, Yukito Kishiro', 'Rosa Salazar, Christoph Waltz, Jennifer Connelly', 'Alita is a creation from an age of despair. Found by the mysterious Dr. Ido while trolling for cyborg parts, Alita becomes a lethal, dangerous being. She cannot remember who she is, or where she came from. But to Dr. Ido, the truth is all too clear. She is the one being who can break the cycle of death and destruction left behind from Tiphares. But to accomplish her true purpose, she must fight and kill. And that is where Alita''s true significance comes to bear. She is an angel from heaven. She is an angel of death.', 'https://image.tmdb.org/t/p/w500/xRWht48C2V8XNfzvPehyClOvDni.jpg', null, null),
  ('All the President''s Men', 1976, true, 'PG', 'Alan J. Pakula', '1976-04-09'::date, '138 min', 'Drama, History, Thriller', 'Carl Bernstein, Bob Woodward, William Goldman', 'Dustin Hoffman, Robert Redford, Jack Warden', 'In the run-up to the 1972 elections, Washington Post reporter Bob Woodward covers what seems to be a minor break-in at the Democratic Party National headquarters. He is surprised to find top lawyers already on the defense case, and the discovery of names and addresses of White House fund organizers on the accused further arouses his suspicions. The editor of the Post is prepared to run with the story and assigns Woodward and Carl Bernstein to it. They find the trail leading higher and higher in the White House.', 'https://image.tmdb.org/t/p/w500/cPtSHR7D2WGsDBfnC5DxV927hKn.jpg', null, null),
  ('American Gangster', 2007, true, 'R', 'Ridley Scott', '2007-11-02'::date, '157 min', 'Biography, Crime, Drama', 'Steven Zaillian, Mark Jacobson', 'Denzel Washington, Russell Crowe, Chiwetel Ejiofor', 'Following the death of his employer and mentor, Bumpy Johnson, Frank Lucas establishes himself as the number one importer of heroin in the Harlem district of Manhattan. He does so by buying heroin directly from the source in South East Asia and he comes up with a unique way of importing the drugs into the United States. As a result, his product is superior to what is currently available on the street and his prices are lower. His alliance with the New York Mafia ensures his position. It is also the story of a dedicated and honest policeman, Richie Roberts, who heads up a joint narcotics task force with the Federal government. Based on a true story.', 'https://image.tmdb.org/t/p/w500/m7kJge9DG86Bj7hsBW6xFCMyDkY.jpg', null, null),
  ('An American Haunting', 2005, false, 'PG-13', 'Courtney Solomon', '2006-05-05'::date, '83 min', 'Drama, Horror, Mystery', 'Courtney Solomon, Brent Monahan', 'Donald Sutherland, Sissy Spacek, Rachel Hurd-Wood', 'In 2006, in Red River, Tennessee, a teenager has frequent nightmares. Her mother reads an old letter from 1817 written by her ancestor, Lucy Bell. After a dispute of lands judged by the church, her husband John Bell is cursed by his opponent Kathe Batts, who has a fame of being a witch. From this moment on, an entity threatens John and her daughter Betsy Bell, attacking the girl during the nights. With the support of Betsy''s school teacher Richard Powell, who tries to find rational explanations for the manifestation; her brother John Bell Jr.; and their friend James Johnston, who unsuccessfully tries to exorcize the entity from the house, the family does their best to protect Betsy in the haunted house.', 'https://image.tmdb.org/t/p/w500/5ePaCimd7cA9zYNib8WfIbWnrCf.jpg', null, null),
  ('Angels and Demons', 2009, true, 'Not Rated', 'Steve Kaminski', '2009-05-01'::date, '59 min', 'N/A', 'Houston Curtis (created by), Vicky Landin', 'Paul Dale Roberts, William Dyrness, Evelyn Bierniat, Allen Jahsmann', 'Mysteries of Angels and Demons talks to theologians and occult experts and examines cultural and sociological perceptions of demons and angels in religion and spirituality. It also looks at eyewitness testimony from several people who claim to have had encounters with angels and demons.', 'https://image.tmdb.org/t/p/w500/tFZQAuulEOtFTp0gHbVdEXwGrYe.jpg', null, null),
  ('Annabelle', 2014, true, 'R', 'John R. Leonetti', '2014-10-03'::date, '99 min', 'Horror, Mystery, Thriller', 'Gary Dauberman', 'Ward Horton, Annabelle Wallis, Alfre Woodard', 'John Form has found the perfect gift for his expectant wife, Mia - a beautiful, rare vintage doll in a pure white wedding dress. But Mia''s delight with Annabelle doesn''t last long. On one horrific night, their home is invaded by members of a satanic cult, who violently attack the couple. Spilled blood and terror are not all they leave behind. The cultists have conjured an entity so malevolent that nothing they did will compare to the sinister conduit to the damned that is now... Annabelle.', 'https://image.tmdb.org/t/p/w500/yLsuU2P2SpDYFwtZQ7dtfVAf6TE.jpg', null, null),
  ('Annabelle Comes Home', 2019, true, 'R', 'Gary Dauberman', '2019-06-26'::date, '106 min', 'Horror, Mystery, Thriller', 'Gary Dauberman, James Wan', 'Vera Farmiga, Patrick Wilson, Mckenna Grace', 'Determined to keep Annabelle from wreaking more havoc, demonologists Ed and Lorraine Warren bring the possessed doll to the locked artifacts room in their home, placing her "safely" behind sacred glass and enlisting a priest''s holy blessing. But an unholy night of horror awaits as Annabelle awakens the evil spirits in the room, who all set their sights on a new target--the Warrens'' ten-year-old daughter, Judy, and her friends.', 'https://image.tmdb.org/t/p/w500/qWsHMrbg9DsBY3bCMk9jyYCRVRs.jpg', null, null),
  ('Annabelle: Creation', 2017, true, 'R', 'David F. Sandberg', '2017-08-11'::date, '109 min', 'Horror, Mystery, Thriller', 'Gary Dauberman', 'Anthony LaPaglia, Samara Lee, Miranda Otto', 'The manufacturer of dolls Samuel Mullins is a happy family man with his wife Esther and their daughter Bee, who dies after being hit by a car. Twelve years later, Samuel and his wife, Esther, welcomes a nun and six orphaned girls to his home. He tells that only a locked room (that belonged to Bee) and Esther''s room would be off limits for the girls. The crippled girl, Janice, manages to sneak in Bee''s room during the night and finds a doll locked inside a closet. After she plays in the room, she is haunted by an evil force. What has Janice unleashed in Bee''s room?', 'https://image.tmdb.org/t/p/w500/tb86j8jVCVsdZnzf8I6cIi65IeM.jpg', null, null),
  ('Annihilation', 2018, true, 'R', 'Alex Garland', '2018-02-23'::date, '115 min', 'Adventure, Drama, Horror', 'Alex Garland, Jeff VanderMeer', 'Natalie Portman, Jennifer Jason Leigh, Tessa Thompson', 'A biologist''s husband disappears. She puts her name forward for an expedition into an environmental disaster zone, but does not find what she''s expecting. The expedition team is made up of the biologist, an anthropologist, a psychologist, a surveyor, and a linguist.', 'https://image.tmdb.org/t/p/w500/4YRplSk6BhH6PRuE9gfyw9byUJ6.jpg', null, 'Alex Garland'),
  ('Ant-Man', 2015, true, 'PG-13', 'Peyton Reed', '2015-07-17'::date, '117 min', 'Action, Comedy, Sci-Fi', 'Edgar Wright, Joe Cornish, Adam McKay', 'Paul Rudd, Michael Douglas, Corey Stoll', 'Armed with the astonishing ability to shrink in scale but increase in strength, con-man Scott Lang must embrace his inner-hero and help his mentor, Dr. Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.', 'https://image.tmdb.org/t/p/w500/rQRnQfUl3kfp78nCWq8Ks04vnq1.jpg', null, null),
  ('Ant-Man and the Wasp', 2018, true, 'PG-13', 'Peyton Reed', '2018-07-06'::date, '118 min', 'Action, Adventure, Comedy', 'Chris McKenna, Erik Sommers, Paul Rudd', 'Paul Rudd, Evangeline Lilly, Michael Peña', 'In the aftermath of Captain America: Civil War (2016), Scott Lang grapples with the consequences of his choices as both a superhero and a father. As he struggles to rebalance his home life with his responsibilities as Ant-Man, he''s confronted by Hope van Dyne and Dr. Hank Pym with an urgent new mission. Scott must once again put on the suit and learn to fight alongside The Wasp as the team works together to uncover secrets from their past.', 'https://image.tmdb.org/t/p/w500/cFQEO687n1K6umXbInzocxcnAQz.jpg', null, null),
  ('Apollo 13', 1995, true, 'PG', 'Ron Howard', '1995-06-30'::date, '140 min', 'Adventure, Drama, History', 'Jim Lovell, Jeffrey Kluger, William Broyles Jr.', 'Tom Hanks, Bill Paxton, Kevin Bacon', 'Based on the true story of the ill-fated 13th Apollo mission bound for the moon. Astronauts Lovell, Haise and Swigert were scheduled to fly Apollo 14, but are moved up to 13. It''s 1970, and The US has already achieved their lunar landing goal, so there''s little interest in this "routine" flight.. until that is, things go very wrong, and prospects of a safe return fade.', 'https://image.tmdb.org/t/p/w500/tVeKscCm2fY1xDXZk8PgnZ87h9S.jpg', null, null),
  ('April Fool''s Day', 1986, false, 'R', 'Fred Walton', '1986-03-28'::date, '89 min', 'Horror, Mystery', 'Danilo Bach', 'Deborah Foreman, Griffin O''Neal, Clayton Rohner', 'A group of eight college friends gather together at an island mansion belonging to heiress Muffy St. John to celebrate their final year of school. They soon discover that each has a hidden secret from their past which is revealed, and soon after, they turn up dead. Yet, are they really dead? Or is it just part of some very real and cruel April Fool''s jokes? The hostess, Muffy, is the only one who apparently knows what''s going on. But then again, is it really her doing the killing?', 'https://image.tmdb.org/t/p/w500/zNx2tNRzRyPsBSHX1VF2c7U0UyW.jpg', null, null),
  ('Arachnophobia', 1990, true, 'PG-13', 'Frank Marshall', '1990-07-18'::date, '109 min', 'Comedy, Horror, Thriller', 'Don Jakoby, Al Williams, Wesley Strick', 'Jeff Daniels, Julian Sands, John Goodman', 'A large spider from the jungles of South America is accidentally transported in a crate with a dead body to America where it mates with a local spider. Soon after, the residents of a small California town disappear as the result of spider bites from the deadly spider offspring. It''s up to a couple of doctors with the help of an insect exterminator to annihilate these eight legged freaks before they take over the entire town.', 'https://image.tmdb.org/t/p/w500/lHjpwv1Yv2RcGcTQb4Lc1cKw1y9.jpg', null, null),
  ('Arlington Road', 1999, true, 'R', 'Mark Pellington', '1999-07-09'::date, '117 min', 'Action, Crime, Drama', 'Ehren Kruger', 'Jeff Bridges, Tim Robbins, Joan Cusack', 'In suburban Reston, Virginia, George Washington University American History professor Michael Faraday is still mourning the death of his wife, FBI agent Leah Faraday, after three years. His inside knowledge of the agency colors what he teaches in his classes. Although on good terms with Leah''s ex-partner, Whit Carver, and the agency in general, Michael wants the agency at least to acknowledge their responsibility in her death in the line of duty. Michael is moving on with his personal life, he being in a serious relationship with his former teaching assistant Brooke Wolfe. Although he likes Brooke, Michael and Leah''s nine year old son, Grant Faraday, may not yet be quite ready for Brooke to be a permanent part of their lives. It is only in helping adolescent Brady Lang who he sees in medical distress that Michael meets his new neighbors, Oliver and Cheryl Lang, Brady''s parents. In the process, Michael and Brooke becomes friends with the Langs, as Grant and Brady become friends. However, the more time that he spends with them and catches discrepancies in their stories, Michael becomes suspicious that the Langs may not be everything they appear on the surface. As such, Michael, against Brooke''s concerns of invasion of the Lang''s privacy, begins his own investigation of Oliver in particular. What Michael discovers has serious national security implications, as well as possible life threatening dangers to him, Brooke and Grant.', 'https://image.tmdb.org/t/p/w500/4yYHyZuyTTQaEZuHKS7561jXjtR.jpg', null, null),
  ('Arrival', 2016, true, 'PG-13', 'Denis Villeneuve', '2016-11-11'::date, '116 min', 'Drama, Mystery, Sci-Fi', 'Eric Heisserer, Ted Chiang', 'Amy Adams, Jeremy Renner, Forest Whitaker', 'Linguistics professor Louise Banks leads an elite team of investigators when gigantic spaceships touchdown in 12 locations around the world. As nations teeter on the verge of global war, Banks and her crew must race against time to find a way to communicate with the extraterrestrial visitors. Hoping to unravel the mystery, she takes a chance that could threaten her life and quite possibly all of mankind.', 'https://image.tmdb.org/t/p/w500/pEzNVQfdzYDzVK0XqxERIw2x2se.jpg', null, null),
  ('Assassin''s Creed', 2016, false, 'PG-13', 'Justin Kurzel', '2016-12-21'::date, '115 min', 'Action, Adventure, Sci-Fi', 'Michael Lesslie, Adam Cooper, Bill Collage', 'Michael Fassbender, Marion Cotillard, Jeremy Irons', 'Through a revolutionary technology that unlocks his genetic memories, Callum Lynch (Michael Fassbender) experiences the adventures of his ancestor, Aguilar de Nerha, in 15th Century Spain. Callum discovers he is descended from a mysterious secret society, the Assassins, and amasses incredible knowledge and skills to take on the oppressive and powerful Templar organization in the present day.', 'https://image.tmdb.org/t/p/w500/kDXewoEcvbn0pUvJ8W3vfkuWgHw.jpg', null, null),
  ('Avatar', 2009, true, 'PG-13', 'James Cameron', '2009-12-18'::date, '162 min', 'Action, Adventure, Fantasy', 'James Cameron', 'Sam Worthington, Zoe Saldana, Sigourney Weaver', 'When his brother is killed in a robbery, paraplegic Marine Jake Sully decides to take his place in a mission on the distant world of Pandora. There he learns of greedy corporate figurehead Parker Selfridge''s intentions of driving off the native humanoid "Na''vi" in order to mine for the precious material scattered throughout their rich woodland. In exchange for the spinal surgery that will fix his legs, Jake gathers knowledge, of the Indigenous Race and their Culture, for the cooperating military unit spearheaded by gung-ho Colonel Quaritch, while simultaneously attempting to infiltrate the Na''vi people with the use of an "avatar" identity. While Jake begins to bond with the native tribe and quickly falls in love with the beautiful alien Neytiri, the restless Colonel moves forward with his ruthless extermination tactics, forcing the soldier to take a stand - and fight back in an epic battle for the fate of Pandora.', 'https://image.tmdb.org/t/p/w500/gKY6q7SjCkAU6FqvqWybDYgUKIF.jpg', null, null),
  ('Avengers: Age of Ultron', 2015, true, 'PG-13', 'Joss Whedon', '2015-05-01'::date, '141 min', 'Action, Adventure, Sci-Fi', 'Joss Whedon, Stan Lee, Jack Kirby', 'Robert Downey Jr., Chris Evans, Mark Ruffalo', 'Tony Stark creates the Ultron Program to protect the world, but when the peacekeeping program becomes hostile, The Avengers go into action to try and defeat a virtually impossible enemy together. Earth''s mightiest heroes must come together once again to protect the world from global extinction.', 'https://image.tmdb.org/t/p/w500/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg', null, null),
  ('Avengers: Endgame', 2019, true, 'PG-13', 'Anthony Russo, Joe Russo', '2019-04-26'::date, '181 min', 'Action, Adventure, Drama', 'Christopher Markus, Stephen McFeely, Stan Lee', 'Robert Downey Jr., Chris Evans, Mark Ruffalo', 'After the devastating events of Avengers: Infinity War (2018), the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos''s actions and undo the chaos to the universe, no matter what consequences may be in store, and no matter who they face...', 'https://image.tmdb.org/t/p/w500/bR8ISy1O9XQxqiy0fQFw2BX72RQ.jpg', null, null),
  ('Avengers: Infinity War', 2018, true, 'PG-13', 'Anthony Russo, Joe Russo', '2018-04-27'::date, '149 min', 'Action, Adventure, Sci-Fi', 'Christopher Markus, Stephen McFeely, Stan Lee', 'Robert Downey Jr., Chris Hemsworth, Mark Ruffalo', 'As the Avengers and their allies have continued to protect the world from threats too large for any one hero to handle, a new danger has emerged from the cosmic shadows: Thanos. A despot of intergalactic infamy, his goal is to collect all six Infinity Stones, artifacts of unimaginable power, and use them to inflict his twisted will on all of reality. Everything the Avengers have fought for has led up to this moment, the fate of Earth and existence has never been more uncertain.', 'https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', null, null),
  ('Baby Driver', 2017, true, 'R', 'Edgar Wright', '2017-06-28'::date, '113 min', 'Action, Crime, Drama', 'Edgar Wright', 'Ansel Elgort, Jon Bernthal, Jon Hamm', 'Baby is a young and partially hearing impaired getaway driver who can make any wild move while in motion with the right track playing. It''s a critical talent he needs to survive his indentured servitude to the crime boss, Doc, who values his role in his meticulously planned robberies. However, just when Baby thinks he is finally free and clear to have his own life with his new girlfriend, Debora, Doc coerces him back for another job. Now saddled with a crew of thugs too violently unstable to keep to Doc''s plans, Baby finds himself and everything he cares for in terrible danger. To survive and escape the coming maelstrom, it will take all of Baby''s skill, wits and daring, but even on the best track, can he make it when life is forcing him to face the music?', 'https://image.tmdb.org/t/p/w500/tYzFuYXmT8LOYASlFCkaPiAFAl0.jpg', null, null),
  ('Batman v Superman: Dawn of Justice', 2016, false, 'R', 'Zack Snyder', '2016-03-25'::date, '151 min', 'Action, Adventure, Sci-Fi', 'Bob Kane, Bill Finger, Jerry Siegel', 'Ben Affleck, Henry Cavill, Amy Adams', 'The general public is concerned over having Superman on their planet and letting the "Dark Knight" - Batman - pursue the streets of Gotham. While this is happening, a power-phobic Batman tries to attack Superman. Meanwhile, Superman tries to settle on a decision, and Lex Luthor, the criminal mastermind and millionaire, tries to use his own advantages to fight the "Man of Steel".', 'https://image.tmdb.org/t/p/w500/5UsK3grJvtQrtzEgqNlDljJW96w.jpg', null, null),
  ('Dark City', 1998, false, 'R', 'Alex Proyas', '1998-02-27'::date, '100 min', 'Fantasy, Mystery, Sci-Fi', 'Alex Proyas, Lem Dobbs, David S. Goyer', 'Rufus Sewell, Kiefer Sutherland, Jennifer Connelly', 'John Murdoch awakens alone in a strange hotel to find that he has lost his memory and is wanted for a series of brutal and bizarre murders. While trying to piece together his past, he stumbles upon a fiendish underworld controlled by a group of beings known as The Strangers who possess the ability to put people to sleep and alter the city and its inhabitants. Now Murdoch must find a way to stop them before they take control of his mind and destroy him.', 'https://image.tmdb.org/t/p/w500/tNPEGju4DpTdbhBphNmZoEi9Bd3.jpg', null, null),
  ('Beautiful Creatures', 2013, false, 'PG-13', 'Richard LaGravenese', '2013-02-14'::date, '124 min', 'Drama, Fantasy, Romance', 'Richard LaGravenese, Kami Garcia, Margaret Stohl', 'Alice Englert, Viola Davis, Emma Thompson', 'Teenager Ethan Wate (Alden Ehrenreich) is obsessed with his urge to finish high school, go on to college, and leave behind the small town of Gatlin, South Carolina, until a mysterious girl invades his dreams. When he meets Lena Duchannes (Alice Englert), a newcomer who has just enrolled in his school, he knows she''s the girl in his dreams. Lena is rejected by the rest of her classmates for being the niece of Macon Ravenwood (Jeremy Irons), whom the town''s superstitious residents consider to be a devil-worshiper. But Ethan gives her a ride anyway and they fall in love. Lena reveals to her new boyfriend that she is a witch, and that on her 16th birthday she will be claimed by either the forces of light or of darkness. She can only remain in the light if she doesn''t remain in love with Ethan. Worse, her evil mother Sarafine (Dame Emma Thompson) is casting spells to push her to the dark side. Ethan joins her in a search to find a magic spell to save their doomed love. Will they succeed?', 'https://image.tmdb.org/t/p/w500/t7PWQHpJHb2ozALCfaPaC5aHxBs.jpg', null, null),
  ('Beowulf', 2007, false, 'PG-13', 'Robert Zemeckis', '2007-11-16'::date, '115 min', 'Animation, Action, Adventure', 'Neil Gaiman, Roger Avary, Anonymous', 'Ray Winstone, Crispin Glover, Angelina Jolie', 'Set against the coming of Christianity, this is the story of the last hero: in 507, a monstrous troll wreaks havoc in the mead hall of Danish King Hrothgar (Sir Anthony Hopkins). He offers rewards for the death of Grendel (Crispin Glover), so Beowulf (Ray Winstone), a great and boastful Geat warrior, arrives with his thanes. Beowulf sets aside his armor and awaits the monster. A fierce battle ensues that leads to Beowolf''s entering the watery lair of Grendel''s Mother (Angelina Jolie), where a devil''s bargain awaits. Beowulf returns to Herot, the castle, and becomes King. Jump ahead many years, and the sins of the father are visited upon Beowulf and his kingdom. The hero must face his weakness and be heroic once again. Is the age of demons over?', 'https://image.tmdb.org/t/p/w500/7QsWYyJAV97N9jOh21pdRIqJeJq.jpg', null, null),
  ('Beyond the Law', 1993, false, 'R', 'Larry Ferguson', '1993-04-22'::date, '108 min', 'Crime, Drama, Thriller', 'Larry Ferguson', 'Charlie Sheen, Linda Fiorentino, Michael Madsen', 'Dan Saxon (Charlie Sheen) is an undercover cop who infiltrates a biker gang to nail the scum behind a drug-smuggling operation. In order to maintain the trust of the gang''s leader, Blood (Michael Madsen), he must commit ever more dangerous and heinous crimes. Just how far ''beyond the law'' will Saxon go?', 'https://image.tmdb.org/t/p/w500/vzlSfPrQDExlb8y8TAfjiYuk3hN.jpg', null, null),
  ('Big Fish', 2003, false, 'PG-13', 'Tim Burton', '2004-01-09'::date, '125 min', 'Adventure, Drama, Fantasy', 'Daniel Wallace, John August', 'Ewan McGregor, Albert Finney, Billy Crudup', 'United Press International journalist Will Bloom and his French freelance photojournalist wife Josephine Bloom, who is pregnant with their first child, leave their Paris base to return to Will''s hometown of Ashton, Alabama on the news that his father, Edward Bloom, stricken with cancer, will soon die, he being taken off chemotherapy treatment. Although connected indirectly through Will''s mother/Edward''s wife, Sandra Bloom, Will has been estranged from his father for three years since his and Josephine''s wedding. Will''s issue with his father is the fanciful tales Edward has told of his life all his life, not only to Will but the whole world. As a child when Edward was largely absent as a traveling salesman, Will believed those stories, but now realizes that he does not know his father, who, as he continues to tell these stories, he will never get to know unless Edward comes clean with the truth before he dies. On the brink of his own family life beginning, Will does not want to be the kind of father Edward has been to him. One of those stories from Edward''s childhood - that he saw his own death in the glass eye of a witch - led to him embracing life since he would not have to fear death knowing when and how it would eventually come. The question is whether Will will be able to reconcile Edward''s stories against his real life, either directly from Edward before he dies and/or from other sources, and thus allow Will to come to a new understanding of himself and his life, past, present and future.', 'https://image.tmdb.org/t/p/w500/tjK063yCgaBAluVU72rZ6PKPH2l.jpg', null, null),
  ('Big Hero 6', 2014, false, 'PG', 'Don Hall, Chris Williams', '2014-11-07'::date, '102 min', 'Animation, Action, Adventure', 'Jordan Roberts, Robert L. Baird, Daniel Gerson', 'Ryan Potter, Scott Adsit, Jamie Chung', 'When a devastating event befalls the city of San Fransokyo and catapults Hiro into the midst of danger, he turns to Baymax and his close friends adrenaline junkie Go Go Tomago, neatnik Wasabi, chemistry whiz Honey Lemon and fanboy Fred. Determined to uncover the mystery, Hiro transforms his friends into a band of high-tech heroes called "Big Hero 6."', 'https://image.tmdb.org/t/p/w500/2mxS4wUimwlLmI1xp6QW6NSU361.jpg', null, null),
  ('Big Trouble in Little China', 1986, true, 'PG-13', 'John Carpenter', '1986-07-02'::date, '99 min', 'Action, Adventure, Comedy', 'Gary Goldman, David Z. Weinstein, W.D. Richter', 'Kurt Russell, Kim Cattrall, Dennis Dun', 'Truck driver Jack Burton arrives in Chinatown, San Francisco, and goes to the airport with his Chinese friend Wang Chi to welcome his green-eyed fiancée Miao Yin who is arriving from China. However she is kidnapped on the arrival by a Chinese street gang and Jack and Wang chase the group. Soon they learn that the powerful evil sorcerer called David Lo Pan, who has been cursed more than two thousand years ago to exist without physical body, needs to marry a woman with green eyes to retrieve his physical body and Miao is the chosen one. Jack and Wang team-up with the lawyer Gracie Law, the bus driver and sorcerer apprentice Egg Shen and their friends and embark in a great adventure in the underground of Chinatown, where they face a world of magicians and magic, monsters and martial arts fighters.', 'https://image.tmdb.org/t/p/w500/tJXWBW5LLA1u12WdWQZRPvxBq4k.jpg', null, null),
  ('Black Panther', 2018, true, 'PG-13', 'Ryan Coogler', '2018-02-16'::date, '134 min', 'Action, Adventure, Sci-Fi', 'Ryan Coogler, Joe Robert Cole, Stan Lee', 'Chadwick Boseman, Michael B. Jordan, Lupita Nyong''o', 'After the events of Captain America: Civil War, Prince T''Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country''s new king. However, T''Challa soon finds that he is challenged for the throne from factions within his own country. When two foes conspire to destroy Wakanda, the hero known as Black Panther must team up with C.I.A. agent Everett K. Ross and members of the Dora Milaje, Wakandan special forces, to prevent Wakanda from being dragged into a world war.', 'https://image.tmdb.org/t/p/w500/uxzzxijgPIY7slzFvMotPv8wjKA.jpg', null, null),
  ('Black Widow', 2021, true, 'PG-13', 'Cate Shortland', '2021-07-09'::date, '134 min', 'Action, Adventure, Sci-Fi', 'Eric Pearson, Jac Schaeffer, Ned Benson', 'Scarlett Johansson, Florence Pugh, David Harbour', 'In Marvel Studios'' action-packed spy thriller "Black Widow," Natasha Romanoff aka Black Widow confronts the darker parts of her ledger when a dangerous conspiracy with ties to her past arises. Pursued by a force that will stop at nothing to bring her down, Natasha must deal with her history as a spy and the broken relationships left in her wake long before she became an Avenger.', 'https://image.tmdb.org/t/p/w500/7JPpIjhD2V0sKyFvhB9khUMa30d.jpg', null, null),
  ('Dawn of the Planet of the Apes', 2014, true, 'PG-13', 'Matt Reeves', '2014-07-11'::date, '130 min', 'Action, Adventure, Drama', 'Mark Bomback, Rick Jaffa, Amanda Silver', 'Gary Oldman, Keri Russell, Andy Serkis', 'A growing nation of genetically evolved apes led by Caesar is threatened by a band of human survivors of the devastating virus unleashed a decade earlier. They reach a fragile peace, but it proves short-lived, as both sides are brought to the brink of a war that will determine who will emerge as Earth''s dominant species.', 'https://image.tmdb.org/t/p/w500/kScdQEwS9jPEdnO23XjGAtaoRcT.jpg', null, null),
  ('BlacKkKlansman', 2018, false, 'R', 'Spike Lee', '2018-08-10'::date, '135 min', 'Biography, Comedy, Crime', 'Charlie Wachtel, David Rabinowitz, Kevin Willmott', 'John David Washington, Adam Driver, Laura Harrier', 'In the early 1970s, Ron Stallworth is hired as the first black officer in the Colorado Springs, Colorado police department. Stallworth is initially assigned to work in the records room, where he faces racial slurs from his coworkers. Stallworth requests a transfer to go undercover, and is assigned to infiltrate a local rally at which national civil rights leader Kwame Ture (birth name Stokely Carmichael) is to give a speech. At the rally, Stallworth meets Patrice Dumas, the president of the black student union at Colorado College. While taking Ture to his hotel, Patrice is stopped by patrolman Andy Landers, a corrupt, racist officer in Stallworth''s precinct, who threatens Ture and sexually assaults Patrice..', 'https://image.tmdb.org/t/p/w500/8jxqAvSDoneSKRczaK8v9X5gqBp.jpg', null, null),
  ('Blade', 1998, true, 'R', 'Stephen Norrington', '1998-08-21'::date, '120 min', 'Action, Horror, Sci-Fi', 'David S. Goyer', 'Wesley Snipes, Stephen Dorff, Kris Kristofferson', 'In a world where vampires walk the earth, Blade has a goal. His goal is to rid the world of all vampire evil. When Blade witnesses a vampire bite Dr. Karen Jenson, he fights away the beast and takes Jenson back to his hideout. Here, alongside Abraham Whistler, Blade attempts to help heal Jenson. The vampire Quinn who was attacked by Blade, reports back to his master Deacon Frost, who is planning a huge surprise for the human population.', 'https://image.tmdb.org/t/p/w500/hx0sdduAsr4rq03RZKZzglR25z7.jpg', null, null),
  ('Blade II', 2002, true, 'R', 'Guillermo del Toro', '2002-03-22'::date, '117 min', 'Action, Horror, Sci-Fi', 'Marv Wolfman, Gene Colan, David S. Goyer', 'Wesley Snipes, Kris Kristofferson, Ron Perlman', 'A rare mutation has occurred within the vampire community. The Reaper. A vampire so consumed with an insatiable bloodlust that they prey on vampires as well as humans, transforming victims who are unlucky enough to survive into Reapers themselves. Now their quickly expanding population threatens the existence of vampires, and soon there won''t be enough humans in the world to satisfy their bloodlust. Blade, Whistler and an armory expert named Scud are curiously summoned by the Shadow Council. The council reluctantly admits that they are in a dire situation and they require Blade''s assistance. Blade then tenuously enters into an alliance with The Bloodpack, an elite team of vampires trained in all modes of combat to defeat the Reaper threat. Blade''s team and the Bloodpack are the only line of defense which can prevent the Reaper population from wiping out the vampire and human populations.', 'https://image.tmdb.org/t/p/w500/yDHwo3eWcMiy5LnnEnlGV9iLu9k.jpg', null, null),
  ('Blade Runner 2049', 2017, true, 'R', 'Denis Villeneuve', '2017-10-06'::date, '164 min', 'Action, Drama, Mystery', 'Hampton Fancher, Michael Green, Philip K. Dick', 'Harrison Ford, Ryan Gosling, Ana de Armas', 'Thirty years after the events of Blade Runner (1982), a new Blade Runner, L.A.P.D. Officer "K" (Ryan Gosling), unearths a long-buried secret that has the potential to plunge what''s left of society into chaos. K''s discovery leads him on a quest to find Rick Deckard (Harrison Ford), a former L.A.P.D. Blade Runner, who has been missing for thirty years.', 'https://image.tmdb.org/t/p/w500/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', null, null),
  ('Blade: Trinity', 2004, true, 'R', 'David S. Goyer', '2004-12-08'::date, '113 min', 'Action, Horror, Sci-Fi', 'David S. Goyer, Marv Wolfman, Gene Colan', 'Wesley Snipes, Kris Kristofferson, Parker Posey', 'Blade finds himself alone surrounded by enemies, fighting an up hill battle with the vampire nation and now humans. He joins forces with a group of vampire hunters who call themselves the Nightstalkers. The vampire nation awakens the king of vampires Dracula from his slumber with intentions of using his primitive blood to become day-walkers. On the other side is Blade and his team manifesting a virus that could wipe out the vampire race once and for all. In the end the two sides will collide and only one will come out victorious, a battle between the ultimate vampire who never knew defeat, facing off against the greatest vampire slayer.', 'https://image.tmdb.org/t/p/w500/6f7iXvPOnf83MaLB1JmPzUor1rr.jpg', null, null),
  ('Blood Diamond', 2006, false, 'R', 'Edward Zwick', '2006-12-08'::date, '143 min', 'Adventure, Drama, Thriller', 'Charles Leavitt, C. Gaby Mitchell', 'Leonardo DiCaprio, Djimon Hounsou, Jennifer Connelly', 'A story following Archer, a man tortured by his roots. With a strong survival instinct, he has made himself a key player in the business of conflict diamonds. Political unrest is rampant in Sierra Leone as people fight tooth for tooth. Upon meeting Solomon, and the beautiful Maddy, Archer''s life changes forever as he is given a chance to make peace with the war around him.', 'https://image.tmdb.org/t/p/w500/bqKNoySmI4eOjsSjJEnLj4j2HAp.jpg', null, null),
  ('Blue Hawaii', 1961, false, 'PG', 'Norman Taurog', '1961-12-13'::date, '102 min', 'Comedy, Musical', 'Allan Weiss, Hal Kanter', 'Elvis Presley, Joan Blackman, Angela Lansbury', 'Chad Gates (Elvis Presley) has just gotten out of the Army, and is happy to be back in Hawaii with his surfboard, his beach buddies, and his girlfriend. His father wants him to go to work at the Great Southern Hawaiian Fruit Company, but he is reluctant. So he goes to work as a tour guide at his girlfriend''s agency.', 'https://image.tmdb.org/t/p/w500/kujIwcrOsgcyRLbs5xfwU1ADwHk.jpg', null, null),
  ('Brave', 2012, false, 'PG', 'Mark Andrews, Brenda Chapman, Steve Purcell', '2012-06-19'::date, '93 min', 'Animation, Action, Adventure', 'Brenda Chapman, Mark Andrews, Steve Purcell', 'Kelly Macdonald, Billy Connolly, Emma Thompson', 'Set in Scotland in a rugged and mythical time, this movie features Princess Merida (Kelly Macdonald), an aspiring archer and impetuous daughter of Queen Elinor (Dame Emma Thompson). Merida makes a reckless choice that unleashes unintended peril and forces her to spring into action to set things right.', 'https://image.tmdb.org/t/p/w500/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', null, null),
  ('Braveheart', 1995, false, 'R', 'Mel Gibson', '1995-05-24'::date, '178 min', 'Biography, Drama, War', 'Randall Wallace', 'Mel Gibson, Sophie Marceau, Patrick McGoohan', 'William Wallace is a Scottish rebel who leads an uprising against the cruel English ruler Edward the Longshanks, who wishes to inherit the crown of Scotland for himself. When he was a young boy, William Wallace''s father and brother, along with many others, lost their lives trying to free Scotland. Once he loses another of his loved ones, William Wallace begins his long quest to make Scotland free once and for all, along with the assistance of Robert the Bruce.', 'https://image.tmdb.org/t/p/w500/or1gBugydmjToAEq7OZY0owwFk.jpg', null, null),
  ('Bruce Almighty', 2003, false, 'PG-13', 'Tom Shadyac', '2003-05-23'::date, '101 min', 'Comedy, Fantasy', 'Steve Koren, Mark O''Keefe, Steve Oedekerk', 'Jim Carrey, Jennifer Aniston, Morgan Freeman', 'Bruce Nolan, a television reporter in Buffalo, N.Y., is discontented with almost everything in life despite his popularity and the love of his girlfriend Grace . At the end of the worst day of his life, Bruce angrily ridicules and rages against God and God responds. God appears in human form and, endowing Bruce with divine powers, challenges Bruce to take on the big job to see if he can do it any better.', 'https://image.tmdb.org/t/p/w500/f0QqG14SZYYZcV4VWykVc5w13dz.jpg', null, null),
  ('Captain America: Civil War', 2016, true, 'PG-13', 'Anthony Russo, Joe Russo', '2016-05-06'::date, '147 min', 'Action, Sci-Fi', 'Christopher Markus, Stephen McFeely, Joe Simon', 'Chris Evans, Robert Downey Jr., Scarlett Johansson', 'With many people fearing the actions of super heroes, the government decides to push for the Hero Registration Act, a law that limits a hero''s actions. This results in a division in The Avengers. Iron Man stands with this Act, claiming that their actions must be kept in check otherwise cities will continue to be destroyed, but Captain America feels that saving the world is daring enough and that they cannot rely on the government to protect the world. This escalates into an all-out war between Team Iron Man (Iron Man, Black Panther, Vision, Black Widow, War Machine, and Spider-Man) and Team Captain America (Captain America, Bucky Barnes, Falcon, Scarlet Witch, Hawkeye, and Ant Man) while a new villain emerges.', 'https://image.tmdb.org/t/p/w500/rAGiXaUfPzY7CDEyNKUofk3Kw2e.jpg', null, null),
  ('Captain America: The First Avenger', 2011, true, 'PG-13', 'Joe Johnston', '2011-07-22'::date, '124 min', 'Action, Adventure, Sci-Fi', 'Christopher Markus, Stephen McFeely, Joe Simon', 'Chris Evans, Hugo Weaving, Samuel L. Jackson', 'It is 1942, America has entered World War II, and sickly but determined Steve Rogers is frustrated at being rejected yet again for military service. Everything changes when Dr. Erskine recruits him for the secret Project Rebirth. Proving his extraordinary courage, wits and conscience, Rogers undergoes the experiment and his weak body is suddenly enhanced into the maximum human potential. When Dr. Erskine is then immediately assassinated by an agent of Nazi Germany''s secret HYDRA research department (headed by Johann Schmidt, a.k.a. the Red Skull), Rogers is left as a unique man who is initially misused as a propaganda mascot; however, when his comrades need him, Rogers goes on a successful adventure that truly makes him Captain America, and his war against Schmidt begins.', 'https://image.tmdb.org/t/p/w500/vSNxAJTlD0r02V9sPYpOjqDZXUK.jpg', null, null),
  ('Captain America: The Winter Soldier', 2014, true, 'PG-13', 'Anthony Russo, Joe Russo', '2014-04-04'::date, '136 min', 'Action, Adventure, Sci-Fi', 'Christopher Markus, Stephen McFeely, Joe Simon', 'Chris Evans, Samuel L. Jackson, Scarlett Johansson', 'For Steve Rogers, awakening after decades of suspended animation involves more than catching up on pop culture; it also means that this old school idealist must face a world of subtler threats and difficult moral complexities. That becomes clear when Director Nick Fury is killed by the mysterious assassin, the Winter Soldier, but not before warning Rogers that SHIELD has been subverted by its enemies. When Rogers acts on Fury''s warning to trust no one there, he is branded as a traitor by the organization. Now a fugitive, Captain America must get to the bottom of this deadly mystery with the help of the Black Widow and his new friend, The Falcon. However, the battle will be costly for the Sentinel of Liberty, with Rogers finding enemies where he least expects them while learning that the Winter Soldier looks disturbingly familiar.', 'https://image.tmdb.org/t/p/w500/tVFRpFw3xTedgPGqxW0AOI8Qhh0.jpg', null, null),
  ('Captain Marvel', 2019, true, 'PG-13', 'Anna Boden, Ryan Fleck', '2019-03-08'::date, '123 min', 'Action, Adventure, Sci-Fi', 'Anna Boden, Ryan Fleck, Geneva Robertson-Dworet', 'Brie Larson, Samuel L. Jackson, Ben Mendelsohn', 'After crashing an experimental aircraft, Air Force pilot Carol Danvers is discovered by the Kree and trained as a member of the elite Starforce Military under the command of her mentor Yon-Rogg. Six years later, after escaping to Earth while under attack by the Skrulls, Danvers begins to discover there''s more to her past. With help from S.H.I.E.L.D. agent Nick Fury, they set out to unravel the truth.', 'https://image.tmdb.org/t/p/w500/AtsgWhDnHTq68L0lLsUrCnM7TjG.jpg', null, null),
  ('Casino', 1995, false, 'R', 'Martin Scorsese', '1995-11-22'::date, '178 min', 'Crime, Drama', 'Nicholas Pileggi, Martin Scorsese', 'Robert De Niro, Sharon Stone, Joe Pesci', 'This Martin Scorsese film depicts the Janus-like quality of Las Vegas--it has a glittering, glamorous face, as well as a brutal, cruel one. Ace Rothstein and Nicky Santoro, mobsters who move to Las Vegas to make their mark, live and work in this paradoxical world. Seen through their eyes, each as a foil to the other, the details of mob involvement in the casinos of the 1970s and ''80s are revealed. Ace is the smooth operator of the Tangiers casino, while Nicky is his boyhood friend and tough strongman, robbing and shaking down the locals. However, they each have a tragic flaw--Ace falls in love with a hustler, Ginger, and Nicky falls into an ever-deepening spiral of drugs and violence.', 'https://image.tmdb.org/t/p/w500/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg', null, null),
  ('Chappie', 2015, false, 'R', 'Neill Blomkamp', '2015-03-06'::date, '120 min', 'Action, Crime, Drama', 'Neill Blomkamp, Terri Tatchell', 'Sharlto Copley, Dev Patel, Hugh Jackman', 'In Johannesburg, the police department reduced the high rating of criminality using robots from the Tetravaal Company, designed by the engineer Deon Wilson. The former military Vincent Moore is envious of Deon, since he has developed another project called Moose, but neither Tetravaal nor the police department is interested. Deon has just developed an Artificial Intelligence but the Tetravaal''s CEO Michelle Bradley asks him to abort the project. Deon decides to bring the damaged Robot 22 that was sent to be crushed to test his A.I. However he is kidnapped by the criminals Ninja, Yo-Landi and Amerika that want him to stop the robot cops. When they see the damaged robot in the van, they force Deon to program it to heist banks with them and they call it Chappie. However, Chappie acts like a child and need to be trained to learn and grow. Meanwhile Vincent follows Deon and plots an evil scheme to activate his robot.', 'https://image.tmdb.org/t/p/w500/uuDUpzlMFomdSfNWlpEPS9nVZWV.jpg', null, null),
  ('Children of Men', 2006, false, 'R', 'Alfonso Cuarón', '2007-01-05'::date, '109 min', 'Action, Drama, Sci-Fi', 'Alfonso Cuarón, Timothy J. Sexton, David Arata', 'Julianne Moore, Clive Owen, Chiwetel Ejiofor', 'London, 2027. In this dystopian world, humans have been incapable of reproducing for eighteen years for an unknown reason, meaning the imminent extinction of the species. Britain is the one remaining civilized society on the planet, which has resulted in people wanting to immigrate there. As such, it has become a police state in order to handle the immigrants, who are placed into refugee camps. Lowly government bureaucrat Theo Faron, once an activist, is approached by the Fishes, deemed a terrorist group, led by his ex-wife Julian Taylor, who he has not seen in close to twenty years, their marriage which disintegrated following the death of their infant son Dylan during the 2008 flu pandemic. Although the Fishes did use terrorist means in their on-going revolution against the state in the fight for immigrant rights, Julian vows that they now garner support solely by speaking to the people. What she wants is for Theo to use his connections to get transit papers for a young immigrant woman named Kee who needs to get to the coast. Although initially reluctant to do it because of the difficulty, Theo is able to grant Julian this favor, however with the change that he now needs to accompany Kee on her journey. As Theo and Kee progress on that journey, Theo learns more and more about what''s going on, including the reason that Kee needs to get to the coast, the fact that no one in the group knows if their end destination even exists, and that his and Kee''s lives are in greater danger than he believed when they started the journey. But Theo''s sole mission becomes to help Kee at any cost for the survival of the species.', 'https://image.tmdb.org/t/p/w500/8Xgvmx7WWc7Z9Ws9RAYk7uya2kh.jpg', null, null),
  ('Daddy''s Home 2', 2017, false, 'PG-13', 'Sean Anders', '2017-11-10'::date, '100 min', 'Comedy', 'Sean Anders, John Morris, Brian Burns', 'Will Ferrell, Mark Wahlberg, Mel Gibson', 'After burying the hatchet in Daddy''s Home (2015), the stepfather with a heart of gold, Brad, and the kids'' biological dad with the perfect six-pack, Dusty, are now proud co-dads, working in unison to care for Megan and Dylan. This year, with Christmas just around the corner, the once-incompatible parents and their families decide to spend the holidays together; however, things will take a turn for the unexpected when Dusty''s alpha-dad, Kurt, and Brad''s touchy-feely father, Don, decide to pay a visit. Now--as the merry holidaymakers end up in a snow-capped cabin for a week--it seems that there''s no escape from an impending Yuletide disaster unless the two pairs of fathers learn how to coexist and work together for the sake of the kids. Will things work out in the end? Can the four daddies save Christmas?', 'https://image.tmdb.org/t/p/w500/rF2IoKL0IFmumEXQFUuB8LajTYP.jpg', null, null),
  ('Deadpool', 2016, true, 'R', 'Tim Miller', '2016-02-12'::date, '108 min', 'Action, Comedy', 'Rhett Reese, Paul Wernick', 'Ryan Reynolds, Morena Baccarin, T.J. Miller', 'This is the origin story of former Special Forces operative turned mercenary Wade Wilson, who after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.', 'https://image.tmdb.org/t/p/w500/3E53WEZJqP6aM84D8CckXx4pIHw.jpg', null, null),
  ('Close Encounters of the Third Kind', 1977, true, 'PG', 'Steven Spielberg', '1977-12-14'::date, '138 min', 'Drama, Sci-Fi', 'Steven Spielberg, Hal Barwood, Jerry Belson', 'Richard Dreyfuss, François Truffaut, Teri Garr', 'Two parallel stories are told. In the first, a group of research scientists from a variety of backgrounds are investigating the strange appearance of items in remote locations, primarily desert regions. In continuing their investigation, one of the lead scientists, a Frenchman named Claude Lacombe, incorporates the Kodály method of music education as a means of communication in their work. The response, in turn, at first baffles the researchers, until American cartographer David Laughlin deciphers the meaning of the response. In the second, electric company lineman and family man Roy Neary and single mother Jillian Guiler are among some individuals in Muncie, Indiana who experience some paranormal activity before some flashes of bright lights in the sky, which they believe to be a UFO. Roy becomes obsessed with what he saw, unlike some others, especially in some form of authority, who refuse to acknowledge their belief that it was a UFO in not wanting to appear crazy. That obsession both for Roy and Jillian is ratcheted up a notch when they begin to have a vision of a mound with vertical striations on its side as a key to what is going on. While the obsession negatively affects Roy''s life as he knows it in its entirety, Jillian knows she has to find the answer as to its meaning, especially as it relates to her only child, three year old Barry Guiler, who may be more attuned to what is happening than the adult figures around him. These two stories have the potential to intersect if Roy and Jillian can discover where they''ve seen that mound before, and if they can overcome what they believe to be the lies perpetrated by those in authority in covering up what is going on.', 'https://image.tmdb.org/t/p/w500/gCWPB8cF82tqzrS9tvzcO6q6nyz.jpg', null, null),
  ('Cloverfield', 2008, false, 'PG-13', 'Matt Reeves', '2008-01-18'::date, '85 min', 'Action, Horror, Sci-Fi', 'Drew Goddard', 'Mike Vogel, Jessica Lucas, Lizzy Caplan', 'To celebrate Rob''s massive promotion, his lover, Beth, and friends, decide to throw a massive surprise farewell party, now that he is about to move to Japan. However, a deafening explosion and the arrival of an enormous scaly and gangly creature will abruptly interrupt the festivities, as all hell breaks loose in New York City, and the Statue of Liberty is decapitated. As the reptilian behemoth levels Manhattan, a daring dash to rescue Beth begins, while at the same time, everything is recorded through the lens of a hand-held camcorder, amid mayhem and destruction. In the end, where did this relentless invader come from, and above all, is there a chance of survival? As they go to investigate, an adventure deep into the streets of New York begins, as the friends are determined to rescue Rob''s true love.', 'https://image.tmdb.org/t/p/w500/qIegUGJqyMMCRjkKV1s7A9MqdJ8.jpg', null, null),
  ('Coco', 2017, false, 'PG', 'Lee Unkrich, Adrian Molina', '2017-11-22'::date, '105 min', 'Animation, Adventure, Drama', 'Lee Unkrich, Jason Katz, Matthew Aldrich', 'Anthony Gonzalez, Gael García Bernal, Benjamin Bratt', 'Despite his family''s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.', 'https://image.tmdb.org/t/p/w500/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', null, null),
  ('Constantine', 2005, false, 'R', 'Francis Lawrence', '2005-02-18'::date, '121 min', 'Action, Fantasy, Horror', 'Jamie Delano, Garth Ennis, Kevin Brodbin', 'Keanu Reeves, Rachel Weisz, Djimon Hounsou', 'John Constantine is approached by Det. Angela Dodson who needs his help to prove that her twin sister Isabel''s death was not a suicide. The dead woman was a devout Catholic and Angela refuses to accept she would have taken her own life. She''s asked Constantine for help because he has a reputation for dealing with the mystical. In fact, he is a demon hunter whose sole purpose on Earth is to send demons back to the nether regions. John himself has been to Hell and knows that he is destined to return there on his death - but hopes his good deeds may find him a place in Heaven. As he looks into Isabel''s death, he realizes demons are trying to break through to the human world, and his battles lead him into a direct conflict with Satan.', 'https://image.tmdb.org/t/p/w500/vPYgvd2MwHlxTamAOjwVQp4qs1W.jpg', null, null),
  ('Contact', 1997, true, 'PG', 'Robert Zemeckis', '1997-07-11'::date, '150 min', 'Drama, Mystery, Sci-Fi', 'James V. Hart, Michael Goldenberg, Carl Sagan', 'Jodie Foster, Matthew McConaughey, Tom Skerritt', 'Astronomer Dr. Ellie Arroway has long been interested in contact to faraway lands, a love fostered in her childhood by her father, Ted Arroway (David Morse), who died when she was nine-years-old, leaving her orphaned. Her current work in monitoring for extraterrestrial life is based on that love and is in part an homage to her father. Ever since funding from the National Science Foundation (N.S.F.) was pulled on her work, which is referred to some, including her N.S.F. superior David Drumlin (Tom Skerritt), as more science fiction than science, Ellie, with a few of her rogue scientist colleagues, have looked for funding from where ever they could get it to continue their work. When Ellie and her colleagues hear chatter originating from the vicinity of the star Vega, Ellie feels vindicated. But that vindication is short lived when others, including politicians, the military, religious leaders, and other scientists, such as Drumlin, try to take over her work. When the messages received from space are decoded, the project takes on a whole new dimension, which strengthens for Ellie the quest for the truth. Thrown into the mix are the unknown person who has up until now funded most of Ellie''s work and what his motivations are, and Palmer Joss (Matthew McConaughey), a renowned author and theologian, who despite their fundamental differences in outlook, is mutually attracted to Ellie, that attraction based in part on intellect and their common goal of wanting to know the truth.', 'https://image.tmdb.org/t/p/w500/bCpMIywuNZeWt3i5UMLEIc0VSwM.jpg', null, null),
  ('Crank', 2006, false, 'R', 'Mark Neveldine, Brian Taylor', '2006-09-01'::date, '88 min', 'Action, Crime, Thriller', 'Mark Neveldine, Brian Taylor', 'Jason Statham, Amy Smart, Carlos Sanz', 'Poisoned by the potent and deadly mix of synthetic drugs called "The Beijing Cocktail" for getting in the way of the Triads, the tough-as-nails British hitman living in Los Angeles, Chev Chelios, wakes up with a terrible headache. With less than an hour to live, Chev will have to use all the help he can get from his doctor, and use every trick in the book, to consistently keep his heart rate up so that the adrenaline in his bloodstream staves off the effects of the deadly toxin. Now, his heart is pounding faster than any other human being, and as Chelios darts across the city''s streets in search of an antidote and the arrogant criminal, Ricky Verona, to exact his revenge, he finds himself compelled to pick fights with no-nonsense drug dealers, murderous assassins, and an army of thugs. But, can Chelios stay alive long enough to protect those he loves, and make it through the day?', 'https://image.tmdb.org/t/p/w500/rsKmhnvzJezjwC1Ud2Hh37oNpdQ.jpg', null, null),
  ('Daddy''s Home', 2015, false, 'PG-13', 'Sean Anders', '2015-12-25'::date, '96 min', 'Comedy, Family', 'Brian Burns, Sean Anders, John Morris', 'Will Ferrell, Mark Wahlberg, Linda Cardellini', 'Stepfather Brad Whitaker is hoping for his stepchildren to love him and treat him like a dad. All is going well until the biological father, Dusty Mayron, shows up, then everything takes a toll. His stepchildren start putting him second and their father first, and now Dusty will have to learn that being a good dad is about pains and struggles. Brad will also experience once again what it''s like to be a stepdad.', 'https://image.tmdb.org/t/p/w500/fB9lALk9zKsMYWvf0bJSkJN219Z.jpg', null, null),
  ('Deadpool 2', 2018, true, 'R', 'David Leitch', '2018-05-18'::date, '119 min', 'Action, Adventure, Comedy', 'Rhett Reese, Paul Wernick, Ryan Reynolds', 'Ryan Reynolds, Josh Brolin, Morena Baccarin', 'After losing Vanessa (Morena Baccarin), the love of his life, 4th-wall breaking mercenary Wade Wilson aka Deadpool (Ryan Reynolds) must assemble a team and protect a young, fat mutant Russell Collins aka Firefist (Julian Dennison) from Cable (Josh Brolin), a no-nonsense, dangerous cyborg from the future, and must also learn the most important lesson of all: to be part of a family again.', 'https://image.tmdb.org/t/p/w500/to0spRl1CMDvyUbOnbb4fTk3VAd.jpg', null, null),
  ('Deep Impact', 1998, false, 'PG-13', 'Mimi Leder', '1998-05-08'::date, '120 min', 'Action, Drama, Sci-Fi', 'Bruce Joel Rubin, Michael Tolkin', 'Robert Duvall, Téa Leoni, Elijah Wood', 'Journalist Jenny Lerner is assigned to look into the background of Secretary Alan Rittenhouse who abruptly resigned from government citing his wife''s ill health. She learns from his secretary that Rittenhouse was having an affair with someone named Ellie but when she confronts him, his strange reaction leads her to reconsider her story. In fact, a comet, discovered the previous year by high school student Leo Biederman and astronomer Dr. Marcus Wolf, is on a collision course with the Earth, an Extinction Level Event. A joint US-Russian team is sent to destroy the comet but should it fail, special measures are to be put in place to secure the future of mankind. As the space mission progresses, many individuals deal with their fears and ponder their future.', 'https://image.tmdb.org/t/p/w500/a3vQS7JKqlOb3MdVJHuTCP9s7Mg.jpg', null, null),
  ('District 9', 2009, true, 'R', 'Neill Blomkamp', '2009-08-14'::date, '112 min', 'Action, Sci-Fi, Thriller', 'Neill Blomkamp, Terri Tatchell', 'Sharlto Copley, David James, Jason Cope', 'In 1982, a massive star ship bearing a bedraggled alien population, nicknamed "The Prawns," appeared over Johannesburg, South Africa. Twenty-eight years later, the initial welcome by the human population has faded. The refugee camp where the aliens were located has deteriorated into a militarized ghetto called District 9, where they are confined and exploited in squalor. In 2010, the munitions corporation, Multi-National United, is contracted to forcibly evict the population with operative Wikus van der Merwe in charge. In this operation, Wikus is exposed to a strange alien chemical and must rely on the help of his only two new ''Prawn'' friends.', 'https://image.tmdb.org/t/p/w500/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg', null, null),
  ('Doctor Strange', 2016, true, 'PG-13', 'Scott Derrickson', '2016-11-04'::date, '115 min', 'Action, Adventure, Fantasy', 'Jon Spaihts, Scott Derrickson, C. Robert Cargill', 'Benedict Cumberbatch, Chiwetel Ejiofor, Rachel McAdams', 'Marvel''s "Doctor Strange" follows the story of the talented neurosurgeon Doctor Stephen Strange who, after a tragic car accident, must put ego aside and learn the secrets of a hidden world of mysticism and alternate dimensions. Based in New York City''s Greenwich Village, Doctor Strange must act as an intermediary between the real world and what lies beyond, utilising a vast array of metaphysical abilities and artifacts to protect the Marvel Cinematic Universe.', 'https://image.tmdb.org/t/p/w500/xf8PbyQcR5ucXErmZNzdKR0s8ya.jpg', null, null),
  ('Don Juan DeMarco', 1994, false, 'PG-13', 'Jeremy Leven', '1995-04-07'::date, '97 min', 'Comedy, Drama, Romance', 'Lord Byron, Jeremy Leven', 'Johnny Depp, Marlon Brando, Faye Dunaway', 'Well-respected psychiatrist Dr. Jack Mickler is only 10 days away from his retirement. A week before he is due to leave, he encounters a young man who attempts suicide--would be a pretty straightforward case except the young man claims to be Don Juan, the fabled Spanish nobleman and world renowned seducer/lover of woman. Despite original hostility from his co-workers, Jack manages to persuade his associates to put the youth in his care for 10 days after which the youth will undergo an evaluation to be either released from psychiatric care or sent to a mental institution. However, as the 10 days progresses, Dr. Mickler and the other staff become gradually drawn into to the young man''s exotic world of love, passion and pleasure as he recounts his story to them. Whilst doing so the man''s philosophies and zeal for life and love begins to revive Dr. Mickler''s somewhat passionless relationship with his wife, Marilyn as well as challenging his own views and ethics to the point where both he and the audience begin to question: could this young man truly be Don Juan?', 'https://image.tmdb.org/t/p/w500/fe0TuYz9jCKUba2Omj48K8bWJ8z.jpg', null, null),
  ('Double Jeopardy', 1999, false, 'R', 'Bruce Beresford', '1999-09-24'::date, '105 min', 'Crime, Drama, Mystery', 'David Weisberg, Douglas Cook', 'Ashley Judd, Tommy Lee Jones, Bruce Greenwood', 'When Nick Parsons appears to be murdered his wife Libby is tried and convicted. Six years later Libby is paroled and is pursued by Travis Lehman (her parole officer) as she sets out to find her son and settle the score with Nick.', 'https://image.tmdb.org/t/p/w500/dPd9QvEeMQpgHO6iLB1LqALTZl.jpg', null, null),
  ('The Cat in the Hat', 2003, false, 'PG', 'Bo Welch', '2003-11-21'::date, '82 min', 'Adventure, Comedy, Family', 'Dr. Seuss, Alec Berg, David Mandel', 'Mike Myers, Spencer Breslin, Dakota Fanning', 'Conrad and Sally Walden (Spencer Breslin and Dakota Fanning) are home alone with their pet fish. It is raining outside, and there is nothing to do. Until The Cat in the Hat (''Mike Myers'') walks in the front door. He introduces them to their imagination, and at first it''s all fun and games, until things get out of hand, and The Cat must go, go, go, before their mother gets back, but their pompous neighbor has bigger plans for them.', 'https://image.tmdb.org/t/p/w500/uYYLz67e5xEQMsY858VSSCDsLU6.jpg', null, null),
  ('Draft Day', 2014, true, 'PG-13', 'Ivan Reitman', '2014-04-11'::date, '110 min', 'Drama, Sport', 'Scott Rothman, Rajiv Joseph', 'Kevin Costner, Chadwick Boseman, Jennifer Garner', 'It''s draft day in the NFL, and as General Manager of the Cleveland Browns, Sonny is forced to come up with a big move. After trading for the number one pick, Sonny has to choose between a lower-ranked linebacker with a questionable past, or a celebrated quarterback with a questionable future. All the while, Sonny is walking in the footsteps of his father, and personal complications force their way to the surface.', 'https://image.tmdb.org/t/p/w500/bnl2ocjS1io4UCPhjoFuPKmJ9bf.jpg', null, null),
  ('Drive Angry', 2011, false, 'R', 'Patrick Lussier', '2011-02-25'::date, '104 min', 'Action, Comedy, Fantasy', 'Todd Farmer, Patrick Lussier', 'Nicolas Cage, Amber Heard, William Fichtner', 'John Milton is up against the clock: Jonah King, the leader of a Satanic cult, has murdered Milton''s daughter and kidnapped her baby. In three days, King and his followers will sacrifice the child at midnight. Milton picks up the trail in Oklahoma as well as rescuing a waitress named Piper from her brutal, two-timing fiancé. There are odd things about Milton: his driver''s license is out of date, he has a very strange gun, and he''s being pursued by a man in a suit who carries FBI ID and calls himself the Accountant. Piper, who''s lived a life on the sidelines, has to piece things together on the fly as they close in on King.', 'https://image.tmdb.org/t/p/w500/nx2pChi41Xv4dsXsfSG3gnKcWaY.jpg', null, null),
  ('Dune', 1984, true, 'PG-13', 'David Lynch', '1984-12-14'::date, '137 min', 'Action, Adventure, Sci-Fi', 'Frank Herbert, David Lynch', 'Kyle MacLachlan, Virginia Madsen, Francesca Annis', 'In the distant year of 10191, all the planets of the known Universe are under the control of Padishah Emperor Shaddam IV and the most important commodity in the Universe is a substance called the spice "MELANGE" which is said to have the power of extending life, expanding the consciousness and even to "fold space" ; being able to travel to any distance without physically moving. This spice "MELANGE" is said to only be produced in the desert planet of Arrakis, where the FREMEN people have the prophecy of a man who will lead them to true freedom. This "desert planet"of Arrakis is also known as DUNE. A secret report of the space "GUILD" talks about some circumstances and plans that could jeopardize the production of "SPICE" with four planets involved: ARRAKIS, CALADAN, GIEDI PRIME and KAITAIN, a world at least visually very alike to Earth and house of the Emperor of the known Universe. The "GUILD" sends a third stage navigator to KAITAIN to ask details from the Emperor and to demand him the killing of young Paul Atreides, son of the Duke Leto Atreides of CALADAN.', 'https://image.tmdb.org/t/p/w500/4kJmUCE7mkVJjXa7A0g2rY4IGTm.jpg', null, null),
  ('Edge of Darkness', 2010, false, 'R', 'Martin Campbell', '2010-01-29'::date, '117 min', 'Action, Adventure, Drama', 'William Monahan, Andrew Bovell, Troy Kennedy Martin', 'Mel Gibson, Ray Winstone, Danny Huston', 'Thomas Craven is a detective who has spent years working the streets of Boston. When his own daughter is killed outside his own home, Craven soon realizes that her death is only one piece of an intriguing puzzle filled with corruption and conspiracy, and it falls to him to discover who is behind the crime.', 'https://image.tmdb.org/t/p/w500/pvHjp1vEFmp5FquSCPQ2O95tIZJ.jpg', null, null),
  ('Ender''s Game', 2013, true, 'PG-13', 'Gavin Hood', '2013-11-01'::date, '114 min', 'Action, Adventure, Sci-Fi', 'Gavin Hood, Orson Scott Card', 'Harrison Ford, Asa Butterfield, Hailee Steinfeld', 'The Earth was ravaged by the Formics, an alien race seemingly determined to destroy humanity. Fifty years later, the people of Earth remain banded together to prevent their own annihilation from this technologically superior alien species. Ender Wiggin, a quiet but brilliant boy, may become the savior of the human race. He is separated from his beloved sister and his terrifying brother and brought to battle school in orbit around earth. He will be tested and honed into an empathetic killer who begins to despise what he does as he learns to fight in hopes of saving Earth and his family.', 'https://image.tmdb.org/t/p/w500/wgDlp3CT8SyLKJ52oFxrQONcw86.jpg', null, null),
  ('Eternal Sunshine of the Spotless Mind', 2004, false, 'R', 'Michel Gondry', '2004-03-19'::date, '108 min', 'Drama, Romance, Sci-Fi', 'Charlie Kaufman, Michel Gondry, Pierre Bismuth', 'Jim Carrey, Kate Winslet, Tom Wilkinson', 'Much to his surprise, timid Joel Barish is shocked to discover that the love of his life, sparky Clementine, has had him erased from her memory. To pay her back in the same coin, poor Joel summons up the courage to undergo a painless but intricate medical procedure to do the same, utterly unaware that darkness is an essential part of the light. Now, as hurt and angry Joel''s ugly recollections of Clementine gradually fade away, giving way to a soulless black void, suddenly, he begins having second thoughts, toying with the idea of stopping the irreversible process. In the end, is ignorance really bliss?', 'https://image.tmdb.org/t/p/w500/5MwkWH9tYHv3mV9OdYTMR5qreIz.jpg', null, null),
  ('Eurotrip', 2004, false, 'R', 'Jeff Schaffer, Alec Berg, David Mandel', '2004-02-20'::date, '92 min', 'Comedy', 'Alec Berg, David Mandel, Jeff Schaffer', 'Scott Mechlowicz, Jacob Pitts, Michelle Trachtenberg', 'Ohio high school student Scott Thomas is a good student and nice guy - albeit a little predictable - who is about to graduate and go into pre-med. He is unceremoniously dumped by his whorish girlfriend Fiona on graduation day. Among the people he turns to in his hour of despair is his German pen pal, Mike. Scott and Mike seem to have a special connection. After Mike makes advances to Scott now that he and Fiona are not seeing each other, Scott abruptly sends Mike a message saying he never wants to hear from him again. However, Scott learns shorty thereafter that Mike is actually a beautiful girl named Mieke. By this time, Mieke has blocked his messages. Thinking that Mieke is actually who he was meant to be with, Scott, impulsively for a change, decides to go to Berlin to be with her. Along for the ride is Scott''s best friend, the girl crazy Cooper Harris. They manage only to get a flight into London, and thus have to make their way from London to Berlin. Along the way in Paris, they run into their high school friends, twins Jenny and Jamie, who are backpacking through Europe. Scott and Cooper consider them the most mismatched twins ever, Jamie who is a walking encyclopedia, and Jenny a girl who they treat as just one of the guys. As the four try to make their way to Berlin, they run into a few obstacles and few adventures. Scott hopes that all these problems are worth it when he has his much hyped in his mind meeting with Mieke.', 'https://image.tmdb.org/t/p/w500/iLdO4PwbZCCQSa9rchZMwuJm9xe.jpg', null, null),
  ('Every Which Way But Loose', 1978, false, 'PG', 'James Fargo', '1978-12-20'::date, '114 min', 'Action, Comedy', 'Jeremy Joe Kronsberg', 'Clint Eastwood, Sondra Locke, Geoffrey Lewis', 'Philo Beddoe (Clint Eastwood) is an easy-going trucker and a great fist-fighter. With two friends, Orville (Geoffrey Lewis), who promotes prize-fights for him, and Clyde (Manis the Orangutan), the orangutan he won on a bet, he roams the San Fernando Valley in search of cold beer, country music, and the occasional punch-up. But he is floored by dainty little country and western singer, Lynn Halsey-Taylor (Sondra Locke), who gives him the slip when she realizes he''s getting too serious. Phil, Clyde, and Orville set off in pursuit, pestered by bikers.', 'https://image.tmdb.org/t/p/w500/vcSfAskDGCgInfJAXwLLORPQLAO.jpg', null, null),
  ('Ex Machina', 2014, true, 'R', 'Alex Garland', '2015-04-24'::date, '108 min', 'Drama, Sci-Fi, Thriller', 'Alex Garland', 'Alicia Vikander, Domhnall Gleeson, Oscar Isaac', 'Caleb, a 26 year old programmer at the world''s largest internet company, wins a competition to spend a week at a private mountain retreat belonging to Nathan, the reclusive CEO of the company. But when Caleb arrives at the remote location he finds that he will have to participate in a strange and fascinating experiment in which he must interact with the world''s first true artificial intelligence, housed in the body of a beautiful robot girl.', 'https://image.tmdb.org/t/p/w500/dmJW8IAKHKxFNiUnoDR7JfsK7Rp.jpg', null, 'Alex Garland'),
  ('Excision', 2012, false, 'Not Rated', 'Richard Bates Jr.', '2012-11-02'::date, '81 min', 'Comedy, Drama, Horror', 'Richard Bates Jr.', 'AnnaLynne McCord, Roger Bart, Ariel Winter', '18-year-old Pauline lives with her family, including younger sister Grace who has Cystic Fibrosis. Pauline has delusions of being a great surgeon, and she also has some horrific dreams that she actually finds "stimulating," to say the least. Her family puts up with her delusions, and her school classmates find her annoying. As this is all happening around her, she has a plan that will leave them all shocked--and some of them may not survive.', 'https://image.tmdb.org/t/p/w500/3aLgB6FTQlNanER0RpckbKdwyh9.jpg', null, null),
  ('Exorcist II: The Heretic', 1977, false, 'R', 'John Boorman, Rospo Pallenberg', '1977-06-17'::date, '117 min', 'Horror', 'William Goodhart, William Peter Blatty, Rospo Pallenberg', 'Richard Burton, Linda Blair, Louise Fletcher', 'Dr. Gene Tuskin works with troubled children, perhaps none more troubled than Regan MacNeil, who suffers from bad dreams and repressed memories. The memories she represses are of the time she was possessed by a demon. Dr. Tuskin''s invention, a device that hypnotizes two persons and links their minds together, reveals that the demon, named Pazuzu, still lurks within her. It is desperate to emerge again and wreak havoc. Meanwhile, Father Philip Lamont is ordered by his cardinal to investigate the death of Father Merrin, the priest who died while performing an exorcism on Regan. Father Lamont undertakes his task reluctantly. He feels unworthy of his assignment. He also feels that Evil is literally an entity and that this entity is winning the battle over Good. His investigation takes him to Africa where he locates another recipient of Merrin''s exorcising and learns something fascinating and terrible about locusts.', 'https://image.tmdb.org/t/p/w500/g9i3LTMYLRHvCYSKimZEfd1Vqy7.jpg', null, null),
  ('Exorcist: The Beginning', 2004, false, 'R', 'Renny Harlin', '2004-08-20'::date, '114 min', 'Horror, Mystery, Thriller', 'William Peter Blatty, William Wisher, Caleb Carr', 'Stellan Skarsgård, Izabella Scorupco, James D''Arcy', 'Archeologist Lankester Merrin is asked to go to East Africa to excavate a church that has been found completely buried in sand. Merrin is also an ordained Roman Catholic priest who, still haunted by what he was forced to do during World War II in his native Holland, eschews any religion or belief. He''s fascinated by what he finds and that it dates hundred of years before Christianity was introduced to the area. Accompanied by a young priest, Father Francis, to keep an eye on the religious elements of what they find, Merrin makes his way to the camp. There he meets a young doctor, Sarah and soon realizes there is an air of gloom that envelops the entire site. Workmen go mad and a young boy is mauled by a pack of hyenas while completely ignoring his younger brother Joseph. Inside the church itself they find signs of desecration. Merrin is forced to re-examine his lack of faith and come face to face with the devil.', 'https://image.tmdb.org/t/p/w500/4b7Mhc4HZN7XzMMLukaQ9C0x1Dx.jpg', null, null),
  ('Fantastic Beasts and Where to Find Them', 2016, true, 'PG-13', 'David Yates', '2016-11-18'::date, '132 min', 'Adventure, Family, Fantasy', 'J.K. Rowling', 'Eddie Redmayne, Katherine Waterston, Alison Sudol', 'In mid-1920s New York, Newt Scamander, a British young activist wizard, arrives in the city, holding a mysterious leather suitcase that shelters diverse and magical creatures that exist among us. Amid an already fragile equilibrium of secrecy, and the increasing disasters ascribed to the dark wizard, Gellert Grindelwald, Newt''s precious suitcase goes missing, and to make matters worse, several creatures manage to escape. Before long, this unforeseen complication catches Senior Auror Percival Graves'' attention who targets Newt, against the backdrop of an invisible, devastating, and utterly unpredictable menace that still wreaks havoc on 5th Avenue. In the end, is there a hidden agenda behind Graves'' intentions? Moreover, what will happen to the remaining fantastic beasts that are still on the loose?', 'https://image.tmdb.org/t/p/w500/fLsaFKExQt05yqjoAvKsmOMYvJR.jpg', 'Wizarding World', null),
  ('Faster', 2010, false, 'R', 'George Tillman Jr.', '2010-11-24'::date, '98 min', 'Action, Crime, Drama', 'Tony Gayton, Joe Gayton', 'Dwayne Johnson, Billy Bob Thornton, Maggie Grace', 'A lone man, recently released from prison, seeks out the people from his past who he believes betrayed him. While he forces each to atone for their sins, he must also face what meting out vengeance will do to his immortal soul. Meanwhile, he''s not the only one looking to settle old scores: hired by the man responsible for the events which led him to prison, an eccentric contract killer follows his every move. Scenes of them crossing paths, sometimes violently, are interspersed with the assassin''s self-realizations of how to deal with struggles within his own life. As if old enemies and hired guns aren''t enough, a young female detective begrudgingly works alongside a veteran investigator looking to simply survive his last two weeks on the force before retirement, as they seek out the brazen ex-con who has been blazing a path of gasoline-powered destruction in his vintage Chevelle.', 'https://image.tmdb.org/t/p/w500/AsUeaXrhw4oscCSjUZ6heh1pVvd.jpg', null, null),
  ('Fight Club', 1999, false, 'R', 'David Fincher', '1999-10-15'::date, '139 min', 'Drama', 'Chuck Palahniuk, Jim Uhls', 'Brad Pitt, Edward Norton, Meat Loaf', 'A nameless first person narrator (Edward Norton) attends support groups in attempt to subdue his emotional state and relieve his insomniac state. When he meets Marla (Helena Bonham Carter), another fake attendee of support groups, his life seems to become a little more bearable. However when he associates himself with Tyler (Brad Pitt) he is dragged into an underground fight club and soap making scheme. Together the two men spiral out of control and engage in competitive rivalry for love and power.', 'https://image.tmdb.org/t/p/w500/pB8BM7pdSp6B6Ih7QZ4DrQ3PmJK.jpg', null, null),
  ('Fool''s Gold', 2008, false, 'PG-13', 'Andy Tennant', '2008-02-08'::date, '112 min', 'Action, Adventure, Comedy', 'John Claflin, Daniel Zelman, Andy Tennant', 'Matthew McConaughey, Kate Hudson, Donald Sutherland', 'Benjamin Finnegan is a deep-sea treasure hunter certain he''s onto the find of the century in waters near an island close to Key West owned by a murderous rap star to whom Ben is in debt. Ben''s flat broke and recently divorced from Tess, his long-time research and diving partner whom he still loves. She''s nearby, working as a steward aboard the yacht of Nigel Honeycutt, a multimillionaire. The rapper has hired a rival treasurer hunter. Can Ben convince Nigel to bankroll his search, convince Tess to work with him, keep the rapper and his thugs at bay, and find a Spanish treasure hidden for centuries and rich beyond imagination?', 'https://image.tmdb.org/t/p/w500/f4djEBW3nyGRPLTcDlWYyaO43mx.jpg', null, null),
  ('Forrest Gump', 1994, false, 'PG-13', 'Robert Zemeckis', '1994-07-06'::date, '142 min', 'Drama, Romance', 'Winston Groom, Eric Roth', 'Tom Hanks, Robin Wright, Gary Sinise', 'Forrest Gump is a simple man with a low I.Q. but good intentions. He is running through childhood with his best and only friend Jenny. His ''mama'' teaches him the ways of life and leaves him to choose his destiny. Forrest joins the army for service in Vietnam, finding new friends called Dan and Bubba, he wins medals, creates a famous shrimp fishing fleet, inspires people to jog, starts a ping-pong craze, creates the smiley, writes bumper stickers and songs, donates to people and meets the president several times. However, this is all irrelevant to Forrest who can only think of his childhood sweetheart Jenny Curran, who has messed up her life. Although in the end all he wants to prove is that anyone can love anyone.', 'https://image.tmdb.org/t/p/w500/saHP97rTPS5eLmrLQEcANmKrsFl.jpg', null, null),
  ('Free Guy', 2021, false, 'PG-13', 'Shawn Levy', '2021-08-13'::date, '115 min', 'Action, Adventure, Comedy', 'Matt Lieberman, Zak Penn', 'Ryan Reynolds, Jodie Comer, Taika Waititi', 'In the extremely popular video game, Free City, a NPC named Guy learns the true nature of his existence when he meets the girl of his dreams, a human player. This player''s interactions with Guy has massive affects on him, the game, and real world as they play it.', 'https://image.tmdb.org/t/p/w500/6PFJrMvoQwBxQITLYHj09VeJ37q.jpg', null, null),
  ('Freeway', 1996, false, 'R', 'Matthew Bright', '1997-09-03'::date, '104 min', 'Crime, Drama, Thriller', 'Matthew Bright', 'Reese Witherspoon, Kiefer Sutherland, Bokeem Woodbine', 'Little Red Riding Hood for the 1990''s: After her mom and step-dad are arrested, 15-year-old Vanessa Lutz decides that instead of once again being put into a foster home, she''d rather go and search for the grandmother she''s never met, and live with her. "On the way to grandma''s house," (actually a trailer park) Vanessa''s car breaks down, and she''s picked up from the side of the road by Bob Wolverton, a counselor at a school for troubled boys. Bob slowly earns Vanessa''s trust, and eventually convinces her to talk about her sexual abuse at the hands of her stepfather. When Vanessa realizes that Bob is enjoying what she''s saying, she realizes that he''s "The I-5 Killer," from the news. She tries to get out of his truck, but the inside door handle has been removed...', 'https://image.tmdb.org/t/p/w500/m0pAARUq3foDWFsrUmlYDHtNPE9.jpg', null, null),
  ('Galaxy Quest', 1999, true, 'PG', 'Dean Parisot', '1999-12-25'::date, '102 min', 'Adventure, Comedy, Sci-Fi', 'David Howard, Robert Gordon', 'Tim Allen, Sigourney Weaver, Alan Rickman', 'The sci-fi television series "Galaxy Quest", which took place aboard the intergalactic spaceship NSEA Protector, starred Jason Nesmith as suave Commander Peter Quincy Taggart, Gwen DeMarco as sexy communications person Lt. Tawny Madison (a role which consisted solely of repeating what the computer stated, much to Gwen''s chagrin), Shakespearean trained Sir Alexander Dane as alien Dr. Lazarus, Fred Kwan as engineer Tech Sergeant Chen, and Tommy Webber as child pilot Laredo. Eighteen years after the series last aired, it lives on in the hearts of its rabid fans. However, it lives on in infamy for its stars, who have not been able to find meaningful acting work since. Their current lives revolve around cashing in on however those roles will afford, which usually entails attending fan conventions or worse, such as electronic store openings. Only Jason seems to relish his lot in life, until he finds out that his co-stars detest him because of his superior attitude as "the Commander", and much of the public considers him a laughing stock. Their lives change when Jason is approached by who he thinks are convention fans asking for help. They are in reality an alien race called Thermians, led by Mathesar, who have modeled their existence after the series, which they believe to be real. When Jason and then the rest of his co-stars (along with Guy Fleegman, who was killed off before the opening credits in only one episode) go along with the Thermians, Jason''s co-stars who believe they are off to yet another paying gig, they learn that they have to portray their roles for real. Without screenwriters to get them to a happy and heroic ending, they have to trust that their play acting will work, especially in dealing with the Thermians'' nemesis, General Sarris. Guy in particular fears that he will go the way his character did on the series. But when they run across technical issues that they as actors didn''t care anything about during the filming of the series and thus now don''t know how to deal with, they need to find someone who should know what to do.', 'https://image.tmdb.org/t/p/w500/fZXSwgZknp81vmciTb86rw0MejV.jpg', null, null),
  ('Game Night', 2018, false, 'R', 'John Francis Daley, Jonathan Goldstein', '2018-02-23'::date, '100 min', 'Action, Adventure, Comedy', 'Mark Perez', 'Jason Bateman, Rachel McAdams, Kyle Chandler', 'Married competitive gamer couple Max and Annie are trying to have a child, but their attempts are unsuccessful due to Max''s stress surrounding his feelings of inadequacy when compared to his successful, attractive brother Brooks. During Max and Annie''s routine weekend game night with their friends Ryan, and married couple Kevin and Michelle, Brooks shows up Max by arriving in a Corvette Stingray (Max''s dream car) and sharing an embarrassing childhood story about Max. Brooks offers to host the next game night at a house he''s renting while he''s in town. Meanwhile, Max and Annie are trying to keep their game nights secret from their neighbor Gary, an awkward police officer after his divorce from their friend Debbie..', 'https://image.tmdb.org/t/p/w500/85R8LMyn9f2Lev2YPBF8Nughrkv.jpg', null, null),
  ('Gangs of New York', 2002, false, 'R', 'Martin Scorsese', '2002-12-20'::date, '167 min', 'Crime, Drama', 'Jay Cocks, Steven Zaillian, Kenneth Lonergan', 'Leonardo DiCaprio, Cameron Diaz, Daniel Day-Lewis', 'In the god-forsaken district of early-1860s Lower Manhattan known as the Five Points, the vicious Nativist, Bill "The Butcher" Cutting, is the supreme overlord of an area riddled with crime, prostitution, theft and murder, as the American Civil War still rages on. Sixteen whole years after the brutal murder of his father from Bill''s blood-stained hands, an orphaned Irish-American, Amsterdam Vallon, returns to this melting pot of corruption to avenge his untimely death; however, a lot has changed since then. Who can remember the once-innocent boy and now a young man bent on revenge, who works his way up to the hierarchy of Five Points? Will Amsterdam ever taste the dangerous but sweet fruit of retribution?', 'https://image.tmdb.org/t/p/w500/lemqKtcCuAano5aqrzxYiKC8kkn.jpg', null, null),
  ('Ghost in the Shell', 2017, false, 'PG-13', 'Rupert Sanders', '2017-03-31'::date, '107 min', 'Action, Crime, Drama', 'Shirow Masamune, Jamie Moss, William Wheeler', 'Scarlett Johansson, Pilou Asbæk, Takeshi Kitano', 'In the near future, human organs are enhanced by the cybernetics technology developed by the powerful Hanka Robotics Corporation owned by Cutter. Dr. Ouelet is responsible for the development of the secret project 2571 of a full mechanical body to be connected to a human brain. She uses the brain of a young woman that lost her parents in a cyber attack as subject of a prototype. One year later, the woman is ranked Major and has joined Section 9, an anti-terrorist division commanded by Chief Daisuke Aramaki, working with agents Batou and Togusa. She needs to use a medicine to help the integration of her brain with the mechanical body and has no recollections of her previous life. When Section 9 hunts down the terrorist Kuze, Major learns the secrets about Hanka Robotics and the experiment she was subjected. Now she faces her ultimate enemy: Kuze, a criminal who has managed to hack into the brains of androids and control them.', 'https://image.tmdb.org/t/p/w500/9gC88zYUBARRSThcG93MvW14sqx.jpg', null, null),
  ('Ghost in the Shell', 1995, false, 'TV-MA', 'Mizuho Nishikubo, Mamoru Oshii', '1996-03-29'::date, '83 min', 'Animation, Action, Crime', 'Shirow Masamune, Kazunori Itô', 'Atsuko Tanaka, Iemasa Kayumi, Akio Ôtsuka', 'It is the year 2029. Technology has advanced so far that cyborgs are commonplace. In addition, human brains can connect to the internet directly. Major Motoko Kusanagi is an officer in Section 9, an elite, secretive police division that deals with special operations, including counter terrorism and cyber crime. She is currently on the trail of the Puppet Master, a cyber criminal who hacks into the brains of cyborgs in order to obtain information and to commit other crimes.', 'https://image.tmdb.org/t/p/w500/9gC88zYUBARRSThcG93MvW14sqx.jpg', null, null),
  ('Ghost Ship', 2002, false, 'R', 'Steve Beck', '2002-10-25'::date, '91 min', 'Horror, Mystery, Thriller', 'Mark Hanlon, John Pogue', 'Julianna Margulies, Gabriel Byrne, Ron Eldard', 'After discovering a passenger ship missing since 1962 floating adrift on the Bering Sea, salvagers claim the vessel as their own. Once they begin towing the ghost ship towards harbor, a series of bizarre ocurrences happen and the group becomes trapped inside the ship, which they soon learn is inhabited by a demonic creature.', 'https://image.tmdb.org/t/p/w500/kIlzZJqV4SCGHrrjoGLBhmsO7z2.jpg', null, null),
  ('Ghosts of Mars', 2001, false, 'R', 'John Carpenter', '2001-08-24'::date, '98 min', 'Action, Horror, Sci-Fi', 'Larry Sulkis, John Carpenter', 'Natasha Henstridge, Ice Cube, Pam Grier', '200 years in the future a Martian police unit is dispatched to transport a dangerous prisoner from a mining outpost back to justice. But when the team arrives they find the town deserted and some of the inhabitants possessed by the former inhabitants of the planet.', 'https://image.tmdb.org/t/p/w500/i2zztssCIbahGES1fdfWFmDXian.jpg', null, null),
  ('Gods of Egypt', 2016, false, 'PG-13', 'Alex Proyas', '2016-02-26'::date, '127 min', 'Action, Adventure, Drama', 'Matt Sazama, Burk Sharpless', 'Brenton Thwaites, Nikolaj Coster-Waldau, Gerard Butler', 'Set, the merciless god of darkness, has taken over the throne of Egypt and plunged the once peaceful and prosperous empire into chaos and conflict. Few dare to rebel against him. A young thief, whose love was taken captive by the god, seeks to dethrone and defeat Set with the aid of the powerful god Horus.', 'https://image.tmdb.org/t/p/w500/hzH7fwaTyQNITLo40Hu3R7cVMqv.jpg', null, null),
  ('Godzilla', 2014, false, 'PG-13', 'Gareth Edwards', '2014-05-16'::date, '123 min', 'Action, Adventure, Sci-Fi', 'Dave Callaham, Max Borenstein', 'Aaron Taylor-Johnson, Elizabeth Olsen, Bryan Cranston', 'In 1999, the Janjira nuclear plant was mysteriously destroyed with most hands lost including supervisor Joe Brody''s colleague and wife, Sandra. Years later, Joe''s son, Ford, a US Navy ordnance disposal officer, must go to Japan to help his estranged father who obsessively searches for the truth of the incident. In doing so, father and son discover the disaster''s secret cause on the wreck''s very grounds. This enables them to witness the reawakening of a terrible threat to all of Humanity, which is made all the worse with a second secret revival elsewhere. Against this cataclysm, the only hope for the world may be Godzilla, but the challenge for the King of the Monsters will be great even as Humanity struggles to understand the destructive ally they have.', 'https://image.tmdb.org/t/p/w500/zokD6uxR2iWfYM3Y84yGJvnNTK7.jpg', null, null),
  ('Gone Girl', 2014, false, 'R', 'David Fincher', '2014-10-03'::date, '149 min', 'Drama, Mystery, Thriller', 'Gillian Flynn', 'Ben Affleck, Rosamund Pike, Neil Patrick Harris', 'On the occasion of his fifth wedding anniversary, Nick Dunne reports that his wife, Amy, has gone missing. Under pressure from the police and a growing media frenzy, Nick''s portrait of a blissful union begins to crumble. Soon his lies, deceits and strange behavior have everyone asking the same dark question: Did Nick Dunne kill his wife?', 'https://image.tmdb.org/t/p/w500/ts996lKsxvjkO2yiYG0ht4qAicO.jpg', null, null),
  ('Goodfellas', 1990, false, 'R', 'Martin Scorsese', '1990-09-21'::date, '145 min', 'Biography, Crime, Drama', 'Nicholas Pileggi, Martin Scorsese', 'Robert De Niro, Ray Liotta, Joe Pesci', 'Henry Hill might be a small time gangster, who may have taken part in a robbery with Jimmy Conway and Tommy De Vito, two other gangsters who might have set their sights a bit higher. His two partners could kill off everyone else involved in the robbery, and slowly start to think about climbing up through the hierarchy of the Mob. Henry, however, might be badly affected by his partners'' success, but will he consider stooping low enough to bring about the downfall of Jimmy and Tommy?', 'https://image.tmdb.org/t/p/w500/aKuFiU82s5ISJpGZp7YkIr3kCUd.jpg', null, null),
  ('Gran Torino', 2008, false, 'R', 'Clint Eastwood', '2009-01-09'::date, '116 min', 'Drama', 'Nick Schenk, Dave Johannson', 'Clint Eastwood, Bee Vang, Christopher Carley', 'Walt Kowalski (Clint Eastwood) is a widower who holds onto his prejudices despite the changes in his Michigan neighborhood and the world around him. Kowalski is a grumpy, tough-minded, unhappy old man who can''t get along with either his kids or his neighbors. He is a Korean War veteran whose prize possession is a 1972 Gran Torino he keeps in mint condition. When his neighbor Thao Lor (Bee Vang), a young Hmong teenager under pressure from his gang member cousin, tries to steal his Gran Torino, Kowalski sets out to reform the youth. Drawn against his will into the life of Thao''s family, Kowalski is soon taking steps to protect them from the gangs that infest their neighborhood.', 'https://image.tmdb.org/t/p/w500/zUybYvxWdAJy5hhYovsXtHSWI1l.jpg', null, null),
  ('Grave of the Fireflies', 1988, false, 'Not Rated', 'Isao Takahata', '1989-07-26'::date, '88 min', 'Animation, Drama, War', 'Akiyuki Nosaka, Isao Takahata', 'Tsutomu Tatsumi, Ayano Shiraishi, Akemi Yamaguchi', 'The story of Seita and Setsuko, two young Japanese siblings, living in the declining days of World War II. When an American firebombing separates the two children from their parents, the two siblings must rely completely on one another while they struggle to fight for their survival.', 'https://image.tmdb.org/t/p/w500/k9tv1rXZbOhH7eiCk378x61kNQ1.jpg', null, null),
  ('Grease', 1978, false, 'PG', 'Randal Kleiser', '1978-06-16'::date, '110 min', 'Comedy, Musical, Romance', 'Jim Jacobs, Warren Casey, Bronte Woodard', 'John Travolta, Olivia Newton-John, Stockard Channing', 'A musical about teens in love in the 1950s. It''s California 1958 and greaser Danny Zuko (John Travolta) and Australian Sandy Olsson (Olivia Newton-John) are in love. They spend time at the beach, and when they go back to school, what neither of them knows is that they both now attend Rydell High. Danny''s the leader of the T-Birds, a group of black leather jacket-wearing greasers while Sandy hangs with the Pink Ladies, a group of pink-wearing girls led by Rizzo (Stockard Channing). When they clash at Rydell''s first pep rally, Danny isn''t the same Danny from the beach. They try to be like each other so they can be together.', 'https://image.tmdb.org/t/p/w500/hPBIursfYm5ziEmNPrJXkKIDrdI.jpg', null, null),
  ('The Mummy', 2017, true, 'PG-13', 'Alex Kurtzman', '2017-06-09'::date, '110 min', 'Action, Adventure, Fantasy', 'David Koepp, Christopher McQuarrie, Dylan Kussman', 'Tom Cruise, Sofia Boutella, Annabelle Wallis', 'Though safely entombed in a crypt deep beneath the unforgiving desert, an ancient princess, whose destiny was unjustly taken from her, is awakened in our current day bringing with her malevolence grown over millennia, and terrors that defy human comprehension.', 'https://image.tmdb.org/t/p/w500/zxkY8byBnCsXodEYpK8tmwEGXBI.jpg', null, null),
  ('Green Lantern', 2011, false, 'PG-13', 'Martin Campbell', '2011-06-17'::date, '114 min', 'Action, Adventure, Sci-Fi', 'Greg Berlanti, Michael Green, Marc Guggenheim', 'Ryan Reynolds, Blake Lively, Peter Sarsgaard', 'In a mysterious universe, the Green Lantern Corps, an elite defense force of peace and justice have existed for centuries. Reckless test pilot Hal Jordan acquires superhuman powers when he is chosen by the Ring, the willpower-fed source of power. Reluctantly at first, he takes on the challenge after the death of Abin Sur, the finest Green Lantern. Putting his self-doubts aside, and spurred on by his sense of duty and love for his beautiful, intellectually equal, colleague, Carol Ferris, he is soon called to defend mankind from Parallax, a powerful, evil being who feeds on fear. Hal Jordan is the universe''s last chance, as many Green Lanterns have been killed and the Corps is weakened, and he might just be the right Green Lantern for the duty of keeping the world safe from harm.', 'https://image.tmdb.org/t/p/w500/fj21HwUprqjjwTdkKC1XZurRSpV.jpg', null, null),
  ('Guardians of the Galaxy', 2014, true, 'PG-13', 'James Gunn', '2014-08-01'::date, '121 min', 'Action, Adventure, Comedy', 'James Gunn, Nicole Perlman, Dan Abnett', 'Chris Pratt, Vin Diesel, Bradley Cooper', 'After stealing a mysterious orb in the far reaches of outer space, Peter Quill from Earth is now the main target of a manhunt led by the villain known as Ronan the Accuser. To help fight Ronan and his team and save the galaxy from his power, Quill creates a team of space heroes known as the "Guardians of the Galaxy" to save the galaxy.', 'https://image.tmdb.org/t/p/w500/r7vmZjiyZw9rpJMQJdXpjgiCOk9.jpg', null, null),
  ('Guardians of the Galaxy Vol. 2', 2017, true, 'PG-13', 'James Gunn', '2017-05-05'::date, '136 min', 'Action, Adventure, Comedy', 'James Gunn, Dan Abnett, Andy Lanning', 'Chris Pratt, Zoe Saldana, Dave Bautista', 'After saving Xandar from Ronan''s wrath, the Guardians are now recognized as heroes. Now the team must help their leader Star Lord (Chris Pratt) uncover the truth behind his true heritage. Along the way, old foes turn to allies and betrayal is blooming. And the Guardians find that they are up against a devastating new menace who is out to rule the galaxy.', 'https://image.tmdb.org/t/p/w500/y4MBh0EjBlMuOzv9axM4qJlmhzz.jpg', null, null),
  ('Hancock', 2008, false, 'R', 'Peter Berg', '2008-07-02'::date, '92 min', 'Action, Comedy, Drama', 'Vy Vincent Ngo, Vince Gilligan', 'Will Smith, Charlize Theron, Jason Bateman', 'The powerful superhero John Hancock has become a joke because of his alcoholism and clumsiness. He has also become the most hated man in Los Angeles. Though he has saved many lives, he also destroyed a lot of property, costing the city millions every time he goes into action. When he saves the life of PR expert Ray Embrey from an oncoming train, the executive is thankful and believes he can restore Hancock''s image as a true superhero. He brings the anti-hero home for dinner and introduces him to his son Aaron, a big fan, and to his wife, Mary. But for some mysterious reason Mary doesn''t want Hancock anywhere near her or her family.', 'https://image.tmdb.org/t/p/w500/7DyuV2G0hLEqHeueDfOqhZ2DVut.jpg', null, null),
  ('Hanna', 2011, false, 'PG-13', 'Joe Wright', '2011-04-08'::date, '111 min', 'Action, Adventure, Drama', 'Seth Lochhead, David Farr', 'Saoirse Ronan, Cate Blanchett, Eric Bana', 'Hanna (Saoirse Ronan) is a teenage girl. Uniquely, she has the strength, the stamina, and the skills of a soldier. These come from being raised by her father, Erik Heller (Eric Bana), an ex-C.I.A. man, in the wilds of Finland. Living a life unlike any other teenager, her upbringing and training have been one and the same, all geared to making her the perfect assassin. The turning point in her adolescence is a sharp one; sent into the world by her father on a mission, Hanna journeys stealthily across Europe while eluding agents dispatched after her by ruthless intelligence operative, Marissa Wiegler (Cate Blanchett), who has secrets of her own. As she nears her ultimate target, Hanna faces startling revelations about her existence and unexpected questions about her humanity.', 'https://image.tmdb.org/t/p/w500/gRvxRMtejJa9jjfDDUibUIfIJbP.jpg', null, null),
  ('Harry Potter and the Chamber of Secrets', 2002, true, 'PG', 'Chris Columbus', '2002-11-15'::date, '161 min', 'Adventure, Family, Fantasy', 'J.K. Rowling, Steve Kloves', 'Daniel Radcliffe, Rupert Grint, Emma Watson', 'Forced to spend his summer holidays with his muggle relations, Harry Potter (Daniel Radcliffe) gets a real shock when he gets a surprise visitor: Dobby (Toby Jones) the house-elf, who warns Harry against returning to Hogwarts, for terrible things are going to happen. Harry decides to ignore Dobby''s warning and continues with his pre-arranged schedule. But at Hogwarts, strange and terrible things are indeed happening. Harry is suddenly hearing mysterious voices from inside the walls, muggle-born students are being attacked, and a message scrawled on the wall in blood puts everyone on his or her guard, "The Chamber Of Secrets Has Been Opened. Enemies Of The Heir, Beware".', 'https://image.tmdb.org/t/p/w500/sdEOH0992YZ0QSxgXNIGLq1ToUi.jpg', 'Wizarding World', null),
  ('Harry Potter and the Deathly Hallows: Part 1', 2010, true, 'PG-13', 'David Yates', '2010-11-19'::date, '146 min', 'Adventure, Family, Fantasy', 'Steve Kloves, J.K. Rowling', 'Daniel Radcliffe, Emma Watson, Rupert Grint', 'Voldemort''s (Ralph Fiennes'') power is growing stronger. He now has control over the Ministry of Magic and Hogwarts. Harry (Daniel Radcliffe), Ron (Rupert Grint), and Hermione (Emma Watson) decide to finish Dumbledore''s (Sir Michael Gambon''s) work and find the rest of the Horcruxes to defeat the Dark Lord. But little hope remains for the trio and the rest of the Wizarding World, so everything they do must go as planned.', 'https://image.tmdb.org/t/p/w500/iGoXIpQb7Pot00EEdwpwPajheZ5.jpg', 'Wizarding World', null),
  ('Harry Potter and the Deathly Hallows: Part 2', 2011, true, 'PG-13', 'David Yates', '2011-07-15'::date, '130 min', 'Adventure, Family, Fantasy', 'Steve Kloves, J.K. Rowling', 'Daniel Radcliffe, Emma Watson, Rupert Grint', 'Harry (Daniel Radcliffe), Ron (Rupert Grint), and Hermione (Emma Watson) continue their quest of finding and destroying Voldemort''s (Ralph Fiennes'') three remaining Horcruxes, the magical items responsible for his immortality. But as the mystical Deathly Hallows are uncovered, and Voldemort finds out about their mission, the biggest battle begins, and life as they know it will never be the same again.', 'https://image.tmdb.org/t/p/w500/c54HpQmuwXjHq2C9wmoACjxoom3.jpg', 'Wizarding World', null),
  ('Harry Potter and the Goblet of Fire', 2005, true, 'PG-13', 'Mike Newell', '2005-11-18'::date, '157 min', 'Adventure, Family, Fantasy', 'Steve Kloves, J.K. Rowling', 'Daniel Radcliffe, Emma Watson, Rupert Grint', 'Harry''s (Daniel Radcliffe''s) fourth year at Hogwarts is about to start and he is enjoying the summer vacation with his friends. They get the tickets to The Quidditch World Cup Final, but after the match is over, people dressed like Lord Voldemort''s (Ralph Fiennes'') "Death Eaters" set a fire to all of the visitors'' tents, coupled with the appearance of Voldemort''s symbol, the "Dark Mark" in the sky, which causes a frenzy across the magical community. That same year, Hogwarts is hosting "The Triwizard Tournament", a magical tournament between three well-known schools of magic : Hogwarts, Beauxbatons, and Durmstrang. The contestants have to be above the age of seventeen, and are chosen by a magical object called "The Goblet of Fire". On the night of selection, however, the Goblet spews out four names instead of the usual three, with Harry unwittingly being selected as the Fourth Champion. Since the magic cannot be reversed, Harry is forced to go with it and brave three exceedingly difficult tasks.', 'https://image.tmdb.org/t/p/w500/fECBtHlr0RB3foNHDiCBXeg9Bv9.jpg', 'Wizarding World', null),
  ('Harry Potter and the Half-Blood Prince', 2009, true, 'PG', 'David Yates', '2009-07-15'::date, '153 min', 'Action, Adventure, Family', 'Steve Kloves, J.K. Rowling', 'Daniel Radcliffe, Emma Watson, Rupert Grint', 'During Harry Potter''s sixth year at Hogwarts, he finds a book that once belonged to the mysterious Half-Blood Prince that earns him the respect of his new Potions professor Horace Slughorn. In addition, Dumbledore must prepare Harry for the ultimate final confrontation by finding out the secret behind Voldemort''s power. Meanwhile, a hidden enemy waits in the shadows to carry out a mission given to him by the Dark Lord.', 'https://image.tmdb.org/t/p/w500/z7uo9zmQdQwU5ZJHFpv2Upl30i1.jpg', 'Wizarding World', null),
  ('Harry Potter and the Order of the Phoenix', 2007, true, 'PG-13', 'David Yates', '2007-07-11'::date, '138 min', 'Action, Adventure, Family', 'Michael Goldenberg, J.K. Rowling', 'Daniel Radcliffe, Emma Watson, Rupert Grint', 'After a lonely summer on Privet Drive, Harry (Daniel Radcliffe) returns to a Hogwarts full of ill-fortune. Few of students and parents believe him or Dumbledore (Sir Michael Gambon) that Voldemort (Ralph Fiennes) is really back. The ministry had decided to step in by appointing a new Defense Against the Dark Arts teacher, Professor Dolores Umbridge (Imelda Staunton), who proves to be the nastiest person Harry has ever encountered. Harry also can''t help stealing glances with the beautiful Cho Chang (Katie Leung). To top it off are dreams that Harry can''t explain, and a mystery behind something for which Voldemort is searching. With these many things, Harry begins one of his toughest years at Hogwarts School of Witchcraft and Wizardry.', 'https://image.tmdb.org/t/p/w500/5aOyriWkPec0zUDxmHFP9qMmBaj.jpg', 'Wizarding World', null),
  ('Harry Potter and the Prisoner of Azkaban', 2004, true, 'PG', 'Alfonso Cuarón', '2004-06-04'::date, '142 min', 'Adventure, Family, Fantasy', 'J.K. Rowling, Steve Kloves', 'Daniel Radcliffe, Emma Watson, Rupert Grint', 'Harry Potter (Daniel Radcliffe) is having a tough time with his relatives (yet again). He runs away after using magic to inflate Uncle Vernon''s (Richard Griffiths'') sister Marge (Pam Ferris), who was being offensive towards Harry''s parents. Initially scared for using magic outside the school, he is pleasantly surprised that he won''t be penalized after all. However, he soon learns that a dangerous criminal and Voldemort''s trusted aide Sirius Black (Gary Oldman) has escaped from Azkaban Prison and wants to kill Harry to avenge the Dark Lord. To worsen the conditions for Harry, vile creatures called Dementors are appointed to guard the school gates and inexplicably happen to have the most horrible effect on him. Little does Harry know that by the end of this year, many holes in his past (whatever he knows of it) will be filled up and he will have a clearer vision of what the future has in store.', 'https://image.tmdb.org/t/p/w500/aWxwnYoe8p2d2fcxOqtvAtJ72Rw.jpg', 'Wizarding World', null),
  ('Harry Potter and the Sorcerer''s Stone', 2001, true, 'PG', 'Chris Columbus', '2001-11-16'::date, '152 min', 'Adventure, Family, Fantasy', 'J.K. Rowling, Steve Kloves', 'Daniel Radcliffe, Rupert Grint, Emma Watson', 'This is the tale of Harry Potter (Daniel Radcliffe), an ordinary eleven-year-old boy serving as a sort of slave for his aunt and uncle who learns that he is actually a wizard and has been invited to attend the Hogwarts School for Witchcraft and Wizardry. Harry is snatched away from his mundane existence by Rubeus Hagrid (Robbie Coltrane), the groundskeeper for Hogwarts, and quickly thrown into a world completely foreign to both him and the viewer. Famous for an incident that happened at his birth, Harry makes friends easily at his new school. He soon finds, however, that the wizarding world is far more dangerous for him than he would have imagined, and he quickly learns that not all wizards are ones to be trusted.', 'https://image.tmdb.org/t/p/w500/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', 'Wizarding World', null),
  ('Heat', 1995, false, 'R', 'Michael Mann', '1995-12-15'::date, '170 min', 'Action, Crime, Drama', 'Michael Mann', 'Al Pacino, Robert De Niro, Val Kilmer', 'Hunters and their prey--Neil and his professional criminal crew hunt to score big money targets (banks, vaults, armored cars) and are, in turn, hunted by Lt. Vincent Hanna and his team of cops in the Robbery/Homicide police division. A botched job puts Hanna onto their trail while they regroup and try to put together one last big ''retirement'' score. Neil and Vincent are similar in many ways, including their troubled personal lives. At a crucial moment in his life, Neil disobeys the dictum taught to him long ago by his criminal mentor--''Never have anything in your life that you can''t walk out on in thirty seconds flat, if you spot the heat coming around the corner''--as he falls in love. Thus the stage is set for the suspenseful ending....', 'https://image.tmdb.org/t/p/w500/umSVjVdbVwtx5ryCA2QXL44Durm.jpg', null, null),
  ('Hellboy', 2004, false, 'PG-13', 'Guillermo del Toro', '2004-04-02'::date, '122 min', 'Action, Adventure, Fantasy', 'Guillermo del Toro, Peter Briggs, Mike Mignola', 'Ron Perlman, Doug Jones, Selma Blair', 'At the end of World War II, Nazi officers Karl Ruprecht Kroenen and Ilsa Haupstein start an experiment to raise the forces of Hell trough Russian dark mystic Rasputin on a Scottish island, but it''s interrupted by an allied commando guided by professor Trevor "Broom" Bruttenholm. He prevents killing the human-demonic half-blood, which was accidentally created and raises this "Hellboy", while rising to head of a secret C.I.A.-linked U.S. agency Bureau of Paranormal Research, which secretly studies and uses the occult, including supernatural freaks. As "father" Broom is aging, he hand-picks brilliant, sensitive Agent John Myers as new minder-companion, as regular "warrior" Agent Clay can''t empathize and lacks flexibility mental. Hellboy is quite a handful, regularly spotted by worried civilians on unauthorized excursions, especially to pyro-telekinetic freak friend in a mental asylum. Johnny, Hellboy, and Clay team up on missions against paranormal threats with aquatic-bionic freak Abe Sapien. Their task proves to be daunting, as monster Sammael multiplies every time it "dies", while Rasputin and the Nazis reemerge, armed for revenge.', 'https://image.tmdb.org/t/p/w500/lbaTEneOofwvAyg77R8HbFML2zT.jpg', null, null),
  ('Hercules', 1997, false, 'G', 'Ron Clements, John Musker', '1997-06-27'::date, '93 min', 'Animation, Action, Adventure', 'Ron Clements, John Musker, Don McEnery', 'Tate Donovan, Susan Egan, James Woods', 'Hercules, son of the Greek God, Zeus, is turned into a half-god, half-mortal by evil Hades, God of the Underworld, who plans to overthrow Zeus. Hercules is raised on Earth and retains his god-like strength, but when he discovers his immortal heritage Zeus tells him that to return to Mount Olympus he must become a true hero. Hercules becomes a famous hero with the help of his friend Pegasus and his personal trainer, Phil the satyr. Hercules battles monsters, Hades and the Titans, but it is his self-sacrifice to rescue his love Meg which makes him a true hero.', 'https://image.tmdb.org/t/p/w500/dK9rNoC97tgX3xXg5zdxFisdfcp.jpg', null, null),
  ('High School Musical 3: Senior Year', 2008, false, 'G', 'Kenny Ortega', '2008-10-24'::date, '112 min', 'Comedy, Drama, Family', 'Peter Barsocchini', 'Zac Efron, Vanessa Hudgens, Ashley Tisdale', 'Troy and the gang of East High School are going through their senior year, facing graduating and going their separate ways. Coming to terms with the reality of it all, Troy wants to attend the nearby University of Albuquerque next year on a basketball scholarship, but Gabriella wants to attend Stanford University in California. Meanwhile, Sharpay, the school''s shallow and spoiled rich girl, plots to go all out planning the school''s final musical show with the idea to add music to her hopes and fears about the future. While Sharpay takes an up-and-coming British exchange student under her wing, her flamboyant fraternal twin brother, Ryan, has his sights set on something different after school. In addition, Troy''s best friend and basketball teammate Chad, and Garbiella''s best friend Taylor, all have their sights set on their plans after high school and come to terms with the reality of the real world.', 'https://image.tmdb.org/t/p/w500/aq2o1wT0crBOTxof36O6KTyjpgE.jpg', null, null),
  ('Insidious: Chapter 2', 2013, false, 'PG-13', 'James Wan', '2013-09-13'::date, '106 min', 'Horror, Mystery, Thriller', 'Leigh Whannell, James Wan', 'Patrick Wilson, Rose Byrne, Barbara Hershey', 'Renai is interrogated by a police detective about the supernatural events in the house. While the police investigate the house, the Lambert family temporarily moves to the old house of Lorraine Lambert. Renai is haunted by a woman in white and Josh has a strange behavior at home. Meanwhile Lorraine seeks out Elise''s partners Specs and Tucker expecting to find answers.', 'https://image.tmdb.org/t/p/w500/w5JjiB3O1CLDXbTJe1QpU5RHmlU.jpg', null, null),
  ('The Northman', 2022, true, 'R', 'Robert Eggers', '2022-04-22'::date, '137 min', 'Action, Adventure, Drama', 'Sjón, Robert Eggers', 'Alexander Skarsgård, Nicole Kidman, Claes Bang', 'A young Viking prince is on a quest to avenge his father''s murder.', 'https://image.tmdb.org/t/p/w500/aSSJMnHknzKjlZ6zybwD7eyJ4Po.jpg', null, null),
  ('Highlander', 1986, false, 'R', 'Russell Mulcahy', '1986-03-07'::date, '116 min', 'Action, Adventure, Fantasy', 'Gregory Widen, Peter Bellwood, Larry Ferguson', 'Christopher Lambert, Sean Connery, Clancy Brown', 'In New York City, the owner of a sophisticated antique shop Russell Edwin Nash is challenged to a sword fight in the parking lot of the Madison Square Garden by a man called Iman Fasil that is beheaded by Russell. He hides his sword and is arrested by the police while leaving the stadium. Russell recalls his life in the sixteenth century in Scotland, when he is Connor MacLeod, and is fatally wounded in a battle against another Clan. However, he surprisingly survives and his Clan believes he has a pact with the devil and expels him from their lands. Then he meets Juan Sanchez Villa-Lobos Ramirez, who explains that he is immortal unless he is beheaded. Further, the immortals dispute a game killing each other and in the end only one survives receiving a prize with the power of the other immortals. Russell is released by the police, but the snoopy forensic agent Brenda J. Wyatt is attracted by the case since she found fragments of an ancient Katana and follows Russell. But the also immortal Kurgan is hunting down MacLeod, and Brenda is in the middle of their battle.', 'https://image.tmdb.org/t/p/w500/8Z8dptJEypuLoOQro1WugD855YE.jpg', null, null),
  ('Hot Fuzz', 2007, false, 'R', 'Edgar Wright', '2007-04-20'::date, '121 min', 'Action, Comedy, Mystery', 'Edgar Wright, Simon Pegg', 'Simon Pegg, Nick Frost, Martin Freeman', 'Top London cop PC Nicholas Angel is good. Too good. To stop the rest of his team looking bad, he is reassigned to the quiet town of Sandford. He is paired with Danny Butterman, who endlessly questions him on the action lifestyle. Everything seems quiet for Angel until two actors are found decapitated. It is called an accident, but Angel won''t accept that, especially when more and more people turn up dead. Angel and Danny clash with everyone while they try to uncover the truth behind the mystery of the apparent "accidents".', 'https://image.tmdb.org/t/p/w500/4Br5qhGrfIxlJmlnR2qfCRYioqq.jpg', null, null),
  ('House on Haunted Hill', 1999, true, 'R', 'William Malone', '1999-10-29'::date, '93 min', 'Horror, Mystery, Thriller', 'Robb White, Dick Beebe', 'Geoffrey Rush, Famke Janssen, Taye Diggs', 'When an eccentric millionaire offer a group of opposites $1,000,000 to spend the night in a so called "Haunted House" with a murderous past, they figure it is a quick way to get quick money and leave. All of them are sure it is some made up story just to mess with their heads a little and test their courage. But, once they stay in the house they start to think about the mistake they made in coming there when mysterious things start to happen.', 'https://image.tmdb.org/t/p/w500/weiGTsZqBglKxkIn5xj1nEjxn81.jpg', null, null),
  ('Housebound', 2014, true, 'Not Rated', 'Gerard Johnstone', '2014-09-04'::date, '107 min', 'Comedy, Horror, Mystery', 'Gerard Johnstone', 'Morgana O''Reilly, Rima Te Wiata, Glen-Paul Waru', 'Kylie Bucknell is forced to return to the house she grew up in when the court places her on home detention. Her punishment is made all the more unbearable by the fact she has to live there with her mother Miriam - a well-intentioned blabbermouth who''s convinced that the house is haunted. Kylie dismisses Miriam''s superstitions as nothing more than a distraction from a life occupied by boiled vegetables &amp; small-town gossip. However, when she too becomes privy to unsettling whispers &amp; strange bumps in the night, she begins to wonder whether she''s inherited her overactive imagination, or if the house is in fact possessed by a hostile spirit who''s less than happy about the new living arrangement.', 'https://image.tmdb.org/t/p/w500/jPKEeHmUuoDnIaRs6VUqSr4qRGR.jpg', null, null),
  ('How to Train Your Dragon', 2010, false, 'PG', 'Dean DeBlois, Chris Sanders', '2010-03-26'::date, '98 min', 'Animation, Action, Adventure', 'William Davies, Dean DeBlois, Chris Sanders', 'Jay Baruchel, Gerard Butler, Christopher Mintz-Plasse', 'Long ago up North on the Island of Berk, the young Viking, Hiccup, wants to join his town''s fight against the dragons that continually raid their town. However, his macho father and village leader, Stoik the Vast, will not allow his small, clumsy, but inventive son to do so. Regardless, Hiccup ventures out into battle and downs a mysterious Night Fury dragon with his invention, but can''t bring himself to kill it. Instead, Hiccup and the dragon, whom he dubs Toothless, begin a friendship that would open up both their worlds as the observant boy learns that his people have misjudged the species. But even as the two each take flight in their own way, they find that they must fight the destructive ignorance plaguing their world.', 'https://image.tmdb.org/t/p/w500/ygGmAO60t8GyqUo9xYeYxSZAR3b.jpg', null, null),
  ('Immortals', 2011, false, 'R', 'Tarsem Singh', '2011-11-11'::date, '110 min', 'Action, Drama, Fantasy', 'Charley Parlapanides, Vlas Parlapanides', 'Henry Cavill, Mickey Rourke, John Hurt', 'Eons after the Gods won their mythic struggle against the Titans, a new evil threatens the land. Mad with power, King Hyperion (Mickey Rourke) has declared war against humanity. Amassing a bloodthirsty army of soldiers disfigured by his own hand, Hyperion has scorched Greece in search of the legendary Epirus Bow, a weapon of unimaginable power forged in the heavens by Ares (Daniel Sharman). Only he who possesses this bow can unleash the Titans, who have been imprisoned deep within the walls of Mount Tartaros since the dawn of time and thirst for revenge. In the King''s hands, the bow would rain destruction upon mankind and annihilate the Gods. But ancient law dictates the Gods must not intervene in man''s conflict. They remain powerless to stop Hyperion, until a peasant named Theseus (Henry Cavill) comes forth as their only hope. Secretly chosen by Zeus (Luke Evans), Theseus must save his people from Hyperion and his hordes. Rallying a band of fellow outsiders, including visionary Priestess Phaedra (Freida Pinto) and cunning slave Stavros (Stephen Dorff), one hero will lead the uprising, or watch his homeland fall into ruin and his Gods vanish into legend.', 'https://image.tmdb.org/t/p/w500/4SPPX5KIyaQ9O8n5rLvvUIiIhpF.jpg', null, null),
  ('Inception', 2010, true, 'PG-13', 'Christopher Nolan', '2010-07-16'::date, '148 min', 'Action, Adventure, Sci-Fi', 'Christopher Nolan', 'Leonardo DiCaprio, Joseph Gordon-Levitt, Elliot Page', 'Dom Cobb is a skilled thief, the absolute best in the dangerous art of extraction, stealing valuable secrets from deep within the subconscious during the dream state, when the mind is at its most vulnerable. Cobb''s rare ability has made him a coveted player in this treacherous new world of corporate espionage, but it has also made him an international fugitive and cost him everything he has ever loved. Now Cobb is being offered a chance at redemption. One last job could give him his life back but only if he can accomplish the impossible, inception. Instead of the perfect heist, Cobb and his team of specialists have to pull off the reverse: their task is not to steal an idea, but to plant one. If they succeed, it could be the perfect crime. But no amount of careful planning or expertise can prepare the team for the dangerous enemy that seems to predict their every move. An enemy that only Cobb could have seen coming.', 'https://image.tmdb.org/t/p/w500/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', null, null),
  ('Incredibles 2', 2018, false, 'PG', 'Brad Bird', '2018-06-15'::date, '118 min', 'Animation, Action, Adventure', 'Brad Bird', 'Craig T. Nelson, Holly Hunter, Sarah Vowell', 'While the Parr family has accepted its collective calling as superheroes, the fact remains that their special heroism is still illegal. After they are arrested after unsuccessfully trying to stop the Underminer, their future seems bleak. However, the wealthy Deavor siblings of Devtech offer new hope with a bold project to rehabilitate the public image and legal status of Supers, with Elastigirl being assigned on point to be the shining example. Now having agreed for now to stay at home to care of the kids, Mr. Incredible finds domestic life a daunting challenge, especially with baby Jack-Jack''s newly emerged powers making him almost impossible to manage. However, Elastigirl soon has her own concerns dealing with the menace of a new supervillain, Screenslaver, who is wreaking havoc with his mind control abilities. Now, Elastigirl must solve the mystery of this enemy, who has malevolent designs on the world with the Parr family and friends key targets of this evil.', 'https://image.tmdb.org/t/p/w500/9lFKBtaVIhP7E2Pk0IY1CwTKTMZ.jpg', null, null),
  ('Independence Day', 1996, false, 'PG-13', 'Roland Emmerich', '1996-07-03'::date, '145 min', 'Action, Adventure, Sci-Fi', 'Dean Devlin, Roland Emmerich', 'Will Smith, Bill Pullman, Jeff Goldblum', 'On July 2nd, communications systems worldwide are sent into chaos by a strange atmospheric interference. It is soon learned by the military that a number of enormous objects are on a collision course with Earth. At first thought to be meteors, they are later revealed to be gigantic spacecraft, piloted by a mysterious alien species. After attempts to communicate with the aliens go nowhere, David Levinson, an ex-scientist turned cable technician, discovers that the aliens are going to attack major points around the globe in less than a day. On July 3rd, the aliens all but obliterate New York, Los Angeles and Washington, as well as Paris, London, Houston and Moscow. The survivors set out in convoys towards Area 51, a strange government testing ground where it is rumored the military has a captured alien spacecraft of their own. The survivors devise a plan to fight back against the enslaving aliens, and July 4th becomes the day humanity will fight for its freedom. July 4th is their Independence Day...', 'https://image.tmdb.org/t/p/w500/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg', null, null),
  ('Independence Day: Resurgence', 2016, false, 'PG-13', 'Roland Emmerich', '2016-06-24'::date, '120 min', 'Action, Adventure, Sci-Fi', 'Gabriel Sherman, James A. Woods, Dean Devlin', 'Liam Hemsworth, Jeff Goldblum, Bill Pullman', 'Two decades after the freak alien invasion that nearly destroyed mankind a new threat emerges. This Alien mothership is more than twice the size as the last one and once again, the world''s armies must band together to save the world. Do they have enough firepower or will this battle change and will aliens take over?', 'https://image.tmdb.org/t/p/w500/9S50foUIYGwiNPWOxi1WJF6IPwI.jpg', null, null),
  ('Indiana Jones and the Kingdom of the Crystal Skull', 2008, false, 'PG-13', 'Steven Spielberg', '2008-05-22'::date, '122 min', 'Action, Adventure', 'David Koepp, George Lucas, Jeff Nathanson', 'Harrison Ford, Cate Blanchett, Shia LaBeouf', 'During the Cold War, Soviet Agents watch Professor Henry "Indiana" Jones, Jr. (Harrison Ford), when a young man brings him a coded message from an aged, demented colleague, Professor Harold Oxley (Sir John Hurt). Led by the brilliant Irina Spalko (Cate Blanchett), the Soviets tail Jones and the young man, Mutt Williams (Shia LeBeouf), to Peru. With Oxley''s code, they find a legendary skull made of a single piece of quartz. If Jones can deliver the skull to its rightful place, all may be well. But if Irina takes it to its origin, she''ll gain powers that could endanger the West. Aging professor and young buck join forces with a woman from Jones'' past, Marion Ravenwood (Karen Allen), to face the dangers of the jungle, Russia, and the supernatural.', 'https://image.tmdb.org/t/p/w500/56As6XEM1flWvprX4LgkPl8ii4K.jpg', null, null),
  ('Indiana Jones and the Last Crusade', 1989, false, 'PG-13', 'Steven Spielberg', '1989-05-24'::date, '127 min', 'Action, Adventure', 'Jeffrey Boam, George Lucas, Menno Meyjes', 'Harrison Ford, Sean Connery, Alison Doody', 'An art collector appeals to Indiana Jones to embark on a search for the Holy Grail. He learns that another archaeologist has disappeared while searching for the precious goblet, and the missing man is his own father, Dr. Henry Jones. The artifact is much harder to find than they expected, and its powers are too much for those impure of heart.', 'https://image.tmdb.org/t/p/w500/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg', null, null),
  ('Raiders of the Lost Ark', 1981, false, 'PG', 'Steven Spielberg', '1981-06-12'::date, '115 min', 'Action, Adventure', 'Lawrence Kasdan, George Lucas, Philip Kaufman', 'Harrison Ford, Karen Allen, Paul Freeman', 'The year is 1936. An archeology professor named Indiana Jones is venturing in the jungles of South America searching for a golden statue. Unfortunately, he sets off a deadly trap but miraculously escapes. Then, Jones hears from a museum curator named Marcus Brody about a biblical artifact called The Ark of the Covenant, which can hold the key to human existence. Jones has to venture to vast places such as Nepal and Egypt to find this artifact. However, he will have to fight his enemy Rene Belloq and a band of Nazis in order to reach it.', 'https://image.tmdb.org/t/p/w500/ceG9VzoRAVGwivFU403Wc3AHRys.jpg', null, null),
  ('Indiana Jones and the Temple of Doom', 1984, false, 'PG', 'Steven Spielberg', '1984-05-23'::date, '118 min', 'Action, Adventure', 'Willard Huyck, Gloria Katz, George Lucas', 'Harrison Ford, Kate Capshaw, Ke Huy Quan', 'Indiana Jones teams up with a nightclub singer named Wilhelmina "Willie" Scott and a twelve-year-old Chinese boy named Short Round. They end up in a small distressed village in India, where the people believe that evil spirits have taken all their children away after a sacred precious stone was stolen. They also discover the great mysterious terror surrounding a booby-trapped temple known as the Temple of Doom. Thuggee is beginning to attempt to rise once more, believing that with the power of all five Sankara stones they can rule the world. It''s all up to Indiana to put an end to the Thuggee campaign, rescue the lost children, win the girl and conquer the Temple of Doom.', 'https://image.tmdb.org/t/p/w500/gpdVNUaa4LhRMLfJOPj1AZdhAZ3.jpg', null, null),
  ('Inferno', 2016, true, 'PG-13', 'Ron Howard', '2016-10-28'::date, '121 min', 'Action, Adventure, Crime', 'Dan Brown, David Koepp', 'Tom Hanks, Felicity Jones, Irrfan Khan', 'A famous symbologist on a trail of clues tied to the great Dante himself. When Langdon wakes up in an Italian hospital with amnesia, he teams up with Sienna Brooks, a doctor he hopes will help him recover his memories. Together, they race across Europe and against the clock to stop a madman from unleashing a global virus that would wipe out half of the world''s population.', 'https://image.tmdb.org/t/p/w500/cnqvFvjAaV28F1tU7986VVg0WP7.jpg', null, null),
  ('Inside Man', 2006, false, 'R', 'Spike Lee', '2006-03-24'::date, '129 min', 'Crime, Drama, Mystery', 'Russell Gewirtz', 'Denzel Washington, Clive Owen, Jodie Foster', 'Composed and meticulous, the soft-spoken and ingenious bank robber, Dalton Russell, has orchestrated the perfect heist--shortly, the Manhattan bank at the corner of Wall Street and Broadway along with dozens of hostages will be his to command. Try as he might, the rough hostage negotiator, Keith Frazier, is always one step behind the criminal mastermind--and what is more disheartening--the institution''s silver-haired founder, Arthur Case, recruits the intelligent problem-fixer, Madeline White, to retrieve something of paramount importance. However, the thieves seem to procrastinate intentionally, when they should be rushing into action. Will Arthur and Madeline get what they want this time?', 'https://image.tmdb.org/t/p/w500/ffMUgkDZICNiyaws1Jkv8qG8uFW.jpg', null, null),
  ('Inside Out', 2015, false, 'PG', 'Pete Docter, Ronnie Del Carmen', '2015-06-19'::date, '95 min', 'Animation, Adventure, Comedy', 'Pete Docter, Ronnie Del Carmen, Meg LeFauve', 'Amy Poehler, Bill Hader, Lewis Black', 'Growing up can be a bumpy road, and it''s no exception for Riley, who is uprooted from her Midwest life when her father starts a new job in San Francisco. Like all of us, Riley is guided by her emotions - Joy, Fear, Anger, Disgust and Sadness. The emotions live in Headquarters, the control center inside Riley''s mind, where they help advise her through everyday life. As Riley and her emotions struggle to adjust to a new life in San Francisco, turmoil ensues in Headquarters. Although Joy, Riley''s main and most important emotion, tries to keep things positive, the emotions conflict on how best to navigate a new city, house and school.', 'https://image.tmdb.org/t/p/w500/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg', null, null),
  ('Insidious', 2010, false, 'PG-13', 'James Wan', '2011-04-01'::date, '103 min', 'Horror, Mystery, Thriller', 'Leigh Whannell', 'Patrick Wilson, Rose Byrne, Ty Simpkins', 'A gripping story of a family in search of help for their son, Dalton, who fell into a coma after a mysterious incident in the attic. Little do they know that there is much more to this endless sleep than meets the eye as they explore the paranormal, and rediscover the past; the key to getting their son back once and for all.', 'https://image.tmdb.org/t/p/w500/1egpmVXuXed58TH2UOnX1nATTrf.jpg', null, null),
  ('Omni Loop', 2024, true, 'PG-13', 'Bernardo Britto', '2024-09-20'::date, '107 min', 'Drama, Sci-Fi', 'Bernardo Britto', 'Mary-Louise Parker, Ayo Edebiri, Carlos Jacott', 'A woman from Miami, Florida decides to solve time travel in order to go back and be the person she always intended to.', 'https://image.tmdb.org/t/p/w500/aKrwq3HeyFcl5MXb7tcsileoF9I.jpg', null, null),
  ('Insidious: Chapter 3', 2015, false, 'PG-13', 'Leigh Whannell', '2015-06-05'::date, '97 min', 'Horror, Mystery, Thriller', 'Leigh Whannell', 'Dermot Mulroney, Stefanie Scott, Angus Sampson', 'After trying to connect with her dead mother, teenager Quinn Brenner, asks psychic Elise Rainier to help her, she refuses due to negotiate events in her childhood. Quinn starts noticing paranormal events happen in her house. After a vicious attack from a demon her father goes back and begs Elise Rainier to use her abilities to contact the other side in hope to stop these attacks by this furious demon content for a body.', 'https://image.tmdb.org/t/p/w500/iDdGfdNvY1EX0uDdA4Ru77fwMfc.jpg', null, null),
  ('Insidious: The Last Key', 2018, false, 'PG-13', 'Adam Robitel', '2018-01-05'::date, '103 min', 'Horror, Mystery, Thriller', 'Leigh Whannell', 'Lin Shaye, Leigh Whannell, Angus Sampson', 'The parapsychologist Dr. Elise Rainier has nightmares with her childhood in New Mexico, where she lived with her brother Christian, her supportive mother Audrey and her father Gerald, who frequently beats her when she claims that she sees ghosts everywhere in the house. When the client Ted Garza calls Elise to ask for help since he is haunted since he moved to a house in New Mexico, Elise refuses the request since the address is the same house where she spent her childhood. However she changes her mind and accepts the job, and travels with her assistants Specs and Tucker to New Mexico where they will discover an evil entity in the house.', 'https://image.tmdb.org/t/p/w500/nb9fc9INMg8kQ8L7sE7XTNsZnUX.jpg', null, null),
  ('Interstellar', 2014, true, 'PG-13', 'Christopher Nolan', '2014-11-07'::date, '169 min', 'Adventure, Drama, Sci-Fi', 'Jonathan Nolan, Christopher Nolan', 'Matthew McConaughey, Anne Hathaway, Jessica Chastain', 'Earth''s future has been riddled by disasters, famines, and droughts. There is only one way to ensure mankind''s survival: Interstellar travel. A newly discovered wormhole in the far reaches of our solar system allows a team of astronauts to go where no man has gone before, a planet that may have the right environment to sustain human life.', 'https://image.tmdb.org/t/p/w500/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg', null, null),
  ('Into the Storm', 2014, false, 'PG-13', 'Steven Quale', '2014-08-08'::date, '89 min', 'Action, Adventure, Drama', 'John Swetnam', 'Richard Armitage, Sarah Wayne Callies, Matt Walsh', 'In the span of a single day, the town of Silverton is ravaged by an unprecedented onslaught of tornadoes. The entire town is at the mercy of the erratic and deadly cyclones, even as storm trackers predict the worst is yet to come. Most people seek shelter, while others run towards the vortex, testing how far a storm chaser will go for that once-in-a-lifetime shot.', 'https://image.tmdb.org/t/p/w500/kBgrhrES9kMKSPxawUYV61KjlnB.jpg', null, null),
  ('Iron Man', 2008, true, 'PG-13', 'Jon Favreau', '2008-05-02'::date, '126 min', 'Action, Adventure, Sci-Fi', 'Mark Fergus, Hawk Ostby, Art Marcum', 'Robert Downey Jr., Gwyneth Paltrow, Terrence Howard', 'Tony Stark. Genius, billionaire, playboy, philanthropist. Son of legendary inventor and weapons contractor Howard Stark. When Tony Stark is assigned to give a weapons presentation to an Iraqi unit led by Lt. Col. James Rhodes, he''s given a ride on enemy lines. That ride ends badly when Stark''s Humvee that he''s riding in is attacked by enemy combatants. He survives - barely - with a chest full of shrapnel and a car battery attached to his heart. In order to survive he comes up with a way to miniaturize the battery and figures out that the battery can power something else. Thus Iron Man is born. He uses the primitive device to escape from the cave in Iraq. Once back home, he then begins work on perfecting the Iron Man suit. But the man who was put in charge of Stark Industries has plans of his own to take over Tony''s technology for other matters.', 'https://image.tmdb.org/t/p/w500/78lPtwv72eTNqFW9COBYI0dWDJa.jpg', null, null),
  ('Iron Man 2', 2010, true, 'PG-13', 'Jon Favreau', '2010-05-07'::date, '124 min', 'Action, Sci-Fi', 'Justin Theroux, Stan Lee, Don Heck', 'Robert Downey Jr., Mickey Rourke, Gwyneth Paltrow', 'With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press, and the public to share his technology with the military. Unwilling to let go of his invention, Stark, along with Pepper Potts, and James "Rhodey" Rhodes at his side, must forge new alliances - and confront powerful enemies.', 'https://image.tmdb.org/t/p/w500/6WBeq4fCfn7AN0o21W9qNcRF2l9.jpg', null, null),
  ('Iron Man 3', 2013, true, 'PG-13', 'Shane Black', '2013-05-03'::date, '130 min', 'Action, Adventure, Sci-Fi', 'Drew Pearce, Shane Black, Stan Lee', 'Robert Downey Jr., Guy Pearce, Gwyneth Paltrow', 'Marvel''s "Iron Man 3" pits brash-but-brilliant industrialist Tony Stark/Iron Man against an enemy whose reach knows no bounds. When Stark finds his personal world destroyed at his enemy''s hands, he embarks on a harrowing quest to find those responsible. This journey, at every turn, will test his mettle. With his back against the wall, Stark is left to survive by his own devices, relying on his ingenuity and instincts to protect those closest to him. As he fights his way back, Stark discovers the answer to the question that has secretly haunted him: does the man make the suit or does the suit make the man?', 'https://image.tmdb.org/t/p/w500/qhPtAc1TKbMPqNvcdXSOn9Bn7hZ.jpg', null, null),
  ('It', 2017, false, 'R', 'Andy Muschietti', '2017-09-08'::date, '135 min', 'Horror', 'Chase Palmer, Cary Joji Fukunaga, Gary Dauberman', 'Bill Skarsgård, Jaeden Martell, Finn Wolfhard', 'In the Town of Derry, the local kids are disappearing one by one. In a place known as ''The Barrens'', a group of seven kids are united by their horrifying and strange encounters with an evil clown and their determination to kill It.', 'https://image.tmdb.org/t/p/w500/9E2y5Q7WlCVNEhP5GiVTjhEhx1o.jpg', null, null),
  ('Jason Bourne', 2016, true, 'PG-13', 'Paul Greengrass', '2016-07-29'::date, '123 min', 'Action, Thriller', 'Paul Greengrass, Christopher Rouse, Robert Ludlum', 'Matt Damon, Tommy Lee Jones, Alicia Vikander', 'Jason Bourne is again being hunted by the CIA. It begins when Nicky Parsons a former CIA operative who helped Bourne, who went under and now works with a man who''s a whistle blower and is out to expose the CIA''s black ops. Nicky hacks into the CIA and downloads everything on all their Black Ops, including Treadstone which Bourne was a part of. And Heather Lee, a CIA agent, discovers the hack and brings it to the attention of CIA Director Dewey, the man behind the Black Ops. He orders Parsons be found and, hopefully, Bourne, too.', 'https://image.tmdb.org/t/p/w500/xA7N41glw17MBQtcWSm2eBlBRuG.jpg', null, null),
  ('Jaws', 1975, false, 'PG', 'Steven Spielberg', '1975-06-20'::date, '124 min', 'Adventure, Drama, Thriller', 'Peter Benchley, Carl Gottlieb', 'Roy Scheider, Robert Shaw, Richard Dreyfuss', 'It''s a hot summer on Amity Island, a small community whose main business is its beaches. When new Sheriff Martin Brody discovers the remains of a shark attack victim, his first inclination is to close the beaches to swimmers. This doesn''t sit well with Mayor Larry Vaughn and several of the local businessmen. Brody backs down to his regret as that weekend a young boy is killed by the predator. The dead boy''s mother puts out a bounty on the shark and Amity is soon swamped with amateur hunters and fisherman hoping to cash in on the reward. A local fisherman with much experience hunting sharks, Quint, offers to hunt down the creature for a hefty fee. Soon Quint, Brody and Matt Hooper from the Oceanographic Institute are at sea hunting the Great White shark. As Brody succinctly surmises after their first encounter with the creature, they''re going to need a bigger boat.', 'https://image.tmdb.org/t/p/w500/lxM6kqilAdpdhqUl2biYp5frUxE.jpg', null, null),
  ('Jeepers Creepers', 2001, false, 'R', 'Victor Salva', '2001-08-31'::date, '90 min', 'Horror, Mystery', 'Victor Salva', 'Gina Philips, Justin Long, Jonathan Breck', 'On their way back home during the spring break, Darry and Patricia Jenner witness a mysterious person dumping something down a tunnel. Deciding to discover what was dumped down there, Darry discovers a huge disturbing hideout full of modified bodies. Darry and Patricia set off to get help, unaware that the individual is now aware of who has been down the tunnel. Darry and Patricia soon realizes that their pursuer is not just a mysterious person, but something even more horrifying, who has more in store than they could possibly imagine.', 'https://image.tmdb.org/t/p/w500/g410Y1U1ELbmJG14Zru3UAimm1G.jpg', null, null),
  ('Jessabelle', 2014, false, 'PG-13', 'Kevin Greutert', '2014-11-07'::date, '90 min', 'Drama, Horror, Mystery', 'Robert Ben Garant', 'Sarah Snook, Mark Webber, Joelle Carter', 'Jessabelle "Jessie" Laurent is pregnant and accepts to move to the house of her boyfriend to raise a family of their own. However they have a car accident where her boyfriend and her baby die. Jessie is seriously wounded and trapped to a wheelchair, and the direction of the hospital asks her to contact her estranged father to help her. Leon Laurent brings his daughter to his house in Louisiana and lodges her in her mother''s room. Jessie snoops around the room and finds a videotape where her mother Kate Laurent is pregnant and reads tarot cards to her. She tells that Jessie would never left Louisiana; she is attracted by water; and another woman wants her out of the house. However Leon arrives and destroys the tape. On the next morning, Jessie watches another videotape when her father is out of the house, and her mother talks about the man that had taught her to read cards, Moses. Jessie is haunted by the ghost of a woman and her father discovers the two other videotapes she has hidden. When he tries to destroy them, something happens to him and he is burnt to death trapped in a shed. During the funeral, Jessie meets her high-school friend Preston Sanders (Mark Webber), who is unhappily married. Preston decides to help Jessie after watching the videotapes. Who might be haunting Jessie?', 'https://image.tmdb.org/t/p/w500/9WP1ADKCeDG0avA0WSo4mUemTqW.jpg', null, null),
  ('JFK', 1991, false, 'R', 'Oliver Stone', '1991-12-20'::date, '189 min', 'Drama, History, Thriller', 'Jim Garrison, Jim Marrs, Oliver Stone', 'Kevin Costner, Gary Oldman, Jack Lemmon', 'On November 22, 1963, president John F. Kennedy is assassinated in Dallas. Lee Harvey Oswald is arrested for the crime and subsequently shot by Jack Ruby, supposedly avenging the president''s death. An investigation concludes that Lee Harvey Oswald and Jack Ruby acted alone in their respective crimes, but Louisiana district attorney Jim Garrison is skeptical. Assembling a trusted group of people, Garrison conducts his own investigation, bringing about backlash from powerful government and political figures.', 'https://image.tmdb.org/t/p/w500/r0VWVTYlqdRCK5ZoOdNnHdqM2gt.jpg', null, null),
  ('Jimmy Neutron: Boy Genius', 2001, false, 'G', 'John A. Davis', '2001-12-21'::date, '82 min', 'Animation, Action, Adventure', 'John A. Davis, David N. Weiss, J. David Stem', 'Debi Derryberry, Rob Paulsen, Megan Cavanagh', 'Jimmy Neutron is a boy genius and way ahead of his friends, but when it comes to being cool, he''s a little behind. All until one day when his parents, and parents all over Earth are kidnapped by aliens, it''s up to him to lead all the children of the world to rescue their parents.', 'https://image.tmdb.org/t/p/w500/pUwdquA6Bf3Gq8yT5iQL1Yq0jkl.jpg', null, null),
  ('John Wick', 2014, true, 'R', 'Chad Stahelski', '2014-10-24'::date, '101 min', 'Action, Crime, Thriller', 'Derek Kolstad', 'Keanu Reeves, Michael Nyqvist, Alfie Allen', 'With the untimely death of his beloved wife still bitter in his mouth, John Wick, the expert former assassin, receives one final gift from her--a precious keepsake to help John find a new meaning in life now that she is gone. But when the arrogant Russian mob prince, Iosef Tarasov, and his men pay Wick a rather unwelcome visit to rob him of his prized 1969 Mustang and his wife''s present, the legendary hitman will be forced to unearth his meticulously concealed identity. Blind with revenge, John will immediately unleash a carefully orchestrated maelstrom of destruction against the sophisticated kingpin, Viggo Tarasov, and his family, who are fully aware of his lethal capacity. Now, only blood can quench the boogeyman''s thirst for retribution.', 'https://image.tmdb.org/t/p/w500/fZPSd91yGE9fCcCe6OoQr6E3Bev.jpg', null, null),
  ('John Wick: Chapter 2', 2017, true, 'R', 'Chad Stahelski', '2017-02-10'::date, '122 min', 'Action, Crime, Thriller', 'Derek Kolstad', 'Keanu Reeves, Riccardo Scamarcio, Ian McShane', 'Bound by an inescapable blood debt to the Italian crime lord, Santino D''Antonio, and with his precious 1969 Mustang still stolen, John Wick--the taciturn and pitiless assassin who thirsts for seclusion--is forced to visit Italy to honour his promise. But, soon, the Bogeyman will find himself dragged into an impossible task in the heart of Rome''s secret criminal society, as every killer in the business dreams of cornering the legendary Wick who now has an enormous price on his head. Drenched in blood and mercilessly hunted down, John Wick can surely forget a peaceful retirement as no one can make it out in one piece.', 'https://image.tmdb.org/t/p/w500/hXWBc0ioZP3cN4zCu6SN3YHXZVO.jpg', null, null),
  ('Joker', 2019, false, 'R', 'Todd Phillips', '2019-10-04'::date, '122 min', 'Crime, Drama, Thriller', 'Todd Phillips, Scott Silver, Bob Kane', 'Joaquin Phoenix, Robert De Niro, Zazie Beetz', 'Arthur Fleck works as a clown and is an aspiring stand-up comic. He has mental health issues, part of which involves uncontrollable laughter. Times are tough and, due to his issues and occupation, Arthur has an even worse time than most. Over time these issues bear down on him, shaping his actions, making him ultimately take on the persona he is more known as...Joker.', 'https://image.tmdb.org/t/p/w500/udDclJoHjfjb8Ekgsd4FDteOkCU.jpg', null, null),
  ('Jurassic Park III', 2001, true, 'PG-13', 'Joe Johnston', '2001-07-18'::date, '92 min', 'Action, Adventure, Sci-Fi', 'Michael Crichton, Peter Buchman, Alexander Payne', 'Sam Neill, William H. Macy, Téa Leoni', 'Dr. Alan Grant is now a happy man with the previous incidents of Jurassic Park now behind him. Grant is that happy that he announce in public, that nothing on Earth can persuade him back onto the islands. Maybe nothing, except Paul Kirby. Kirby and his wife, Amanda want a plane to fly them over Isla Sorna, with Dr. Grant as their guide. But not everything Kirby says is true. When the plane lands, Dr. Grant realizes that there is another reason why they are there, that he doesn''t know of. Now, Dr. Grant is stuck on an island he has never been on before, with what was a plane journey now turned into a search party.', 'https://image.tmdb.org/t/p/w500/oQXj4NUfS3r3gHXtDOzcJgj1lLc.jpg', null, null),
  ('Jurassic World', 2015, true, 'PG-13', 'Colin Trevorrow', '2015-06-12'::date, '124 min', 'Action, Adventure, Sci-Fi', 'Rick Jaffa, Amanda Silver, Colin Trevorrow', 'Chris Pratt, Bryce Dallas Howard, Ty Simpkins', 'Twenty-two years after the original Jurassic Park failed, the new park, also known as Jurassic World, is open for business. After years of studying genetics, the scientists on the park genetically engineer a new breed of dinosaur, the Indominus Rex. When everything goes horribly wrong, will our heroes make it off the island?', 'https://image.tmdb.org/t/p/w500/rhr4y79GpxQF9IsfJItRXVaoGs4.jpg', null, null),
  ('Jurassic World: Fallen Kingdom', 2018, true, 'PG-13', 'J.A. Bayona', '2018-06-22'::date, '128 min', 'Action, Adventure, Sci-Fi', 'Derek Connolly, Colin Trevorrow, Michael Crichton', 'Chris Pratt, Bryce Dallas Howard, Rafe Spall', 'Three years after the Jurassic World theme park was closed down, Owen and Claire return to Isla Nublar to save the dinosaurs when they learn that a once dormant volcano on the island is active and is threatening to extinguish all life there. Along the way, Owen sets out to find Blue, his lead raptor, and discovers a conspiracy that could disrupt the natural order of the entire planet. Life has found a way, again.', 'https://image.tmdb.org/t/p/w500/x8cLgs0uXlb9rmpuVIxopoRGnCr.jpg', null, null),
  ('Justice League', 2017, false, 'PG-13', 'Zack Snyder', '2017-11-17'::date, '120 min', 'Action, Adventure, Fantasy', 'Jerry Siegel, Joe Shuster, Chris Terrio', 'Ben Affleck, Gal Gadot, Jason Momoa', 'Fueled by his restored faith in humanity and inspired by Superman''s selfless act, Bruce Wayne enlists the help of his newfound ally, Diana Prince, to face an even greater enemy. Together, Batman and Wonder Woman work quickly to find and recruit a team of meta-humans to stand against this newly awakened threat. But despite the formation of this unprecedented league of heroes-Batman, Wonder Woman, Aquaman, Cyborg and The Flash-it may already be too late to save the planet from an assault of catastrophic proportions.', 'https://image.tmdb.org/t/p/w500/hg6RYpSb3vU4i3yQDtE1YhSZNh5.jpg', null, null),
  ('Terrifier 2', 2022, true, 'Not Rated', 'Damien Leone', '2022-10-06'::date, '138 min', 'Horror', 'Damien Leone', 'Lauren LaVera, David Howard Thornton, Elliott Fullam', 'After being resurrected by a sinister entity, Art the Clown returns to the timid town of Miles County where he targets a teenage girl and her younger brother on Halloween night.', 'https://image.tmdb.org/t/p/w500/qEAlwXbYk6IHA4ztoS2XFFaa7Xo.jpg', null, null),
  ('Kevin Hart: Let Me Explain', 2013, false, 'R', 'Leslie Small, Tim Story', '2013-07-03'::date, '75 min', 'Documentary, Comedy', 'Kevin Hart', 'Kevin Hart, Harry Ratchford, Will ''Spank'' Horton', 'Kevin is throwing a celebration party, but guests tell him that he has changed since his divorce. He tries to explain himself, but they will not let him, so he decides to do a show at Madison Square Garden letting him explain, which sold out with 30,000 people. The film also shows performances of his sold-out shows from all around the world..', 'https://image.tmdb.org/t/p/w500/lzYQkVuEN0zw2JvJsMUsOU47nb4.jpg', null, null),
  ('Kick-Ass', 2010, false, 'R', 'Matthew Vaughn', '2010-04-16'::date, '117 min', 'Action, Comedy, Crime', 'Jane Goldman, Matthew Vaughn, Mark Millar', 'Aaron Taylor-Johnson, Nicolas Cage, Chloë Grace Moretz', 'Dave Lizewski is an unnoticed high school student and comic book fan with a few friends and who lives alone with his father. His life is not very difficult and his personal trials not that overwhelming. However, one day he makes the simple decision to become a super-hero even though he has no powers or training.', 'https://image.tmdb.org/t/p/w500/iHMbrTHJwocsNvo5murCBw0CwTo.jpg', null, null),
  ('Kick-Ass 2', 2013, false, 'R', 'Jeff Wadlow', '2013-08-16'::date, '103 min', 'Action, Comedy, Crime', 'Jeff Wadlow, Mark Millar, John Romita Jr.', 'Aaron Taylor-Johnson, Chloë Grace Moretz, Christopher Mintz-Plasse', 'After Kick-Ass'' insane bravery inspires a new wave of self-made masked crusaders, led by the badass Colonel Stars and Stripes, our hero joins them on patrol. When these amateur superheroes are hunted down by Red Mist -- reborn as The Mother F%&amp;*^r -- only the blade-wielding Hit Girl can prevent their annihilation. When we last saw junior assassin Hit Girl and young vigilante Kick-Ass, they were trying to live as normal teenagers Mindy and Dave. With graduation looming and uncertain what to do, Dave decides to start the world''s first superhero team with Mindy. Unfortunately, when Mindy is busted for sneaking out as Hit Girl, she''s forced to retire-leaving her to navigate the terrifying world of high-school mean girls on her own. With no one left to turn to, Dave joins forces with Justice Forever, run by a born-again ex-mobster named Colonel Stars and Stripes. Just as they start to make a real difference on the streets, the world''s first super villain, The Mother F%&amp;*^r, assembles his own evil league and puts a plan in motion to make Kick-Ass and Hit Girl pay for what they did to his dad. But there''s only one problem with his scheme: If you mess with one member of Justice Forever, you mess with them all.', 'https://image.tmdb.org/t/p/w500/1go2A3gdQjaMuHWquybgoJlQRcX.jpg', null, null),
  ('Kidnap', 2017, false, 'R', 'Luis Prieto', '2017-08-04'::date, '95 min', 'Action, Crime, Thriller', 'Knate Lee', 'Halle Berry, Sage Correa, Chris McGinn', 'In the US, a child goes missing every 40 seconds. You never think it will happen to you. Until it does. Alone and scared, Karla Dyson (Halle Berry) is unwilling to leave the fate of her son''s life in someone else''s hands. When she catches a glimpse of the abductors speeding away, she decides to fight back. In a heart pounding race against time, Karla begins a high speed pursuit and will stop at nothing to save her son''s life.', 'https://image.tmdb.org/t/p/w500/fwdOX3PEZlOLXr9SMpgRnSmTVFp.jpg', null, null),
  ('Kill Bill: Vol. 1', 2003, false, 'R', 'Quentin Tarantino', '2003-10-10'::date, '111 min', 'Action, Crime, Thriller', 'Quentin Tarantino, Uma Thurman', 'Uma Thurman, David Carradine, Daryl Hannah', 'The lead character, called ''The Bride,'' was a member of the Deadly Viper Assassination Squad, led by her lover ''Bill.'' Upon realizing she was pregnant with Bill''s child, ''The Bride'' decided to escape her life as a killer. She fled to Texas, met a young man, who, on the day of their wedding rehearsal was gunned down by an angry and jealous Bill (with the assistance of the Deadly Viper Assassination Squad). Four years later, ''The Bride'' wakes from a coma, and discovers her baby is gone. She, then, decides to seek revenge upon the five people who destroyed her life and killed her baby. The saga of Kill Bill Volume I begins.', 'https://image.tmdb.org/t/p/w500/v7TaX8kXMXs5yFFGR41guUDNcnB.jpg', null, null),
  ('Kill Bill: Vol. 2', 2004, false, 'R', 'Quentin Tarantino', '2004-04-16'::date, '137 min', 'Action, Crime, Thriller', 'Quentin Tarantino, Uma Thurman', 'Uma Thurman, David Carradine, Michael Madsen', 'The murderous Bride is back and she is still continuing her vengeance quest against her ex-boss, Bill, and taking aim at Bill''s younger brother Budd and Elle Driver, the only survivors from the squad of assassins who betrayed her four years earlier. It''s all leading up to the ultimate confrontation with Bill, the Bride''s former master and the man who ordered her execution!', 'https://image.tmdb.org/t/p/w500/vr9w5OrpAPjCdccZ6xheBqGkxwM.jpg', null, null),
  ('King Kong', 2005, false, 'PG-13', 'Peter Jackson', '2005-12-14'::date, '187 min', 'Action, Adventure, Romance', 'Fran Walsh, Philippa Boyens, Peter Jackson', 'Naomi Watts, Jack Black, Adrien Brody', 'Carl Denham needs to finish his movie and has the perfect location; Skull Island. But he still needs to find a leading lady. This ''soon-to-be-unfortunate'' soul is Ann Darrow. No one knows what they will encounter on this island and why it is so mysterious, but once they reach it, they will soon find out. Living on this hidden island is a giant gorilla and this beast now has Ann is its grasps. Carl and Ann''s new love, Jack Driscoll must travel through the jungle looking for Kong and Ann, whilst avoiding all sorts of creatures and beasts. But Carl has another plan in mind.', 'https://image.tmdb.org/t/p/w500/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg', null, null),
  ('Kingdom of Heaven', 2005, false, 'R', 'Ridley Scott', '2005-05-06'::date, '144 min', 'Action, Adventure, Drama', 'William Monahan', 'Orlando Bloom, Eva Green, Liam Neeson', 'It is the time of the Crusades during the Middle Ages -- the world-shaping 200-year collision between Europe and the East. A blacksmith named Balian has lost his family and nearly his faith. The religious wars raging in the far-off Holy Land seem remote to him, yet he is pulled into that immense drama. Amid the pageantry and intrigues of medieval Jerusalem, he falls in love, grows into a leader, and ultimately uses all his courage and skill to defend the city against staggering odds. Destiny comes seeking Balian in the form of a great knight, Godfrey of Ibelin, a Crusader briefly home to France from fighting in the East. Revealing himself as Balian''s father, Godfrey shows him the true meaning of knighthood and takes him on a journey across continents to the fabled Holy City. In Jerusalem at that moment--between the Second and Third Crusades--a fragile peace prevails, through the efforts of its enlightened Christian king, Baldwin IV, aided by his advisor Tiberias, and the military restraint of the legendary Muslim leader Saladin Ayubi. But Baldwin''s days are numbered, and strains of fanaticism, greed, and jealousy among the Crusaders threaten to shatter the truce. King Baldwin''s vision of peace--a kingdom of heaven--is shared by a handful of knights, including Godfrey of Ibelin, who swear to uphold it with their lives and honor. As Godfrey passes his sword to his son, he also passes on that sacred oath: to protect the helpless, safeguard the peace, and work toward harmony between religions and cultures, so that a kingdom of heaven can flourish on earth. Balian takes the sword and steps into history.', 'https://image.tmdb.org/t/p/w500/rNaBe4TwbMef71sgscqabpGKsxh.jpg', null, null),
  ('Kingsman: The Golden Circle', 2017, false, 'R', 'Matthew Vaughn', '2017-09-22'::date, '141 min', 'Action, Adventure, Comedy', 'Jane Goldman, Matthew Vaughn, Mark Millar', 'Taron Egerton, Colin Firth, Mark Strong', 'After the Kingsman headquarters are blown up by a psychotic criminal named Poppy Adams (Julianne Moore), the surviving agents find their way to an allied secret organization based in Kentucky, named "Statesman". The two agencies must now work together in order to save the world and take down the so called "Golden Circle".', 'https://image.tmdb.org/t/p/w500/34xBL6BXNYFqtHO9zhcgoakS4aP.jpg', null, null),
  ('Oblivion', 2013, true, 'PG-13', 'Joseph Kosinski', '2013-04-19'::date, '124 min', 'Action, Adventure, Sci-Fi', 'Karl Gajdusek, Michael Arndt, Joseph Kosinski', 'Tom Cruise, Morgan Freeman, Andrea Riseborough', 'One of the few remaining drone repairmen assigned to Earth, its surface devastated after decades of war with the alien Scavs, discovers a crashed spacecraft with contents that bring into question everything he believed about the war, and may even put the fate of mankind in his hands.', 'https://image.tmdb.org/t/p/w500/eO3r38fwnhb58M1YgcjQBd3VNcp.jpg', null, null),
  ('Kingsman: The Secret Service', 2014, false, 'R', 'Matthew Vaughn', '2015-02-13'::date, '129 min', 'Action, Adventure, Comedy', 'Jane Goldman, Matthew Vaughn, Mark Millar', 'Colin Firth, Taron Egerton, Samuel L. Jackson', 'A young man named Gary "Eggsy" Unwin (Taron Egerton), whose father died when he was a young boy, is dealing with living with the creep his mother is with now, who mistreats her and him. He goes out and does something to one of the creep''s friends. He gets arrested and he calls the number a man gave him around the time his father died, to call if he needs help. A man named Harry Hart (Colin Firth) approaches him and tells him he''s the one who helped him. He tells him that he knew his father. When the man Eggsy slighted wants some payback, Harry takes care of him and his companions single-handedly. Harry then tells Eggsy that he''s part of a secret organization called "The Kingsman", and his father was also part of it. He died trying to make the world safe. Harry offers Eggsy the opportunity to be a Kingsman, and he takes it. He undergoes a gruelling training course. Harry is looking into the demise of another Kingsman, and the trail leads him to tech billionaire Valentine, a.k.a. "V" (Samuel L. Jackson), who is also curious about the group following him, the Kingsman.', 'https://image.tmdb.org/t/p/w500/r6q9wZK5a2K51KFj4LWVID6Ja1r.jpg', null, null),
  ('Knives Out', 2019, true, 'PG-13', 'Rian Johnson', '2019-11-27'::date, '130 min', 'Comedy, Crime, Drama', 'Rian Johnson', 'Daniel Craig, Chris Evans, Ana de Armas', 'When renowned crime novelist Harlan Thrombey (Christopher Plummer) is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc (Daniel Craig) is mysteriously enlisted to investigate. From Harlan''s disfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.', 'https://image.tmdb.org/t/p/w500/pThyQovXQrw2m0s9x82twj48Jq4.jpg', null, null),
  ('Krampus', 2015, false, 'PG-13', 'Michael Dougherty', '2015-12-04'::date, '98 min', 'Comedy, Fantasy, Horror', 'Todd Casey, Michael Dougherty, Zach Shields', 'Adam Scott, Toni Collette, David Koechner', 'When his dysfunctional family clashes over the holidays, young Max (Emjay Anthony) gets disillusioned and turns his back on Christmas. Meanwhile, this lack of festive spirit unleashes the wrath of Krampus: a demonic force of ancient evil intent on punishing non-believers. All hell breaks loose as beloved holiday icons take on a monstrous life of their own, laying siege to the fractured family''s home and forcing them to fight for one another if they hope to survive.', 'https://image.tmdb.org/t/p/w500/mzPCU6xQ2XQmD76cDVZPm5PZAaS.jpg', null, null),
  ('Krull', 1983, false, 'PG', 'Peter Yates', '1983-07-29'::date, '121 min', 'Action, Adventure, Fantasy', 'Stanford Sherman', 'Ken Marshall, Lysette Anthony, Freddie Jones', 'In the face of total annihilation by the omnipotent Beast''s unstoppable hordes of Slayers, the young aristocrats of two hostile neighbouring nations--the brave Prince Colwyn and the fair Princess Lyssa--are about to come into union, and form an alliance against the common enemy. However, the otherworldly adversary is all-powerful, and before long, a fateful abduction will trigger a desperate quest to the evil entity''s grim Black Fortress, as Colwyn and a handful of mismatched defenders are willing to dice with death to ensure the land''s future. In this suicide mission, the magical, five-edged weapon known as the Glaive is their only chance of survival. Can Prince Colwyn slay the Beast, save Lyssa and Krull, the small planet in the middle of the vast galaxy?', 'https://image.tmdb.org/t/p/w500/izDbySIrTmID0Nh6UqcWrUvOMjU.jpg', null, null),
  ('Kung Fu Panda', 2008, false, 'PG', 'Mark Osborne, John Stevenson', '2008-06-06'::date, '92 min', 'Animation, Action, Adventure', 'Jonathan Aibel, Glenn Berger, Ethan Reiff', 'Jack Black, Ian McShane, Angelina Jolie', 'It''s the story about a lazy, irreverent slacker panda, named Po, who is the biggest fan of Kung Fu around...which doesn''t exactly come in handy while working every day in his family''s noodle shop. Unexpectedly chosen to fulfill an ancient prophecy, Po''s dreams become reality when he joins the world of Kung Fu and studies alongside his idols, the legendary Furious Five -- Tigress, Crane, Mantis, Viper and Monkey -- under the leadership of their guru, Master Shifu. But before they know it, the vengeful and treacherous snow leopard Tai Lung is headed their way, and it''s up to Po to defend everyone from the oncoming threat. Can he turn his dreams of becoming a Kung Fu master into reality? Po puts his heart - and his girth - into the task, and the unlikely hero ultimately finds that his greatest weaknesses turn out to be his greatest strengths.', 'https://image.tmdb.org/t/p/w500/wWt4JYXTg5Wr3xBW2phBrMKgp3x.jpg', null, null),
  ('Labyrinth', 1986, false, 'PG', 'Jim Henson', '1986-06-27'::date, '101 min', 'Adventure, Family, Fantasy', 'Dennis Lee, Jim Henson, Terry Jones', 'David Bowie, Jennifer Connelly, Toby Froud', 'Teenager Sarah is forced by her father and her stepmother to babysit her baby brother Toby while they are outside home. Toby does not stop crying and Sarah wishes that her stepbrother be taken by the Goblin King Jareth. Out of the blue, Toby stops crying and when Sarah looks for him in the cradle, she learns that her wish was granted and the Goblin King Jareth has taken him to his castle in the Goblin City in the middle of a labyrinth. Sarah repents and asks Jareth to give Toby back; but the Goblin King tells her that she has to rescue her brother before midnight. Soon Sarah teams up with some allies. Will they rescue Toby in time?', 'https://image.tmdb.org/t/p/w500/hbSdA1DmNA9IlfVoqJkIWYF2oYm.jpg', null, null),
  ('Legion', 2010, false, 'R', 'Scott Stewart', '2010-01-22'::date, '100 min', 'Action, Fantasy, Horror', 'Peter Schink, Scott Stewart', 'Paul Bettany, Dennis Quaid, Charles S. Dutton', 'An out-of-the-way diner becomes the unlikely battleground for the survival of the human race. When God loses faith in humankind, he sends his legion of angels to bring on the Apocalypse. Humanity''s only hope lies in a group of strangers trapped in a desert diner with the Archangel Michael (Bettany).', 'https://image.tmdb.org/t/p/w500/ykocDqwg5PRUopnBVb1x1DWnEJF.jpg', null, null),
  ('Lethal Weapon', 1987, false, 'R', 'Richard Donner', '1987-03-06'::date, '109 min', 'Action, Crime, Thriller', 'Shane Black, Jeffrey Boam', 'Mel Gibson, Danny Glover, Gary Busey', 'Martin Riggs is an L.A. cop with suicidal tendencies and Roger Murtaugh is the unlucky police officer with whom Riggs is assigned. Together they uncover a huge drug-smuggling operation, and as their success rate grows so does their friendship.', 'https://image.tmdb.org/t/p/w500/6gt44oqb4nE8vflPElffeGwsHVl.jpg', null, null),
  ('Lethal Weapon 2', 1989, false, 'R', 'Richard Donner', '1989-07-07'::date, '114 min', 'Action, Crime, Thriller', 'Jeffrey Boam, Shane Black, Warren Murphy', 'Mel Gibson, Danny Glover, Joe Pesci', 'Riggs and Murtaugh are trying to take down some drug dealers but the they turn out to be not run of the mill drug dealers; they have automatic weapons and helicopters. Eventually they grab one of their vehicles and find a million dollars worth of gold coins or Krugerrands in the trunk. Later Murtaugh is threatened by the men they''re pursuing. That''s when the Captain reassigns them to protect a man named Leo Getz who is suppose to testify in a big case. When they get to where Leo is, someone tries to kill him and that''s when they learn he laundered half a billion dollars worth of drug money. He then takes them to a place he once went to and that''s when the people there start shooting at them. Later when they come back with back up they learn that the men work for the South African consulate and have diplomatic immunity. They deduce that they are the ones they were looking for, but because of they have diplomatic immunity they can''t do anything.', 'https://image.tmdb.org/t/p/w500/ZsUGxTnZ4TzTrHSAfUPJcliL1K.jpg', null, null),
  ('Lethal Weapon 3', 1992, false, 'R', 'Richard Donner', '1992-05-15'::date, '118 min', 'Action, Crime, Thriller', 'Jeffrey Boam, Robert Mark Kamen, Shane Black', 'Mel Gibson, Danny Glover, Joe Pesci', 'Archetypal buddy cops Riggs and Murtaugh are back for another round of high-stakes action, this time setting their collective sights on bringing down a former Los Angeles police lieutenant turned black market weapons dealer. Lorna Cole joins as the beautiful yet hardnosed internal affairs sergeant who catches Riggs''s eye.', 'https://image.tmdb.org/t/p/w500/smzJxEnusgqv3bvHIWwf4cuwPcr.jpg', null, null),
  ('Life', 2017, false, 'R', 'Daniel Espinosa', '2017-03-24'::date, '104 min', 'Horror, Sci-Fi, Thriller', 'Rhett Reese, Paul Wernick', 'Jake Gyllenhaal, Rebecca Ferguson, Ryan Reynolds', 'Six astronauts aboard the space station study a sample collected from Mars that could provide evidence for extraterrestrial life on the Red Planet. The crew determines that the sample contains a large, single-celled organism - the first example of life beyond Earth. But..things aren''t always what they seem. As the crew begins to conduct research, and their methods end up having unintended consequences, the life form proves more intelligent than anyone ever expected.', 'https://image.tmdb.org/t/p/w500/wztfli5NgYDgurVgShNflvnyA3Z.jpg', null, null),
  ('Limitless', 2011, true, 'PG-13', 'Neil Burger', '2011-03-18'::date, '105 min', 'Sci-Fi, Thriller', 'Leslie Dixon, Alan Glynn', 'Bradley Cooper, Anna Friel, Abbie Cornish', 'An action-thriller about a writer who takes an experimental drug that allows him to use 100% of his mind. As one man evolves into the perfect version of himself, forces more corrupt than he can imagine mark him for assassination. Out-of-work writer Eddie Morra''s (Cooper) rejection by girlfriend Lindy (Abbie Cornish) confirms his belief that he has zero future. That all vanishes the day an old friend introduces Eddie to NZT, a designer pharmaceutical that makes him laser-focused and more confident than any man alive. Now on an NZT-fueled odyssey, everything Eddie''s read, heard or seen is instantly organized and available to him. As the former nobody rises to the top of the financial world, he draws the attention of business mogul Carl Van Loon (De Niro), who sees this enhanced version of Eddie as the tool to make billions, but brutal side effects jeopardize his meteoric ascent. With a dwindling stash and hit men who will eliminate him to get the NZT, Eddie must stay wired long enough to elude capture and fulfill his destiny. If he can''t, he will become just another victim who thought he''d found invincibility in a bottle.', 'https://image.tmdb.org/t/p/w500/kCokPP4WCQRrrAuZ7FcpIyHr8b2.jpg', null, null),
  ('Edge of Tomorrow', 2014, false, 'PG-13', 'Doug Liman', '2014-06-06'::date, '113 min', 'Action, Adventure, Sci-Fi', 'Christopher McQuarrie, Jez Butterworth, John-Henry Butterworth', 'Tom Cruise, Emily Blunt, Bill Paxton', 'An alien race has hit the Earth in an unrelenting assault, unbeatable by any military unit in the world. Major William Cage (Cruise) is an officer who has never seen a day of combat when he is unceremoniously dropped into what amounts to a suicide mission. Killed within minutes, Cage now finds himself inexplicably thrown into a time loop-forcing him to live out the same brutal combat over and over, fighting and dying again...and again. But with each battle, Cage becomes able to engage the adversaries with increasing skill, alongside Special Forces warrior Rita Vrataski (Blunt). And, as Cage and Vrataski take the fight to the aliens, each repeated encounter gets them one step closer to defeating the enemy!', 'https://image.tmdb.org/t/p/w500/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg', null, null),
  ('Logan', 2017, true, 'R', 'James Mangold', '2017-03-03'::date, '137 min', 'Action, Drama, Sci-Fi', 'James Mangold, Scott Frank, Michael Green', 'Hugh Jackman, Patrick Stewart, Dafne Keen', 'In 2029 the mutant population has shrunken significantly due to genetically modified plants designed to reduce mutant powers and the X-Men have disbanded. Logan, whose power to self-heal is dwindling, has surrendered himself to alcohol and now earns a living as a chauffeur. He takes care of the ailing old Professor X whom he keeps hidden away. One day, a female stranger asks Logan to drive a girl named Laura to the Canadian border. At first he refuses, but the Professor has been waiting for a long time for her to appear. Laura possesses an extraordinary fighting prowess and is in many ways like Wolverine. She is pursued by sinister figures working for a powerful corporation; this is because they made her, with Logan''s DNA. A decrepit Logan is forced to ask himself if he can or even wants to put his remaining powers to good use. It would appear that in the near-future, the times in which they were able put the world to rights with razor sharp claws and telepathic powers are now over.', 'https://image.tmdb.org/t/p/w500/fnbjcRDYn6YviCcePDnGdyAkYsB.jpg', null, null),
  ('Lucy', 2014, false, 'R', 'Luc Besson', '2014-07-25'::date, '89 min', 'Action, Sci-Fi, Thriller', 'Luc Besson', 'Scarlett Johansson, Morgan Freeman, Choi Min-sik', 'It was supposed to be a simple job. All Lucy had to do was deliver a mysterious briefcase to Mr. Jang. But immediately Lucy is caught up in a nightmarish deal where she is captured and turned into a drug mule for a new and powerful synthetic drug. When the bag she is carrying inside of her stomach leaks, Lucy''s body undergoes unimaginable changes that begins to unlock her mind''s full potential. With her new-found powers, Lucy turns into a merciless warrior intent on getting back at her captors. She receives invaluable help from Professor Norman, the leading authority on the human mind, and French police captain Pierre Del Rio.', 'https://image.tmdb.org/t/p/w500/dhjyfcwEoW6jJ4Q7DpZTp6E58GA.jpg', null, null),
  ('Lyle', 2014, false, 'Not Rated', 'Stewart Thorndike', '2014-07-12'::date, '62 min', 'Drama, Horror', 'Stewart Thorndike', 'Gaby Hoffmann, Ingrid Jungermann, Eleanor Hopkins', 'A mother''s grief over the death of her toddler leads to horror.', 'https://image.tmdb.org/t/p/w500/4FRemdj1umhlu11hpVXEuqGeFC0.jpg', null, null),
  ('Mad Max: Fury Road', 2015, false, 'R', 'George Miller', '2015-05-15'::date, '120 min', 'Action, Adventure, Sci-Fi', 'George Miller, Brendan McCarthy, Nick Lathouris', 'Tom Hardy, Charlize Theron, Nicholas Hoult', 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and almost everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order. There''s Max, a man of action and a man of few words, who seeks peace of mind following the loss of his wife and child in the aftermath of the chaos. And Furiosa, a woman of action and a woman who believes her path to survival may be achieved if she can make it across the desert back to her childhood homeland.', 'https://image.tmdb.org/t/p/w500/hA2ple9q4qnwxp3hKVNhroipsir.jpg', null, null),
  ('Magic Mike', 2012, false, 'R', 'Steven Soderbergh', '2012-06-29'::date, '110 min', 'Comedy, Drama, Music', 'Reid Carolin', 'Channing Tatum, Alex Pettyfer, Olivia Munn', 'Mike Lane is a thirty-year old living in Tampa, Florida. By day he works as a roofer while at night, as Magic Mike, he is the star attraction of the Kings of Tampa, a group of male strippers. Secretly he wants out in order to further a projected furniture-making business but his credit rating precludes a bank loan for this despite his considerable savings. One night Adam, a teen-aged work-mate of Mike, follows him to the club and, when one of the acts is unable to go on, he is prevailed upon to strip - becoming a huge hit. However success goes to his head and his foolish actions not only threaten to jeopardize his sister Brooke''s relationship with Mike but Mike''s ambitions as well.', 'https://image.tmdb.org/t/p/w500/cfRv1INLSSumjvxAqEGOP6b0Aw1.jpg', null, null),
  ('Mallrats', 1995, false, 'R', 'Kevin Smith', '1995-10-20'::date, '94 min', 'Comedy, Romance', 'Kevin Smith', 'Shannen Doherty, Jeremy London, Jason Lee', 'Brodie Bruce, a Sega and comic book obsessed college student, and his best friend, TS Quint, are both dumped by their girlfriends on the same day, and to deal with their loss, they both go to the local mall. Along the way, they meet up with some friends, including Willam, a guy who stares at Magic Eye pictures, desprately trying to see the hidden image; Gwen, one of TS''s ex-girlfriends; and Jay &amp; Silent Bob, of Clerks fame. Eventually, they decide to try and win back their significant others, and take care of their respective nemesises (TS''s girlfriend''s father, and a store clerk who hates the two for not having any shopping agenda).', 'https://image.tmdb.org/t/p/w500/2ip0sGIMPN0XEN6q3lQIoaNI6tP.jpg', null, null),
  ('The LEGO Movie', 2014, false, 'PG', 'Phil Lord, Christopher Miller', '2014-02-07'::date, '100 min', 'Animation, Action, Adventure', 'Phil Lord, Christopher Miller, Dan Hageman', 'Chris Pratt, Will Ferrell, Elizabeth Banks', 'The LEGO Movie is a 3D animated film which follows lead character, Emmet a completely ordinary LEGO mini-figure who is identified as the most "extraordinary person" and the key to saving the Lego universe. Emmet and his friends go on an epic journey to stop the evil tyrant, Lord Business.', 'https://image.tmdb.org/t/p/w500/lbctonEnewCYZ4FYoTZhs8cidAl.jpg', null, null),
  ('Man on Fire', 2004, false, 'R', 'Tony Scott', '2004-04-23'::date, '146 min', 'Action, Crime, Drama', 'A.J. Quinnell, Brian Helgeland', 'Denzel Washington, Christopher Walken, Dakota Fanning', 'Hard-drinking, burnt-out ex-CIA operative John Creasy has given up on life until he''s hired as a bodyguard to protect 9-year-old Pita Ramos. Bit by bit, Creasy begins to reclaim some of his soul, but when Pita is kidnapped, Creasy''s fiery rage is finally released and he will stop at nothing to save her as he sets out on a dangerous, revenge-fueled rescue mission.', 'https://image.tmdb.org/t/p/w500/grCGLCcTHv9TChibzOwzUpykcjB.jpg', null, null),
  ('Mars Attacks!', 1996, false, 'PG-13', 'Tim Burton', '1996-12-13'::date, '106 min', 'Comedy, Sci-Fi', 'Len Brown, Woody Gelman, Wally Wood', 'Jack Nicholson, Pierce Brosnan, Sarah Jessica Parker', 'It is a normal day for everyone, until President of the United States James Dale (Jack Nicholson) announces Martians have been spotted circling Earth. The Martians land and a meeting is arranged, but not everything goes to plan, and the Martians seem to have other plans for Earth. Are they just misunderstood beings or do they really want to destroy all of humanity?', 'https://image.tmdb.org/t/p/w500/vUbGCNSEilGvxRQZi2kfTPRP0pS.jpg', null, null),
  ('Marshall', 2017, false, 'PG-13', 'Reginald Hudlin', '2017-10-13'::date, '118 min', 'Biography, Crime, Drama', 'Michael Koskoff, Jacob Koskoff', 'Chadwick Boseman, Josh Gad, Kate Hudson', 'In 1940, Thurgood Marshall is a young lawyer for the NAACP who criss-crosses the country defending innocent African-Americans from unjust indictments in court. His latest case is in Bridgeport, Connecticut where an African-American chauffeur is accused of rape of a wealthy white society woman. To admit Marshall into the local Bar, insurance lawyer Sam Friedman is picked over his objections to do introductions in court. However, Friedman''s commitment changes drastically when the racist judge forbids Marshall to speak in court, forcing Friedman to act as lead counsel. Now in an intolerable situation for the pair, Marshall must guide his new compatriot through this criminal trial even as Friedman endures not only this unfamiliar area of law, but also the bigoted pressure he now must share. However, the case proves more complex than either anticipates with unexpected twists and turns even as it becomes a vital one that would define two careers as well as the fight for justice in America.', 'https://image.tmdb.org/t/p/w500/2KfdXsXTCbMie0wB1mSmIX60C2F.jpg', null, null),
  ('The Avengers', 2012, true, 'PG-13', 'Joss Whedon', '2012-05-04'::date, '143 min', 'Action, Sci-Fi', 'Joss Whedon, Zak Penn', 'Robert Downey Jr., Chris Evans, Scarlett Johansson', 'Loki, the adopted brother of Thor, teams-up with the Chitauri Army and uses the Tesseract''s power to travel from Asgard to Midgard to plot the invasion of Earth and become a king. The director of the agency S.H.I.E.L.D., Nick Fury, sets in motion project Avengers, joining Tony Stark a.k.a. the Iron Man; Steve Rogers, a.k.a. Captain America; Bruce Banner, a.k.a. The Hulk; Thor; Natasha Romanoff, a.k.a. Black Widow; and Clint Barton, a.k.a. Hawkeye, to save the world from the powerful Loki and the alien invasion.', 'https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', null, null),
  ('Men in Black', 1997, false, 'PG-13', 'Barry Sonnenfeld', '1997-07-02'::date, '98 min', 'Action, Adventure, Comedy', 'Lowell Cunningham, Ed Solomon', 'Tommy Lee Jones, Will Smith, Linda Fiorentino', 'Based off of the comic book. Unbeknownst to other people, there is a private agency code named MiB. This agency is some kind of extra terrestrial surveillance corporation. Then, one of the agency''s finest men only going by the name "K" (Tommy Lee Jones) , is recruiting for a new addition to the agency. He has chosen James Edwards (Will Smith) of the N.Y.P.D. Then, one day, a flying saucer crashes into Earth. This was an alien a part of the "Bug" race. He takes the body of a farmer (Vincent D''Onofrio) and heads to New York. He is searching for a super energy source called "The Galaxy". Now, Agents J and K must stop the bug before it can escape with the galaxy.', 'https://image.tmdb.org/t/p/w500/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg', null, null),
  ('Men in Black', 2012, false, 'PG-13', 'Barry Sonnenfeld', '2012-05-25'::date, '106 min', 'Action, Adventure, Comedy', 'Etan Cohen, Lowell Cunningham', 'Will Smith, Tommy Lee Jones, Josh Brolin', 'After breaking out of LunarMax, a moon-based maximum security prison, Boris the Animal (Jemaine Clement) decides to go back in time and eliminate the person who arrested him - Agent K (Josh Brolin). When he does so, Agent J (Will Smith) realizes that the timeline has been changed and he too travels back to July 15, 1969, the day before Agent K is killed. After overcoming some disbelief, J manages to convince young K and others of just who he is and why he''s there. With the help of Griffin (Michael Stuhlbarg), a being who can see all timelines, they track Boris down. J also learns a secret, something old Agent K (Tommy Lee Jones) had never told him.', 'https://image.tmdb.org/t/p/w500/uLOmOF5IzWoyrgIF5MfUnh5pa1X.jpg', null, null),
  ('Men in Black II', 2002, false, 'PG-13', 'Barry Sonnenfeld', '2002-07-03'::date, '88 min', 'Action, Adventure, Comedy', 'Lowell Cunningham, Robert Gordon, Barry Fanaro', 'Tommy Lee Jones, Will Smith, Rip Torn', 'Kay and Jay reunite to provide our best, last and only line of defense against a sinister seductress who levels the toughest challenge yet to the MIBs untarnished mission statement: protecting the earth from the scum of the universe. It''s been four years since the alien-seeking agents averted an intergalactic disaster of epic proportions. And now it''s a race against the clock as Jay must convince Kay-who not only has absolutely no memory of his time spent with the Men In Black, but is also the only living person left with the expertise to save the galaxy-to reunite with the MIB before the earth submits to ultimate destruction.', 'https://image.tmdb.org/t/p/w500/enA22EPyzc2WQ1VVyY7zxresQQr.jpg', null, null),
  ('Men of Honor', 2000, false, 'R', 'George Tillman Jr.', '2000-11-10'::date, '129 min', 'Biography, Drama', 'Scott Marshall Smith', 'Cuba Gooding Jr., Robert De Niro, Charlize Theron', 'The story ultimately revolves around two "men of honor"; their relationship, their individual and joint failures and triumphs. Carl Brashear is determined to be the first African American Navy Diver in a time where racism is rife. Leslie Sunday is his embittered trainer, determined to see him fail. Fate, challenges and circumstances eventually draw these two men together in a tale of turbulence and ultimately triumph.', 'https://image.tmdb.org/t/p/w500/wNUAnXV1mzOOfvnVBIYsalkk078.jpg', null, null),
  ('Minority Report', 2002, false, 'PG-13', 'Steven Spielberg', '2002-06-21'::date, '145 min', 'Action, Crime, Mystery', 'Scott Frank, Jon Cohen, Philip K. Dick', 'Tom Cruise, Colin Farrell, Samantha Morton', 'In the year 2054 A.D. crime is virtually eliminated from Washington D.C. thanks to an elite law enforcing squad "Precrime". They use three gifted humans (called "Pre-Cogs") with special powers to see into the future and predict crimes beforehand. John Anderton heads Precrime and believes the system''s flawlessness steadfastly. However one day the Pre-Cogs predict that Anderton will commit a murder himself in the next 36 hours. Worse, Anderton doesn''t even know the victim. He decides to get to the mystery''s core by finding out the ''minority report'' which means the prediction of the female Pre-Cog Agatha that "might" tell a different story and prove Anderton innocent.', 'https://image.tmdb.org/t/p/w500/qtgFcnwh9dAFLocsDk2ySDVS8UF.jpg', null, null),
  ('Mission to Mars', 2000, false, 'PG', 'Brian De Palma', '2000-03-10'::date, '114 min', 'Adventure, Sci-Fi, Thriller', 'Lowell Cannon, Jim Thomas, John Thomas', 'Tim Robbins, Gary Sinise, Don Cheadle', 'When a mysterious storm kills all but one crew member of the first manned mission to mars, a rescue mission is launched. Once on the red planet, the crew finds the sole survivor of the first mission who informs them that this was no ordinary storm. It was meant to protect something. But what?', 'https://image.tmdb.org/t/p/w500/cTKWoBpN5Gvi0vpMb9mLtYlwXqT.jpg', null, null),
  ('Mission: Impossible - Dead Reckoning', 2023, true, 'PG-13', 'Christopher McQuarrie', '2023-07-12'::date, '163 min', 'Action, Adventure, Thriller', 'Bruce Geller, Christopher McQuarrie, Erik Jendresen', 'Tom Cruise, Hayley Atwell, Ving Rhames', 'Ethan Hunt and his IMF team must track down a dangerous weapon before it falls into the wrong hands.', 'https://image.tmdb.org/t/p/w500/NNxYkU70HPurnNCSiCjYAmacwm.jpg', null, null),
  ('Moana', 2016, true, 'PG', 'Ron Clements, John Musker, Don Hall', '2016-11-23'::date, '107 min', 'Animation, Adventure, Comedy', 'Jared Bush, Ron Clements, John Musker', 'Auli''i Cravalho, Dwayne Johnson, Rachel House', 'Moana Waialiki is a sea voyaging enthusiast and the only daughter of a chief in a long line of navigators. When her island''s fishermen can''t catch any fish and the crops fail, she learns that the demigod Maui caused the blight by stealing the heart of the goddess, Te Fiti. The only way to heal the island is to persuade Maui to return Te Fiti''s heart, so Moana sets off on an epic journey across the Pacific. The film is based on stories from Polynesian mythology.', 'https://image.tmdb.org/t/p/w500/9tzN8sPbyod2dsa0lwuvrwBDWra.jpg', null, null),
  ('Mobsters', 1991, false, 'R', 'Michael Karbelnikoff', '1991-07-26'::date, '104 min', 'Crime, Drama', 'Michael Mahern, Nicholas Kazan', 'Christian Slater, Patrick Dempsey, Rodney Eastman', 'The story of a group of friends in turn of the century New York City, from their early days as street hoods to their rise in the world of organized crime. As their crime empire expands, they have to deal with many problems, including their own differing opinions on how to run their business, the local Godfather, Don Faranzano (Sir Michael Gambon), and the psychotic Mad Dog Coll (Nicholas Sadler).', 'https://image.tmdb.org/t/p/w500/l7GfcGzH4UQzzP0Q3EfBiDbm5yu.jpg', null, null),
  ('Monster House', 2006, false, 'PG', 'Gil Kenan', '2006-07-21'::date, '91 min', 'Animation, Comedy, Family', 'Dan Harmon, Rob Schrab, Pamela Pettler', 'Mitchel Musso, Sam Lerner, Spencer Locke', '13-year-old DJ is observing his neighbor Nebbercracker on the other side of the street in the suburb that destroys tricycles of children that trespass his lawn. When DJ''s parents travel on the eve of Halloween and the abusive babysitter Zee stays with him, he calls his clumsy best friend Chowder to play basketball. But when the ball falls in Nebbercracker''s lawn, the old man has a heart attack, and soon they find that the house is a monster. Later the boys rescue the smart Jenny from the house and the trio unsuccessfully tries to convince the babysitter, her boyfriend Bones and two police officers that the haunted house is a monster, but nobody believes them. The teenagers ask their video-game addicted acquaintance Skull how to destroy the house, and they disclose its secret on the Halloween night.', 'https://image.tmdb.org/t/p/w500/zCRPr4bkO3ae0U1134vJ39xZnAG.jpg', null, null),
  ('Monster-in-Law', 2005, false, 'PG-13', 'Robert Luketic', '2005-05-13'::date, '101 min', 'Comedy, Romance', 'Anya Kochoff', 'Jennifer Lopez, Michael Vartan, Jane Fonda', 'After years of looking for Mr. Right, Charlotte ''Charlie'' Cantilini finally finds the man of her dreams, Kevin Fields, only to discover that his mother, Viola, is the woman of her nightmares. A recently fired news anchor who is afraid she will lose her son the way she has just lost her career, Viola determines to scare off her son''s new fiancé by becoming the world''s worst mother-in-law. While Viola''s long-time assistant Ruby does her best to help Viola execute her crazy schemes, Charlie decides to fight back and the gloves come off as the two women battle it out to see just who is the alpha-female.', 'https://image.tmdb.org/t/p/w500/iRqcGkIPdRbEaW0xMEA5kgceUF8.jpg', null, null),
  ('The Meaning of Life', 1983, false, 'R', 'Terry Jones', '1983-03-31'::date, '107 min', 'Comedy, Musical', 'Graham Chapman, John Cleese, Terry Gilliam', 'John Cleese, Terry Gilliam, Eric Idle', 'Why are we here, what''s it all about? The Monty Python team is trying to sort out the most important question on Earth: what is the meaning of life? They do so by exploring the various stages of life, starting with birth. A doctor seems more interested in his equipment than in delivering the baby or caring for the mother, a Roman Catholic couple have quite a lot of children because "every sperm is sacred". In the growing and learning part of life, Catholic schoolboys attend a rather strange church service and ditto sex education lesson. Onto war, where an officer''s plan to attack is thwarted by his underlings wanting to celebrate his birthday, and an officer''s leg is bitten off by presumably an African tiger. At middle age, a couple orders "philosophy" at a restaurant, after which, the movie continues with live organ transplants. The autumn years are played in a restaurant, which, after being treated to the song "Isn''t It Awfully Nice to Have a Penis?" by an entertainer, sees the arrival of an extremely fat man. He can eat a lot, but also throw up quite copiously. The Grim Reaper brings for the final stage of human life, death, a visit to a mansion, where the people are rather interested in him. But life doesn''t stop at death. It''s onto heaven, where it''s always Christmas.', 'https://image.tmdb.org/t/p/w500/9yavZ9WgEZIpWi2EbVW8At9RPdo.jpg', null, null),
  ('Mrs. Doubtfire', 1993, false, 'PG-13', 'Chris Columbus', '1993-11-24'::date, '125 min', 'Comedy, Drama', 'Anne Fine, Randi Mayem Singer, Leslie Dixon', 'Robin Williams, Sally Field, Pierce Brosnan', 'Eccentric actor Daniel Hillard is an amusing and caring father. But after a disastrous birthday party for his son, Chris, his wife, Miranda, draws the line and files a divorce. He can see their three children only once a week which doesn''t sit well with him. He also holds a job at a TV studio as a shipping clerk under the recommendation of his liason. But when Miranda puts out an ad for a nanny, he takes it upon himself to make a disguise as a British lady named Mrs. Doubtfire. And he must also deal with Miranda''s new boyfriend, Stu Dunemyer.', 'https://image.tmdb.org/t/p/w500/shHrSmXS5140o6sQzgzXxn3KqSm.jpg', null, null),
  ('Mystery Science Theater 3000: The Movie', 1996, false, 'PG-13', 'Jim Mallon', '1996-04-19'::date, '73 min', 'Comedy, Drama, Fantasy', 'Michael J. Nelson, Trace Beaulieu, Jim Mallon', 'Trace Beaulieu, Michael J. Nelson, Jim Mallon', 'The mad and evil scientist, Dr. Clayton Forrester, has created an evil little scheme that is bound to give him world global domination but first thing''s first. He plans to torment Mike Nelson and the robots by sending them a real stinker of a film to watch called, "This Island Earth." He is convinced that this movie will drive them insane. And since the guys cannot control when the movie begins or ends, they are forced to witness the true horror that is this awful movie that has a lobster creature dressed in slacks. But will this be the ultimate cheese that breaks the boys'' spirits? It''s up to one test subject''s quick wit, sharp sense of humor, and utter intolerance for cinematic garbage to foil the plans of the scientist and to save the Earth.', 'https://image.tmdb.org/t/p/w500/tlakU3uwNiUgd7aOlb2RoAsGTnY.jpg', null, null),
  ('National Lampoon''s Animal House', 1978, false, 'R', 'John Landis', '1978-07-28'::date, '109 min', 'Comedy', 'Harold Ramis, Douglas Kenney, Chris Miller', 'John Belushi, Karen Allen, Tom Hulce', 'Faber College has one frat house so disreputable it will take anyone. It has a second one full of white, anglo-saxon, rich young men who are so sanctimonious no one can stand them except Dean Wormer. The dean enlists the help of the second frat to get the boys of Delta House off campus. The dean''s plan comes into play just before the homecoming parade to end all parades for all time.', 'https://image.tmdb.org/t/p/w500/fWooBbipMRIKeSRhEzmeaDV0T8H.jpg', null, null),
  ('Night at the Museum', 2006, false, 'PG', 'Shawn Levy', '2006-12-22'::date, '108 min', 'Adventure, Comedy, Family', 'Robert Ben Garant, Thomas Lennon, Milan Trenc', 'Ben Stiller, Carla Gugino, Ricky Gervais', 'In New York, unemployed and divorced Larry Daley is a complete loser. His son Nick is very disappointed with his father who is going to be evicted. Larry accepts the job of night watchman in the Museum of Natural History and takes the place of three old security guards that have just retired in order to raise some money and pay his bills. On his first shift, Larry soon realizes that everything at the museum is not as it seems as the statues begin to come to life after the sun sets. The Museum transforms into complete chaos with the inexperienced Larry in charge as he learns that an old Egyptian stone that came to the Museum in 1950 brings these statues to life until dawn. When Larry brings his son to spend a night with him, the three old guards break into the Museum to try to steal the magical stone. Larry organizes all the historic characters to help him stop the criminals and save the museum.', 'https://image.tmdb.org/t/p/w500/pDsAAYf6Zn0yiAGJ6lYGs6hoZ4E.jpg', null, null),
  ('Observance', 2015, false, 'Not Rated', 'Joseph Sims-Dennett', '2016-04-07'::date, '87 min', 'Drama, Horror, Mystery', 'Joseph Sims-Dennett, Josh Zammit', 'Stephanie King, Lindsay Farris, Brendan Cowell', 'In the grip of grief following the death of his young son, his marriage on the rocks and nearing bankruptcy, Parker reluctantly returns to work as a private investigator. Embarking on an unusual assignment to observe a woman from an abandoned apartment, Parker witnesses bizarre happenings surrounding her, unaware that the derelict building that he surveys her from has birthed a dark presence which slowly threatens to consume him.', 'https://image.tmdb.org/t/p/w500/1IlUgK8p19iOkk4u9sUEeenWNgf.jpg', null, null),
  ('Oppenheimer', 2023, true, 'R', 'Christopher Nolan', '2023-07-21'::date, '180 min', 'Biography, Drama, History', 'Christopher Nolan, Kai Bird, Martin Sherwin', 'Cillian Murphy, Emily Blunt, Matt Damon', 'A dramatization of the life story of J. Robert Oppenheimer, the physicist who had a large hand in the development of the atomic bomb, thus helping end World War 2. We see his life from university days all the way to post-WW2.', 'https://image.tmdb.org/t/p/w500/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', null, null),
  ('Orphan', 2009, false, 'R', 'Jaume Collet-Serra', '2009-07-24'::date, '123 min', 'Horror, Mystery, Thriller', 'David Leslie Johnson-McGoldrick, Alex Mace', 'Vera Farmiga, Peter Sarsgaard, Isabelle Fuhrman', 'Kate and John Coleman are rebuilding their troubled marriage after the loss of their baby. The couple decide to adopt a child. When they meet 9-year-old Esther at the St. Marina Orphanage, they immediately fall in love with the well-educated orphan. Their son, Daniel is hostile to his new sister, but their deaf mute daughter, Max is enchanted with her - at first. Eventually, Kate begins to feel that Esther is manipulative and possibly even psychologically damaged. John refuses to listen to his wife''s misgivings. Kate calls Sister Abigail at the orphanage, and the nun informs her that Esther has a troubled and mysterious history. Kate delves further into Esther''s past and discovers she is not what she seems to be.', 'https://image.tmdb.org/t/p/w500/lCGpOgoTOGLtZnBiGY9HRg5Xnjd.jpg', null, null),
  ('Ouija: Origin of Evil', 2016, false, 'PG-13', 'Mike Flanagan', '2016-10-21'::date, '99 min', 'Drama, Horror, Mystery', 'Mike Flanagan, Jeff Howard, Juliet Snowden', 'Elizabeth Reaser, Lulu Wilson, Annalise Basso', 'In 1967 Los Angeles, a young widow named Alice Zander works out of her suburban home as a spiritual medium, accompanied by her daughters, 15-year-old Paulina "Lina" and 9-year old Doris. The family is still reeling over the recent death of Roger, Alice''s husband and the kids'' father. At Lina''s suggestion, Alice incorporates a Ouija board into her readings. While trying out the board, she unknowingly contacts a spirit named Marcus that begins to possess Doris. Alice receives a notice that the bank intends to foreclose on their home. Doris contacts the board for help, believing she is communicating with her dead father. The spirit leads her to a secret compartment behind the basement wall containing a pouch of cash. When she gives the money to her mother, the family has an Ouija session, believing they can contact Roger. When the board answers a question only Roger would know the answer to, a thrilled Alice begins believing that they are in contact with her dead husband..', 'https://image.tmdb.org/t/p/w500/gwynHc2RrOFaplYMMpQRpr3TIA4.jpg', null, null),
  ('Pacific Rim', 2013, false, 'PG-13', 'Guillermo del Toro', '2013-07-12'::date, '131 min', 'Action, Adventure, Sci-Fi', 'Travis Beacham, Guillermo del Toro', 'Idris Elba, Charlie Hunnam, Rinko Kikuchi', 'When monstrous creatures, known as Kaiju, started rising from the sea, a war began that would take millions of lives and consume humanity''s resources for years on end. To combat the giant Kaiju, a special type of weapon was devised: massive robots, called Jaegers, which are controlled simultaneously by two pilots whose minds are locked in a neural bridge. But even the Jaegers are proving nearly defenseless in the face of the relentless Kaiju. On the verge of defeat, the forces defending mankind have no choice but to turn to two unlikely heroes - a washed up former pilot (Charlie Hunnam) and an untested trainee (Rinko Kikuchi) - who are teamed to drive a legendary but seemingly obsolete Jaeger from the past. Together, they stand as mankind''s last hope against the mounting apocalypse.', 'https://image.tmdb.org/t/p/w500/8wo4eN8dWKaKlxhSvBz19uvj8gA.jpg', null, null),
  ('Paul', 2011, false, 'R', 'Greg Mottola', '2011-03-18'::date, '104 min', 'Adventure, Comedy, Sci-Fi', 'Simon Pegg, Nick Frost', 'Simon Pegg, Nick Frost, Seth Rogen', 'Two sci-fi geeks take a pilgrimage to America''s UFO heartland. While there, they accidentally meet an alien who brings them on an insane road trip that alters their universe forever. For the past 60 years, an alien named Paul (voiced by Seth Rogen) has been hanging out at a top-secret military base. When he discovers he''s been taken prisoner, the space-traveling smart ass decides to escape the compound and hop on the first vehicle out of town - a rented RV containing Earthlings Graeme Willy (Simon Pegg) and Clive Gollings (Nick Frost). Chased by federal agents and the fanatical father of a young woman that they accidentally kidnap, Graeme and Clive hatch a fumbling escape plan to return Paul to his mother ship. And as two nerds struggle to help, one little green man might just take his fellow outcasts from misfits to intergalactic heroes.', 'https://image.tmdb.org/t/p/w500/bX8TP2qRWh2OcmeUHGn1ENDkCu6.jpg', null, null),
  ('Pirates of the Caribbean: At World''s End', 2007, true, 'PG-13', 'Gore Verbinski', '2007-05-25'::date, '169 min', 'Action, Adventure, Fantasy', 'Ted Elliott, Terry Rossio, Stuart Beattie', 'Johnny Depp, Orlando Bloom, Keira Knightley', 'After Elizabeth, Will, and Captain Barbossa rescue Captain Jack Sparrow from the land of the dead, they must face their foes, Davy Jones and Lord Cutler Beckett. Beckett, now with control of Jones'' heart, forms a dark alliance with him in order to rule the seas and wipe out the last of the Pirates. Now, Jack, Barbossa, Will, Elizabeth, Tia Dalma, and crew must call the Pirate Lords from the four corners of the globe, including the infamous Sao Feng, to gathering. The Pirate Lords want to release the goddess Calypso, Davy Jones''s damned lover, from the trap they sent her to out of fear, in which the Pirate Lords must combine the 9 pieces that bound her by ritual to undo it and release her in hopes that she will help them fight. With this, all pirates will stand together and will make their final stand for freedom against Beckett, Jones, Norrington, the Flying Dutchman, and the entire East India Trading Company.', 'https://image.tmdb.org/t/p/w500/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg', null, null),
  ('Pirates of the Caribbean: Dead Man''s Chest', 2006, true, 'PG-13', 'Gore Verbinski', '2006-07-07'::date, '151 min', 'Action, Adventure, Fantasy', 'Ted Elliott, Terry Rossio, Stuart Beattie', 'Johnny Depp, Orlando Bloom, Keira Knightley', 'Once again we''re plunged into the world of sword fights and "savvy" pirates. Captain Jack Sparrow is reminded he owes a debt to Davy Jones, who captains the flying Dutchman, a ghostly ship, with a crew from hell. Facing the "locker" Jack must find the heart of Davy Jones but to save himself he must get the help of quick-witted Will Turner and Elizabeth Swan. If that''s not complicated enough, Will and Elizabeth are sentenced to hang, unless Will can get Lord Cutler Beckett Jack''s compass. Will is forced to join another crazy adventure with Jack.', 'https://image.tmdb.org/t/p/w500/lAhcKRt0ggTFkeFL95jrGQYaRXs.jpg', null, null),
  ('Pirates of the Caribbean: Dead Men Tell No Tales', 2017, true, 'PG-13', 'Joachim Rønning, Espen Sandberg', '2017-05-26'::date, '129 min', 'Action, Adventure, Fantasy', 'Jeff Nathanson, Terry Rossio, Ted Elliott', 'Johnny Depp, Geoffrey Rush, Javier Bardem', 'Captain Jack Sparrow (Johnny Depp) finds the winds of ill-fortune blowing even more strongly when deadly ghost pirates led by his old nemesis, the terrifying Captain Salazar (Javier Bardem), escape from the Devil''s Triangle, determined to kill every pirate at sea...including him. Captain Jack''s only hope of survival lies in seeking out the legendary Trident of Poseidon, a powerful artifact that bestows upon its possessor total control over the seas.', 'https://image.tmdb.org/t/p/w500/qwoGfcg6YUS55nUweKGujHE54Wy.jpg', null, null),
  ('Pirates of the Caribbean: On Stranger Tides', 2011, true, 'PG-13', 'Rob Marshall', '2011-05-20'::date, '136 min', 'Action, Adventure, Fantasy', 'Ted Elliott, Terry Rossio, Stuart Beattie', 'Johnny Depp, Penélope Cruz, Ian McShane', 'Captain Jack Sparrow (Johnny Depp) crosses paths with a woman from his past, Angelica (Penélope Cruz), and he''s not sure if it''s love, or if she''s a ruthless con artist who''s using him to find the fabled Fountain of Youth. When she forces him aboard the Queen Anne''s Revenge, the ship of the formidable pirate Blackbeard (Ian McShane), Jack finds himself on an unexpected adventure in which he doesn''t know who to fear more: Blackbeard or the woman from his past.', 'https://image.tmdb.org/t/p/w500/keGfSvCmYj7CvdRx36OdVrAEibE.jpg', null, null),
  ('Pirates of the Caribbean: The Curse of the Black Pearl', 2003, true, 'PG-13', 'Gore Verbinski', '2003-07-09'::date, '143 min', 'Action, Adventure, Fantasy', 'Ted Elliott, Terry Rossio, Stuart Beattie', 'Johnny Depp, Geoffrey Rush, Orlando Bloom', 'This swash-buckling tale follows the quest of Captain Jack Sparrow, a savvy pirate, and Will Turner, a resourceful blacksmith, as they search for Elizabeth Swann. Elizabeth, the daughter of the governor and the love of Will''s life, has been kidnapped by the feared Captain Barbossa. Little do they know, but the fierce and clever Barbossa has been cursed. He, along with his large crew, are under an ancient curse, doomed for eternity to neither live, nor die. That is, unless a blood sacrifice is made.', 'https://image.tmdb.org/t/p/w500/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', null, null),
  ('Pitch Black', 2000, false, 'R', 'David Twohy', '2000-02-18'::date, '109 min', 'Action, Horror, Sci-Fi', 'Jim Wheat, Ken Wheat, David Twohy', 'Radha Mitchell, Cole Hauser, Vin Diesel', 'The space transport vessel "Hunter-Gratzner" carrying 40 people on-board crashes on a desert planet when the ship is struck in a meteor storm. There are only 11 survivors, among them are pilot Carolyn Fry (Who has assumed command after the ship''s captain is killed), bounty hunter William J. Johns, religious man Abu Al-Walid, Antiques dealer Paris P. Ogilvie, runaway teenager Jack, settlers John ''Zeke'' Ezekiel and his lover Sharon ''Shazza'' Montgomery, and Richard B. Riddick, a dangerous escaped convict. Marooned, the survivors discover the barren and hot desert-scape has sunlight from three suns. Not only must they find food and water and worry about Riddick, the survivors find themselves being hunted by the planet''s flesh-eating alien inhabitants when the planet is engulfed in darkness, which happens every 22 years, as they emerge from underground to hunt and eat all signs of life. Fry and the survivors find Riddick is their best chance of survival, as Riddick has surgically-enhanced eyes that allow him to see in the dark as they set out to find a way of escaping from the planet and getting to an escape shuttle, before they all get eaten by the creatures on the surface.', 'https://image.tmdb.org/t/p/w500/3AnlxZ5CZnhKKzjgFyY6EHxmOyl.jpg', null, null),
  ('Point Break', 1991, false, 'R', 'Kathryn Bigelow', '1991-07-12'::date, '122 min', 'Action, Crime, Thriller', 'Rick King, W. Peter Iliff', 'Patrick Swayze, Keanu Reeves, Gary Busey', 'In Los Angeles, California, a gang of bank robbers call themselves The Ex-Presidents. commit their crimes while wearing masks of ex-Presidents Reagan, Carter, Nixon, and Johnson. The F.B.I. believes that the members of the gang could be surfers, and send young Agent Johnny Utah undercover at the beach to mix with the surfers and gather information. Utah meets surfer Bodhi, and gets drawn into the lifestyle of his new friend.', 'https://image.tmdb.org/t/p/w500/tlbERIghrQ4oofqlbF7H0K0EYnx.jpg', null, null),
  ('Poltergeist', 1982, false, 'PG', 'Tobe Hooper', '1982-06-04'::date, '114 min', 'Horror, Thriller', 'Steven Spielberg, Michael Grais, Mark Victor', 'JoBeth Williams, Heather O''Rourke, Craig T. Nelson', 'A young family are visited by ghosts in their home. At first the ghosts appear friendly, moving objects around the house to the amusement of everyone, then they turn nasty and start to terrorise the family before they "kidnap" the youngest daughter.', 'https://image.tmdb.org/t/p/w500/4eMN3GANH5GG4kXdHkrTZEUuQ9M.jpg', null, null),
  ('Powder', 1995, false, 'PG-13', 'Victor Salva', '1995-10-27'::date, '111 min', 'Drama, Fantasy, Mystery', 'Victor Salva', 'Mary Steenburgen, Sean Patrick Flanery, Lance Henriksen', 'When sheriff Barnum investigates the death of an elderly rural resident, he discovers a teenage grandson living in the basement. Raised by his grandparents, he has experienced the world only through books, never leaving the family farm. He is sent to a state home for boys where he has trouble fitting in socially. His odd appearance and unusual abilities cause the small town residents to fear and ridicule him. However, not all are afraid. Some begin to view his potential and gifts with wonderment.', 'https://image.tmdb.org/t/p/w500/aQSA63T7zyzZxBZxr2MQaxt1gtO.jpg', null, null),
  ('Practical Magic', 1998, false, 'PG-13', 'Griffin Dunne', '1998-10-16'::date, '104 min', 'Comedy, Drama, Fantasy', 'Alice Hoffman, Robin Swicord, Akiva Goldsman', 'Sandra Bullock, Nicole Kidman, Stockard Channing', 'Sisters Sally Owens (Sandra Bullock) and Gillian Owens (Nicole Kidman) have a special bond with each other despite being different in personality and outlook. Having grown up with their spinster Aunt Frances (Stockard Channing) and Aunt Jet (Dianne Wiest) in the long time Owens family house on an island off the coast of Massachusetts following the death of their father and then their mother, they are the latest in a long line of witches. Rumors of the Owens women being witches have existed for generations in the small close-minded town in which they live, despite there being no hard evidence. The Owens women are also under a curse that any man with who they fall in love is doomed. With this experience, extroverted Gillian decides to leave the island to live life to the fullest, in the process, falling for Jimmy Angelov (Goran Visnjic), a Bulgarian who grew up near Transylvania. More introspective Sally, who has sworn off the use of magic except in its most practical sense, has taken measures not to fall in love because of the curse, but ends up falling for and marrying Michael (Mark Feuerstein), a local merchant, the two who end up having two daughters of their own. The curse works its way into Gillian''s and Sally''s lives in different ways. The outcomes of the curse on their collective lives become more complicated with the arrival into town of Tuscon Police Detective Gary Hallet (Aidan Quinn), whose arrival is not by accident and involves more than just his stated professional purpose.', 'https://image.tmdb.org/t/p/w500/AwmToSgf2IL3aHv0QRVsR5KvChv.jpg', null, null),
  ('Predator', 1987, true, 'R', 'John McTiernan', '1987-06-12'::date, '107 min', 'Action, Adventure, Horror', 'Jim Thomas, John Thomas', 'Arnold Schwarzenegger, Carl Weathers, Kevin Peter Hall', 'A team of special force ops, led by a tough but fair soldier, Major "Dutch" Schaefer, are ordered to assist CIA man, Colonel Al Dillon, on a rescue mission for potential survivors of a Helicopter downed over remote South American jungle. Not long after they land, Dutch and his team discover that they have been sent in under false pretenses. This deception turns out to be the least of their worries though, when they find themselves being methodically hunted by something not of this world.', 'https://image.tmdb.org/t/p/w500/k3mW4qfJo6SKqe6laRyNGnbB9n5.jpg', 'Alien/Predator', null),
  ('Predator 2', 1990, true, 'R', 'Stephen Hopkins', '1990-11-21'::date, '108 min', 'Action, Horror, Sci-Fi', 'Jim Thomas, John Thomas', 'Danny Glover, Gary Busey, Kevin Peter Hall', 'LAPD lieutenant Mike Harrigan (Danny Glover) and his cocky detective partner Jerry Lambert (Bill Paxton) soon realize that what seemed a bloody feud between voodoo high priest King Willie''s (Calvin Lockhart) Jamaican gangs and Ramon Vega''s (Corey Rand) Colombian drug gang is actually the work of a scary third party. Peter Keyes''s (Gary Busey) federal team shields the crime scene even for the LAPD, but after forensics proves it must be an alien, who keeps making victims, the chase brings them all together.', 'https://image.tmdb.org/t/p/w500/83X4VwY9sdSJykskmsplIVG0a4h.jpg', 'Alien/Predator', null),
  ('Blink Twice', 2024, true, 'R', 'Zoë Kravitz', '2024-08-23'::date, '102 min', 'Mystery, Thriller', 'Zoë Kravitz, E.T. Feigenbaum', 'Naomi Ackie, Channing Tatum, Alia Shawkat', 'When tech billionaire Slater King meets cocktail waitress Frida at his fundraising gala, he invites her to join him and his friends on a dream vacation on his private island. As strange things start to happen, Frida questions her ...', 'https://image.tmdb.org/t/p/w500/lZGOK0I2DJSRlEPNOAFTSNxSjDD.jpg', null, null),
  ('Predators', 2010, true, 'R', 'Nimród Antal', '2010-07-09'::date, '107 min', 'Action, Adventure, Sci-Fi', 'Alex Litvak, Michael Finch, Jim Thomas', 'Adrien Brody, Laurence Fishburne, Topher Grace', 'When a group of elite warriors find themselves in a jungle they realize that they are on a completely different planet and it''s home to a race of extraterrestrial hunters. The group consists of a mercenary known as Royce, an IDF sniper known as Isabelle, a Russian Spetsnaz known as Nikolai, a drug cartel enforcer known as Cuchillo, an RUF officer known as Mombasa, a death row inmate known as Stans, a Yakuza assassin known as Hanzo, and an American doctor known as Edwin. It''s up to these 8 individuals to stop their hunters and get off the planet.', 'https://image.tmdb.org/t/p/w500/sx5EuckP7SBQrlMlxg0PLt282WS.jpg', 'Alien/Predator', null),
  ('Priest', 2011, false, 'PG-13', 'Scott Stewart', '2011-05-13'::date, '87 min', 'Action, Fantasy, Horror', 'Cory Goodman, Min-Woo Hyung', 'Paul Bettany, Cam Gigandet, Maggie Q', 'PRIEST, a post-apocalyptic action thriller, is set in an alternative world -- one ravaged by centuries of war between man and vampires. The story revolves around a legendary Warrior Priest from the last Vampire War who now lives in obscurity among the other downtrodden human inhabitants in walled-in dystopian cities ruled by the Church. When his niece is abducted by a murderous pack of vampires, Priest breaks his sacred vows to venture out on a quest to find her before they turn her into one of them. He is joined on his crusade by his niece''s boyfriend, a trigger-fingered young wasteland sheriff, and a former Warrior Priestess who possesses otherworldly fighting skills.', 'https://image.tmdb.org/t/p/w500/fYHiA7LPGl9DG7m3DUs0Td1VMcO.jpg', null, null),
  ('Prometheus', 2012, true, 'R', 'Ridley Scott', '2012-06-08'::date, '124 min', 'Adventure, Mystery, Sci-Fi', 'Jon Spaihts, Damon Lindelof, Dan O''Bannon', 'Noomi Rapace, Logan Marshall-Green, Michael Fassbender', 'Following a faint trail of clues, the accomplished archaeologist, Doctor Elizabeth Shaw, and her partner, Charlie Holloway, along with a seventeen-man crew, embark on an ambitious, deep-space scientific expedition. Aboard the revolutionary space-exploration starship, USCSS Prometheus, the team sets foot on the rocky terrain of the desolate exomoon, LV-223, in 2093, to investigate the existence of the superior extraterrestrial species known as the "Engineers". But, there, inside a mysterious, complex structure of cavernous dark chambers and an intricate underground system of tunnels, more enigmas await. Now, a terrifying discovery threatens not only the outcome of the bold outer-space mission but also the very future of humankind. Is the world prepared for the answers to the fundamental questions of human existence?', 'https://image.tmdb.org/t/p/w500/qsYQflQhOuhDpQ0W2aOcwqgDAeI.jpg', null, null),
  ('Public Enemies', 2009, false, 'R', 'Michael Mann', '2009-07-01'::date, '140 min', 'Action, Biography, Crime', 'Ronan Bennett, Michael Mann, Ann Biderman', 'Christian Bale, Johnny Depp, Christian Stolte', 'The difficult 1930s is a time of robbers who knock over banks and other rich targets with alarming frequency. Of them, none is more notorious than John Dillinger, whose gang plies its trade with cunning efficiency against big businesses while leaving ordinary citizens alone. As Dillinger becomes a folk hero, FBI head J. Edger Hoover is determined to stop his ilk by assigning ace agent Melvin Purvis to hunt down Dillinger. As Purvis struggles with the manhunt''s realities, Dillinger himself faces an ominous future with the loss of friends, dwindling options and a changing world of organized crime with no room for him.', 'https://image.tmdb.org/t/p/w500/3KgtekisQBrHRsm2cD5UOB6Ce3k.jpg', null, null),
  ('Pumpkinhead', 1988, false, 'R', 'Stan Winston', '1989-01-13'::date, '86 min', 'Fantasy, Horror', 'Ed Justin, Mark Patrick Carducci, Stan Winston', 'Lance Henriksen, Jeff East, John D''Aquino', 'After a group of teens accidentally kill a young boy named Billy Harley, his father Ed is devastated and the only thing he wants is revenge. He goes to an old woman who is said to be a witch and conjures a demonic creature known as Pumpkinhead, and unleashes him on the teens.', 'https://image.tmdb.org/t/p/w500/gx7Gej5Srp3E13oqy1Kghtox2VZ.jpg', null, null),
  ('Purple Rain', 1984, false, 'R', 'Albert Magnoli', '1984-07-27'::date, '111 min', 'Drama, Music, Romance', 'Albert Magnoli, William Blinn', 'Prince, Apollonia Kotero, Morris Day', 'A young man with a talent for music has begun a career with much promise. He meets an aspiring singer, Apollonia, and finds that talent alone isn''t all that he needs. A complicated tale of his repeating his father''s self destructive behavior, losing Apollonia to another singer (Morris Day), and his coming to grips with his own connection to other people ensues.', 'https://image.tmdb.org/t/p/w500/vkQmzaSuDj8QyXmwNhCceCAmwUe.jpg', null, null),
  ('Ready Player One', 2018, false, 'PG-13', 'Steven Spielberg', '2018-03-29'::date, '140 min', 'Action, Adventure, Sci-Fi', 'Zak Penn, Ernest Cline', 'Tye Sheridan, Olivia Cooke, Ben Mendelsohn', 'In the year 2045, the real world is a harsh place. The only time Wade Watts (Tye Sheridan) truly feels alive is when he escapes to the OASIS, an immersive virtual universe where most of humanity spends their days. In the OASIS, you can go anywhere, do anything, be anyone-the only limits are your own imagination. The OASIS was created by the brilliant and eccentric James Halliday (Mark Rylance), who left his immense fortune and total control of the Oasis to the winner of a three-part contest he designed to find a worthy heir. When Wade conquers the first challenge of the reality-bending treasure hunt, he and his friends-aka the High Five-are hurled into a fantastical universe of discovery and danger to save the OASIS.', 'https://image.tmdb.org/t/p/w500/pU1ULUq8D3iRxl1fdX2lZIzdHuI.jpg', null, null),
  ('Real Genius', 1985, false, 'PG', 'Martha Coolidge', '1985-08-07'::date, '108 min', 'Comedy, Romance, Sci-Fi', 'Neal Israel, Pat Proft, PJ Torokvei', 'Val Kilmer, Stacy Peralta, Daniel Ades', 'Mitch Taylor is one of the youngest students ever accepted to a university known for its programs for geniuses. He partners up with his roommate, science club legend Chris Knight, on a project to develop a high-powered laser. Together with their hyperkinetic friends, they employ their intellects in the pursuit of bigger blasts, practical jokes, and a deeper understanding of what real genius means. When they find out that their professor intends to turn their work over to the military for use as a weapon, they decide to get even.', 'https://image.tmdb.org/t/p/w500/8az0Tr8hEGDmrUH9WlFz1QIKsMy.jpg', null, null),
  ('RED', 2010, false, 'PG-13', 'Robert Schwentke', '2010-10-15'::date, '111 min', 'Action, Comedy, Crime', 'Jon Hoeber, Erich Hoeber, Warren Ellis', 'Bruce Willis, Helen Mirren, Morgan Freeman', 'Frank (Bruce Willis) is retired, bored, and lonely living off of his government pension in a nondescript suburb in an equally nondescript house. The only joy in Frank''s life is his calls to the government pension processing center when he gets to talk to his case worker, Sarah (Mary-Louis Parker). Sarah is as bored and lonely as Frank and marks her conversations with the unknown Frank and her spy novels as the only things fun in her life. When something in Frank''s past forces him back into his old line of work and puts an unwitting Sarah in the middle of the intrigue, Frank and Sarah begin a journey into his past and the people with whom he used to work. Like Frank they are all "R.E.D." - Retired Extremely Dangerous.', 'https://image.tmdb.org/t/p/w500/8eeK3OB5PeSRQD7BpZcGZKkehG.jpg', null, null),
  ('Red Dragon', 2002, false, 'R', 'Brett Ratner', '2002-10-04'::date, '124 min', 'Crime, Drama, Thriller', 'Thomas Harris, Ted Tally', 'Anthony Hopkins, Edward Norton, Ralph Fiennes', 'After escaping death by the skin of his teeth while on the hunt for the elusive madman, Dr Hannibal Lecter, the now-retired and emotionally scarred FBI agent, Will Graham, finds himself back in action. Reluctantly, as yet another monstrous serial killer known as "The Tooth Fairy" terrorises Baltimore, Graham turns to Lecter, the evil mastermind who''s been under lock and key for three long years, to lend a hand in this challenging and time-sensitive case. But, to delve deep into the demented mind of a killer, one must first face his inner demons, and Will already knows that his insane imprisoned assistant is a gifted manipulator. Can Graham find the horrifying Red Dragon in time before another family suffers?', 'https://image.tmdb.org/t/p/w500/ou9ZKA2cms02b7CdCdVqGkKu0O0.jpg', null, null),
  ('Reservoir Dogs', 1992, false, 'R', 'Quentin Tarantino', '1992-09-02'::date, '99 min', 'Crime, Thriller', 'Quentin Tarantino, Roger Avary', 'Harvey Keitel, Tim Roth, Michael Madsen', 'Six thugs, who are strangers to each other, are hired by a crime boss, Joe Cabot, to carry out a diamond robbery. Right at the outset, they are given false names with the intention that they won''t get too close and will concentrate on the job instead. They are completely sure that the robbery is going to be a success. But, when the police show up right at the time and the site of the robbery, panic spreads amongst the group members, and two of them are killed in the subsequent shootout, along with a few policemen and civilians. When the remaining people assemble at the premeditated rendezvous point (a warehouse), they begin to suspect that one of them is an undercover cop.', 'https://image.tmdb.org/t/p/w500/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg', null, null),
  ('Resident Evil', 2002, false, 'R', 'Paul W.S. Anderson', '2002-03-15'::date, '100 min', 'Action, Horror, Sci-Fi', 'Paul W.S. Anderson', 'Milla Jovovich, Michelle Rodriguez, Ryan McCluskey', 'A virus has escaped in a secret facility called "The Hive," turning the staff into hungry zombies and releasing the mutated Lab "Animals" that they were studying. The complex computer shuts down the base to prevent infection. The parent corporation sends in an elite military unit, where they meet Alice, who is suffering from amnesia due to exposure to nerve gas. The military team must shut down the computer and get out, fighting their way past zombies, mutants, and the computer itself, before the virus escapes and infects the rest of the world. Alice must also come to terms with her slowly-returning memories.', 'https://image.tmdb.org/t/p/w500/1UKNef590A0ZaMnxsscIcWuK1Em.jpg', null, null),
  ('Resident Evil: Apocalypse', 2004, false, 'R', 'Alexander Witt', '2004-09-10'::date, '94 min', 'Action, Horror, Sci-Fi', 'Paul W.S. Anderson', 'Milla Jovovich, Sienna Guillory, Eric Mabius', 'Alice awakens from a terrible sleep to find her worst fears realized--the bloodthirsty Undead, which she and the now-annihilated squad of elite military fought to destroy, have been unleashed on the city that surrounds the secret facility of the Umbrella Corporation. Discovering she was an Umbrella experiment, Alice has been bio-genetically enhanced with new strengths, senses and dexterity--and she will need them. In the heart of the ravaged Raccoon City, a small group of uninfected people, including Jill Valentine, a recently demoted member of Raccoon City''s elite Special Tactics and Rescue Services team, and Umbrella Corporation Security Officer Carlos Oliveira, fight for their lives against swarms of Undead and the deadlier and faster Lickers. Running out of luck and resources, the group is rescued by Alice, and they begin to wage an exhilarating battle to survive and escape before the Umbrella Corporation erases its experiment from the face of the earth. Their only hope lies somewhere within Raccoon City--Dr Charles Ashford, one of the leading scientists for the Umbrella Corporation, will help Alice and the others escape the city safely--if they find his daughter. Angie Ashford became separated from her father and now hides in fear. Alice, Jill and Carlos will have to fight their way through an army of Undead to save her. All the while, a secret weapon code-named Nemesis has been experimentally altered with greater modifications than Alice and has been programmed to track and destroy them. They will need all their strengths and skills to fight the battle of their lives against the mindless evil that has infected the city and the powerful forces that unleashed it on mankind.', 'https://image.tmdb.org/t/p/w500/way9dOm4dM2sm9UMcu2PEXMTX0q.jpg', null, null),
  ('Resident Evil: Extinction', 2007, false, 'R', 'Russell Mulcahy', '2007-09-21'::date, '94 min', 'Action, Horror, Sci-Fi', 'Paul W.S. Anderson', 'Milla Jovovich, Ali Larter, Oded Fehr', 'Years after the Raccoon City disaster, Alice is on her own; aware that she has become a liability and could endanger those around her, she is struggling to survive and bring down the Umbrella Corporation led by the sinister Albert Wesker and head researcher Dr. Isaacs. Meanwhile, traveling through the Nevada Desert and the ruins of Las Vegas, Carlos Olivera, L.J., and new survivors K-Mart, Claire Redfield, and Nurse Betty must fight to survive extinction against hordes of zombies, killer crows and the most terrifying creatures created as a result of the deadly T-Virus that has killed millions.', 'https://image.tmdb.org/t/p/w500/6yaLr7Ymg5cvbtSVi5hHwBKx35I.jpg', null, null),
  ('Resolution', 2012, false, 'Not Rated', 'Justin Benson, Aaron Moorhead', '2013-01-23'::date, '93 min', 'Drama, Horror, Mystery', 'Justin Benson', 'Peter Cilella, Vinny Curran, Emily Montague', 'A man imprisons his estranged junkie friend in an isolated cabin in the boonies of San Diego to force him through a week of sobriety, but the events of that week are being mysteriously manipulated.', 'https://image.tmdb.org/t/p/w500/wrzbVOuiuwSPMfWVaUQUDbyqx9V.jpg', null, null),
  ('Rise of the Planet of the Apes', 2011, true, 'PG-13', 'Rupert Wyatt', '2011-08-05'::date, '105 min', 'Action, Drama, Sci-Fi', 'Rick Jaffa, Amanda Silver, Pierre Boulle', 'James Franco, Andy Serkis, Freida Pinto', 'At the story''s heart is Caesar (Andy Serkis), a chimpanzee who gains human-like intelligence and emotions from an experimental drug. Raised like a child by the drug''s creator, Will Rodman (James Franco) and a primatologist Caroline Aranha (Freida Pinto), Caesar ultimately finds himself taken from the humans he loves and imprisoned in an ape sanctuary in San Bruno. Seeking justice for his fellow inmates, Caesar gives the fellow apes the same drug that he inherited. He then assembles a simian army and escapes the sanctuary - putting man and ape on a collision course that could change the planet forever.', 'https://image.tmdb.org/t/p/w500/oqA45qMyyo1TtrnVEBKxqmTPhbN.jpg', null, null),
  ('Robots', 2005, true, 'PG', 'Chris Wedge, Carlos Saldanha', '2005-03-27'::date, '91 min', 'Animation, Adventure, Comedy', 'David Lindsay-Abaire, Lowell Ganz, Babaloo Mandel', 'Ewan McGregor, Halle Berry, Mel Brooks', 'Even in a world populated entirely by mechanical beings Rodney Copperbottom is considered a genius inventor. Rodney dreams of two things, making the world a better place and meeting his idol, the master inventor Bigweld. On his journey he encounters Cappy, a beautiful executive ''bot with whom Rodney is instantly smitten, the nefarious corporate tyrant Ratchet who locks horns with Rodney, and a group of misfit ''bots known as the Rusties, led by Fender and Piper Pinwheeler.', 'https://image.tmdb.org/t/p/w500/fnKCh67l2DDG9NxxIlk9IpsXQ99.jpg', null, null),
  ('Rogue One: A Star Wars Story', 2016, true, 'PG-13', 'Gareth Edwards', '2016-12-16'::date, '133 min', 'Action, Adventure, Sci-Fi', 'Chris Weitz, Tony Gilroy, John Knoll', 'Felicity Jones, Diego Luna, Alan Tudyk', 'All looks lost for the Rebellion against the Empire as they learn of the existence of a new super weapon, the Death Star. Once a possible weakness in its construction is uncovered, the Rebel Alliance must set out on a desperate mission to steal the plans for the Death Star. The future of the entire galaxy now rests upon its success.', 'https://image.tmdb.org/t/p/w500/i0yw1mFbB7sNGHCs7EXZPzFkdA1.jpg', null, null),
  ('San Andreas', 2015, false, 'PG-13', 'Brad Peyton', '2015-05-29'::date, '114 min', 'Action, Adventure, Thriller', 'Carlton Cuse, Andre Fabrizio, Jeremy Passmore', 'Dwayne Johnson, Carla Gugino, Alexandra Daddario', 'In San Andreas, California is experiencing a statewide earthquake that goes on record as easily the biggest earthquake in history. Dwayne Johnson plays Ray Gaines, a helicopter rescue pilot for the Los Angeles Fire Department, who is trying to find his daughter, Blake (Alexandra Daddario), who is in San Francisco amid-st the chaos. Ray''s estranged wife, Emma, is forced to turn to Ray for help, as he is her last resort. Together they journey to save their daughter.', 'https://image.tmdb.org/t/p/w500/2Gfjn962aaFSD6eST6QU3oLDZTo.jpg', null, null),
  ('Star Wars: Episode V The Empire Strikes Back', 1980, true, 'PG', 'Irvin Kershner', '1980-06-18'::date, '124 min', 'Action, Adventure, Fantasy', 'Leigh Brackett, Lawrence Kasdan, George Lucas', 'Mark Hamill, Harrison Ford, Carrie Fisher', 'Luke Skywalker, Han Solo, Princess Leia and Chewbacca face attack by the Imperial forces and its AT-AT walkers on the ice planet Hoth. While Han and Leia escape in the Millennium Falcon, Luke travels to Dagobah in search of Yoda. Only with the Jedi Master''s help will Luke survive when the Dark Side of the Force beckons him into the ultimate duel with Darth Vader.', 'https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', null, null),
  ('Sausage Party', 2016, false, 'R', 'Conrad Vernon, Greg Tiernan', '2016-08-12'::date, '89 min', 'Animation, Adventure, Comedy', 'Kyle Hunter, Ariel Shaffir, Seth Rogen', 'Seth Rogen, Kristen Wiig, Jonah Hill', 'The products at Shopwell''s Grocery Store are made to believe a code that helps them live happy lives until it''s time for them to leave the comfort of the supermarket and head for the great beyond. However, after a botched trip to the great beyond leaves one sausage named Frank and his companion Bun stranded, Frank goes to great lengths (pun intended) to return to his package and make another trip to the great beyond. But as Frank''s journey takes him from one end of the supermarket to the other, Frank''s quest to discover the truth about his existence as a sausage turns incredibly dark. Can he expose the truth to the rest of the supermarket and get his fellow products to rebel against their human masters?', 'https://image.tmdb.org/t/p/w500/vNgdPJQ5CI60oEiiHLKRNrsDhMy.jpg', null, null),
  ('Say Anything', 1989, false, 'PG-13', 'Cameron Crowe', '1989-04-14'::date, '100 min', 'Comedy, Drama, Romance', 'Cameron Crowe', 'John Cusack, Ione Skye, John Mahoney', 'High school senior Lloyd Dobler wants nothing more than to go out with beautiful and intelligent Diane Court. Lloyd attempts to win her heart over the objections of her over-protective father before Diane leaves for a scholarship in England.', 'https://image.tmdb.org/t/p/w500/nkucKciFGSRalw6dJtsglWqOXMC.jpg', null, null),
  ('Scarface', 1983, false, 'R', 'Brian De Palma', '1983-12-09'::date, '170 min', 'Crime, Drama', 'Oliver Stone, Howard Hawks, Ben Hecht', 'Al Pacino, Michelle Pfeiffer, Steven Bauer', 'Tony Montana manages to leave Cuba during the Mariel exodus of 1980. He finds himself in a Florida refugee camp but his friend Manny has a way out for them: undertake a contract killing and arrangements will be made to get a green card. He''s soon working for drug dealer Frank Lopez and shows his mettle when a deal with Colombian drug dealers goes bad. He also brings a new level of violence to Miami. Tony is protective of his younger sister but his mother knows what he does for a living and disowns him. Tony is impatient and wants it all however, including Frank''s empire and his mistress Elvira Hancock. Once at the top however, Tony''s outrageous actions make him a target and everything comes crumbling down.', 'https://image.tmdb.org/t/p/w500/iQ5ztdjvteGeboxtmRdXEChJOHh.jpg', null, null),
  ('Scooby-Doo and the Cyber Chase', 2001, false, 'Unrated', 'Jim Stenstrum', '2001-10-09'::date, '74 min', 'Animation, Action, Adventure, Comedy, Family, Mystery, Sci-Fi', 'Mark Turosz, William Hanna (characters)', 'Scott Innes, Joe Alaskey, Bob Bergen, Grey Griffin', 'When Scooby and the gang visit a scientist at a university to check out the game he created about them, they get trapped in the game itself and have to play the game to get out of it once and for all, while they face an enemy known as the ''Phantom Virus''.', 'https://image.tmdb.org/t/p/w500/mKmFscYvGLMnZ5TslwxCge5oELO.jpg', null, null),
  ('Scooby-Doo and the Witch''s Ghost', 1999, false, 'Unrated', 'Jim Stenstrum', '1999-10-05'::date, '66 min', 'Animation, Comedy, Family, Fantasy, Mystery', 'Rick Copp, David A. Goodman, Glenn Leopold (special story consultant), Lance Falk (additional development), Michael Diaz (additional development)', 'Scott Innes, Mary Kay Bergman, Frank Welker, B.J. Ward', 'When the Mystery Gang meet famous horror writer Ben Ravencroft on their last mystery, he invites them to the small town Oakhaven, Massachusetts. While there for the Autumn Harvest Festival, Ben explains the history of his ancestor Sarah Ravencroft, who happens to be an evil witch. At the same time, the Hex Girls, an all-female Gothic rock band, come to town bringing an audience there. The gang investigate the mysterious sightings while they are there which seems to be connected to the locals of the town which turns into something much more.', 'https://image.tmdb.org/t/p/w500/7QdF1SKEIBtlkJZtkWM4qekwEtG.jpg', null, null),
  ('Scott Pilgrim vs. the World', 2010, false, 'PG-13', 'Edgar Wright', '2010-08-13'::date, '112 min', 'Action, Comedy, Fantasy', 'Michael Bacall, Edgar Wright, Bryan Lee O''Malley', 'Michael Cera, Mary Elizabeth Winstead, Kieran Culkin', 'Scott Pilgrim plays in a band which aspires to success. He dates Knives Chau, a high-school girl five years younger, and he hasn''t recovered from being dumped by his former girlfriend, now a success with her own band. When Scott falls for Ramona Flowers, he has trouble breaking up with Knives and tries to romance Ramona. As if juggling two women wasn''t enough, Ramona comes with baggage: seven ex-lovers, with each of whom Scott must do battle to the death in order to win Ramona.', 'https://image.tmdb.org/t/p/w500/g5IoYeudx9XBEfwNL0fHvSckLBz.jpg', null, null),
  ('Serenity', 2005, true, 'PG-13', 'Joss Whedon', '2005-09-30'::date, '119 min', 'Action, Adventure, Sci-Fi', 'Joss Whedon', 'Nathan Fillion, Gina Torres, Chiwetel Ejiofor', 'Serenity continues the story of the TV series it was based upon ("Firefly"). River Tam had a secret - one in which she''s not even aware - so dangerous, no one''s safe, as an Alliance operative''s sent to capture her, and all others are considered irrelevant to his job.', 'https://image.tmdb.org/t/p/w500/4sqUOaPFoP2W81mq1UYqZqf5WzA.jpg', null, null),
  ('Session 9', 2001, false, 'R', 'Brad Anderson', '2001-09-14'::date, '97 min', 'Drama, Horror, Mystery', 'Brad Anderson, Stephen Gevedon', 'David Caruso, Stephen Gevedon, Paul Guilfoyle', 'An asbestos abatement crew wins the bid for an abandoned insane asylum. What should be a straightforward, if rather rushed, job, is complicated by the personal histories of the crew. In particular, Hank is dating Phil''s old girlfriend, and Gordon''s new baby seems to be unnerving him more than should be expected. Things get more complicated as would-be lawyer Mike plays the tapes from a former patient with multiple personalities, including the mysterious Simon who does not appear until Session 9, and as Hank disappears after finding some old coins.', 'https://image.tmdb.org/t/p/w500/A3Au37c3KJX29BDvldzGiYtaU5B.jpg', null, null),
  ('Se7en', 1995, false, 'R', 'David Fincher', '1995-09-22'::date, '127 min', 'Crime, Drama, Mystery', 'Andrew Kevin Walker', 'Morgan Freeman, Brad Pitt, Kevin Spacey', 'A film about two homicide detectives'' (Morgan Freeman and Brad Pitt) desperate hunt for a serial killer who justifies his crimes as absolution for the world''s ignorance of the Seven Deadly Sins. The movie takes us from the tortured remains of one victim to the next as the sociopathic "John Doe" (Kevin Spacey) sermonizes to Detectives Somerset and Mills -- one sin at a time. The sin of Gluttony comes first and the murderer''s terrible capacity is graphically demonstrated in the dark and subdued tones characteristic of film noir. The seasoned and cultured but jaded Somerset researches the Seven Deadly Sins in an effort to understand the killer''s modus operandi while the bright but green and impulsive Detective Mills (Pitt) scoffs at his efforts to get inside the mind of a killer...', 'https://image.tmdb.org/t/p/w500/191nKfP0ehp3uIvWqgPbFmI4lv9.jpg', null, null),
  ('Shaun of the Dead', 2004, false, 'R', 'Edgar Wright', '2004-09-24'::date, '99 min', 'Comedy, Horror', 'Simon Pegg, Edgar Wright', 'Simon Pegg, Nick Frost, Kate Ashfield', 'Shaun (Simon Pegg) doesn''t have a very good day, so he decides to turn his life around by getting his ex to take him back, but he times it for right in the middle of what may be a zombie apocalypse. But for him, it''s an opportunity to show everyone he knows how useful he is by saving them all. All he has to do is survive, and get his ex back.', 'https://image.tmdb.org/t/p/w500/dgXPhzNJH8HFTBjXPB177yNx6RI.jpg', null, null),
  ('Signs', 2002, false, 'PG-13', 'M. Night Shyamalan', '2002-08-02'::date, '106 min', 'Drama, Mystery, Sci-Fi', 'M. Night Shyamalan', 'Mel Gibson, Joaquin Phoenix, Rory Culkin', 'Preacher Graham Hess loses his faith in God after his wife dies in a brutal car accident. He lives with his children and brother in a farmhouse. Crop circles start to appear in their cornfields; Graham dismisses them as mischief by miscreants. After hearing strange noises and watching news coverage on crop circles appearing all over the world, the family grows suspicious of alien activities. Now they must stick together as a family and believe, to survive and escape the ordeal.', 'https://image.tmdb.org/t/p/w500/YtrIdrTxpRhvCnlw43dwOjfLqx.jpg', null, null),
  ('SiREN', 2016, false, 'Not Rated', 'Gregg Bishop', '2016-12-02'::date, '82 min', 'Horror, Mystery, Thriller', 'Ben Collins, Luke Piotrowski, David Bruckner', 'Chase Williamson, Hannah Fierman, Justin Welborn', 'A bachelor party becomes a savage fight for survival when the groomsmen unwittingly unleash a fabled predator upon the festivities.', 'https://image.tmdb.org/t/p/w500/dAEodQQODOtOlhiQQTW7n1eS9ft.jpg', null, null),
  ('Slither', 2006, false, 'R', 'James Gunn', '2006-03-31'::date, '95 min', 'Comedy, Horror, Sci-Fi', 'James Gunn', 'Nathan Fillion, Elizabeth Banks, Michael Rooker', 'From the depths of the endless space, a flaming meteorite crashes into the dark woods of the sleepy town of Wheelsy, South Carolina. As the scorched rock reveals its silent content--a baneful parasitic organism--a subtle alien invasion commences, and the war''s unlucky first victim is the town''s local businessman, Grant. Little by little, as an internal change transforms Grant into an utterly hideous monstrosity, his wife, Starla, starts to feel that something''s been eating at him the last few days. Now, before the unstoppable extraterrestrial attack, no one is safe, and to make matters worse, Grant''s transformation is far from over yet. Who can stop the slithering army from outer space?', 'https://image.tmdb.org/t/p/w500/zNlJvCY3Pz7SE09Lf4G7uPs5XFZ.jpg', null, null),
  ('Smokin'' Aces', 2006, false, 'R', 'Joe Carnahan', '2007-01-26'::date, '108 min', 'Action, Comedy, Crime', 'Joe Carnahan', 'Jeremy Piven, Ryan Reynolds, Ray Liotta', 'Mob boss Primo Sparazza has taken out a hefty contract on Buddy "Aces" Israel, a sleazy magician who has agreed to turn state''s evidence against the Vegas mob. The FBI, sensing a chance to use this small-time con to bring down big-target Sparazza, places Aces into protective custody-under the supervision of two agents dispatched to Aces'' Lake Tahoe hideout. When the word of the price on Aces'' head spreads into the community of ex-cons and cons-to-be, it entices bounty hunters, thugs-for-hire, deadly vixens and double-crossing mobsters to join in the hunt. With all eyes on Tahoe, this rogues'' gallery collides in a comic race to hit the jackpot and rub out Aces.', 'https://image.tmdb.org/t/p/w500/nrdnN8WqvyOt8Bnl3hgWcZD6ZyM.jpg', null, null),
  ('Snatched', 2017, false, 'R', 'Jonathan Levine', '2017-05-12'::date, '90 min', 'Action, Adventure, Comedy', 'Katie Dippold', 'Amy Schumer, Goldie Hawn, Kim Caramele', 'Freshly dumped by her musician boyfriend and fired from her job, all on the same day, suddenly, the rudderless thirtysomething, Emily Middleton, finds herself with two non-refundable tickets to Ecuador. Finding hard to swallow that she is about to lose the trip of a lifetime, Emily turns to the only person left to come with her: her idiosyncratic, phobic, and cat-loving mother, Linda. But, there, the dream holiday soon turns into an Equatorial nightmare when the mother-and-daughter duo ends up conned and abducted in broad daylight. Now, to stay alive, scaredy-cat Linda and impulsive Emily will need to set aside their differences, and like a fish out of water, navigate through dense jungle thickets. But, can they make it happen?', 'https://image.tmdb.org/t/p/w500/gsleO1KultziWltEAngAEZkxQhf.jpg', null, null),
  ('Snow White and the Huntsman', 2012, false, 'PG-13', 'Rupert Sanders', '2012-06-01'::date, '127 min', 'Action, Adventure, Drama', 'Evan Daugherty, John Lee Hancock, Hossein Amini', 'Kristen Stewart, Chris Hemsworth, Charlize Theron', 'Snow White, imprisoned daughter of the late king, escapes just as the Magic Mirror declares her the source of the Evil Queen''s immortality. The Queen sends her men, led by a local huntsman, to bring her back. But upon her capture, the huntsman finds he''s being played and turns against the Queen''s men, saving Snow White in the process. Meanwhile, Snow''s childhood friend, William, learns that she is alive and sets off to save her.', 'https://image.tmdb.org/t/p/w500/8HUa5kRubYbnAD5UVpnhTGGgMTW.jpg', null, null),
  ('Solo: A Star Wars Story', 2018, true, 'PG-13', 'Ron Howard', '2018-05-25'::date, '135 min', 'Action, Adventure, Sci-Fi', 'Jonathan Kasdan, Lawrence Kasdan, George Lucas', 'Alden Ehrenreich, Woody Harrelson, Emilia Clarke', 'With the emerging demand of hyperfuel and other resources, Han Solo finds himself in the middle of a heist alongside other criminals, where they meet the likes of Chewbacca and Lando Calrissian in an adventurous situation exposing the criminal underworld.', 'https://image.tmdb.org/t/p/w500/4oD6VEccFkorEBTEDXtpLAaz0Rl.jpg', null, null),
  ('Southbound', 2015, false, 'R', 'Roxanne Benjamin, Matt Bettinelli-Olpin, David Bruckner', '2016-02-09'::date, '89 min', 'Horror', 'Matt Bettinelli-Olpin, Roxanne Benjamin, Susan Burke', 'Chad Villella, Matt Bettinelli-Olpin, Kristina Pesic', 'On a desolate stretch of desert highway, weary travelers - two men on the run from their past, a band on their way to the next gig, a man struggling to get home, a brother in search of his long-lost sister and a family on vacation - are forced to confront their worst fears and darkest secrets in a series of interwoven tales of terror and remorse on the open road.', 'https://image.tmdb.org/t/p/w500/jHwarubiAKFdMt6MfM0TZ8mY8uO.jpg', null, null),
  ('Space Cowboys', 2000, false, 'PG-13', 'Clint Eastwood', '2000-08-04'::date, '130 min', 'Action, Adventure, Thriller', 'Ken Kaufman, Howard Klausner', 'Clint Eastwood, Tommy Lee Jones, Donald Sutherland', 'When a Russian satellite orbiting the Earth starts to veer off course. It seems like the guidance system in the satellite is of American origin. It''s important to try and fix it before it comes into the atmosphere. N.A.S.A. man, Bob Gerson (James Cromwell) tries to find out who designed it, and discovers that it was designed by Frank Corvin (Clint Eastwood), an Air Force pilot who, forty years ago, was part of a team who was originally suppose to go to space, but when N.A.S.A. was formed and Gerson''s influence, they were dropped. Gerson asks Frank to help, but Frank still holds a grudge. But after some prodding, he agrees but only if he and his team can go there so he can fix it. Gerson reluctantly agrees, so Frank recruits his former team members, "Tank" Sullivan (James Garner), Jerry O''Neill (Donald Sutherland), and "Hawk" Hawkins (Tommy Lee Jones) to join him. After some strenuous tests, they''re cleared. And they go up with two other astronauts and check out the satellite and discover that they weren''t told the whole truth.', 'https://image.tmdb.org/t/p/w500/hPzt1bbA1sUDQOl6Vujmyz2hjLN.jpg', null, null),
  ('Spectre', 2015, true, 'PG-13', 'Sam Mendes', '2015-11-06'::date, '148 min', 'Action, Adventure, Thriller', 'John Logan, Neal Purvis, Robert Wade', 'Daniel Craig, Christoph Waltz, Léa Seydoux', 'A cryptic message from the past sends James Bond (Daniel Craig) on a rogue mission to Mexico City and eventually Rome, where he meets Lucia Sciarra (Monica Belluci), the beautiful and forbidden widow of an infamous criminal. Bond infiltrates a secret meeting and uncovers the existence of the sinister organisation known as S.P.E.C.T.R.E. Meanwhile, back in London, Max Denbigh (Andrew Scott), the new head of the Centre of National Security, questions Bond''s actions and challenges the relevance of MI6, led by M (Ralph Fiennes). Bond covertly enlists Miss Eve Moneypenny (Naomie Harris) and Q (Ben Whishaw) to help him seek out Dr. Madeleine Swann (Léa Seydoux), the daughter of his old nemesis Mr. White (Jesper Christensen), who may hold the clue to untangling the web of S.P.E.C.T.R.E. As the daughter of the assassin, she understands Bond in a way most others cannot. As Bond ventures towards the heart of S.P.E.C.T.R.E., he learns a chilling connection between him and the enemy he seeks.', 'https://image.tmdb.org/t/p/w500/zj8ongFhtWNsVlfjOGo8pSr7PQg.jpg', null, null),
  ('Spider-Man: Far From Home', 2019, true, 'PG-13', 'Jon Watts', '2019-07-02'::date, '129 min', 'Action, Adventure, Comedy', 'Chris McKenna, Erik Sommers, Stan Lee', 'Tom Holland, Samuel L. Jackson, Jake Gyllenhaal', 'Our friendly neighborhood Super Hero decides to join his best friends Ned, MJ, and the rest of the gang on a European vacation. However, Peter''s plan to leave super heroics behind for a few weeks are quickly scrapped when he begrudgingly agrees to help Nick Fury uncover the mystery of several elemental creature attacks, creating havoc across the continent.', 'https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', null, null),
  ('Spider-Man: Homecoming', 2017, true, 'PG-13', 'Jon Watts', '2017-07-07'::date, '133 min', 'Action, Adventure, Sci-Fi', 'Jonathan Goldstein, John Francis Daley, Jon Watts', 'Tom Holland, Michael Keaton, Robert Downey Jr.', 'A young Peter Parker/Spider-Man begins to navigate his newfound identity as the web-slinging super hero Spider-Man. Thrilled by his experience with the Avengers, Peter returns home, where he lives with his Aunt May, under the watchful eye of his new mentor Tony Stark. Peter tries to fall back into his normal daily routine - distracted by thoughts of proving himself to be more than just your friendly neighborhood Spider-Man - but when the Vulture emerges as a new villain, everything that Peter holds most important will be threatened.', 'https://image.tmdb.org/t/p/w500/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg', null, null),
  ('Spider-Man: Into the Spider-Verse', 2018, true, 'PG', 'Bob Persichetti, Peter Ramsey, Rodney Rothman', '2018-12-14'::date, '117 min', 'Animation, Action, Adventure', 'Phil Lord, Rodney Rothman', 'Shameik Moore, Jake Johnson, Hailee Steinfeld', 'Phil Lord and Christopher Miller, the creative minds behind The Lego Movie and 21 Jump Street, bring their unique talents to a fresh vision of a different Spider-Man Universe, with a groundbreaking visual style that''s the first of its kind. "Spider-Man(TM): Into the Spider-Verse" introduces Brooklyn teen Miles Morales (Shameik Moore), and the limitless possibilities of the Spider-Verse, where more than one can wear the mask.', 'https://image.tmdb.org/t/p/w500/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', null, null),
  ('Spider-Man: No Way Home', 2021, true, 'PG-13', 'Jon Watts', '2021-12-17'::date, '148 min', 'Action, Adventure, Fantasy', 'Chris McKenna, Erik Sommers, Stan Lee', 'Tom Holland, Zendaya, Benedict Cumberbatch', 'Peter Parker''s secret identity is revealed to the entire world. Desperate for help, Peter turns to Doctor Strange to make the world forget that he is Spider-Man. The spell goes horribly wrong and shatters the multiverse, bringing in monstrous villains that could destroy the world.', 'https://image.tmdb.org/t/p/w500/1g0dhYtq4irTY1GPXvft6k4YLjm.jpg', null, null),
  ('Spring', 2014, false, 'Not Rated', 'Justin Benson, Aaron Moorhead', '2015-03-20'::date, '109 min', 'Drama, Horror, Romance', 'Justin Benson', 'Lou Taylor Pucci, Nadia Hilker, Francesco Carnelutti', 'A young man in a personal tailspin flees from US to Italy, where he sparks up a romance with a woman harboring a dark, primordial secret.', 'https://image.tmdb.org/t/p/w500/tGiyGOHAtB0dZFirNbiTWapOpQG.jpg', null, null),
  ('Star Trek', 2009, true, 'PG-13', 'J.J. Abrams', '2009-05-08'::date, '127 min', 'Action, Adventure, Sci-Fi', 'Roberto Orci, Alex Kurtzman, Gene Roddenberry', 'Chris Pine, Zachary Quinto, Simon Pegg', 'On the day of James T. Kirk''s birth, his father dies on his damaged starship in a last stand against a Romulan mining vessel looking for Ambassador Spock, who in this time, has grown on Vulcan disdained by his neighbors for his half-human heritage. 25 years later, James T. Kirk has grown into a young rebellious troublemaker. Challenged by Captain Christopher Pike to realize his potential in Starfleet, he comes to annoy academy instructors like Commander Spock. Suddenly, there is an emergency on Vulcan and the newly-commissioned USS Enterprise is crewed with promising cadets like Nyota Uhura, Hikaru Sulu, Pavel Chekov and even Kirk himself, thanks to Leonard McCoy''s medical trickery. Together, this crew will have an adventure in the final frontier where the old legend is altered forever as a new version of the legend begins.', 'https://image.tmdb.org/t/p/w500/hN2ZtF3Uw6mhIHZiqL0SKzELtKn.jpg', null, null),
  ('Star Trek Beyond', 2016, true, 'PG-13', 'Justin Lin', '2016-07-22'::date, '122 min', 'Action, Adventure, Sci-Fi', 'Simon Pegg, Doug Jung, Gene Roddenberry', 'Chris Pine, Zachary Quinto, Karl Urban', 'After stopping off at Starbase Yorktown, a remote outpost on the fringes of Federation space, the USS Enterprise, halfway into their five-year mission, is destroyed by an unstoppable wave of unknown aliens. With the crew stranded on an unknown planet and with no apparent means of rescue, they find themselves fighting against a ruthless enemy with a well-earned hatred of the Federation and everything it stands for. Only a rebellious alien warrior can help them reunite and leave the planet to stop this deadly menace from beginning a possible galactic war.', 'https://image.tmdb.org/t/p/w500/m7SHlvcGfCkbzk2xP7XHDOI6o93.jpg', null, null),
  ('Star Trek Into Darkness', 2013, true, 'PG-13', 'J.J. Abrams', '2013-05-16'::date, '132 min', 'Action, Adventure, Sci-Fi', 'Roberto Orci, Alex Kurtzman, Damon Lindelof', 'Chris Pine, Zachary Quinto, Zoe Saldana', 'When the USS Enterprise crew is called back home, they find an unstoppable force of terror from within their own organization has detonated the fleet and everything it stands for, leaving our world in a state of crisis. With a personal score to settle, Captain Kirk leads a manhunt to a war-zone world to capture a one-man weapon of mass destruction. As our space heroes are propelled into an epic chess game of life and death, love will be challenged, friendships will be torn apart, and sacrifices must be made for the only family Kirk has left: his crew.', 'https://image.tmdb.org/t/p/w500/Aim3kVNh1MPIxPEFeJrl9e9Uf1a.jpg', null, null),
  ('Star Wars: Episode IV A New Hope', 1977, true, 'PG', 'George Lucas', '1977-05-25'::date, '121 min', 'Action, Adventure, Fantasy', 'George Lucas', 'Mark Hamill, Harrison Ford, Carrie Fisher', 'The Imperial Forces, under orders from cruel Darth Vader, hold Princess Leia hostage in their efforts to quell the rebellion against the Galactic Empire. Luke Skywalker and Han Solo, captain of the Millennium Falcon, work together with the companionable droid duo R2-D2 and C-3PO to rescue the beautiful princess, help the Rebel Alliance and restore freedom and justice to the Galaxy.', 'https://image.tmdb.org/t/p/w500/6FfCtAuVAW8XJjZ7eWeLibRLWTw.jpg', null, null),
  ('Star Wars: Episode II Attack of the Clones', 2002, true, 'PG', 'George Lucas', '2002-05-16'::date, '142 min', 'Action, Adventure, Fantasy', 'George Lucas, Jonathan Hales', 'Hayden Christensen, Natalie Portman, Ewan McGregor', 'Ten years after the invasion of Naboo, the Galactic Republic is facing a Separatist movement and the former queen and now Senator Padmé Amidala travels to Coruscant to vote on a project to create an army to help the Jedi to protect the Republic. Upon arrival, she escapes from an attempt to kill her, and Obi-Wan Kenobi and his Padawan Anakin Skywalker are assigned to protect her. They chase the shape-shifter Zam Wessell but she is killed by a poisoned dart before revealing who hired her. The Jedi Council assigns Obi-Wan Kenobi to discover who has tried to kill Amidala and Anakin to protect her in Naboo. Obi-Wan discovers that the dart is from the planet Kamino, and he heads to the remote planet. He finds an army of clones that has been under production for years for the Republic and that the bounty hunter Jango Fett was the matrix for the clones. Meanwhile Anakin and Amidala fall in love with each other, and he has nightmarish visions of his mother. They travel to his home planet, Tatooine, to see his mother, and he discovers that she has been abducted by Tusken Raiders. Anakin finds his mother dying, and he kills all the Tusken tribe, including the women and children. Obi-Wan follows Jango Fett to the planet Geonosis where he discovers who is behind the Separatist movement. He transmits his discoveries to Anakin since he cannot reach the Jedi Council. Who is the leader of the Separatist movement? Will Anakin receive Obi-Wan''s message? And will the secret love between Anakin and Amidala succeed?', 'https://image.tmdb.org/t/p/w500/oZNPzxqM2s5DyVWab09NTQScDQt.jpg', null, null),
  ('Star Wars: Episode VI Return of the Jedi', 1983, true, 'PG', 'Richard Marquand', '1983-05-25'::date, '131 min', 'Action, Adventure, Fantasy', 'Lawrence Kasdan, George Lucas', 'Mark Hamill, Harrison Ford, Carrie Fisher', 'Luke Skywalker battles Jabba the Hutt and Darth Vader to save his comrades in the Rebel Alliance and triumph over the Galactic Empire. Han Solo and Princess Leia reaffirm their love, and team with Chewbacca, Lando Calrissian, the Ewoks, and droids C-3PO and R2-D2 to aid in the disruption of the Dark Side, and the defeat of the evil emperor.', 'https://image.tmdb.org/t/p/w500/jQYlydvHm3kUix1f8prMucrplhm.jpg', null, null),
  ('Star Wars: Episode III Revenge of the Sith', 2005, true, 'PG-13', 'George Lucas', '2005-05-19'::date, '140 min', 'Action, Adventure, Fantasy', 'George Lucas', 'Hayden Christensen, Natalie Portman, Ewan McGregor', 'Nearly three years have passed since the beginning of the Clone Wars. The Republic, with the help of the Jedi, take on Count Dooku and the Separatists. With a new threat rising, the Jedi Council sends Obi-Wan Kenobi and Anakin Skywalker to aid the captured Chancellor. Anakin feels he is ready to be promoted to Jedi Master. Obi-Wan is hunting down the Separatist General, Grievous. When Anakin has future visions of pain and suffering coming Padmé''s way, he sees Master Yoda for counsel. When Darth Sidious executes Order 66, it destroys most of all the Jedi have built. Experience the birth of Darth Vader. Feel the betrayal that leads to hatred between two brothers. And witness the power of hope.', 'https://image.tmdb.org/t/p/w500/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg', null, null),
  ('Star Wars: Episode VII The Force Awakens', 2015, true, 'PG-13', 'J.J. Abrams', '2015-12-18'::date, '138 min', 'Action, Adventure, Sci-Fi', 'Lawrence Kasdan, J.J. Abrams, Michael Arndt', 'Daisy Ridley, John Boyega, Oscar Isaac', '30 years after the defeat of Darth Vader and the Empire, Rey, a scavenger from the planet Jakku, finds a BB-8 droid that knows the whereabouts of the long lost Luke Skywalker. Rey, as well as a rogue stormtrooper and two smugglers, are thrown into the middle of a battle between the Resistance and the daunting legions of the First Order.', 'https://image.tmdb.org/t/p/w500/wqnLdwVXoBjKibFRR5U3y0aDUhs.jpg', null, null),
  ('Star Wars: Episode VIII The Last Jedi', 2017, true, 'PG-13', 'Rian Johnson', '2017-12-15'::date, '152 min', 'Action, Adventure, Fantasy', 'Rian Johnson, George Lucas', 'Daisy Ridley, John Boyega, Mark Hamill', 'Jedi Master-in-hiding Luke Skywalker unwillingly attempts to guide young hopeful Rey in the ways of the force, while Leia, former princess turned general, attempts to lead what is left of the Resistance away from the ruthless tyrannical grip of the First Order.', 'https://image.tmdb.org/t/p/w500/ySaaKHOLAQU5HoZqWmzDIj1VvZ1.jpg', null, null),
  ('Star Wars: Episode I The Phantom Menace', 1999, true, 'PG', 'George Lucas', '1999-05-19'::date, '136 min', 'Action, Adventure, Fantasy', 'George Lucas', 'Ewan McGregor, Liam Neeson, Natalie Portman', 'The evil Trade Federation, led by Nute Gunray is planning to take over the peaceful world of Naboo. Jedi Knights Qui-Gon Jinn and Obi-Wan Kenobi are sent to confront the leaders. But not everything goes to plan. The two Jedi escape, and along with their new Gungan friend, Jar Jar Binks head to Naboo to warn Queen Amidala, but droids have already started to capture Naboo and the Queen is not safe there. Eventually, they land on Tatooine, where they become friends with a young boy known as Anakin Skywalker. Qui-Gon is curious about the boy, and sees a bright future for him. The group must now find a way of getting to Coruscant and to finally solve this trade dispute, but there is someone else hiding in the shadows. Are the Sith really extinct? Is the Queen really who she says she is? And what''s so special about this young boy?', 'https://image.tmdb.org/t/p/w500/6wkfovpn7Eq8dYNKaG5PY3q2oq6.jpg', null, null),
  ('Star Wars: Episode IX The Rise of Skywalker', 2019, true, 'PG-13', 'J.J. Abrams', '2019-12-20'::date, '141 min', 'Action, Adventure, Fantasy', 'Chris Terrio, J.J. Abrams, Derek Connolly', 'Daisy Ridley, John Boyega, Oscar Isaac', 'While the First Order continues to ravage the galaxy, Rey finalizes her training as a Jedi. But danger suddenly rises from the ashes as the evil Emperor Palpatine mysteriously returns from the dead. While working with Finn and Poe Dameron to fulfill a new mission, Rey will not only face Kylo Ren once more, but she will also finally discover the truth about her parents as well as a deadly secret that could determine her future and the fate of the ultimate final showdown that is to come.', 'https://image.tmdb.org/t/p/w500/db32LaOibwEliAmSL2jjDF6oDdj.jpg', null, null),
  ('Stardust', 2007, false, 'PG-13', 'Matthew Vaughn', '2007-08-10'::date, '127 min', 'Adventure, Family, Fantasy', 'Jane Goldman, Matthew Vaughn, Neil Gaiman', 'Charlie Cox, Claire Danes, Sienna Miller', 'The passage from this world to the fantasy kingdom of Stormhold is through a breach in a wall beside an English village. In the 1800s, a boy becomes a man when he ventures through the breach in pursuit of a fallen star, to prove his love for the village beauty. The star is no lump of rock, it''s a maiden, Yvaine. Tristan, the youth, is not the only one looking for her: three witches, led by Lamia, want her heart to make them young; and, the sons of the dead king of Stormhold want her because she holds a ruby that will give one of them title to the throne. Assisting Tristan are his mother, the victim of a spell, and a cross-dressing pirate of the skies. Will Tristan win his true love?', 'https://image.tmdb.org/t/p/w500/7zbFmxy3DqKYL2M8Hop6uylp2Uy.jpg', null, null),
  ('Stargate', 1994, false, 'PG-13', 'Roland Emmerich', '1994-10-28'::date, '116 min', 'Action, Adventure, Sci-Fi', 'Dean Devlin, Roland Emmerich', 'Kurt Russell, James Spader, Jaye Davidson', 'In 1928, in Egypt, a strange device is found by an expedition. In the present days, the outcast linguist Dr. Daniel Jackson is invited by a mysterious woman to decipher an ancient hieroglyph in a military facility. Soon he finds that the device was developed by an advanced civilization and opens a portal to teletransport to another planet. Dr. Jackson is invited to join a military team under the command of Colonel Jonathan ''Jack'' O''Neil that will explore the new world. They find a land that recalls Egypt and humans in a primitive culture that worship and are slaves to Ra, the God of the Sun. But soon they discover the secret of the mysterious "stargate".', 'https://image.tmdb.org/t/p/w500/4T6Po0XnZlevmhfPh3ZfEs5butR.jpg', null, null),
  ('Stargate Origins: Catherine', 2018, false, 'Not Rated', 'Mercedes Bryce Morgan', '2018-06-19'::date, '104 min', 'Adventure, History, Sci-Fi', 'Mark Ilvedson, Justin Michael Terry, Dean Devlin', 'Ellie Gall, Connor Trinneer, Aylam Orian', 'In 1939, Professor Paul Langford and his daughter Catherine are still grappling with the mysteries of the ancient relic they discovered in the Egyptian desert more than ten years ago. With war looming in Europe and funding running out, these brilliant minds are approaching their lowest ebb. Little do they know, answers are about to present themselves in a dangerous form, when the Nazi Occultist Dr. Wilhelm Brücke approaches their facility with a sinister motive. Enlisting the help of two young soldiers, Catherine must use all of her wit and nous as she and her new allies embark on an adventure into the unknown to rescue her father, and save the Earth from an unimaginable darkness.', null, null, null),
  ('Starship Troopers', 1997, false, 'R', 'Paul Verhoeven', '1997-11-07'::date, '129 min', 'Action, Adventure, Sci-Fi', 'Edward Neumeier, Robert A. Heinlein', 'Casper Van Dien, Denise Richards, Dina Meyer', 'In the distant future high school kids are encouraged to become citizens by joining the military. What they don''t know is that they''ll soon be engaged in a full scale war against a planet of alien insects. The fight is on to ensure the safety of humanity.', 'https://image.tmdb.org/t/p/w500/cxCmv23O7p3hyHwqoktHYkZcGsY.jpg', null, null),
  ('Step Brothers', 2008, false, 'R', 'Adam McKay', '2008-07-25'::date, '98 min', 'Comedy', 'Will Ferrell, Adam McKay, John C. Reilly', 'Will Ferrell, John C. Reilly, Mary Steenburgen', 'Brennan Huff and Dale Doback are both about 40 when Brennan''s mom and Dale''s dad marry. The sons still live with the parents so they must now share a room. Initial antipathy threatens the household''s peace and the parents'' relationship. Dad lays down the law: both slackers have a month to find a job. Out of the job search and their love of music comes a pact that leads to friendship but more domestic disarray compounded by the boys'' sleepwalking. Hovering nearby are Brennan''s successful brother and his lonely wife: the brother wants to help sell his step-father''s house, the wife wants Dale''s attention, and the newlyweds want to retire and sail the seven seas. Can harmony come from the discord?', 'https://image.tmdb.org/t/p/w500/jV0eDViuTRf9cmj4H0JNvbvaNbR.jpg', null, null),
  ('Stigmata', 1999, true, 'R', 'Rupert Wainwright', '1999-09-10'::date, '103 min', 'Horror, Mystery', 'Tom Lazarus, Rick Ramage', 'Patricia Arquette, Gabriel Byrne, Jonathan Pryce', 'A priest from the Vatican is sent to Sao Paulo, Brazil to investigate the appearance of the face of the Virgin Mary on the side of a building. While there he hears of a statue of the Virgin Mary bleeding tears in a small town outside of the city. Meanwhile, a young woman in the U.S. begins to show signs of stigmata, the wounds of Christ. The priest from the Vatican links up with her and cares for her as she is increasingly afflicted by the stigmata. Her ranting and raving finally begins to make sense to the priest who starts to question what his religion has stood for for the last 1900 years.', 'https://image.tmdb.org/t/p/w500/sKS1Vuqj7OQpOumfs6ArC0TICTN.jpg', null, null),
  ('Suicide Kings', 1997, false, 'R', 'Peter O''Fallon', '1998-09-25'::date, '106 min', 'Comedy, Crime, Drama', 'Josh McKinney, Gina Goldman, Wayne Allan Rice', 'Christopher Walken, Denis Leary, Sean Patrick Flanery', 'Ex-mob boss Christopher Walken is kidnapped by a group of four kids in a haphazard attempt at paying the ransom for another, separate kidnapping. Complexities arise as the group cannot seem to do anything right.', 'https://image.tmdb.org/t/p/w500/rQ2Sidqubi7XiHDScFe1faIz3Uv.jpg', null, null),
  ('Suicide Squad', 2016, false, 'PG-13', 'David Ayer', '2016-08-05'::date, '123 min', 'Action, Adventure, Fantasy', 'David Ayer, John Ostrander', 'Will Smith, Jared Leto, Margot Robbie', 'It feels good to be bad...Assemble a team of the world''s most dangerous, incarcerated Super Villains, provide them with the most powerful arsenal at the government''s disposal, and send them off on a mission to defeat an enigmatic, insuperable entity. U.S. intelligence officer Amanda Waller has determined only a secretly convened group of disparate, despicable individuals with next to nothing to lose will do. However, once they realize they weren''t picked to succeed but chosen for their patent culpability when they inevitably fail, will the Suicide Squad resolve to die trying, or decide it''s every man for himself?', 'https://image.tmdb.org/t/p/w500/sk3FZgh3sRrmr8vyhaitNobMcfh.jpg', null, null),
  ('Sunshine', 2007, true, 'R', 'Danny Boyle', '2007-07-27'::date, '107 min', 'Sci-Fi, Thriller', 'Alex Garland', 'Cillian Murphy, Rose Byrne, Chris Evans', '50 years into the future, the Sun begins to die, and Earth is dying as a result. A team of astronauts is sent to revive the Sun - but the mission fails. Seven years later, a new team is sent to finish the mission as mankind''s last hope.', 'https://image.tmdb.org/t/p/w500/3dmW9NWP80wnXln5IUoQTAmXbj5.jpg', null, 'Alex Garland'),
  ('Sweeney Todd: The Demon Barber of Fleet Street', 2007, false, 'R', 'Tim Burton', '2007-12-21'::date, '116 min', 'Drama, Horror, Musical', 'John Logan, Hugh Wheeler, Christopher Bond', 'Johnny Depp, Helena Bonham Carter, Alan Rickman', 'In the Victorian London, the barber Benjamin Barker is married to the gorgeous Lucy and they have a lovely child, Johanna. The beauty of Lucy attracts the attention of the corrupt Judge Turpin, who falsely accuses the barber of a crime that he did not commit and abuses Lucy later after gaining custody of her. After fifteen years in exile, Benjamin returns to London under the new identity of Sweeney Todd, seeking revenge against Turpin. He meets the widow Mrs. Lovett who is the owner of a meat pie shop who tells him that Lucy swallowed arsenic many years ago, and Turpin assigned himself tutor of Johanna. He opens a barber shop above her store, initiating a crime rampage against those who made him suffer and lose his beloved family.', 'https://image.tmdb.org/t/p/w500/gAW4J1bkRjZKmFsJsIiOBASeoAp.jpg', null, null),
  ('Tenet', 2020, true, 'PG-13', 'Christopher Nolan', '2020-09-03'::date, '150 min', 'Action, Sci-Fi, Thriller', 'Christopher Nolan', 'John David Washington, Robert Pattinson, Elizabeth Debicki', 'In a twilight world of international espionage, an unnamed CIA operative, known as The Protagonist, is recruited by a mysterious organization called Tenet to participate in a global assignment that unfolds beyond real time. The mission: prevent Andrei Sator, a renegade Russian oligarch with precognition abilities, from starting World War III. The Protagonist will soon master the art of "time inversion" as a way of countering the threat that is to come.', 'https://image.tmdb.org/t/p/w500/aCIFMriQh8rvhxpN1IWGgvH0Tlg.jpg', null, null),
  ('Terminator Genisys', 2015, false, 'PG-13', 'Alan Taylor', '2015-07-01'::date, '126 min', 'Action, Adventure, Sci-Fi', 'Laeta Kalogridis, Patrick Lussier, James Cameron', 'Arnold Schwarzenegger, Jason Clarke, Emilia Clarke', 'When John Connor, leader of the human resistance, sends Sgt. Kyle Reese back to 1984 to protect Sarah Connor and safeguard the future, an unexpected turn of events creates a fractured time-line. Now, Sgt. Reese finds himself in a new and unfamiliar version of the past, where he is faced with unlikely allies, including the Guardian, dangerous new enemies, and an unexpected new mission: To reset the future.', 'https://image.tmdb.org/t/p/w500/oZRVDpNtmHk8M1VYy1aeOWUXgbC.jpg', null, null),
  ('The A-Team', 2010, false, 'PG-13', 'Joe Carnahan', '2010-06-11'::date, '117 min', 'Action, Adventure, Crime', 'Joe Carnahan, Brian Bloom, Skip Woods', 'Liam Neeson, Bradley Cooper, Sharlto Copley', 'Four American soldiers who are in Iraq are sent on a mission to recover plates for printing 100 dollar bills that were used to print a billion dollars. After doing the job and returning to the base their commanding officer is killed in an explosion and the plates are stolen by another operative. They would be court martialed and sent to different prisons. 6 months later, the leader, Hannibal Smith is visited by a CIA spook who tells him he knows where the man who took the plates is and wants him and his men to recover it. So he helps him escape and he breaks out the others and they go after the plates. But after doing it, they discover that the spook might not be ok. And a military intelligence officer who was involved with one of them is pursuing them.', 'https://image.tmdb.org/t/p/w500/bkAWEx5g5tvRPjtDQyvIZ7LRxQm.jpg', null, null),
  ('The Amazing Spider-Man', 2012, true, 'PG-13', 'Marc Webb', '2012-07-03'::date, '136 min', 'Action, Adventure, Sci-Fi', 'James Vanderbilt, Alvin Sargent, Steve Kloves', 'Andrew Garfield, Emma Stone, Rhys Ifans', 'Peter Parker (Garfield) is an outcast high schooler who was abandoned by his parents as a boy, leaving him to be raised by his Uncle Ben (Sheen) and Aunt May (Field). Like most teenagers, Peter is trying to figure out who he is and how he got to be the person he is today. Peter is also finding his way with his first high school crush, Gwen Stacy (Stone), and together, they struggle with love, commitment, and secrets. As Peter discovers a mysterious briefcase that belonged to his father, he begins a quest to understand his parents'' disappearance - leading him directly to Oscorp and the lab of Dr. Curt Connors (Ifans), his father''s former partner. As Spider-Man is set on a collision course with Connors'' alter-ego, The Lizard, Peter will make life-altering choices to use his powers and shape his destiny to become a hero.', 'https://image.tmdb.org/t/p/w500/jexoNYnPd6vVrmygwF6QZmWPFdu.jpg', null, null),
  ('The Autopsy of Jane Doe', 2016, false, 'R', 'André Øvredal', '2016-12-21'::date, '86 min', 'Horror, Mystery, Thriller', 'Ian Goldberg, Richard Naing', 'Brian Cox, Emile Hirsch, Ophelia Lovibond', 'While investigating the murder of a family, Sheriff Sheldon and his team are puzzled with the discovery of the body of a stranger buried in the basement that does not fit to the crime scene. He brings the corpse of the beautiful Jane Doe late night to the coroner Tommy Tilden and requests to have the cause of death until the next morning to have an answer to the press. Tommy''s son and assistant Austin Tilden is ready to go to the movie theater with his girlfriend Emma, but he decides to stay to help his father in the autopsy. Along the stormy and tragic night, they disclose weird and creepy secrets about Jane Doe.', 'https://image.tmdb.org/t/p/w500/6K0wjP8kPCiPYy9PtXBGuypyt5I.jpg', null, null),
  ('The Cell', 2000, false, 'R', 'Tarsem Singh', '2000-08-18'::date, '107 min', 'Crime, Horror, Sci-Fi', 'Mark Protosevich', 'Jennifer Lopez, Vince Vaughn, Vincent D''Onofrio', 'Catharine Deane is a psychotherapist who is part of a revolutionary new treatment which allows her mind to literally enter the mind of her patients. Her experience in this method takes an unexpected turn when an F.B.I. Agent comes to ask for a desperate favor. They had just tracked down a notorious serial killer, Carl Stargher, whose method of operation is to abduct women one at a time and place them in a secret area where they are kept for about forty hours until they are slowly drowned. Unfortunately, the killer has fallen into an irreversible coma which means he cannot confess where he has taken his latest victim before she dies. Now, Catherine Deane must race against time to explore the twisted mind of the killer to get the information she needs, but Stargher''s damaged personality poses dangers that threaten to overwhelm her.', 'https://image.tmdb.org/t/p/w500/kfYVxvDDAJoFq2knHUzAZP09pAc.jpg', null, null),
  ('The Book of Eli', 2010, false, 'R', 'Albert Hughes, Allen Hughes', '2010-01-15'::date, '118 min', 'Action, Adventure, Drama', 'Gary Whitta', 'Denzel Washington, Mila Kunis, Ray Stevenson', 'In a violent post-apocalyptic society, a drifter, Eli (Denzel Washington), has been wandering westward across North America for the last thirty years. He finds solace in a unique book which he carries on his person and guards closely, while surviving by hunting small animals and seeking goods in destroyed houses and vehicles to trade in villages for water and supplies. When he reaches a village ruled by the powerful mobster, Carnegie (Gary Oldman), the man views Eli''s impressive fighting skills and offers Eli a place within his gang. Carnegie presses his blind lover Claudia (Jennifer Beals) to send her daughter, Solara (Mila Kunis), to at least convince Eli to spend the night by sleeping with him. However, Eli proves to be the better man when he gently declines her advances. The girl sees Eli''s book, and when Carnegie finds out he beats her mother until she reveals what she saw. Carnegie sends his gang into the wasteland to take the book from Eli, but the man proves to be a formidable foe as he makes it more than clear that if they want the book, they must first take his life.', 'https://image.tmdb.org/t/p/w500/1H1y9ZiqNFaLgQiRDDZLA55PviW.jpg', null, null),
  ('The Boondock Saints', 1999, false, 'R', 'Troy Duffy', '2000-01-21'::date, '108 min', 'Action, Crime, Thriller', 'Troy Duffy', 'Willem Dafoe, Sean Patrick Flanery, Norman Reedus', 'Two Irish brothers accidentally kill mafia thugs. They turn themselves in and are released as heroes. They then see it as a calling by God and start knocking off mafia gang members one by one. Willem Dafoe plays the detective trying to figure out the killings, but the closer he comes to catching the Irish brothers, the more he thinks the brothers are doing the right thing.', 'https://image.tmdb.org/t/p/w500/wtLUmkWg41xFLpvmUWAN1mm65f6.jpg', null, null),
  ('The Boondock Saints II: All Saints Day', 2009, false, 'R', 'Troy Duffy', '2009-12-11'::date, '118 min', 'Action, Crime, Thriller', 'Troy Duffy, Taylor Duffy', 'Sean Patrick Flanery, Norman Reedus, Billy Connolly', 'For the last 8 years the brothers have been living with their father on a sheep farm deep in isolated Ireland. One day their uncle tells them that they have been framed for the murder of a Bostonian Catholic priest. The boys must return to Boston to not only clear their names but find the men who framed them.', 'https://image.tmdb.org/t/p/w500/jFHtFInp3tYIBxkwWMfNJf1RBZW.jpg', null, null),
  ('The Bourne Identity', 2002, true, 'PG-13', 'Doug Liman', '2002-06-14'::date, '119 min', 'Action, Mystery, Thriller', 'Tony Gilroy, William Blake Herron, Robert Ludlum', 'Franka Potente, Matt Damon, Chris Cooper', 'When a body is recovered at sea still alive, the mystery man (Damon) seems to have forgotten everything in life, including who he was. Eventually he begins to remember smaller details in life and soon finds out that his name was Jason Bourne. What he doesn''t like is the gun and fake passports belonging to him. Now Bourne, and his new friend, Marie Helena Kreutz (Potente) travel from country to country in search of his new identity. But someone is not happy to see him alive, and is frantically trying to track him down.', 'https://image.tmdb.org/t/p/w500/aP8swke3gmowbkfZ6lmNidu0y9p.jpg', null, null),
  ('The Bourne Legacy', 2012, true, 'PG-13', 'Tony Gilroy', '2012-08-10'::date, '135 min', 'Action, Adventure, Thriller', 'Tony Gilroy, Dan Gilroy, Robert Ludlum', 'Jeremy Renner, Rachel Weisz, Edward Norton', 'When a British reporter was writing an expose about Black Ops operations Treadstone and Black Briar, and the ones responsible for them are concerned. And when Jason Bourne, former Treadstone operative got the file on Treadstone and Black Briar and gave it to Pamela Landy who then passed it to the media. When the men behind Treadstone and Black Briar learn of this, they''re concerned how this will affect other ops they have. They decide it''s best to shut down all ops and make sure make everyone involved disappears. They try to take out Aaron Cross who is part of another op called Outcome, but he manages to survive. He then seeks out Dr. Marta Shearing who worked on him when he began. It seems part of the program is for all subjects to take medications but he has run out, which is why he seeks her. But someone tries to kill her. He saves her and she tells him, he should have stopped taking the medications long ago. They go to Manila so that she can help him. Later the men behind Outcome learn that Cross and Shearing are still alive. They try to get them.', 'https://image.tmdb.org/t/p/w500/1aExL5DTGHj25ZfIC3dDwS84RWi.jpg', null, null),
  ('The Bourne Supremacy', 2004, true, 'PG-13', 'Paul Greengrass', '2004-07-23'::date, '108 min', 'Action, Mystery, Thriller', 'Robert Ludlum, Tony Gilroy', 'Matt Damon, Franka Potente, Joan Allen', 'Two years ago, Jason Bourne thought he had walked away from his past. But now the past catches up to Jason Bourne when the CIA threatens to ruin his new life. Bourne and Marie have maintained their anonymous, underground existence at the cost of permanence. Fueled by splintered nightmares and haunted by the past he cannot remember, Bourne moves Marie from city to city, trying to remain one step ahead of the threat implicit in every unexplained stranger''s glance, every "wrong number" phone call--that at any second, without any warning, he might get pulled back into the world he hopes he left behind.', 'https://image.tmdb.org/t/p/w500/7IYGiDrquvX3q7e9PV6Pejs6b2g.jpg', null, null),
  ('The Bourne Ultimatum', 2007, true, 'PG-13', 'Paul Greengrass', '2007-08-03'::date, '115 min', 'Action, Mystery, Thriller', 'Tony Gilroy, Scott Z. Burns, George Nolfi', 'Matt Damon, Edgar Ramírez, Joan Allen', 'Bourne is once again brought out of hiding, this time inadvertently by London-based reporter Simon Ross who is trying to unveil Operation Blackbriar--an upgrade to Project Treadstone--in a series of newspaper columns. Bourne sets up a meeting with Ross and realizes instantly they''re being scanned. Information from the reporter stirs a new set of memories, and Bourne must finally, ultimately, uncover his dark past whilst dodging The Company''s best efforts in trying to eradicate him.', 'https://image.tmdb.org/t/p/w500/15rMz5MRXFp7CP4VxhjYw4y0FUn.jpg', null, null),
  ('The Cabin in the Woods', 2011, true, 'R', 'Drew Goddard', '2012-04-13'::date, '95 min', 'Horror, Mystery, Thriller', 'Joss Whedon, Drew Goddard', 'Kristen Connolly, Chris Hemsworth, Anna Hutchison', 'Five teenagers head off for a weekend at a secluded cabin in the woods. They arrive to find they are quite isolated with no means of communicating with the outside world. When the cellar door flings itself open, they of course go down to investigate. They find an odd assortment of relics and curios, but when one of the women, Dana, reads from a book, she awakens a family of deadly zombie killers. However, there''s far more going on than meets the eye.', 'https://image.tmdb.org/t/p/w500/zZZe5wn0udlhMtdlDjN4NB72R6e.jpg', null, null),
  ('The Cave', 2005, false, 'PG-13', 'Bruce Hunt', '2005-08-26'::date, '97 min', 'Adventure, Horror, Sci-Fi', 'Michael Steinberg, Tegan West', 'Piper Perabo, Morris Chestnut, Cole Hauser', 'Decades after a rock church in communist Romania''s Carpathians caved when an expedition caused a landslide and buried everyone, Dr. Nicolai''s scientific team exploring the associated Templar Knights monster fighting-legend discovers a deep, flooded cave system and hires the brothers Jack and Tyler''s brilliant divers team to explore it. Another explosion traps them, after finding a mysterious parasite turning all species carnivore, and later an independently evolved predator species. Jack may be infected and turning, but Tyler sticks with him, so the group splits, hunted by the monsters, which also fly.', 'https://image.tmdb.org/t/p/w500/q7eyZY2Akj68ivnRZ86OduCUexy.jpg', null, null),
  ('The Chronicles of Riddick', 2004, false, 'R', 'David Twohy', '2004-06-11'::date, '119 min', 'Action, Adventure, Sci-Fi', 'Jim Wheat, Ken Wheat, David Twohy', 'Vin Diesel, Judi Dench, Colm Feore', 'Richard Bruno Riddick (Vin Diesel), now a hunted man, finds himself in the middle of two opposing forces in a major crusade. Lord Marshal (Colm Feore) is a warrior priest who is the leader of a sect that is waging the tenth and perhaps final crusade five hundred years in the future. Aereon (Dame Judi Dench) is an ambassador from the Elemental race. She is an ethereal being who helps Riddick unearth his origins.', 'https://image.tmdb.org/t/p/w500/iSaB7jBgsU6sXqKneZpdeRw5MSV.jpg', null, null),
  ('The Conjuring', 2013, true, 'R', 'James Wan', '2013-07-19'::date, '112 min', 'Horror, Mystery, Thriller', 'Chad Hayes, Carey W. Hayes', 'Patrick Wilson, Vera Farmiga, Ron Livingston', 'In 1971, Carolyn and Roger Perron move their family into a dilapidated Rhode Island farm house and soon strange things start happening around it with escalating nightmarish terror. In desperation, Carolyn contacts the noted paranormal investigators, Ed and Lorraine Warren, to examine the house. What the Warrens discover is a whole area steeped in a satanic haunting that is now targeting the Perron family wherever they go. To stop this evil, the Warrens will have to call upon all their skills and spiritual strength to defeat this spectral menace at its source that threatens to destroy everyone involved.', 'https://image.tmdb.org/t/p/w500/wVYREutTvI2tmxr6ujrHT704wGF.jpg', null, null),
  ('The Conjuring 2', 2016, true, 'R', 'James Wan', '2016-06-10'::date, '134 min', 'Horror, Mystery, Thriller', 'Chad Hayes, Carey W. Hayes, James Wan', 'Vera Farmiga, Patrick Wilson, Madison Wolfe', 'In 1977, paranormal investigators Ed and Lorraine Warren travel to London, England, where single mother Peggy Hodgson believes that something evil is in her home. When Peggy''s youngest daughter starts showing signs of demonic possession, Ed and Lorraine attempt to help the besieged girl, only to find themselves targeted by the malicious spirits.', 'https://image.tmdb.org/t/p/w500/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg', null, null),
  ('The Crazies', 2010, false, 'R', 'Breck Eisner', '2010-02-26'::date, '101 min', 'Horror', 'Scott Kosar, Ray Wright, George A. Romero', 'Radha Mitchell, Timothy Olyphant, Danielle Panabaker', 'As a toxin begins to turn the residents of Ogden Marsh, Iowa into violent psychopaths, sheriff David Dutton tries to make sense of the situation while he, his wife, and two other unaffected townspeople band together in a fight for survival.', 'https://image.tmdb.org/t/p/w500/ggtG9DZELyTtM2Y0DRJDOJa5iP8.jpg', null, null),
  ('The Curse of La Llorona', 2019, false, 'R', 'Michael Chaves', '2019-04-19'::date, '93 min', 'Horror, Mystery, Thriller', 'Mikki Daughtry, Tobias Iaconis', 'Linda Cardellini, Raymond Cruz, Patricia Velasquez', 'Ignoring the eerie warning of a troubled mother suspected of child endangerment, a social worker and her own small kids are soon drawn into a frightening supernatural realm. Their only hope to survive La Llorona''s deadly wrath may be a disillusioned priest and the mysticism he practices to keep evil at bay, on the fringes where fear and faith collide.', 'https://image.tmdb.org/t/p/w500/hETrPpoKs6BwoilK64YJ7Z5GcRT.jpg', null, null),
  ('The Da Vinci Code', 2006, true, 'PG-13', 'Ron Howard', '2006-05-19'::date, '149 min', 'Mystery, Thriller', 'Akiva Goldsman, Dan Brown', 'Tom Hanks, Audrey Tautou, Jean Reno', 'Dan Brown''s controversial best-selling novel about a powerful secret that''s been kept under wraps for thousands of years comes to the screen in this suspense thriller from Director Ron Howard. The stately silence of Paris'' Louvre museum is broken when one of the gallery''s leading curators is found dead on the grounds, with strange symbols carved into his body and left around the spot where he died. Hoping to learn the significance of the symbols, police bring in Sophie Neveu (Audrey Tautou), a gifted cryptographer who is also the victim''s granddaughter. Needing help, Sophie calls on Robert Langdon (Tom Hanks), a leading symbologist from the United States. As Sophie and Robert dig deeper into the case, they discover the victim''s involvement in the Priory of Sion, a secret society whose members have been privy to forbidden knowledge dating back to the birth of Christianity. In their search, Sophie and Robert happen upon evidence that could lead to the final resting place of the Holy Grail, while members of the priory and an underground Catholic society known as Opus Dei give chase, determined to prevent them from sharing their greatest secrets with the world.', 'https://image.tmdb.org/t/p/w500/9ejKfNk0LBhSI9AahH4f9NJNZNM.jpg', null, null),
  ('The Day After Tomorrow', 2004, false, 'PG-13', 'Roland Emmerich', '2004-05-28'::date, '124 min', 'Action, Adventure, Sci-Fi', 'Roland Emmerich, Jeffrey Nachmanoff', 'Dennis Quaid, Jake Gyllenhaal, Emmy Rossum', 'As Paleoclimatologist Jack Hall is in Antartica, he discovers that a huge ice sheet has sheared off. But what he does not know is that this event will trigger a massive climate shift that will affect the world population. Meanwhile, his son Sam is with friends in New York City to attend an event. There, they discover that it has been raining non-stop for the past three days, and after a series of weather-related disasters begin to occur all over the world, everybody realizes the world is about to enter a new Ice Age and the world population begins trying to evacuate to the warmer climates of the south. Jack makes a daring attempt to rescue his son and his friends who are stuck in New York City and who have managed to survive not only a massive wave but also freezing cold temperatures that could possibly kill them.', 'https://image.tmdb.org/t/p/w500/Wr4HeYQRvwVCxzOV5TmGE7UkXq.jpg', null, null),
  ('The Devil''s Advocate', 1997, false, 'R', 'Taylor Hackford', '1997-10-17'::date, '144 min', 'Drama, Fantasy, Mystery', 'Andrew Neiderman, Jonathan Lemkin, Tony Gilroy', 'Keanu Reeves, Al Pacino, Charlize Theron', 'Kevin Lomax, a ruthless young Florida attorney who never lost a case, is recruited by the most powerful law firm in the world. In spite of his mother''s disagreement (she compares New York City to Babylon), he accepts the offer and the money that comes along. But soon, his wife starts feeling homesick and seeing devilish apparitions. However, Kevin is sinking in his new cases and pays less and less attention to his wife. His boss and mentor, John Milton, seems to always know how to overcome every problem and that just freaks out Kevin.', 'https://image.tmdb.org/t/p/w500/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg', null, null),
  ('The Exorcism of Emily Rose', 2005, false, 'PG-13', 'Scott Derrickson', '2005-09-09'::date, '119 min', 'Drama, Horror, Thriller', 'Paul Harris Boardman, Scott Derrickson', 'Laura Linney, Tom Wilkinson, Shohreh Aghdashloo', 'When a younger girl called Emily Rose dies, everyone puts blame on the exorcism which was performed on her by Father Moore prior to her death. The priest is arrested on suspicion of murder. The trial begins with lawyer Erin Bruner representing Moore, but it is not going to be easy, as no one wants to believe what Father Moore says is true.', 'https://image.tmdb.org/t/p/w500/qMN0HIP34f736kkQcfvTfmL9TP3.jpg', null, null),
  ('The Exorcist', 1973, false, 'R', 'William Friedkin', '1973-12-26'::date, '122 min', 'Horror', 'William Peter Blatty', 'Ellen Burstyn, Max von Sydow, Linda Blair', 'A visiting actress in Washington, D.C., notices dramatic and dangerous changes in the behavior and physical make-up of her 12-year-old daughter. Meanwhile, a young priest at nearby Georgetown University begins to doubt his faith while dealing with his mother''s terminal sickness. And, book-ending the story, a frail, elderly priest recognizes the necessity for a show-down with an old demonic enemy.', 'https://image.tmdb.org/t/p/w500/5x0CeVHJI8tcDx8tUUwYHQSNILq.jpg', null, null),
  ('The Exorcist III', 1990, false, 'R', 'William Peter Blatty', '1990-08-17'::date, '110 min', 'Drama, Horror, Mystery', 'William Peter Blatty', 'George C. Scott, Ed Flanders, Brad Dourif', 'A seemingly endless series of grisly killings that bear the trademark of the mass murderer, the Gemini Killer, terrorise the district of Georgetown. To further complicate matters, even though it''s been seventeen long years since the killer''s execution and that fateful night of pure terror in The Exorcist (1973), the sceptical police officer, Lieutenant William F. Kinderman, is still obsessed with solving the baffling case, as the death toll keeps rising. In the meantime, in the city''s high-security psychiatric institution, a cryptic inmate who bears an uncanny resemblance to the late Father Damien Karras emerges from his deep catatonic state, claiming that he has all the answers Kinderman needs. But, who is the mysterious Patient X? Does the same unholy force that tormented Regan MacNeil have something to do with the brutal demonic murders?', 'https://image.tmdb.org/t/p/w500/rhSftgj3vwpIDSP8v67N8KEubmz.jpg', null, null),
  ('The Invisible Man', 2020, false, 'R', 'Leigh Whannell', '2020-02-28'::date, '124 min', 'Drama, Horror, Mystery', 'Leigh Whannell, H.G. Wells', 'Elisabeth Moss, Oliver Jackson-Cohen, Harriet Dyer', 'The film follows Cecilia, who receives the news of her abusive ex-boyfriend''s suicide. She begins to re-build her life for the better. However, her sense of reality is put into question when she begins to suspect her deceased lover is not actually dead.', 'https://image.tmdb.org/t/p/w500/5EufsDwXdY2CVttYOk2WtYhgKpa.jpg', null, null),
  ('The Fast and the Furious', 2001, false, 'PG-13', 'Rob Cohen', '2001-06-22'::date, '106 min', 'Action, Crime, Thriller', 'Ken Li, Gary Scott Thompson, Erik Bergquist', 'Vin Diesel, Paul Walker, Michelle Rodriguez', 'Los Angeles street racer Dominic Toretto falls under the suspicion of the LAPD as a string of high-speed electronics truck robberies rocks the area. Brian O''Connor, an officer of the LAPD, joins the ranks of Toretto''s highly skilled racing crew undercover to convict Toretto. However, O''Connor finds himself both enamored with this new world and in love with Toretto''s sister, Mia. As a rival racing crew gains strength, O''Connor must decide where his loyalty really lies.', 'https://image.tmdb.org/t/p/w500/gqY0ITBgT7A82poL9jv851qdnIb.jpg', null, null),
  ('The Fifth Element', 1997, true, 'PG-13', 'Luc Besson', '1997-05-09'::date, '126 min', 'Action, Adventure, Sci-Fi', 'Luc Besson, Robert Mark Kamen', 'Bruce Willis, Milla Jovovich, Gary Oldman', 'In the twenty-third century, the universe is threatened by evil. The only hope for mankind is the Fifth Element, who comes to Earth every five thousand years to protect the humans with four stones of the four elements: fire, water, Earth and air. A Mondoshawan spacecraft is bringing The Fifth Element back to Earth but it is destroyed by the evil Mangalores. However, a team of scientists use the DNA of the remains of the Fifth Element to rebuild the perfect being called Leeloo. She escapes from the laboratory and stumbles upon the taxi driver and former elite commando Major Korben Dallas that helps her to escape from the police. Leeloo tells him that she must meet Father Vito Cornelius to accomplish her mission. Meanwhile, the Evil uses the greedy and cruel Jean-Baptiste Emanuel Zorg and a team of mercenary Mangalores to retrieve the stones and avoid the protection of Leeloo. But the skilled Korben Dallas has fallen in love with Leeloo and decides to help her to retrieve the stones.', 'https://image.tmdb.org/t/p/w500/fPtlCO1yQtnoLHOwKtWz7db6RGU.jpg', null, null),
  ('The Forgotten', 2004, false, 'PG-13', 'Joseph Ruben', '2004-09-24'::date, '91 min', 'Drama, Mystery, Sci-Fi', 'Gerald Di Pego', 'Julianne Moore, Dominic West, Christopher Kovaleski', 'In New York, Telly Paretta has been under the psychiatric care of A doctor for months, the therapy to help her deal with the grief associated with losing her nine year old son, Sam, one of 6 children in a plane which disappeared, Slowly, incidents make it seem like Telly is losing her grip on the past, until one day all physical evidence of Sam ever existing disappears.. her husband, Jim and Dr. Munce try to explain to her that her therapy is to help her get over the delusion that she /had a son. As Telly alone goes on a search for evidence to prove the existence of Sam, the only person she is eventually able to convince is Ash Correll, an ex-Hockey player whose daughter was also one of the missing children. One other person they''re able to convince of there ever having been a Sam and Lauren is NYC cop, Ann Pope. Pope believes that 2 people having the same delusion is not a coincidence, Pope has to figure who she can or can''t trust in the matter in uncovering the truth.', 'https://image.tmdb.org/t/p/w500/gANKh0Vm00CTE1Hf2aTh2IIXn8X.jpg', null, null),
  ('The Game', 1997, false, 'R', 'David Fincher', '1997-09-12'::date, '129 min', 'Drama, Mystery, Thriller', 'John Brancato, Michael Ferris', 'Michael Douglas, Deborah Kara Unger, Sean Penn', 'Nicholas Van Orton is a very wealthy San Francisco banker, but he is an absolute loner, even spending his birthday alone. In the year of his 48th birthday (the age his father committed suicide) his brother Conrad, who has gone long ago and surrendered to addictions of all kinds, suddenly returns and gives Nicholas a card giving him entry to unusual entertainment provided by something called Consumer Recreation Services (CRS). Giving in to curiosity, Nicholas visits CRS and all kinds of weird and bad things start to happen to him.', 'https://image.tmdb.org/t/p/w500/4UOa079915QjiTA2u5hT2yKVgUu.jpg', null, null),
  ('The Girl With the Dragon Tattoo', 2011, true, 'R', 'David Fincher', '2011-12-21'::date, '158 min', 'Crime, Drama, Mystery', 'Steven Zaillian, Stieg Larsson', 'Daniel Craig, Rooney Mara, Christopher Plummer', 'Mikael Blomkvist is a disgraced journalist who is asked by a wealthy industrialist to write a biography on his family. But what he really wants Blomkvist to do is to find out what happened to his niece, who went missing 40 years ago. Blomkvist, at first, is not interested, till the man offers to help him clear his name. Blomkvist, begins by talking to the man''s relatives who were there when the girl went missing. And some of them are not forth coming. Blomkvist eventually believes that her disappearance might have something to do with some serial killings that took place 20 years before she disappeared. So he asks for a research assistant. So the industrialist''s man suggests Lisbeth Salander, a talented hacker who does background checks for them and who even did one on Blomkvist. When he sees her report, he''s impressed and asks her to work with him and she does. She''s anti-social but is extremely efficient.', 'https://image.tmdb.org/t/p/w500/8bokS83zGdhaXgN9tjidUKmAftW.jpg', null, null),
  ('The Godfather', 1972, false, 'R', 'Francis Ford Coppola', '1972-03-24'::date, '175 min', 'Crime, Drama', 'Mario Puzo, Francis Ford Coppola', 'Marlon Brando, Al Pacino, James Caan', 'The Godfather "Don" Vito Corleone is the head of the Corleone mafia family in New York. He is at the event of his daughter''s wedding. Michael, Vito''s youngest son and a decorated WW II Marine is also present at the wedding. Michael seems to be uninterested in being a part of the family business. Vito is a powerful man, and is kind to all those who give him respect but is ruthless against those who do not. But when a powerful and treacherous rival wants to sell drugs and needs the Don''s influence for the same, Vito refuses to do it. What follows is a clash between Vito''s fading old values and the new ways which may cause Michael to do the thing he was most reluctant in doing and wage a mob war against all the other mafia families which could tear the Corleone family apart.', 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', null, null),
  ('The Godfather Part II', 1974, false, 'R', 'Francis Ford Coppola', '1974-12-18'::date, '202 min', 'Crime, Drama', 'Francis Ford Coppola, Mario Puzo', 'Al Pacino, Robert De Niro, Robert Duvall', 'The continuing saga of the Corleone crime family tells the story of a young Vito Corleone growing up in Sicily and in 1910s New York; and follows Michael Corleone in the 1950s as he attempts to expand the family business into Las Vegas, Hollywood and Cuba.', 'https://image.tmdb.org/t/p/w500/hek3koDUyRQk7FIhPXsa6mT2Zc3.jpg', null, null),
  ('The Godfather Part III', 1990, false, 'R', 'Francis Ford Coppola', '1990-12-25'::date, '162 min', 'Crime, Drama', 'Mario Puzo, Francis Ford Coppola', 'Al Pacino, Diane Keaton, Andy Garcia', 'In the final installment of the Godfather Trilogy, an aging Don Michael Corleone seeks to legitimize his crime family''s interests and remove himself from the violent underworld but is kept back by the ambitions of the young. While he attempts to link the Corleone''s finances with the Vatican, Michael must deal with the machinations of a hungrier gangster seeking to upset the existing Mafioso order and a young protege''s love affair with his daughter.', 'https://image.tmdb.org/t/p/w500/lm3pQ2QoQ16pextRsmnUbG2onES.jpg', null, null),
  ('The Goonies', 1985, false, 'PG', 'Richard Donner', '1985-06-07'::date, '114 min', 'Adventure, Comedy, Family', 'Chris Columbus, Steven Spielberg', 'Sean Astin, Josh Brolin, Jeff Cohen', 'Mikey and his friends have always wanted to go on an adventure. One night they are all in Mikey''s attic and Mikey stumbles across an old map. Mikey has always wanted to know if One-eyed Willy ever was a real person and now he might. They set off and later realize that they have to go through the evil Mama Fratelli''s restaurant to get to a secret passage to the caves. As they try to get into the caves Mama Fratelli catches Chunk and he is left behind. He then meets Sloth one of Mama Fratelli''s sons with a messed up face. He befriends Sloth. Meanwhile Mama Fratelli and her sons are trying to get to the treasure too. Will the kids make it there before Mama Fratelli does? Will Chuck ever get out of her basement?', 'https://image.tmdb.org/t/p/w500/eBU7gCjTCj9n2LTxvCSIXXOvHkD.jpg', null, null),
  ('The Green Hornet', 2011, false, 'PG-13', 'Michel Gondry', '2011-01-14'::date, '119 min', 'Action, Comedy, Crime', 'Seth Rogen, Evan Goldberg, George W. Trendle', 'Seth Rogen, Jay Chou, Christoph Waltz', 'Playboy Britt Reid (Seth Rogen) becomes the new publisher of Los Angeles'' "The Daily Sentinel" after the sudden death of his father. Britt''s party life is about to change when he and his driver and kung fu expert, Kato (Jay Chou), stop a robbery. With the help of Kato, Britt starts a new career of fighting crime as the masked superhero "The Green Hornet".', 'https://image.tmdb.org/t/p/w500/1YrRviphr3eXPus9iHyQX56QgIE.jpg', null, null),
  ('The Happening', 2008, false, 'R', 'M. Night Shyamalan', '2008-06-13'::date, '91 min', 'Adventure, Drama, Sci-Fi', 'M. Night Shyamalan', 'Mark Wahlberg, Zooey Deschanel, John Leguizamo', 'Elliot Moore is a high school science teacher who quizzes his class one day about an article in the New York Times. It''s about the sudden, mysterious disappearance of bees. Yet again Nature is doing something inexplicable, and whatever science has to say about it will be, in the end, only a theory. Scientists will bring out more theories, but no explanations, when a more urgent dilemma hits the planet. It begins in Central Park. Suddenly and inexplicably, the behavior of everyone in the park changes in a most bizarre and horrible way. Soon, the strange behavior spreads throughout the city and beyond. Elliot, his wife, Alma, and Jess, the young daughter of a friend, will only have theories to guide them where to run and where to hide. But theories may not be enough.', 'https://image.tmdb.org/t/p/w500/fP4nBrtmc0teSDDHzYmDE7TLQBT.jpg', null, null),
  ('The Hitchhiker''s Guide to the Galaxy', 2005, false, 'PG', 'Garth Jennings', '2005-04-29'::date, '109 min', 'Adventure, Comedy, Sci-Fi', 'Douglas Adams, Karey Kirkpatrick', 'Martin Freeman, Yasiin Bey, Sam Rockwell', 'Everyone has bad mornings. You wake up late, you stub your toe, you burn the toast, but for a man named Arthur Dent, this goes far beyond a bad day. When he learns that a friend of his is actually an alien with advanced knowledge of Earth''s impending destruction, he is transported off the Earth seconds before it is blown up to make way for a new hyperspace motorway. And as if that''s not enough, throw in being wanted by the Police, Earth II, an insane electronic encyclopedia, no tea whatsoever, a chronically depressed robot and the search for the meaning of life, and you''ve got the greatest adventure off Earth.', 'https://image.tmdb.org/t/p/w500/yr9A3KGQlxBh3yW0cmglsr8aMIz.jpg', null, null),
  ('The Hobbit: An Unexpected Journey', 2012, true, 'PG-13', 'Peter Jackson', '2012-12-14'::date, '169 min', 'Adventure, Fantasy', 'Fran Walsh, Philippa Boyens, Peter Jackson', 'Martin Freeman, Ian McKellen, Richard Armitage', 'Bilbo Baggins is swept into a quest to reclaim the lost Dwarf Kingdom of Erebor from the fearsome dragon Smaug. Approached out of the blue by the wizard Gandalf the Grey, Bilbo finds himself joining a company of thirteen dwarves led by the legendary warrior, Thorin Oakenshield. Their journey will take them into the Wild; through treacherous lands swarming with Goblins and Orcs, deadly Wargs and Giant Spiders, Shapeshifters and Sorcerers. Although their goal lies to the East and the wastelands of the Lonely Mountain first they must escape the goblin tunnels, where Bilbo meets the creature that will change his life forever ... Gollum. Here, alone with Gollum, on the shores of an underground lake, the unassuming Bilbo Baggins not only discovers depths of guile and courage that surprise even him, he also gains possession of Gollum''s "precious" ring that holds unexpected and useful qualities ... A simple, gold ring that is tied to the fate of all Middle-earth in ways Bilbo cannot begin to know.', 'https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg', null, null),
  ('The Hobbit: The Battle of the Five Armies', 2014, true, 'R', 'Peter Jackson', '2014-12-17'::date, '144 min', 'Adventure, Fantasy', 'Fran Walsh, Philippa Boyens, Peter Jackson', 'Ian McKellen, Martin Freeman, Richard Armitage', 'After the Dragon leaves the Lonely Mountain, the people of Lake-town see a threat coming. Orcs, dwarves, elves and people prepare for war. Bilbo sees Thorin going mad and tries to help. Meanwhile, Gandalf is rescued from the Necromancer''s prison and his rescuers realize who the Necromancer is.', 'https://image.tmdb.org/t/p/w500/xT98tLqatZPQApyRmlPL12LtiWp.jpg', null, null),
  ('The Hobbit: The Desolation of Smaug', 2013, true, 'PG-13', 'Peter Jackson', '2013-12-13'::date, '161 min', 'Adventure, Drama, Fantasy', 'Fran Walsh, Philippa Boyens, Peter Jackson', 'Ian McKellen, Martin Freeman, Richard Armitage', 'After successfully crossing over (and under) the Misty Mountains, Thorin and Company must seek aid from a powerful stranger before taking on the dangers of Mirkwood Forest--without their Wizard. If they reach the human settlement of Lake-town it will be time for the hobbit Bilbo Baggins to fulfill his contract with the dwarves. The party must complete the journey to Lonely Mountain and burglar Baggins must seek out the Secret Door that will give them access to the hoard of the dragon Smaug. And, where has Gandalf got off to? And what is his secret business to the south?', 'https://image.tmdb.org/t/p/w500/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg', null, null),
  ('The Hunt for Red October', 1990, false, 'PG', 'John McTiernan', '1990-03-02'::date, '135 min', 'Action, Adventure, Thriller', 'Tom Clancy, Larry Ferguson, Donald E. Stewart', 'Sean Connery, Alec Baldwin, Scott Glenn', 'In November 1984, at the height of the Cold War, the Soviet Union creates a new nuclear submarine that runs silent due to a revolutionary propulsion system. The Russian submarine Captain, Marko Ramius (Sir Sean Connery), defects. His goal is taking it to the U.S. to prevent the Russians from using it to start nuclear war against the U.S.', 'https://image.tmdb.org/t/p/w500/yVl7zidse4KiWtGMqHFtZCx4X3N.jpg', null, null),
  ('The Huntsman: Winter''s War', 2016, false, 'PG-13', 'Cedric Nicolas-Troyan', '2016-04-22'::date, '114 min', 'Action, Adventure, Drama', 'Evan Spiliotopoulos, Craig Mazin, Evan Daugherty', 'Chris Hemsworth, Jessica Chastain, Charlize Theron', 'Evil sorceress Queen Ravenna''s powers allow her to know that her younger sister Freya, whose powers have not yet emerged, is not only involved in an illicit affair with an already elsewhere engaged nobleman Andrew, but is also pregnant with his child. Sometime after Freya gives birth to a baby girl, Freya discovers that Andrew not only reneged on his promise of elopement with her but also murdered their child. In a grief-fueled rage, her broken heart freezes over and she kills him with her sudden emergence of powers - the elemental control of ice..', 'https://image.tmdb.org/t/p/w500/ekHPrneEoa1EoDclWdillOKznqM.jpg', null, null),
  ('The Incredible Hulk', 2008, true, 'PG-13', 'Louis Leterrier', '2008-06-13'::date, '112 min', 'Action, Adventure, Sci-Fi', 'Zak Penn, Stan Lee, Jack Kirby', 'Edward Norton, Liv Tyler, Tim Roth', 'Depicting the events after the Gamma Bomb. ''The Incredible Hulk'' tells the story of Dr Bruce Banner, who seeks a cure to his unique condition, which causes him to turn into a giant green monster under emotional stress. Whilst on the run from military which seeks his capture, Banner comes close to a cure. But all is lost when a new creature emerges: The Abomination.', 'https://image.tmdb.org/t/p/w500/gKzYx79y0AQTL4UAk1cBQJ3nvrm.jpg', null, null),
  ('The Incredibles', 2004, false, 'PG', 'Brad Bird', '2004-11-28'::date, '115 min', 'Animation, Action, Adventure', 'Brad Bird', 'Craig T. Nelson, Samuel L. Jackson, Holly Hunter', 'Bob Parr (A.K.A. Mr. Incredible), and his wife Helen (A.K.A. Elastigirl), are the world''s greatest famous crime-fighting superheroes in Metroville. Always saving lives and battling evil on a daily basis. But fifteen years later, they have been forced to adopt civilian identities and retreat to the suburbs where they have no choice but to retire as superheroes to live a "normal life" with their three children Violet, Dash and Jack-Jack (who were secretly born with superpowers). Itching to get back into action, Bob gets his chance when a mysterious communication summons him to a remote island for a top secret assignment. He soon discovers that it will take a super family effort to rescue the world from total destruction.', 'https://image.tmdb.org/t/p/w500/2LqaLgk4Z226KkgPJuiOQ58wvrm.jpg', null, null),
  ('Civil War', 2024, true, 'R', 'Alex Garland', '2024-04-12'::date, '109 min', 'Action, Adventure, Thriller', 'Alex Garland', 'Kirsten Dunst, Wagner Moura, Cailee Spaeny', 'A journey across a dystopian future America, following a team of military-embedded journalists as they race against time to reach DC before rebel factions descend upon the White House.', 'https://image.tmdb.org/t/p/w500/sh7Rg8Er3tFcN9BpKIPOMvALgZd.jpg', null, 'Alex Garland'),
  ('The Iron Giant', 1999, false, 'PG', 'Brad Bird', '1999-08-06'::date, '86 min', 'Animation, Action, Adventure', 'Tim McCanlies, Brad Bird, Ted Hughes', 'Eli Marienthal, Harry Connick Jr., Jennifer Aniston', 'This is the story of a nine-year-old boy named Hogarth Hughes who makes friends with an innocent alien giant robot that came from outer space. Meanwhile, a paranoid U.S. Government agent named Kent Mansley arrives in town, determined to destroy the giant at all costs. It''s up to Hogarth to protect him by keeping him at Dean McCoppin''s place in the junkyard.', 'https://image.tmdb.org/t/p/w500/ct04FCFLPImNG5thcPLRnVsZlmS.jpg', null, null),
  ('The Italian Job', 2003, false, 'PG-13', 'F. Gary Gray', '2003-05-30'::date, '111 min', 'Action, Crime, Thriller', 'Troy Kennedy Martin, Donna Powers, Wayne Powers', 'Donald Sutherland, Mark Wahlberg, Edward Norton', 'Led by John Bridger (Donald Sutherland) and Charlie Croker (Mark Wahlberg) a team is assembled for one last heist to steal $35 million in gold bars from a heavily guarded safe in Venice, Italy. After successfully pulling off the heist, a team member, Steve (Edward Norton), driven by greed and jealousy, arranges to take the gold for himself and eliminate the remaining members of the group. Thinking the team dead, he returns to Los Angeles with the gold. Charlie and the survivors of this betrayal follow Steve to L.A. to exact revenge against the traitor. Charlie enlists the help of John Bridger''s daughter, Stella (Charlize Theron) - a professional safe cracker - to get revenge. With Stella and the hacking skills of Lyle (Seth Green), the explosives skills of "Left Ear" (Yasiin Bey), and the driving skills of "Handsome" Rob (Jason Statham) this new team plans and executes a daring heist that weaves through the freeways and subways of L.A.', 'https://image.tmdb.org/t/p/w500/eSkjK4kctyrWpFhxl35GPvSs6tI.jpg', null, null),
  ('The Judge', 2014, false, 'R', 'David Dobkin', '2014-10-10'::date, '141 min', 'Crime, Drama, Mystery', 'Nick Schenk, Bill Dubuque, David Dobkin', 'Robert Downey Jr., Robert Duvall, Vera Farmiga', 'Hank Palmer is a successful defense attorney in Chicago, who is getting a divorce. When his brother calls with the news that their mother has died, Hank returns to his childhood home to attend the funeral. Despite the brittle bond between Hank and the Judge, Hank must come to his father''s aid and defend him in court. Here, Hank discovers the truth behind the case, which binds together the dysfunctional family and reveals the struggles and secrecy of the family.', 'https://image.tmdb.org/t/p/w500/3K93GWotLXe4FqpErri0xkpLaD5.jpg', null, null),
  ('The Last Boy Scout', 1991, false, 'R', 'Tony Scott', '1991-12-13'::date, '105 min', 'Action, Comedy, Crime', 'Shane Black, Greg Hicks', 'Bruce Willis, Damon Wayans, Chelsea Field', 'A down and out cynical detective teams up with a down and out ex-quarterback to try and solve a murder case involving a pro football team and a politician.', 'https://image.tmdb.org/t/p/w500/fNkLz6ITQqTDZHBXqiCrm4kaJKJ.jpg', null, null),
  ('The Last House on the Left', 2009, false, 'R', 'Dennis Iliadis', '2009-03-13'::date, '113 min', 'Horror, Thriller', 'Adam Alleca, Carl Ellsworth, Wes Craven', 'Garret Dillahunt, Monica Potter, Tony Goldwyn', 'After kidnapping and torturing two innocent teen girls, a group of people seek refuge in the home of the parents of one of the victimized girls. When the parents find out what happened to their daughter, they plot and carry out revenge on those that hurt her.', 'https://image.tmdb.org/t/p/w500/2Y35XCUS8U8vC8vs0HDEVkPu1BM.jpg', null, null),
  ('The Last of the Mohicans', 1992, false, 'R', 'Michael Mann', '1992-09-25'::date, '112 min', 'Action, Adventure, Drama', 'James Fenimore Cooper, John L. Balderston, Paul Perez', 'Daniel Day-Lewis, Madeleine Stowe, Russell Means', 'The last members of a dying Native American tribe, the Mohicans -- Uncas, his father Chingachgook, and his adopted half-white brother Hawkeye -- live in peace alongside British colonists. But when the daughters of a British colonel are kidnapped by a traitorous scout, Hawkeye and Uncas must rescue them in the crossfire of a gruesome military conflict of which they wanted no part: the French and Indian War.', 'https://image.tmdb.org/t/p/w500/qzJMPWRtZveBkxXOv3ucWhoJuyj.jpg', null, null),
  ('The Last Samurai', 2003, false, 'R', 'Edward Zwick', '2003-12-05'::date, '154 min', 'Action, Drama', 'John Logan, Edward Zwick, Marshall Herskovitz', 'Tom Cruise, Ken Watanabe, Billy Connolly', 'In the 1870s, Captain Nathan Algren (Tom Cruise), a cynical veteran of the American Civil War, who will work for anyone, is hired by Americans who want lucrative contracts with the Emperor of Japan to train the peasant conscripts for the first standing Imperial Army in modern warfare using firearms. The Imperial Omura (Masato Harada) cabinet''s first priority is to repress a rebellion of traditionalist Samurai, hereditary warriors, who remain devoted to the sacred dynasty, but reject the Westernizing policy, and even refuse firearms. Yet, when his ill-prepared superior force sets out too soon, their panic allows the sword-wielding samurai to crush them. Badly wounded, Algren''s courageous stand makes the samurai leader Katsumoto (Ken Watanabe) spare his life. Once nursed to health, he learns to know and respect the old Japanese way, and participates as advisor in Katsumoto''s failed attempt to save the Bushido tradition, but Omura gets repressive laws enacted. He must now choose to honor his loyalty to one of the embittered sides when the conflict returns to the battlefield.', 'https://image.tmdb.org/t/p/w500/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg', null, null),
  ('The Last Starfighter', 1984, false, 'PG', 'Nick Castle', '1984-07-13'::date, '100 min', 'Action, Adventure, Sci-Fi', 'Jonathan R. Betuel', 'Lance Guest, Robert Preston, Kay E. Kuter', 'Alex Rogan lives in a remote trailer court where his mother is manager and everyone is like a massive extended family. He defeats Starfighter, a stand-up arcade game to the applause of everyone in the court and later finds out he has been turned down for a student loan for college. Depressed, he meets Centauri, who introduces himself as a person from the company that made the game, before Alex really knows what is going on, he is on the ride of his life in a sports car flying through space. Chosen to take the skills he showed on the video game into real combat to protect the galaxy from an invasion. Alex gets as far as the Starfighter base before he really realized that he was conscripted and requests to be taken back home. When he gets back home, he finds a Zando-Zan (alien bounty hunter) is stalking him. Unable to go home and live, Alex returns to the Starfighter base to find all the pilots have been killed and he is the galaxy''s only chance to be saved from invasion. To defeat the invaders, who are paying the bounty on him, he must be victorious.', 'https://image.tmdb.org/t/p/w500/A7oAHTjtYnIEQjJs62IONRufooq.jpg', null, null),
  ('The Last Witch Hunter', 2015, false, 'PG-13', 'Breck Eisner', '2015-10-23'::date, '106 min', 'Action, Adventure, Fantasy', 'Cory Goodman, Matt Sazama, Burk Sharpless', 'Vin Diesel, Rose Leslie, Elijah Wood', 'The modern world holds many secrets, but the most astounding secret of all is that witches still live amongst us; vicious supernatural creatures intent on unleashing the Black Death upon the world. Armies of witch hunters battled the unnatural enemy across the globe for centuries, including Kaulder, a valiant warrior who managed to slay the all-powerful Queen Witch, decimating her followers in the process. In the moments right before her death, the Queen curses Kaulder with her own immortality, forever separating him from his beloved wife and daughter in the afterlife. Today Kaulder is the only one of his kind remaining, and has spent centuries hunting down rogue witches, all the while yearning for his long-lost loved ones. However, unbeknownst to Kaulder, the Queen Witch is resurrected and seeks revenge on her killer causing an epic battle that will determine the survival of the human race.', 'https://image.tmdb.org/t/p/w500/gPA6PFBQPlAY7sCOCKKSSB7HyNl.jpg', null, null),
  ('The LEGO Batman Movie', 2017, false, 'PG', 'Chris McKay', '2017-02-10'::date, '104 min', 'Animation, Action, Adventure', 'Seth Grahame-Smith, Chris McKenna, Erik Sommers', 'Will Arnett, Michael Cera, Rosario Dawson', 'There are big changes brewing in Gotham City, and if he wants to save the city from The Joker''s hostile takeover, Batman may have to drop the lone vigilante thing, try to work with others and maybe, just maybe, learn to lighten up.', 'https://image.tmdb.org/t/p/w500/snGwr2gag4Fcgx2OGmH9otl6ofW.jpg', null, null),
  ('The Lord of the Rings: The Fellowship of the Ring', 2001, true, 'PG-13', 'Peter Jackson', '2001-12-19'::date, '178 min', 'Action, Adventure, Drama', 'J.R.R. Tolkien, Fran Walsh, Philippa Boyens', 'Elijah Wood, Ian McKellen, Orlando Bloom', 'An ancient Ring thought lost for centuries has been found, and through a strange twist of fate has been given to a small Hobbit named Frodo. When Gandalf discovers the Ring is in fact the One Ring of the Dark Lord Sauron, Frodo must make an epic quest to the Cracks of Doom in order to destroy it. However, he does not go alone. He is joined by Gandalf, Legolas the elf, Gimli the Dwarf, Aragorn, Boromir, and his three Hobbit friends Merry, Pippin, and Samwise. Through mountains, snow, darkness, forests, rivers and plains, facing evil and danger at every corner the Fellowship of the Ring must go. Their quest to destroy the One Ring is the only hope for the end of the Dark Lords reign.', 'https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', null, null),
  ('The Lord of the Rings: The Return of the King', 2003, true, 'PG-13', 'Peter Jackson', '2003-12-17'::date, '201 min', 'Action, Adventure, Drama', 'J.R.R. Tolkien, Fran Walsh, Philippa Boyens', 'Elijah Wood, Viggo Mortensen, Ian McKellen', 'The final confrontation between the forces of good and evil fighting for control of the future of Middle-earth. Frodo and Sam reach Mordor in their quest to destroy the One Ring, while Aragorn leads the forces of good against Sauron''s evil army at the stone city of Minas Tirith.', 'https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', null, null),
  ('The Lord of the Rings: The Two Towers', 2002, true, 'PG-13', 'Peter Jackson', '2002-12-18'::date, '179 min', 'Action, Adventure, Drama', 'J.R.R. Tolkien, Fran Walsh, Philippa Boyens', 'Elijah Wood, Ian McKellen, Viggo Mortensen', 'The continuing quest of Frodo and the Fellowship to destroy the One Ring. Frodo and Sam discover they are being followed by the mysterious Gollum. Aragorn, the Elf archer Legolas, and Gimli the Dwarf encounter the besieged Rohan kingdom, whose once great King Theoden has fallen under Saruman''s deadly spell.', 'https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', null, null),
  ('The Lost World: Jurassic Park', 1997, true, 'PG-13', 'Steven Spielberg', '1997-05-22'::date, '129 min', 'Action, Adventure, Sci-Fi', 'Michael Crichton, David Koepp', 'Jeff Goldblum, Julianne Moore, Pete Postlethwaite', 'A research team is sent to an island eighty-seven miles away from the previous home of Jurassic Park, to document and photograph the now liberated dinosaurs. However, InGen the BioEngineering company has sent another larger team to the same island to catch, sedate, and transport some dinosaurs to San Diego where they will be used in a new Jurassic Park location. But life always finds a way. Will both teams return to the mainland with successful findings? Or will another tragedy occur?', 'https://image.tmdb.org/t/p/w500/6fSkhv35nPSw9hwPVCMINQFG1WD.jpg', null, null),
  ('The Man From Earth', 2007, true, 'Not Rated', 'Richard Schenkman', '2007-11-13'::date, '87 min', 'Drama, Fantasy, Mystery', 'Jerome Bixby', 'David Lee Smith, Tony Todd, John Billingsley', 'An impromptu goodbye party for Professor John Oldman becomes a mysterious interrogation after the retiring scholar reveals to his colleagues he has a longer and stranger past than they can imagine.', 'https://image.tmdb.org/t/p/w500/V086R82gNgWrotaXZFO4JhdgB1.jpg', null, null),
  ('The Martian', 2015, false, 'PG-13', 'Ridley Scott', '2015-10-02'::date, '144 min', 'Adventure, Drama, Sci-Fi', 'Drew Goddard, Andy Weir', 'Matt Damon, Jessica Chastain, Kristen Wiig', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive. Millions of miles away, NASA and a team of international scientists work tirelessly to bring "the Martian" home, while his crewmates concurrently plot a daring, if not impossible, rescue mission. As these stories of incredible bravery unfold, the world comes together to root for Watney''s safe return.', 'https://image.tmdb.org/t/p/w500/3ndAx3weG6KDkJIRMCi5vXX6Dyb.jpg', null, null),
  ('The Matrix', 1999, true, 'R', 'Lana Wachowski, Lilly Wachowski', '1999-03-31'::date, '136 min', 'Action, Sci-Fi', 'Lilly Wachowski, Lana Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss', 'Thomas A. Anderson is a man living two lives. By day he is an average computer programmer and by night a hacker known as Neo. Neo has always questioned his reality, but the truth is far beyond his imagination. Neo finds himself targeted by the police when he is contacted by Morpheus, a legendary computer hacker branded a terrorist by the government. As a rebel against the machines, Neo must confront the agents: super-powerful computer programs devoted to stopping Neo and the entire human rebellion.', 'https://image.tmdb.org/t/p/w500/qK76PKQLd6zlMn0u83Ej9YQOqPL.jpg', null, null),
  ('The Matrix Reloaded', 2003, true, 'R', 'Lana Wachowski, Lilly Wachowski', '2003-05-15'::date, '138 min', 'Action, Sci-Fi', 'Lilly Wachowski, Lana Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss', 'In this second adventure, Neo and the rebel leaders estimate that they have 72 hours until Zion falls under siege to the Machine Army. Only a matter of hours separates the last human enclave on Earth from 250,000 Sentinels programmed to destroy mankind. But the citizens of Zion, emboldened by Morpheus conviction that the One will fulfill the Oracles Prophecy and end the war with the Machines, rest all manner of hope and expectation on Neo, who finds himself stalled by disturbing visions as he searches for a course of action.', 'https://image.tmdb.org/t/p/w500/aA5qHS0FbSXO8PxcxUIHbDrJyuh.jpg', null, null),
  ('The Matrix Revolutions', 2003, true, 'R', 'Lana Wachowski, Lilly Wachowski', '2003-11-05'::date, '129 min', 'Action, Sci-Fi', 'Lilly Wachowski, Lana Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss', 'Neo finds himself trapped between the Matrix and the Real World. Meanwhile, Zion is preparing for the oncoming war with the machines with very little chances of survival. Neo''s associates set out to free him from The Merovingian since it''s believed that he is the One who will end the war between humans and the machines. What they do not know is that there is a threat from a third party, someone who has plans to destroy both worlds.', 'https://image.tmdb.org/t/p/w500/bkkS61w94ZVMNVd8KEyyJl2tnY5.jpg', null, null),
  ('The Meg', 2018, false, 'PG-13', 'Jon Turteltaub', '2018-08-10'::date, '113 min', 'Action, Horror, Sci-Fi', 'Dean Georgaris, Jon Hoeber, Erich Hoeber', 'Jason Statham, Bingbing Li, Rainn Wilson', 'Five years ago, expert sea diver and Naval Captain Jonas Taylor encountered an unknown danger in the unexplored recesses of the Mariana Trench that forced him to abort his mission and abandon half his crew. Though the tragic incident earned him a dismissal from service, what ultimately cost him his career, his marriage and any semblance of honor was his unsupported and incredulous claims of what caused it - an attack on his vessel by a mammoth, 70-foot sea creature, believed to be extinct for more than a million years. But when a submersible lies sunk and disabled at the bottom of the ocean - carrying his ex-wife among the team onboard - he is the one who gets the call. Whether a shot at redemption or a suicide mission, Jonas must confront his fears and risk his own life and the lives of everyone trapped below on a single question: Could the Carcharodon Megalodon - the largest marine predator that ever existed - still be alive - and on the hunt?', 'https://image.tmdb.org/t/p/w500/eyWICPcxOuTcDDDbTMOZawoOn8d.jpg', null, null),
  ('The Mummy', 1999, false, 'PG-13', 'Stephen Sommers', '1999-05-07'::date, '124 min', 'Action, Adventure, Fantasy', 'Stephen Sommers, Lloyd Fonvielle, Kevin Jarre', 'Brendan Fraser, Rachel Weisz, John Hannah', 'An English librarian called Evelyn Carnahan becomes interested in starting an archaeological dig at the ancient city of Hamunaptra. She gains the help of Rick O''Connell, after saving him from his death. What Evelyn, her brother Jonathan and Rick are unaware of is that another group of explorers are interested in the same dig. Unfortunately for everyone, this group ends up unleashing a curse which been laid on the dead High Priest Imhotep. Now ''The Mummy'' is awake and it''s going to take a lot more than guns to send him back to where he came from.', 'https://image.tmdb.org/t/p/w500/yhIsVvcUm7QxzLfT6HW2wLf5ajY.jpg', null, null),
  ('The Mummy Returns', 2001, false, 'PG-13', 'Stephen Sommers', '2001-05-04'::date, '130 min', 'Action, Adventure, Fantasy', 'Stephen Sommers', 'Brendan Fraser, Rachel Weisz, John Hannah', 'Many years ago, in Ancient Egypt, the Scorpion King led a menacing army, but when he sold his soul to Anubis, he was erased from history. Now he is only a myth...or is he? Rick and Evelyn O''Connell are still discovering new artifacts, along with their 8 year old son Alex. They discover the Bracelet of Anubis. But someone else is after the bracelet. High Priest Imhotep has been brought back from the dead once again and wants the bracelet, to control the Scorpion King''s army. That''s not the only problem. Imhotep now has Alex and with the bracelet attached to him, doesn''t have long to live.', 'https://image.tmdb.org/t/p/w500/kdJsW7hcy1lrj7tdMPycTAQPAiR.jpg', null, null),
  ('The Mummy: Tomb of the Dragon Emperor', 2008, false, 'PG-13', 'Rob Cohen', '2008-08-01'::date, '112 min', 'Action, Adventure, Fantasy', 'Alfred Gough, Miles Millar, John L. Balderston', 'Brendan Fraser, Jet Li, Maria Bello', 'Centuries ago, the evil Emperor Han was cursed by the sorceress Zi Yuan who transformed him and his army into mummies. In 1946, the explorer Rick O''Connell and his wife Evelyn O''Connell are invited by the British government to take a relic, the diamond "The Eye of Shangri-La" to China. The ancient stone is capable of resurrecting the Emperor Han and of pointing the way to Shangri-La and the eternal pool of life. When the couple reaches China, they meet their son Alex O''Connell, who has discovered the tomb of Han, and Evelyn''s brother Jonathan Carnahan. The O''Connells are betrayed by their friend Prof. Roger Wilson, who is associated with General Yang. Yang wants to serve Emperor Han, so he resurrects the mummy and they head for Shangri-La. The guardian of Han''s tomb (and Zi''s daughter) Lin tells them that the only ways to destroy Han are to prevent him from reaching Shangri-La or by stabbing his heart with a cursed dagger.', 'https://image.tmdb.org/t/p/w500/A3acM1lX5PNWQa6r5qeMAJOxbnT.jpg', null, null),
  ('The Nightmare Before Christmas', 1993, false, 'PG', 'Henry Selick', '1993-10-29'::date, '76 min', 'Animation, Family, Fantasy', 'Tim Burton, Michael McDowell, Caroline Thompson', 'Danny Elfman, Chris Sarandon, Catherine O''Hara', 'Jack Skellington, the pumpkin king of Halloween Town, is bored with doing the same thing every year for Halloween. One day he stumbles into Christmas Town, and is so taken with the idea of Christmas that he tries to get the resident bats, ghouls, and goblins of Halloween Town to help him put on Christmas instead of Halloween -- but alas, they can''t get it quite right.', 'https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', null, null),
  ('The Ninth Gate', 1999, false, 'R', 'Roman Polanski', '2000-03-10'::date, '133 min', 'Mystery, Thriller', 'Arturo Pérez-Reverte, John Brownjohn, Enrique Urbizu', 'Johnny Depp, Frank Langella, Lena Olin', 'In New York, the money-driven dealer Dean Corso is a rare-books expert and partner of Bernie, who owns a bookstore. He is contacted by the renowned collector of books about the devil Boris Balkan, who has just acquired the rare The Nine Gates of the Kingdom of Shadows from the collector Andrew Telfer, to verify whether his book is authentic or a forgery. Balkan explains that the book was written by the writer Aristide Torchia, in 1666, with Lucifer and he was burned at the stake with his entire work. There are only three exemplars of The Nine Gates and in accordance with the legend, its nine engravings form a riddle to conjure the devil. The skeptical Corso accepts the assignment and has to fly to Sintra, Portugal, and Paris, France, to contact the owners Victor Fargas and Baroness Kessler and find the genuine exemplar for Balkan. Meanwhile, he asks Bernie to hide the rare book. Before traveling to Europe, the widow Liana Telfer wants to retrieve the book and has sex with Corso, but he does not accept her offer. When Corso returns to Bernie''s bookstore, he finds his friend murdered in the same position of an engraving. Corso travels to Toledo, Spain, to meet the Ceniza twin brothers and learn more about The Nine Gates. During his journey in Europe, Corso is pursued by Liana and her bodyguard, who belong to the sect The Order of the Silver Serpents, and is protected by a mysterious Girl with supernatural powers. Meanwhile, the owners of the two other exemplars of The Nine Gates are murdered. Corso becomes obsessed with the book and discloses the truth about it.', 'https://image.tmdb.org/t/p/w500/iFDtmA8Bg9zE4NcsjcmGfqFN01H.jpg', null, null),
  ('The Nun', 2018, true, 'R', 'Corin Hardy', '2018-09-07'::date, '96 min', 'Horror, Mystery, Thriller', 'Gary Dauberman, James Wan', 'Demián Bichir, Taissa Farmiga, Jonas Bloquet', 'When a young nun at a cloistered abbey in Romania takes her own life, a priest with a haunted past and a novitiate on the threshold of her final vows are sent by the Vatican to investigate. Together they uncover the order''s unholy secret. Risking not only their lives but their faith and their very souls, they confront a malevolent force in the form of the same demonic nun that first terrorized audiences in ''The Conjuring 2,'' as the abbey becomes a horrific battleground between the living and the damned.', 'https://image.tmdb.org/t/p/w500/sFC1ElvoKGdHJIWRpNB3xWJ9lJA.jpg', null, null),
  ('The Punisher', 2004, false, 'R', 'Jonathan Hensleigh', '2004-04-16'::date, '124 min', 'Action, Crime, Drama', 'Jonathan Hensleigh, Michael France', 'Thomas Jane, John Travolta, Samantha Mathis', 'Special agent Frank Castle had it all: A loving family, a great life, and an adventurous job. But when his life is taken away from him by a ruthless criminal and his associates, Frank has become reborn. Now serving as judge, jury, and executioner, he''s a new kind of vigilante out to wage a one man war against those who have done him wrong.', 'https://image.tmdb.org/t/p/w500/7rmA1HwYp2GKM85BL0cVwCaosGr.jpg', null, null),
  ('The Ring', 2002, false, 'PG-13', 'Gore Verbinski', '2002-10-18'::date, '115 min', 'Horror, Mystery', 'Ehren Kruger, Kôji Suzuki, Hiroshi Takahashi', 'Naomi Watts, Martin Henderson, Brian Cox', 'Rachel Keller is a journalist investigating a videotape that may have killed four teenagers (including her niece). There is an urban legend about this tape: the viewer will die seven days after watching it. If the legend is correct, Rachel will have to run against time to save her son''s and her own life.', 'https://image.tmdb.org/t/p/w500/AeRpUynJKDpJveklBJipOYrVxCS.jpg', null, null),
  ('The Ring Two', 2005, false, 'PG-13', 'Hideo Nakata', '2005-03-18'::date, '110 min', 'Horror, Mystery', 'Ehren Kruger, Kôji Suzuki, Hiroshi Takahashi', 'Naomi Watts, David Dorfman, Sissy Spacek', 'A high school student named Jake tries to make his girlfriend Emily watch a cursed tape. But then Jake finds out that Emily covered her eyes and didn''t watch the tape, and then Jake is killed by Samara Morgan (from the first The Ring movie). Rachel Keller learns of Jake''s death and finds his twisted body in the back of an ambulance. Rachel then realizes she once again has to save her son Aidan from Samara the evil ghost child.', 'https://image.tmdb.org/t/p/w500/bHbz7z2pecTawhkqLpuC2m0qywe.jpg', null, null),
  ('The Rocky Horror Picture Show', 1975, false, 'R', 'Jim Sharman', '1975-12-18'::date, '100 min', 'Comedy, Horror, Musical', 'Richard O''Brien, Jim Sharman', 'Tim Curry, Susan Sarandon, Barry Bostwick', 'On a wild and rain-swept late-November evening, somewhere at an empty stretch of road outside Ohio''s merry Denton, blissfully-affianced, prudish, boringly-innocent young pair Brad Majors (Barry Bostwick) and Janet Weiss (Susan Sarandon) find themselves stranded on their way to visit an ex-tutor. Instead, the couple will inadvertently unearth the cross-dressing Dr. Frank-N-Furter''s (Tim Curry''s) spooky lair of inexhaustible oddities, just in time to partake in the out-of-this-world mad scientist''s proud unveiling of his latest, delightfully extravagant, most daring creation: the ultimate male and the perfect sex symbol: the flaxen-haired Rocky Horror (Peter Hinwood). But, little by little, as the effervescent transgressive force gobbles up whole the unsuspecting visitors of the night, Brad and Janet slowly begin to embrace the potent fascinations of seduction, while an idolized Rocky roams free in the mansion. Who can interrupt man''s union with the absolute pleasure?', 'https://image.tmdb.org/t/p/w500/3pyE6ZqDbuJi7zrNzzQzcKTWdmN.jpg', null, null),
  ('The Scorpion King', 2002, false, 'PG-13', 'Chuck Russell', '2002-04-19'::date, '92 min', 'Action, Adventure, Fantasy', 'Stephen Sommers, Jonathan Hales, William Osborne', 'Dwayne Johnson, Steven Brand, Michael Clarke Duncan', 'In ancient Gomorrah, thousands of years before the Pyramids, the remaining free nomadic tribes are forced to form an uneasy alliance to put an end to mighty King Memnon''s reign of tyranny. One of the few survivors and the last of the Akkadians, the brave assassin, Mathayus, is entrusted with the impossible task of executing Memnon''s fortune-telling sorceress, Cassandra, only to find himself up against a seemingly indestructible evil army. Now, with the help of his new powerful allies, including the great warrior, Balthazar, Mathayus returns to the legendary city to infiltrate Memnon''s impenetrable fortress in the desert and exact his revenge. Is Mathayus destined to be the next Scorpion King?', 'https://image.tmdb.org/t/p/w500/aITIsX20tACn6jgtyDcCYpRT216.jpg', null, null),
  ('The Shallows', 2016, false, 'PG-13', 'Jaume Collet-Serra', '2016-06-24'::date, '86 min', 'Action, Drama, Horror', 'Anthony Jaswinski', 'Blake Lively, Óscar Jaenada, Angelo Josue Lozano Corzo', 'In the taut thriller The Shallows, when Nancy (Blake Lively) is surfing on a secluded beach, she finds herself on the feeding ground of a great white shark. Though she is stranded only 200 yards from shore, survival proves to be the ultimate test of wills, requiring all of Nancy''s ingenuity, resourcefulness, and fortitude.', 'https://image.tmdb.org/t/p/w500/bnBV7hZmLuA0Si5Aop481sPF2RY.jpg', null, null),
  ('The Social Network', 2010, false, 'PG-13', 'David Fincher', '2010-10-01'::date, '120 min', 'Biography, Drama', 'Aaron Sorkin, Ben Mezrich', 'Jesse Eisenberg, Andrew Garfield, Justin Timberlake', 'On a fall night in 2003, Harvard undergrad and computer programming genius Mark Zuckerberg sits down at his computer and heatedly begins working on a new idea. In a fury of blogging and programming, what begins in his dorm room soon becomes a global social network and a revolution in communication. A mere six years and 500 million friends later, Mark Zuckerberg is the youngest billionaire in history... but for this entrepreneur, success leads to both personal and legal complications.', 'https://image.tmdb.org/t/p/w500/n0ybibhJtQ5icDqTp8eRytcIHJx.jpg', null, null),
  ('The Sting', 1973, false, 'PG', 'George Roy Hill', '1973-12-25'::date, '129 min', 'Comedy, Crime, Drama', 'David S. Ward', 'Paul Newman, Robert Redford, Robert Shaw', 'Johnny Hooker, a small time grifter, unknowingly steals from Doyle Lonnegan, a big time crime boss, when he pulls a standard street con. Lonnegan demands satisfaction for the insult. After his partner, Luther, is killed, Hooker flees, and seeks the help of Henry Gondorff, one of Luther''s contacts, who is a master of the long con. Hooker wants to use Gondorff''s expertise to take Lonnegan for an enormous sum of money to even the score, since he admits he "doesn''t know enough about killing to kill him." They devise a complicated scheme and amass a talented group of other con artists who want their share of the reparations. The stakes are high in this game, and our heroes must not only deal with Lonnegan''s murderous tendencies, but also other side players who want a piece of the action. To win, Hooker and Gondorff will need all their skills...and a fair amount of confidence.', 'https://image.tmdb.org/t/p/w500/4VdQopZb0lx13Me3yxE5rUXMGCI.jpg', null, null),
  ('The Strangers', 2008, false, 'R', 'Bryan Bertino', '2008-05-30'::date, '86 min', 'Horror, Mystery, Thriller', 'Bryan Bertino', 'Scott Speedman, Liv Tyler, Gemma Ward', 'After returning from a wedding reception, a couple staying in an isolated vacation house receive a knock on the door in the mid-hours of the night. What ensues is a violent invasion by three strangers, their faces hidden behind masks. The couple find themselves in a violent struggle, in which they go beyond what either of them thought capable in order to survive.', 'https://image.tmdb.org/t/p/w500/gwsg4qFmLOvlhwXj4OZuxfFUdP0.jpg', null, null),
  ('The Thing', 1982, false, 'R', 'John Carpenter', '1982-06-25'::date, '109 min', 'Horror, Mystery, Sci-Fi', 'Bill Lancaster, John W. Campbell Jr.', 'Kurt Russell, Wilford Brimley, Keith David', 'A US research station, Antarctica, early-winter 1982. The base is suddenly buzzed by a helicopter from the nearby Norwegian research station. They are trying to kill a dog that has escaped from their base. After the destruction of the Norwegian chopper the members of the US team fly to the Norwegian base, only to discover them all dead or missing. They do find the remains of a strange creature the Norwegians burned. The Americans take it to their base and deduce that it is an alien life form. After a while it is apparent that the alien can take over and assimilate into other life forms, including humans, and can spread like a virus. This means that anyone at the base could be inhabited by The Thing, and tensions escalate.', 'https://image.tmdb.org/t/p/w500/tzGY49kseSE9QAKk47uuDGwnSCu.jpg', null, null),
  ('The Thing', 2011, false, 'R', 'Matthijs van Heijningen Jr.', '2011-10-14'::date, '103 min', 'Horror, Mystery, Sci-Fi', 'Eric Heisserer, John W. Campbell Jr.', 'Mary Elizabeth Winstead, Joel Edgerton, Ulrich Thomsen', 'Paleontologist Kate Lloyd is invited by Dr. Sandor Halvorson to join his team who have found something extraordinary. Deep below the Antarctic ice, they have found an alien spacecraft that has been there for perhaps 100,000 years. Not far from where the craft landed, they find the remains of the occupant. It''s cut out of the ice and taken back to their camp but as the ice melts, the creature reanimates and not only begins to attack them but manages to infect them, with team members devolving into the alien creature.', 'https://image.tmdb.org/t/p/w500/dmn2nVo8h7LMnk694JxCRIwK06p.jpg', null, null),
  ('The Thomas Crown Affair', 1999, false, 'R', 'John McTiernan', '1999-08-06'::date, '113 min', 'Crime, Romance, Thriller', 'Alan Trustman, Leslie Dixon, Kurt Wimmer', 'Pierce Brosnan, Rene Russo, Denis Leary', 'Self-made billionaire Thomas Crown is bored of being able to buy everything he desires. Being irresistible to women, he also does not feel any challenge in that area. But there are a few things even he can''t get, therefore Thomas Crown has a seldom hobby: He steals priceless masterpieces of Art. After the theft of a famous painting from Claude Monet, the only person suspecting Thomas Crown is Catherine Banning. Her job is to get the picture back, no matter how she accomplishes her mission. Unfortunately, Catherine gets involved too deeply with Thomas to keep a professional distance to the case. Fortunately, Thomas seems to fall for her, too.', 'https://image.tmdb.org/t/p/w500/5yqs1MVlqdIg1DY5adC5jFx3d7j.jpg', null, null),
  ('The Twilight Saga: Breaking Dawn Part 1', 2011, true, 'PG-13', 'Bill Condon', '2011-11-18'::date, '117 min', 'Adventure, Drama, Fantasy', 'Melissa Rosenberg, Stephenie Meyer', 'Kristen Stewart, Robert Pattinson, Taylor Lautner', 'Bella and Edward celebrate their wedding, but, after their honeymoon on Isle Esme, things take a turn for the worse when Bella realises she is pregnant. As the baby grows at an abnormally fast rate and causes many health problems to Bella, Edward and the wolf pack fear that she may give birth to an immortal child. But the Cullens will do everything they can to ensure that both Bella and the unborn child remain safe.', 'https://image.tmdb.org/t/p/w500/qs8LsHKYlVRmJbFUiSUhhRAygwj.jpg', null, null),
  ('The Twilight Saga: Breaking Dawn Part 2', 2012, true, 'PG-13', 'Bill Condon', '2012-11-16'::date, '115 min', 'Adventure, Drama, Fantasy', 'Stephenie Meyer, Melissa Rosenberg', 'Kristen Stewart, Robert Pattinson, Taylor Lautner', 'The final Twilight Saga begins with Bella now a vampire learning to use her abilities. And happy to see her daughter, Renesmee is flourishing. But when someone sees Renesmee do something that makes them think that she was turned. This person goes to the Volturi, because it is a violation to turn a child. And the penalty is death for both who turned the child into a vampire and the child, cause they deem a turned child too dangerous. Alice gets a vision of the Volturi coming after them. So the Cullens try to convince them that Renesmee is not a threat. So they ask friends and family to come stand with them. But when someone who has it in for the Volturi shows up and tells them they should be ready for a fight. And they get ready.', 'https://image.tmdb.org/t/p/w500/7IGdPaKujv0BjI0Zd0m0a4CzEjJ.jpg', null, null),
  ('The Twilight Saga: Eclipse', 2010, true, 'PG-13', 'David Slade', '2010-06-30'::date, '124 min', 'Action, Adventure, Drama', 'Melissa Rosenberg, Stephenie Meyer', 'Kristen Stewart, Robert Pattinson, Taylor Lautner', 'Bella once again finds herself surrounded by danger as Seattle is ravaged by a string of mysterious killings and a malicious vampire continues her quest for revenge. In the midst of it all, she is forced to choose between her love for Edward and her friendship with Jacob -- knowing that her decision has the potential to ignite the struggle between vampire and werewolf. With her graduation quickly approaching, Bella is confronted with the most important decision of her life.', 'https://image.tmdb.org/t/p/w500/dK4Gi1UdMiHzHc7r7CZQG4IQ9Sr.jpg', null, null),
  ('The Twilight Saga: New Moon', 2009, true, 'PG-13', 'Chris Weitz', '2009-11-20'::date, '130 min', 'Adventure, Drama, Fantasy', 'Melissa Rosenberg, Stephenie Meyer', 'Kristen Stewart, Robert Pattinson, Taylor Lautner', 'After Bella recovers from the vampire attack that almost claimed her life, she looks to celebrate her birthday with Edward and his family. However, a minor accident during the festivities results in Bella''s blood being shed, a sight that proves too intense for the Cullens, who decide to leave the town of Forks, Washington for Bella and Edward''s sake. Initially heartbroken, Bella finds a form of comfort in reckless living, as well as an even-closer friendship with Jacob Black. Danger in different forms awaits.', 'https://image.tmdb.org/t/p/w500/k2qTooPlHffgNABNWxeJdGMglPK.jpg', null, null),
  ('The Village', 2004, false, 'PG-13', 'M. Night Shyamalan', '2004-07-30'::date, '108 min', 'Drama, Mystery, Thriller', 'M. Night Shyamalan', 'Sigourney Weaver, William Hurt, Joaquin Phoenix', 'M Night Shyamalan''s The Village revolves around a desolate town in Pennsylvania. The residents of this town live by strict rules - They are not to leave the village or the monsters beyond their boundaries will surely attack them. Lucius and Ivy have an attraction - a strong one. But when Noah - a man with an intellectual disability and who also has feelings for Ivy, finds out that the two are In love, Noah attacks Lucius. He will die if brave Ivy (who is blind) does not breach the borders and find help to save Lucius.', 'https://image.tmdb.org/t/p/w500/v7UvYtKfIVaHLaHwVgfalyrK7Ho.jpg', null, null),
  ('The Witch', 2015, true, 'R', 'Robert Eggers', '2016-02-19'::date, '92 min', 'Drama, Fantasy, Horror', 'Robert Eggers', 'Anya Taylor-Joy, Ralph Ineson, Kate Dickie', 'New England, 1630: William and Katherine try to lead a devout Christian life, homesteading on the edge of an impassible wilderness, with five children. When their newborn son mysteriously vanishes and their crops fail, the family begins to turn on one another. ''The Witch'' is a chilling portrait of a family unraveling within their own sins, leaving them prey for an inconceivable evil.', 'https://image.tmdb.org/t/p/w500/zap5hpFCWSvdWSuPGAQyjUv2wAC.jpg', null, null),
  ('The Wolfman', 2010, false, 'R', 'Joe Johnston', '2010-02-12'::date, '103 min', 'Drama, Fantasy, Horror', 'Andrew Kevin Walker, David Self, Curt Siodmak', 'Benicio Del Toro, Anthony Hopkins, Emily Blunt', 'Lawrence Talbot''s (Benicio Del Toro''s) childhood ended the night his mother died. His father sent him from the sleepy Victorian hamlet of Blackmoor to an insane asylum, then he went to America. When his brother Ben''s (Simon Merrells'') fiancée Gwen Conliffe (Emily Blunt), tracks him down to help find her missing love, Talbot returns to his father''s estate to learn that his brother''s mauled body has been found. Reunited with his estranged father Sir John Talbot (Sir Anthony Hopkins), Lawrence sets out to find his brother''s killer, and discovers a horrifying destiny for himself. Someone or something with brute strength and insatiable blood lust has been killing the villagers, and a suspicious Scotland Yard Inspector named Aberline (Hugo Weaving) comes to investigate.', 'https://image.tmdb.org/t/p/w500/fQqPoAHvHicie1ttuiV2q0yv9V7.jpg', null, null),
  ('The Woman in Black', 2012, true, 'PG-13', 'James Watkins', '2012-02-03'::date, '95 min', 'Drama, Fantasy, Horror', 'Susan Hill, Jane Goldman', 'Daniel Radcliffe, Janet McTeer, Ciarán Hinds', 'In London, solicitor Arthur Kipps still grieves over the death of his beloved wife Stella on the delivery of their son Joseph four years before. His employer gives him a last chance to keep his job, and he is assigned to travel to the remote village of Crythin Gifford to examine the documentation of the Eel Marsh House that belonged to the recently deceased Mrs. Drablow. Arthur befriends Daily on the train and the man offers a ride to him to the Gifford Arms inn. Arthur has a cold reception and the owner of the inn tells that he did not receive the request of reservation and there is no available room. The next morning, Arthur meets solicitor Jerome who advises him to return to London. However, Arthur goes to the isolated manor and soon he finds that Eel Marsh House is haunted by the vengeful ghost of a woman dressed in black. He also learns that the woman lost her son, drowned in the marsh, and she seeks revenge, taking the children of the terrified locals.', 'https://image.tmdb.org/t/p/w500/nghQnDZE4EsQJ4J4zxR3UqItTpO.jpg', null, null),
  ('The World''s End', 2013, false, 'R', 'Edgar Wright', '2013-08-23'::date, '109 min', 'Action, Comedy, Sci-Fi', 'Simon Pegg, Edgar Wright', 'Simon Pegg, Nick Frost, Martin Freeman', '20 years after attempting an epic pub crawl, five childhood friends reunite when one of them becomes hell bent on trying the drinking marathon again. They are convinced to stage an encore by mate Gary King, a 40-year old man trapped at the cigarette end of his teens, who drags his reluctant pals to their home town and once again attempts to reach the fabled pub, The World''s End. As they attempt to reconcile the past and present, they realize the real struggle is for the future, not just theirs but humankind''s. Reaching The World''s End is the least of their worries.', 'https://image.tmdb.org/t/p/w500/kpglnOBYmKn0AkkWDzGxzKHDbds.jpg', null, null),
  ('Thor', 2011, true, 'PG-13', 'Kenneth Branagh', '2011-05-06'::date, '115 min', 'Action, Fantasy', 'Ashley E. Miller, Zack Stentz, Don Payne', 'Chris Hemsworth, Anthony Hopkins, Natalie Portman', 'The warrior Thor (Chris Hemsworth) is cast out of the fantastic realm of Asgard by his father Odin (Sir Anthony Hopkins) for his arrogance and sent to Earth to live amongst humans. Falling in love with scientist Jane Foster (Natalie Portman) teaches Thor much-needed lessons, and his new-found strength comes into play as a villain from his homeland sends dark forces toward Earth.', 'https://image.tmdb.org/t/p/w500/prSfAi1xGrhLQNxVSUFh61xQ4Qy.jpg', null, null),
  ('Thor: Ragnarok', 2017, true, 'PG-13', 'Taika Waititi', '2017-11-03'::date, '130 min', 'Action, Adventure, Comedy', 'Eric Pearson, Craig Kyle, Christopher L. Yost', 'Chris Hemsworth, Tom Hiddleston, Cate Blanchett', 'Imprisoned on the other side of the universe, the mighty Thor (Chris Hemsworth) finds himself in a deadly gladiatorial contest that puts him against The Incredible Hulk (Mark Ruffalo), his former ally and fellow Avenger. Thor''s quest for survival leads him in a race against time to prevent the all-powerful Hela (Cate Blanchett) from destroying his home world and the Asgardian civilization.', 'https://image.tmdb.org/t/p/w500/rzRwTcFvttcN1ZpX2xv4j3tSdJu.jpg', null, null),
  ('Deadpool & Wolverine', 2024, true, 'R', 'Shawn Levy', '2024-07-26'::date, '128 min', 'Action, Adventure, Comedy', 'Ryan Reynolds, Rhett Reese, Paul Wernick', 'Ryan Reynolds, Hugh Jackman, Emma Corrin', 'Deadpool is offered a place in the Marvel Cinematic Universe by the Time Variance Authority, but instead recruits a variant of Wolverine to save his universe from extinction.', 'https://image.tmdb.org/t/p/w500/8cdWjvZQUExUUTzyp4t6EDMubfO.jpg', null, null),
  ('Thor: The Dark World', 2013, true, 'PG-13', 'Alan Taylor', '2013-11-08'::date, '112 min', 'Action, Adventure, Fantasy', 'Christopher L. Yost, Christopher Markus, Stephen McFeely', 'Chris Hemsworth, Natalie Portman, Tom Hiddleston', 'Thousands of years ago, a race of beings known as Dark Elves tried to send the universe into darkness by using a weapon known as the Aether. Warriors from Asgard stopped them, but their leader Malekith (Christopher Eccleston) escaped to wait for another opportunity. The warriors find the Aether, and since it cannot be destroyed, they try to hide it. In the present day, Jane Foster (Natalie Portman) awaits the return of Thor (Chris Hemsworth), although it has been two years since they last saw once another. In the meantime, Thor has been trying to bring peace to the nine realms. Jane discovers an anomaly similar to the one that brought Thor to Earth. She goes to investigate, finds a wormhole, and is sucked into it. Back on Asgard, Thor wishes to return to Earth, but his father, Odin (Sir Anthony Hopkins), refuses to let him. Thor learns from Heimdall (Idris Elba), who can see into all of the realms, that Jane disappeared. Thor then returns to Earth just as Jane reappears. However, when some Policemen try to arrest her, an unknown energy repulses them. Thor then brings Jane to Asgard to find out what happened to her. When the energy is released again, they discover that when Jane disappeared, she crossed paths with the Aether and it entered her. Malekith, upon sensing that the time to strike is now, seeks out the Aether. He attacks Asgard and Thor''s mother Frigga (Rene Russo) is killed protecting Jane. Odin wants to keep Jane on Asgard so that Malekith will come. Thor disagrees with his plan, so with his cohorts, he decides to take Jane away. He enlists the aid of his brother, Loki (Tom Hiddleston). Unfortunately, Loki''s motivations remain unknown.', 'https://image.tmdb.org/t/p/w500/wp6OxE4poJ4G7c0U2ZIXasTSMR7.jpg', null, null),
  ('Torque', 2004, false, 'PG-13', 'Joseph Kahn', '2004-01-16'::date, '84 min', 'Action, Comedy, Crime', 'Matt Johnson', 'Martin Henderson, Ice Cube, Monet Mazur', 'Biker Cary Ford is framed by an old rival and biker gang leader for the murder of another gang member who happens to be the brother of Trey (Ice Cube), leader of the most feared biker gang in the country. Ford is now on the run trying to clear his name from the murder with Trey and his gang looking for his blood.', 'https://image.tmdb.org/t/p/w500/pY35tW8BMAjZewl87OxjXK8ui02.jpg', null, null),
  ('Toy Story 4', 2019, false, 'G', 'Josh Cooley', '2019-06-21'::date, '100 min', 'Animation, Adventure, Comedy', 'John Lasseter, Andrew Stanton, Josh Cooley', 'Tom Hanks, Tim Allen, Annie Potts', 'Woody, Buzz Lightyear and the rest of the gang embark on a road trip with Bonnie and a new toy named Forky. The adventurous journey turns into an unexpected reunion as Woody''s slight detour leads him to his long-lost friend Bo Peep. As Woody and Bo discuss the old days, they soon start to realize that they''re two worlds apart when it comes to what they want from life as a toy.', 'https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', null, null),
  ('Transformers', 2007, true, 'PG-13', 'Michael Bay', '2007-07-03'::date, '144 min', 'Action, Adventure, Sci-Fi', 'Roberto Orci, Alex Kurtzman, John Rogers', 'Shia LaBeouf, Megan Fox, Josh Duhamel', 'High-school student Sam Witwicky buys his first car, who is actually the Autobot Bumblebee. Bumblebee defends Sam and his girlfriend Mikaela Banes from the Decepticon Barricade, before the other Autobots arrive on Earth. They are searching for the Allspark, and the war on Earth heats up as the Decepticons attack a United States military base in Qatar. Sam and Mikaela are taken by the top-secret agency Sector 7 to help stop the Decepticons, but when they learn the agency also intends to destroy the Autobots, they formulate their own plan to save the world.', 'https://image.tmdb.org/t/p/w500/1P7w3AImoEOWJX7nn3fdaKDfEQA.jpg', null, null),
  ('Tron', 1982, false, 'PG', 'Steven Lisberger', '1982-07-09'::date, '96 min', 'Action, Adventure, Sci-Fi', 'Steven Lisberger, Bonnie MacBird', 'Jeff Bridges, Bruce Boxleitner, David Warner', 'Hacker/arcade owner Kevin Flynn is digitally broken down into a data stream by a villainous software pirate known as Master Control and reconstituted into the internal, 3-D graphical world of computers. It is there, in the ultimate blazingly colorful, geometrically intense landscapes of cyberspace, that Flynn joins forces with Tron to outmaneuver the Master Control Program that holds them captive in the equivalent of a gigantic, infinitely challenging computer game.', 'https://image.tmdb.org/t/p/w500/zwSFEczP7AzqugAHHIX3zHniT0t.jpg', null, null),
  ('Tron: Legacy', 2010, false, 'PG', 'Joseph Kosinski', '2010-12-17'::date, '125 min', 'Action, Adventure, Sci-Fi', 'Edward Kitsis, Adam Horowitz, Brian Klugman', 'Jeff Bridges, Garrett Hedlund, Olivia Wilde', 'Sam Flynn, the tech-savvy 27-year-old son of Kevin Flynn, looks into his father''s disappearance and finds himself pulled into the same world of fierce programs and gladiatorial games where his father has been living for 20 years. Along with Kevin''s loyal confidant Quorra, father and son embark on a life-and-death journey across a visually-stunning cyber universe that has become far more advanced and exceedingly dangerous. Meanwhile, the malevolent program CLU, who dominates the digital world, plans to invade the real world and will stop at nothing to prevent their escape.', 'https://image.tmdb.org/t/p/w500/vuifSABRpSnxCAOxEnWpNbZSXpp.jpg', null, null),
  ('Twilight', 2008, true, 'PG-13', 'Catherine Hardwicke', '2008-11-21'::date, '122 min', 'Drama, Fantasy, Romance', 'Melissa Rosenberg, Stephenie Meyer', 'Kristen Stewart, Robert Pattinson, Billy Burke', 'Bella Swan has always been a little bit different. Never one to run with the crowd, Bella never cared about fitting in with the trendy girls at her Phoenix, Arizona high school. When her mother remarries and Bella chooses to live with her father in the rainy little town of Forks, Washington, she doesn''t expect much of anything to change. But things do change when she meets the mysterious and dazzlingly beautiful Edward Cullen. For Edward is nothing like any boy she''s ever met. He''s nothing like anyone she''s ever met, period. He''s intelligent and witty, and he seems to see straight into her soul. In no time at all, they are swept up in a passionate and decidedly unorthodox romance - unorthodox because Edward really isn''t like the other boys. He can run faster than a mountain lion. He can stop a moving car with his bare hands. Oh, and he hasn''t aged since 1918. Like all vampires, he''s immortal. That''s right - vampire. But he doesn''t have fangs - that''s just in the movies. And he doesn''t drink human blood, though Edward and his family are unique among vampires in that lifestyle choice. To Edward, Bella is that thing he has waited 90 years for - a soul mate. But the closer they get, the more Edward must struggle to resist the primal pull of her scent, which could send him into an uncontrollable frenzy. Somehow or other, they will have to manage their unmanageable love. But when unexpected visitors come to town and realize that there is a human among them Edward must fight to save Bella? A modern, visual, and visceral Romeo and Juliet story of the ultimate forbidden love affair - between vampire and mortal.', 'https://image.tmdb.org/t/p/w500/3Gkb6jm6962ADUPaCBqzz9CTbn9.jpg', null, null),
  ('Twister', 1996, false, 'PG-13', 'Jan de Bont', '1996-05-10'::date, '113 min', 'Action, Adventure, Thriller', 'Michael Crichton, Anne-Marie Martin', 'Helen Hunt, Bill Paxton, Jami Gertz', 'TV weatherman Bill Harding is trying to get his tornado-hunter wife, Jo, to sign divorce papers so he can marry his girlfriend Melissa. But Mother Nature, in the form of a series of intense storms sweeping across Oklahoma, has other plans. Soon the three have joined the team of stormchasers as they attempt to insert a revolutionary measuring device into the very heart of several extremely violent tornados.', 'https://image.tmdb.org/t/p/w500/d4ie3f6QTvNw40V770Uzo87SDZn.jpg', null, null),
  ('Underwater', 2020, false, 'PG-13', 'William Eubank', '2020-01-10'::date, '95 min', 'Action, Horror, Sci-Fi', 'Brian Duffield, Adam Cozad', 'Kristen Stewart, Vincent Cassel, Mamoudou Athie', 'An unknown, massive earthquake happens in a drilling station in the bottom of the Marianna Trench. A scientific crew must find their way across the ocean floor into another station under the threats of deep pressure, dark water, dangerous deep-sea creatures, and a constant lack of oxygen.', 'https://image.tmdb.org/t/p/w500/gzlbb3yeVISpQ3REd3Ga1scWGTU.jpg', null, null),
  ('Underworld', 2003, false, 'R', 'Len Wiseman', '2003-09-19'::date, '121 min', 'Action, Fantasy, Thriller', 'Kevin Grevioux, Len Wiseman, Danny McBride', 'Kate Beckinsale, Scott Speedman, Shane Brolly', 'Against the backdrop of an unseen centuries-old war between the sophisticated Vampire clan and the brutish clan of lycanthropes, the Lycans, the lethally alluring vampire assassin and member of the elite "Death Dealers" squad, Selene, has devoted her existence to eradicating the earth''s scattered pockets of remaining werewolves. With the death of the Lycans'' supreme overlord, Lucian, the vampires'' victory seems near; however, when their arch-enemy takes a special interest in the seemingly harmless human doctor, Michael Corvin, Selene will unearth a long-standing conspiracy. Now, treason, deceit, and conflicting feelings stand in the way of truth, forcing Selene to break protocol for the sake of the vampire race. Can a forbidden relationship put in jeopardy her noble quest? Is this the beginning of a new era, and an entirely different war?', 'https://image.tmdb.org/t/p/w500/zsnQ41UZ3jo1wEeemF0eA9cAIU0.jpg', null, null),
  ('Underworld: Blood Wars', 2016, false, 'R', 'Anna Foerster', '2017-01-06'::date, '91 min', 'Action, Fantasy, Thriller', 'Cory Goodman, Kyle Ward, Kevin Grevioux', 'Kate Beckinsale, Theo James, Tobias Menzies', 'The next installment in the blockbuster franchise, UNDERWORLD: BLOOD WARS follows Vampire death dealer, Selene (Kate Beckinsale) as she fends off brutal attacks from both the Lycan clan and the Vampire faction that betrayed her. With her only allies, David (Theo James) and his father Thomas (Charles Dance), she must stop the eternal war between Lycans and Vampires, even if it means she has to make the ultimate sacrifice.', 'https://image.tmdb.org/t/p/w500/v1ciDCWMG47gdT4kMyjyQbnLQQn.jpg', null, null),
  ('Underworld: Evolution', 2006, false, 'R', 'Len Wiseman', '2006-01-20'::date, '106 min', 'Action, Fantasy, Thriller', 'Danny McBride, Len Wiseman, Kevin Grevioux', 'Kate Beckinsale, Scott Speedman, Bill Nighy', 'As the war between the vampires and the Lycans rages on, the beautiful vampire, Selene, a former member of the Death Dealers, and Michael, the werewolf hybrid, work together in an effort to unlock the secrets of their respective bloodlines. In this ancient feud between the two tribes, they try to unlock the secrets, in a modern tale of action, intrigue, and forbidden love, which takes them into the battle to end all wars, as the immortals must finally face their doom.', 'https://image.tmdb.org/t/p/w500/yT1EDKhCzAumcZeBoAxqm0nY2H8.jpg', null, null),
  ('Underworld: Rise of the Lycans', 2009, false, 'R', 'Patrick Tatopoulos', '2009-01-23'::date, '92 min', 'Action, Fantasy, Thriller', 'Danny McBride, Dirk Blackman, Howard McCain', 'Rhona Mitra, Michael Sheen, Bill Nighy', 'The prequel story traces the origins of the centuries-old blood feud between the aristocratic vampires and their onetime slaves, the Lycans. In the Dark Ages, a young Lycan named Lucian emerges as a powerful leader who rallies the werewolves to rise up against Viktor, the cruel vampire king who has enslaved them. Lucian is joined by his secret lover, Sonja, in his battle against the Vampire army and his struggle for Lycan freedom.', 'https://image.tmdb.org/t/p/w500/yW9gF7rGn8EoV8B8rxOx1xjxVZf.jpg', null, null),
  ('Up', 2009, false, 'PG', 'Pete Docter, Bob Peterson', '2009-07-23'::date, '96 min', 'Animation, Adventure, Comedy', 'Pete Docter, Bob Peterson, Tom McCarthy', 'Edward Asner, Jordan Nagai, John Ratzenberger', 'As a boy, Carl Fredricksen wanted to explore South America and find the forbidden Paradise Falls. About 64 years later he gets to begin his journey along with Boy Scout Russell by lifting his house with thousands of balloons. On their journey, they make many new friends including a talking dog, and figure out that someone has evil plans. Carl soon realizes that this evildoer is his childhood idol.', 'https://image.tmdb.org/t/p/w500/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg', null, null),
  ('V for Vendetta', 2005, false, 'R', 'James McTeigue', '2006-03-17'::date, '132 min', 'Action, Drama, Sci-Fi', 'Lilly Wachowski, Lana Wachowski, David Lloyd', 'Hugo Weaving, Natalie Portman, Rupert Graves', 'In the distant future, Evey Hammond is an average citizen of the United Kingdom, which is under the rule of the fascist and tyrannical Norsefire Party. She is an employee of the state-run British Television Network, but soon, she becomes the number one enemy of the state together with an enigmatic and larger-than-life freedom fighter known only by the letter "V". V informs Evey that she must hide in his underground lair for at least one year, and while she is reluctant to the idea at first, a bond soon forms between the two individuals. In the meanwhile, the mysterious past of V is gradually revealed to the police inspector tasked with capturing him, Eric Finch, and it is not long until he starts questioning everything his government stands for.', 'https://image.tmdb.org/t/p/w500/piZOwjyk1g51oPHonc7zaQY3WOv.jpg', null, null),
  ('Venom', 2018, true, 'PG-13', 'Ruben Fleischer', '2018-10-05'::date, '112 min', 'Action, Adventure, Sci-Fi', 'Jeff Pinkner, Scott Rosenberg, Kelly Marcel', 'Tom Hardy, Michelle Williams, Riz Ahmed', 'After a faulty interview with the Life Foundation ruins his career, former reporter Eddie Brock''s life is in pieces. Six months later, he comes across the Life Foundation again, and he comes into contact with an alien symbiote and becomes Venom, a parasitic antihero.', 'https://image.tmdb.org/t/p/w500/2uNW4WbgBXL25BAbXGLnLqX71Sw.jpg', null, null),
  ('Volcano', 1997, true, 'PG-13', 'Mick Jackson', '1997-04-25'::date, '104 min', 'Action, Drama, Sci-Fi', 'Jerome Armstrong, Billy Ray', 'Tommy Lee Jones, Anne Heche, Gaby Hoffmann', 'Something unspeakably chilling is ultimately starting to heat up at The City of Los Angeles! Beneath the famed La Brea Tar Pits, a raging volcano has formed, raining a storm of deadly fire bombs and an endless tide of white-hot lava upon the stunned city!', 'https://image.tmdb.org/t/p/w500/5xIjktjXuro7anZ6AR58t5ZYWjQ.jpg', null, null),
  ('WALL-E', 2008, false, 'G', 'Andrew Stanton', '2008-06-29'::date, '98 min', 'Animation, Adventure, Family', 'Andrew Stanton, Pete Docter, Jim Reardon', 'Ben Burtt, Elissa Knight, Jeff Garlin', 'In a distant, but not so unrealistic, future where mankind has abandoned earth because it has become covered with trash from products sold by the powerful multi-national Buy N Large corporation, WALL-E, a garbage collecting robot has been left to clean up the mess. Mesmerized with trinkets of Earth''s history and show tunes, WALL-E is alone on Earth except for a sprightly pet cockroach. One day, EVE, a sleek (and dangerous) reconnaissance robot, is sent to Earth to find proof that life is once again sustainable. WALL-E falls in love with EVE. WALL-E rescues EVE from a dust storm and shows her a living plant he found amongst the rubble. Consistent with her "directive", EVE takes the plant and automatically enters a deactivated state except for a blinking green beacon. WALL-E, doesn''t understand what has happened to his new friend, but, true to his love, he protects her from wind, rain, and lightning, even as she is unresponsive. One day a massive ship comes to reclaim EVE, but WALL-E, out of love or loneliness, hitches a ride on the outside of the ship to rescue EVE. The ship arrives back at a large space cruise ship, which is carrying all of the humans who evacuated Earth 700 years earlier. The people of Earth ride around this space resort on hovering chairs which give them a constant feed of TV and video chatting. They drink all of their meals through a straw out of laziness and/or bone loss, and are all so fat that they can barely move. When the auto-pilot computer, acting on hastily-given instructions sent many centuries before, tries to prevent the people of Earth from returning by stealing the plant, WALL-E, EVE, the portly captain, and a band of broken robots stage a mutiny.', null, null, null),
  ('War', 2007, false, 'R', 'Philip G. Atwell', '2007-08-24'::date, '103 min', 'Action, Crime, Thriller', 'Lee Anthony Smith, Gregory J. Bradley', 'Jet Li, Jason Statham, Nadine Velazquez', 'After his partner Tom Lone and family are killed apparently by the infamous and elusive assassin Rogue, FBI agent John Crawford becomes obsessed with revenge as his world unravels into a vortex of guilt and betrayal. Rogue eventually resurfaces to settle a score of his own, setting off a bloody crime war between Asian mob rivals Chang of the Triad''s and Yakuza boss Shiro. When Jack and Rogue finally come face to face, the ultimate truth of their pasts will be revealed.', 'https://image.tmdb.org/t/p/w500/scFc8RD4sFxB2x0eIOaymphMnYh.jpg', null, null),
  ('Warm Bodies', 2013, false, 'PG-13', 'Jonathan Levine', '2013-02-01'::date, '98 min', 'Comedy, Horror, Romance', 'Isaac Marion, Jonathan Levine', 'Nicholas Hoult, Teresa Palmer, John Malkovich', 'With much of the world''s population now an undead horde, R is a young and oddly introspective zombie. While fighting with and feeding on a human scavenger party, R meets Julie and feels an urge to protect her. What happens next is the beginning of a strangely warm relationship that allows R to begin regaining his humanity. As this change spreads through the local undead population like a virus, Julie and R eventually have to face a larger issue when the very nature of their friendship is challenged. Caught between the paranoid human forces and the ferocious "Bonies", zombies who are a mutual threat, R and Julie must find a way to bridge the differences of each side to fight for a better world no one thought possible.', 'https://image.tmdb.org/t/p/w500/c9aMzKmb5yqxLYLRbvrxJh2xlKY.jpg', null, null),
  ('Watchmen', 2009, false, 'R', 'Zack Snyder', '2009-03-06'::date, '162 min', 'Action, Drama, Mystery', 'Dave Gibbons, David Hayter, Alex Tse', 'Jackie Earle Haley, Patrick Wilson, Carla Gugino', 'It''s 1985 in an alternate reality. The Watchmen - comprised of the Comedian, Dr. Manhattan, Nite Owl II, Ozymandias, Rorschach and Silk Spectre II - are a disparate band of masked superheroes, modeled after the Minutemen, who were masked superheroes of a generation earlier, most of who are dead or afflicted by the ravages of life. The Comedian belongs to both groups. Despite the activities of the Watchmen leading to the west winning the Vietnam War which in turn has kept Richard Nixon in the White House, Nixon has now outlawed masks, resulting in the Watchmen disbanding and going into retirement, most hiding their Watchmen past under their human identities. However, the Comedian, in his human persona of Eddie Blake, and Dr. Manhattan - former physicist Jon Osterman who obtained his superhero powers through a scientific accident which almost killed him - now work for the government. Dr. Manhattan''s powers in particular have kept a watch over nuclear proliferation, as he is able to stop any nuclear attack. Regardless, the Cold War is at its height with recent Soviet posturing regarding nuclear bomb buildup. In her human persona of Laurie Jupiter, Silk Spectre II is Dr. Manhattan''s assistant and lover, as much as they can be in Dr. Manhattan''s now non-human state. Meanwhile, Ozymandias has come out to the world as wealthy genius Adrian Veidt, capitalizing on his Ozymandias identity to better the world, and Rorschach continues to work as a vigilante, although one wanted by the law despite he the reason that many criminals are behind bars. When Blake is murdered, Rorschach, as the only one still on the streets, believes the murderer is out to kill all the Watchmen, despite any number of people wanting to kill the Comedian for being a misogynist. Evidence points to it perhaps having something to do with an imminent attempt of nuclear annihilation. Rorschach has to convince his colleagues, who he has not seen since their superhero days, of the validity of his theory for them to come out of retirement, which is no easy task. If they do, which will require them to overcome external forces which seem to be conspiring against them, they will have to discover both who killed the Comedian and why before they befall the same fate as him and/or before the mastermind is able to exact his larger grand plan.', 'https://image.tmdb.org/t/p/w500/aVURelN3pM56lFM7Dgfs5TixcIf.jpg', null, null),
  ('Waterworld', 1995, false, 'PG-13', 'Kevin Reynolds', '1995-07-28'::date, '135 min', 'Action, Adventure, Sci-Fi', 'Peter Rader, David Twohy', 'Kevin Costner, Jeanne Tripplehorn, Dennis Hopper', 'The polar ice caps have melted, and the earth is covered by water. The remaining people travel the seas, in search of survival. Several different societies exist. The Mariner falls from his customary and solitary existence into having to care for a woman and a young girl while being pursued by the evil forces of the Deacon.', 'https://image.tmdb.org/t/p/w500/X4UyUO5jgzs3c5YafnmYKLKKYw.jpg', null, null),
  ('Weird Science', 1985, false, 'PG-13', 'John Hughes', '1985-08-02'::date, '94 min', 'Comedy, Romance, Sci-Fi', 'John Hughes, Al Feldstein, William M. Gaines', 'Anthony Michael Hall, Ilan Mitchell-Smith, Kelly LeBrock', 'Two unpopular teenagers, Gary Wallace and Wyatt Donnelly, fail at all attempts to be accepted by their peers. Their desperation to be liked leads them to "create" a woman via their computer. Their living and breathing creation is a gorgeous woman, Lisa, whose purpose is to boost their confidence level by putting them into situations which require Gary and Wyatt to act like men. On their road to becoming accepted, they encounter many hilarious obstacles, which gives the movie an overall sense of silliness.', 'https://image.tmdb.org/t/p/w500/jaEauZd2joSAKn42D83gm3S0y3F.jpg', null, null),
  ('What We Do in the Shadows', 2014, false, 'R', 'Jemaine Clement, Taika Waititi', '2015-02-13'::date, '86 min', 'Comedy, Horror', 'Jemaine Clement, Taika Waititi', 'Jemaine Clement, Taika Waititi, Cori Gonzalez-Macuer', 'Follow the lives of Viago (Taika Waititi), Deacon (Jonathan Brugh), and Vladislav (Jemaine Clement) - three flatmates who are just trying to get by and overcome life''s obstacles-like being immortal vampires who must feast on human blood. Hundreds of years old, the vampires are finding that beyond sunlight catastrophes, hitting the main artery, and not being able to get a sense of their wardrobe without a reflection-modern society has them struggling with the mundane like paying rent, keeping up with the chore wheel, trying to get into nightclubs, and overcoming flatmate conflicts.', 'https://image.tmdb.org/t/p/w500/a2rD3i3DBMeYbA34rBv6z3B9S3a.jpg', null, null),
  ('Whiskey Tango Foxtrot', 2016, false, 'R', 'Glenn Ficarra, John Requa', '2016-03-04'::date, '112 min', 'Biography, Comedy, Drama', 'Robert Carlock, Kim Barker', 'Tina Fey, Margot Robbie, Martin Freeman', '2003. After careful consideration, Kim Baker, a news copywriter, decides to leave the relative comfort of a New York desk job and serious boyfriend Chris to accept the assignment to work for three months as on-camera reporter in war torn Afghanistan, as her news agency is looking for anyone within their ranks to fill immediately the empty voids overseas. Her only experience of being in such an environment is going through hostile zone training a few years earlier. Immediately upon her arrival in Afghanistan, she realizes that she is ill-prepared emotionally for this assignment, not only enduring the dangers of the war itself, but also the conditions of everyday life, including largely been seen by men as only a "piece of ass" and a distraction despite her being considered average looking back home and not being overtly sexual, and being an individual with a small bladder who is nonetheless told to stay hydrated at all times. She is largely assisted in navigating this new life by Tanya Vanderpoel, a fellow female western correspondent, and Fahim Ahmadzai, her Afghan translator guide. As time goes on, Kim finds that she not only may have a specific and important voice within the press corps, but that she may be losing touch with her life back in the States for good or bad. In addition, she will have to decide how much she is willing to risk, not only for herself but that for her colleagues, to get that next important story. She also has to figure out how much of what she does truly is her, and how much is being as she and the other western press corps members state is being in the "Kabubble". What may also affect her life is how much the war in Afghanistan is overtaken by other world events for which the American public is wanting information, and thus if Afghanistan has a specific time span in her life regardless of how much she may want to stay to tell what she sees as its important stories.', 'https://image.tmdb.org/t/p/w500/xhWbp0lCig5vkdFZPiOGNRL9oMf.jpg', null, null),
  ('Wonder Woman', 2017, false, 'PG-13', 'Patty Jenkins', '2017-06-02'::date, '141 min', 'Action, Adventure, Fantasy', 'Allan Heinberg, Zack Snyder, Jason Fuchs', 'Gal Gadot, Chris Pine, Robin Wright', 'Diana, princess of the Amazons, trained to be an unconquerable warrior. Raised on a sheltered island paradise, when a pilot crashes on their shores and tells of a massive conflict raging in the outside world, Diana leaves her home, convinced she can stop the threat. Fighting alongside man in a war to end all wars, Diana will discover her full powers and her true destiny.', 'https://image.tmdb.org/t/p/w500/v4ncgZjG2Zu8ZW5al1vIZTsSjqX.jpg', null, null),
  ('Wreck-It Ralph', 2012, false, 'PG', 'Rich Moore', '2012-11-02'::date, '101 min', 'Animation, Adventure, Comedy', 'Rich Moore, Phil Johnston, Jim Reardon', 'John C. Reilly, Jack McBrayer, Jane Lynch', 'Wreck-It Ralph longs to be as beloved as his game''s perfect Good Guy, Fix-It Felix. Problem is, nobody loves a Bad Guy. But they do love heroes... so when a modern, first-person shooter game arrives featuring tough-as-nails Sergeant Calhoun, Ralph sees it as his ticket to heroism and happiness. He sneaks into the game with a simple plan -- win a medal -- but soon wrecks everything, and accidentally unleashes a deadly enemy that threatens every game in the arcade. Ralph''s only hope? Vanellope von Schweetz, a young troublemaking "glitch" from a candy-coated cart racing game who might just be the one to teach Ralph what it means to be a Good Guy. But will he realize he is good enough to become a hero before it''s "Game Over" for the entire arcade?', 'https://image.tmdb.org/t/p/w500/zWoIgZ7mgmPkaZjG0102BSKFIqQ.jpg', null, null),
  ('Wrong Turn', 2003, false, 'R', 'Rob Schmidt', '2003-05-30'::date, '84 min', 'Horror, Thriller', 'Alan B. McElroy', 'Eliza Dushku, Jeremy Sisto, Emmanuelle Chriqui', 'Chris Flynn is driving his car for a job interview in another city. However, an accident with a trunk transporting chemical products blocks the highway and Chris looks for an alternative route through the mountains of West Virginia to accomplish his schedule. Due to a lack of attention, he crashes another car parked in the middle of the road with flat tires. Chris meets a group of five friends, who intended to camp in the forest, and they decide to leave the couple Francine and Evan on the place, while Chris, Jessie, Carly and her fiancé Scott tries to find some help. They find a weird cabin in the middle of nowhere, where three violent cannibalistic mountain men with the appearance of monsters live. The two couples try to escape from the mountain men while chased by them.', 'https://image.tmdb.org/t/p/w500/7lyxwOg7SdGff79yKCQmJ3AKWSf.jpg', null, null),
  ('X-Men: Apocalypse', 2016, true, 'PG-13', 'Bryan Singer', '2016-05-27'::date, '144 min', 'Action, Adventure, Sci-Fi', 'Simon Kinberg, Bryan Singer, Michael Dougherty', 'James McAvoy, Michael Fassbender, Jennifer Lawrence', 'Since the dawn of civilization, he was worshiped as a god. Apocalypse, the first and most powerful mutant from Marvel''s X-Men universe, amassed the powers of many other mutants, becoming immortal and invincible. Upon awakening after thousands of years, he is disillusioned with the world as he finds it and recruits a team of powerful mutants, including a disheartened Magneto, to cleanse mankind and create a new world order, over which he will reign. As the fate of the Earth hangs in the balance, Raven with the help of Professor X must lead a team of young X-Men to stop their greatest nemesis and save mankind from complete destruction.', 'https://image.tmdb.org/t/p/w500/ikA8UhYdTGpqbatFa93nIf6noSr.jpg', null, null),
  ('X-Men: Days of Future Past', 2014, true, 'PG-13', 'Bryan Singer', '2014-05-23'::date, '132 min', 'Action, Adventure, Sci-Fi', 'Simon Kinberg, Jane Goldman, Matthew Vaughn', 'Patrick Stewart, Ian McKellen, Hugh Jackman', 'In the future, the mutants and the humans who help them are slaughtered by powerful robots named Sentinels. Professor Xavier, Wolverine, Magneto, Storm, Kitty Pryde, and her friends meet at a monastery in China and Xavier explains that the invincible Sentinels were created using the DNA of Mystique that was captured in 1973 when she tried to assassinate their creator Dr. Bolivar Trask. Xavier tells that their only chance is return to 1973 using Pryde''s ability to join Charles Xavier and Erik Lehnsherr to convince Mystique to give up her intention. However, only Wolverine can withstand the damages of the time travel. Will he succeed in stopping Mystique and the Sentinel Program, and save the mutants and their human friends from annihilation?', 'https://image.tmdb.org/t/p/w500/tYfijzolzgoMOtegh1Y7j2Enorg.jpg', null, null),
  ('X-Men: First Class', 2011, true, 'PG-13', 'Matthew Vaughn', '2011-06-03'::date, '131 min', 'Action, Sci-Fi', 'Ashley E. Miller, Zack Stentz, Jane Goldman', 'James McAvoy, Michael Fassbender, Jennifer Lawrence', 'Before Charles Xavier and Erik Lensherr took the names Professor X and Magneto, they were two young men discovering their powers for the first time. Before they were archenemies, they were closest of friends, working together, with other Mutants (some familiar, some new), to stop the greatest threat the world has ever known. In the process, a rift between them opened, which began the eternal war between Magneto''s Brotherhood and Professor X''s X-MEN.', 'https://image.tmdb.org/t/p/w500/hNEokmUke0dazoBhttFN0o3L7Xv.jpg', null, null),
  ('Zombieland', 2009, false, 'R', 'Ruben Fleischer', '2009-10-02'::date, '88 min', 'Action, Comedy, Horror', 'Rhett Reese, Paul Wernick', 'Jesse Eisenberg, Emma Stone, Woody Harrelson', 'Searching for family. In the early twenty-first century, zombies have taken over America. A shy and college student in Texas has survived by following his 30 rules: like "look in the back seat," "double-tap," "avoid public restrooms." He decides to travel to Ohio to see if his parents are alive. He gets a ride with a savage, brutal zombie-killer headed for Florida, and soon they confront a young woman whose sister has been bitten by a zombie and wants to be put out of her suffering. The sisters were headed to an LA park with atractions they''ve heard is without a zombie.', 'https://image.tmdb.org/t/p/w500/dUkAmAyPVqubSBNRjRqCgHggZcK.jpg', null, null),
  ('Zootopia', 2016, false, 'PG', 'Byron Howard, Rich Moore, Jared Bush', '2016-03-04'::date, '108 min', 'Animation, Action, Adventure', 'Byron Howard, Rich Moore, Jared Bush', 'Ginnifer Goodwin, Jason Bateman, Idris Elba', 'From the largest elephant to the smallest shrew, the city of Zootopia is a mammal metropolis where various animals live and thrive. When Judy Hopps becomes the first rabbit to join the police force, she quickly learns how tough it is to enforce the law. Determined to prove herself, Judy jumps at the opportunity to solve a mysterious case. Unfortunately, that means working with Nick Wilde, a wily fox who makes her job even harder.', 'https://image.tmdb.org/t/p/w500/hlK0e0wAQ3VLuJcsfIYPvb4JVud.jpg', null, null),
  ('Back to the Future', 1985, true, 'PG', 'Robert Zemeckis', '1985-07-03'::date, '116 min', 'Adventure, Comedy, Sci-Fi', 'Robert Zemeckis, Bob Gale', 'Michael J. Fox, Christopher Lloyd, Lea Thompson', 'Marty McFly, a typical American teenager of the Eighties, is accidentally sent back to 1955 in a plutonium-powered DeLorean "time machine" invented by a slightly mad scientist. During his often hysterical, always amazing trip back in time, Marty must make certain his teenage parents-to-be meet and fall in love - so he can get back to the future.', 'https://image.tmdb.org/t/p/w500/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg', null, null),
  ('Back to the Future Part II', 1989, true, 'PG', 'Robert Zemeckis', '1989-11-22'::date, '108 min', 'Adventure, Comedy, Sci-Fi', 'Robert Zemeckis, Bob Gale', 'Michael J. Fox, Christopher Lloyd, Lea Thompson', 'Marty McFly has only just gotten back from the past, when he is once again picked up by Dr. Emmett Brown and sent through time to the future. Marty''s job in the future is to pose as his own son to prevent him from being thrown in prison. Unfortunately, things get worse when the future changes the present.', 'https://image.tmdb.org/t/p/w500/YBawEsTkUZBDajKbd5LiHkmMGf.jpg', null, null),
  ('Back to the Future Part III', 1990, true, 'PG', 'Robert Zemeckis', '1990-05-25'::date, '118 min', 'Adventure, Comedy, Sci-Fi', 'Robert Zemeckis, Bob Gale', 'Michael J. Fox, Christopher Lloyd, Mary Steenburgen', 'Stranded in 1955, Marty McFly receives written word from his friend, Doctor Emmett Brown, as to where can be found the DeLorean time machine. However, an unfortunate discovery prompts Marty to go to his friend''s aid. Using the time machine, Marty travels to the old west where his friend has run afoul of a gang of thugs and has fallen in love with a local schoolteacher. Using the technology from the time, Marty and Emmett devise one last chance to send the two of them back to the future.', 'https://image.tmdb.org/t/p/w500/crzoVQnMzIrRfHtQw0tLBirNfVg.jpg', null, null),
  ('Batman Begins', 2005, true, 'PG-13', 'Christopher Nolan', '2005-06-15'::date, '140 min', 'Action, Crime, Drama', 'Bob Kane, David S. Goyer, Christopher Nolan', 'Christian Bale, Michael Caine, Ken Watanabe', 'When his parents are killed, billionaire playboy Bruce Wayne relocates to Asia, where he is mentored by Henri Ducard and Ra''s Al Ghul in how to fight evil. When learning about the plan to wipe out evil in Gotham City by Ducard, Bruce prevents this plan from getting any further and heads back to his home. Back in his original surroundings, Bruce adopts the image of a bat to strike fear into the criminals and the corrupt as the icon known as "Batman". But it doesn''t stay quiet for long.', 'https://image.tmdb.org/t/p/w500/sPX89Td70IDDjVr85jdSBb4rWGr.jpg', null, null),
  ('The Black Phone', 2021, true, 'R', 'Scott Derrickson', '2022-06-24'::date, '103 min', 'Horror, Mystery, Thriller', 'Joe Hill, Scott Derrickson, C. Robert Cargill', 'Mason Thames, Madeleine McGraw, Ethan Hawke', 'Finney Shaw is a shy but clever 13-year-old boy who is abducted by a sadistic killer and trapped in a soundproof basement where screaming is of no use. When a disconnected phone on the wall begins to ring, Finney discovers that he can hear the voices of the killer''s previous victims. And they are dead-set on making sure that what happened to them doesn''t happen to Finney.', 'https://image.tmdb.org/t/p/w500/p9ZUzCyy9wRTDuuQexkQ78R2BgF.jpg', null, null),
  ('Godzilla x Kong: The New Empire', 2024, true, 'PG-13', 'Adam Wingard', '2024-03-29'::date, '115 min', 'Action, Adventure, Fantasy', 'Terry Rossio, Adam Wingard, Simon Barrett', 'Rebecca Hall, Brian Tyree Henry, Dan Stevens', 'Two ancient titans, Godzilla and Kong, clash in an epic battle as humans unravel their intertwined origins and connection to Skull Island''s mysteries.', 'https://image.tmdb.org/t/p/w500/z1p34vh7dEOnLDmyCrlUVLuoDzd.jpg', null, null),
  ('Hamilton', 2020, true, 'PG-13', 'Thomas Kail', '2020-07-03'::date, '160 min', 'Biography, Drama, History', 'Lin-Manuel Miranda, Ron Chernow', 'Lin-Manuel Miranda, Phillipa Soo, Leslie Odom Jr.', 'Hamilton is the story of America then, told by America now. Featuring a score that blends hip-hop, jazz, R&amp;B, and show tunes, "Hamilton" has taken the story of American founding father Alexander Hamilton and created a revolutionary moment in theater--a musical that has had a profound impact on culture, politics, and education. Captured at the Richard Rodgers Theater on Broadway in June 2016, the film transports its audience into the world of the Broadway show in a uniquely intimate way.', 'https://image.tmdb.org/t/p/w500/h1B7tW0t399VDjAcWJh8m87469b.jpg', null, null),
  ('Jennifer''s Body', 2009, true, 'R', 'Karyn Kusama', '2009-09-18'::date, '102 min', 'Comedy, Horror', 'Diablo Cody', 'Megan Fox, Amanda Seyfried, Adam Brody', 'Nerdy, reserved bookworm Needy Lesnicki, and arrogant, conceited cheerleader Jennifer Check are best friends, though they share little in common. They share even less in common when Jennifer mysteriously gains an appetite for human blood after a disastrous fire at a local bar. As Needy''s male classmates are steadily killed in gruesome attacks, the young girl must uncover the truth behind her friend''s transformation and find a way to stop the bloodthirsty rampage before it reaches her own boyfriend Chip.', 'https://image.tmdb.org/t/p/w500/wrkjsGcFJxcQqR56kJUYAEKKg2T.jpg', null, null),
  ('The King''s Speech', 2010, true, 'R', 'Tom Hooper', '2010-12-25'::date, '118 min', 'Biography, Drama, History', 'David Seidler', 'Colin Firth, Geoffrey Rush, Helena Bonham Carter', 'Britain''s Prince Albert (Colin Firth) must ascend the throne as King George VI, but he has a speech impediment. Knowing that the country needs her husband to be able to communicate effectively, Elizabeth (Helena Bonham Carter) hires Lionel Logue (Geoffrey Rush), an Australian actor and speech therapist, to help him overcome his stammer. An extraordinary friendship develops between the two men, as Logue uses unconventional means to teach the monarch how to speak with confidence.', 'https://image.tmdb.org/t/p/w500/pVNKXVQFukBaCz6ML7GH3kiPlQP.jpg', null, null),
  ('Kingdom of the Planet of the Apes', 2024, true, 'PG-13', 'Wes Ball', '2024-05-10'::date, '145 min', 'Action, Adventure, Drama', 'Josh Friedman, Rick Jaffa, Amanda Silver', 'Owen Teague, Freya Allan, Kevin Durand', 'Many years after the reign of Caesar, a young ape goes on a journey that will lead him to question everything he''s been taught about the past and make choices that will define a future for apes and humans alike.', 'https://image.tmdb.org/t/p/w500/gKkl37BQuKTanygYQG1pyYgLVgf.jpg', null, null),
  ('Knock at the Cabin', 2023, true, 'R', 'M. Night Shyamalan', '2023-02-03'::date, '100 min', 'Horror, Mystery, Thriller', 'Paul Tremblay, M. Night Shyamalan, Steve Desmond', 'Dave Bautista, Jonathan Groff, Ben Aldridge', 'While vacationing, a girl and her parents are taken hostage by armed strangers who demand that the family make a choice to avert the apocalypse.', 'https://image.tmdb.org/t/p/w500/dm06L9pxDOL9jNSK4Cb6y139rrG.jpg', null, null),
  ('Latency', 2024, true, 'PG-13', 'James Croke', '2024-06-14'::date, '94 min', 'Action, Horror, Thriller', 'James Croke', 'Sasha Luss, Alexis Ren, Kelly B. Jones', 'When Hana, a professional gamer who suffers from acute agoraphobia, receives new equipment that enhances her game, she begins to wonder if it is reading her mind - or controlling it.', 'https://image.tmdb.org/t/p/w500/yNBDVUFmvgCgxzpEl5ZJ9TUSc8t.jpg', null, null),
  ('Longlegs', 2024, true, 'R', 'Osgood Perkins', '2024-07-12'::date, '101 min', 'Crime, Horror, Thriller', 'Osgood Perkins', 'Maika Monroe, Nicolas Cage, Blair Underwood', 'In pursuit of a serial killer, an FBI agent uncovers a series of occult clues that she must solve to end his terrifying killing spree.', 'https://image.tmdb.org/t/p/w500/1EwNyiiNFd863H4e8nWEzutnZD7.jpg', null, null),
  ('MaXXXine', 2024, true, 'R', 'Ti West', '2024-07-05'::date, '103 min', 'Crime, Horror', 'Ti West', 'Charley Rowan McCain, Simon Prast, Mia Goth', 'In 1980s Hollywood, adult film star and aspiring actress Maxine Minx finally gets her big break. But as a mysterious killer stalks the starlets of Hollywood, a trail of blood threatens to reveal her sinister past.', 'https://image.tmdb.org/t/p/w500/ArvoFK6nlouZRxYmtIOUzKIrg90.jpg', null, null),
  ('Medicine Man', 1992, true, 'PG-13', 'John McTiernan', '1992-02-07'::date, '106 min', 'Adventure, Drama, Romance', 'Tom Schulman, Sally Robinson', 'Sean Connery, Lorraine Bracco, José Wilker', 'In the beautiful and dangerous Amazon rainforest, dissimilar people must make their choices between business, science, and love.', 'https://image.tmdb.org/t/p/w500/lkHqtViTG4Zzh7i9rrtHJGTnEUg.jpg', null, null),
  ('Midsommar', 2019, true, 'R', 'Ari Aster', '2019-07-03'::date, '148 min', 'Drama, Horror, Mystery', 'Ari Aster', 'Florence Pugh, Jack Reynor, Vilhelm Blomgren', 'Dani (Florence Pugh) and Christian (Jack Reynor) are a young American couple with a relationship on the brink of falling apart. But after a family tragedy keeps them together, Christian invites a grieving Dani to join him and his friends on a trip to a once-in-a-lifetime midsummer festival in a remote Swedish village. What begins as a carefree summer holiday in the North European land of eternal sunlight takes a sinister turn when the insular villagers invite their guests to partake in festivities that render the pastoral paradise increasingly unnerving and viscerally disturbing.', 'https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', null, null),
  ('A Time to Kill', 1996, true, 'R', 'Joel Schumacher', '1996-07-24'::date, '149 min', 'Crime, Drama, Thriller', 'John Grisham, Akiva Goldsman', 'Matthew McConaughey, Sandra Bullock, Samuel L. Jackson', 'When Tonya Hailey, an innocent little African-American girl is raped and beaten by 2 beer-guzzling rednecks, the town of Clanton, Mississippi is shocked. Her father Carl Lee Hailey is outraged, and figuring he could not see those boys set free, decides to take justice into his own hands and kills them in the court house, in front of numerous witnesses. Now it''s up to Jake Brigance to get Carl Lee off the hook. He has people that help him, but he is up against tough D.A. Rufus Buckley. Will he be able to prove that a black man can get a fair trial in Mississippi?', 'https://image.tmdb.org/t/p/w500/w8UCke112E9jrhjKcwG32kyhTx5.jpg', null, null),
  ('Tower of Terror', 1997, true, 'Unrated', 'D.J. MacHale', '1997-10-26'::date, '89 min', 'Comedy, Family, Horror', 'D.J. MacHale', 'Steve Guttenberg, Nia Peeples, Michael McShane', 'A disgraced reporter investigates an abandoned luxury hotel where five people mysteriously disappeared sixty years earlier.', 'https://image.tmdb.org/t/p/w500/eZ17PwwacUBMMGWiQUGjwkag5sy.jpg', null, null),
  ('Twisters', 2024, true, 'PG-13', 'Lee Isaac Chung', '2024-07-19'::date, '122 min', 'Action, Adventure, Thriller', 'Mark L. Smith, Joseph Kosinski, Michael Crichton', 'Daisy Edgar-Jones, Glen Powell, Anthony Ramos', 'Kate Carter, a retired tornado-chaser and meteorologist, is persuaded to return to Oklahoma to work with a new team and new technologies.', 'https://image.tmdb.org/t/p/w500/pjnD08FlMAIXsfOLKQbvmO0f0MD.jpg', null, null),
  ('Uglies', 2024, true, 'PG-13', 'McG', '2024-09-13'::date, '100 min', 'Action, Adventure, Drama', 'Jacob Forman, Vanessa Taylor, Whit Anderson', 'Joey King, Brianne Tju, Keith Powers', 'A world in which a compulsory operation wipes out physical differences and makes everyone pretty.', 'https://image.tmdb.org/t/p/w500/jaUu9zHtbcFwrB5Y1DNYE09HMex.jpg', null, null),
  ('The Untouchables', 1987, true, 'R', 'Brian De Palma', '1987-06-03'::date, '119 min', 'Crime, Drama, Thriller', 'David Mamet, Oscar Fraley, Eliot Ness', 'Kevin Costner, Sean Connery, Robert De Niro', 'After building an empire with bootleg alcohol, legendary crime boss Al Capone rules Chicago with an iron fist. Though Prohibition Agent Eliot Ness attempts to take Capone down, even his best efforts fail due to widespread corruption within the Windy City''s police force. Recruiting an elite group of lawmen who won''t be swayed by bribes or fear, including Irish-American cop Jimmy Malone, Ness renews his determination to bring Capone to justice.', 'https://image.tmdb.org/t/p/w500/8BquGK22zCcsmBWiaIakaaPpSZb.jpg', null, null),
  ('Upgrade', 2018, true, 'R', 'Leigh Whannell', '2018-06-01'::date, '100 min', 'Action, Sci-Fi, Thriller', 'Leigh Whannell', 'Logan Marshall-Green, Melanie Vallejo, Steve Danielsen', 'Grey''s a stay-at-home mechanic, whose wife is Asha. One day, Grey asks Asha to help him return a car to his client. Whilst Grey and Asha''s self-driving car malfunctions, it crashes. Grey watches helplessly as Asha bleeds to death next to him. Grey returns home - a widowed quadriplegic, under the care of his mother. His wife''s death and the inability of police to identify their attackers cause him to sink into a depression. After a suicide attempt, he''s offered to have high tech chip implanted - enabling him to walk. Though initially hesitant, he''s persuaded to have the surgery.', 'https://image.tmdb.org/t/p/w500/woLGROUdPWdBnLVFKYdGD3kFkPY.jpg', null, null),
  ('V/H/S Beyond', 2024, true, 'Not Rated', 'Jay Cheel, Jordan Downey, Christian Long', '2024-10-04'::date, '114 min', 'Horror', 'Evan Dickson, Jordan Downey, Mike Flanagan', 'Phillip Andre Botello, Jolene Andersen, Tyler Andrews', 'Six bloodcurdling tapes unleash horror in a sci-fi inspired hellscape, pushing the boundaries of fear and suspense.', 'https://image.tmdb.org/t/p/w500/wXaf6VGNHIGU7qivapGOF7o4o4N.jpg', null, null),
  ('Mission: Impossible', 1996, true, 'PG-13', 'Brian De Palma', '1996-05-22'::date, '110 min', 'Action, Adventure, Thriller', 'Bruce Geller, David Koepp, Steven Zaillian', 'Tom Cruise, Jon Voight, Emmanuelle Béart', 'Based on the hit television series. Jim Phelps (Jon Voight) was sent to Prague for a mission to prevent the theft of classified material. His wife Claire (Emmanuelle Béart) and his trusted partner Ethan Hunt (Tom Cruise) were members of Phelps'' team. Unfortunately, something went horribly wrong and the mission failed, leaving Ethan Hunt the seemingly lone survivor. After he reported the failed mission, Kittridge (Henry Czerny), the head of the agency, suspects Ethan of being the culprit for the failed mission. Now, Ethan uses unorthodox methods (which includes the aid of an arms dealer going by the name "Max" (Vanessa Redgrave)) to try to find who set him up and to clear his name.', 'https://image.tmdb.org/t/p/w500/l5uxY5m5OInWpcExIpKG6AR3rgL.jpg', null, null),
  ('Mission: Impossible - Fallout', 2018, true, 'PG-13', 'Christopher McQuarrie', '2018-07-27'::date, '147 min', 'Action, Adventure, Thriller', 'Bruce Geller, Christopher McQuarrie', 'Tom Cruise, Henry Cavill, Ving Rhames', 'Two years after Ethan Hunt had successfully captured Solomon Lane, the remnants of the Syndicate have reformed into another organization called the Apostles. Under the leadership of a mysterious fundamentalist known only as John Lark, the organization is planning on acquiring three plutonium cores. Ethan and his team are sent to Berlin to intercept them, but the mission fails when Ethan saves Luther and the Apostles escape with the plutonium. With CIA agent August Walker joining the team, Ethan and his allies must now find the plutonium cores before it''s too late.', 'https://image.tmdb.org/t/p/w500/AkJQpZp9WoNdj7pLYSj1L0RcMMN.jpg', null, null),
  ('Mission: Impossible - Ghost Protocol', 2011, true, 'PG-13', 'Brad Bird', '2011-12-21'::date, '132 min', 'Action, Adventure, Thriller', 'Bruce Geller, Josh Appelbaum, André Nemec', 'Tom Cruise, Jeremy Renner, Simon Pegg', 'In the fourth installment of the Mission Impossible series, Ethan Hunt and a new team race against time to track down Hendricks, a dangerous terrorist who has gained access to Russian nuclear launch codes and is planning a strike on the United States. An attempt by the team to stop him at the Kremlin ends in a disaster, with an explosion causing severe damage to the Kremlin and the IMF being implicated in the bombing, forcing the President to invoke Ghost Protocol, under which the IMF is disavowed, and will be offered no help or backup in any form. Undaunted, Ethan and his team chase Hendricks to Dubai, and from there to Mumbai, but several spectacular action sequences later, they might still be too late to stop a disaster.', 'https://image.tmdb.org/t/p/w500/eRZTGx7GsiKqPch96k27LK005ZL.jpg', null, null),
  ('Mission: Impossible - Rogue Nation', 2015, true, 'PG-13', 'Christopher McQuarrie', '2015-07-31'::date, '131 min', 'Action, Adventure, Thriller', 'Bruce Geller, Christopher McQuarrie, Drew Pearce', 'Tom Cruise, Rebecca Ferguson, Jeremy Renner', 'CIA chief Hunley (Baldwin) convinces a Senate committee to disband the IMF (Impossible Mission Force), of which Ethan Hunt (Cruise) is a key member. Hunley argues that the IMF is too reckless. Now on his own, Hunt goes after a shadowy and deadly rogue organization called the Syndicate.', 'https://image.tmdb.org/t/p/w500/fRJLXQBHK2wyznK5yZbO7vmsuVK.jpg', null, null),
  ('Mission: Impossible II', 2000, true, 'PG-13', 'John Woo', '2000-05-24'::date, '123 min', 'Action, Adventure, Thriller', 'Bruce Geller, Ronald D. Moore, Brannon Braga', 'Tom Cruise, Dougray Scott, Thandiwe Newton', 'Chimera is a deadly virus that will bear a grisly death unless you are given the antidote. The creator of Chimera is murdered and the antidote is stolen by a disavowed I.M.F. Agent, Sean Ambrose (Dougray Scott). The Impossible Mission Force, (I.M.F.), hire the skilled and charming Ethan Hunt (Tom Cruise), and the beautiful Nyah Hall (Thandie Newton), who has had her share with Ambrose. Their mission, should they choose to accept it, is to send Hall undercover to Ambrose and learn what she can for Hunt to bring down Chimera, but they will have to break into a secure lab by jumping off of buildings and dodging bullets. Its impossible.', 'https://image.tmdb.org/t/p/w500/hfnrual76gPeNFduhD4xzHWpfTw.jpg', null, null),
  ('The Haunting', 1999, true, 'PG-13', 'Jan de Bont', '1999-07-23'::date, '113 min', 'Fantasy, Horror, Mystery', 'David Self, Shirley Jackson', 'Liam Neeson, Catherine Zeta-Jones, Owen Wilson', 'A remake of the classic 1963 movie "The Haunting" about a team of paranormal experts who look into strange occurrences in an ill-fated house. Through the course of the night some will unravel, some will question, and all will fight for their lives as the house fights back.', 'https://image.tmdb.org/t/p/w500/xwLldS5JnB4441iS50ha9ZrkaA8.jpg', null, null),
  ('Mission: Impossible III', 2006, true, 'PG-13', 'J.J. Abrams', '2006-05-05'::date, '126 min', 'Action, Adventure, Thriller', 'Alex Kurtzman, Roberto Orci, J.J. Abrams', 'Tom Cruise, Michelle Monaghan, Ving Rhames', 'A man named Owen Davian kills an IMF agent that was sent undercover by the legendary Ethan Hunt, who has retired from combat missions. Hunt now has a fiancé, Julia, who believes that he works for the traffic department when he really trains younger IMF agents to go into combat. He is assigned to his last mission. His mission, should he choose to accept it is to capture Davian, who is selling a toxic weapon called the rabbits foot. But Davian is reckless, cruel, and deadly. He promises Hunt that he will find Julia, hurt her, and Ethan will be too dead to help her. The mission is no more different to others, its dangerous, smart, and impossible; but now it''s personal.', 'https://image.tmdb.org/t/p/w500/vKGYCpmQyV9uHybWDzXuII8Los5.jpg', null, null),
  ('It Follows', 2014, true, 'R', 'David Robert Mitchell', '2015-03-13'::date, '100 min', 'Horror, Mystery, Thriller', 'David Robert Mitchell', 'Maika Monroe, Keir Gilchrist, Olivia Luccardi', 'For 19-year-old Jay, Autumn should be about school, boys, and weekends out at the lake. But after a seemingly innocent sexual encounter, she finds herself plagued by strange visions and the inescapable sense that someone, something, is following her. Faced with this burden, Jay and her friends must find a way to escape the horrors that seem to be only a few steps behind.', 'https://image.tmdb.org/t/p/w500/iwnQ1JH1wdWrGYkgWySptJ5284A.jpg', null, null),
  ('The Fall Guy', 2024, true, 'PG-13', 'David Leitch', '2024-05-03'::date, '126 min', 'Action, Comedy, Drama', 'Glen A. Larson, Drew Pearce', 'Ryan Gosling, Emily Blunt, Aaron Taylor-Johnson', 'A stuntman, fresh off an almost career-ending accident, has to track down a missing movie star, solve a conspiracy and try to win back the love of his life while still doing his day job. What could possibly go right?', 'https://image.tmdb.org/t/p/w500/e7olqFmzcIX5c23kX4zSmLPJi8c.jpg', null, null),
  ('Beetlejuice Beetlejuice', 2024, false, 'PG-13', 'Tim Burton', '2024-09-06'::date, '105 min', 'Comedy, Fantasy, Horror', 'Michael McDowell, Larry Wilson, Alfred Gough', 'Michael Keaton, Winona Ryder, Catherine O''Hara', 'From critically acclaimed filmmaker and screenwriter, Tim Burton presents the long-awaited sequel to the Halloween classic. Keaton''s action-packed comedic demon returns to the silver screen for more mischief than ever before. When the Maitland house EXPLODES, so does the fun, so buckle up. The original cast and crew plus new additions return when Beetlejuice is found homeless in the netherworld. He takes it upon himself to travel back to the mortal world seeking comfort, only to find the Maitland house has blown up due to a gas leak. Leaving our beloved characters without a humble home to share the love. In search of guidance, the crew travels down to the Netherworld only to find there''s a new sheriff in these parts, The Jersey Devil (Will Arnett). Through a surprising turn of events, the self-known ladies man, Beetlejuice learns that the Jersey Devil is his long-lost son through one of his numerous love affairs. Lydia Deetz (Winona Ryder) is wood by the enchanting Jersey Devil, despite being married to a struggling real estate agent (David Harbour). Through kooky scenarios and ecstatic characters, the fun near stops. Though entertaining it is also a heart-wrenching tale that shows Beetlejuice is just another man trying to find his way in the world. The story also progresses the idea that a family is never truly ideal. The story continues when you say the release date three times unbroken. Release date TBD.', 'https://image.tmdb.org/t/p/w500/kKgQzkUCnQmeTPkyIwHly2t6ZFI.jpg', null, null),
  ('Oddity', 2024, true, 'R', 'Damian Mc Carthy', '2024-07-19'::date, '98 min', 'Horror, Thriller', 'Damian Mc Carthy', 'Carolyn Bracken, Johnny French, Steve Wall', 'A psychic medium attempts to uncover the truth behind her sister''s murder at the site of the crime.', 'https://image.tmdb.org/t/p/w500/3Z9c1tbUhP0QruRjczPHnbx3U2D.jpg', null, null),
  ('Salem''s Lot', 2024, false, 'R', 'Gary Dauberman', '2024-10-03'::date, '113 min', 'Horror, Thriller', 'Gary Dauberman, Stephen King', 'Lewis Pullman, Spencer Treat Clark, Pilou Asbæk', 'Ben Mears, a writer who spent part of his childhood in Jerusalem''s Lot, Maine, also known as ''Salem''s Lot, has returned after twenty-five years to write a book about the long-abandoned Marsten House, where he had a bad experience as a child. He soon discovers that an ancient evil has also come to town and its turning the residents into vampires. He vows to stop the plague of undead and save the town.', 'https://image.tmdb.org/t/p/w500/j7ncdqBVufydVzVtxmXu8Ago4ox.jpg', null, null),
  ('Slingshot', 2024, false, 'R', 'Mikael Håfström', '2024-08-30'::date, '108 min', 'Sci-Fi, Thriller', 'R. Scott Adams, Nathan Parker', 'Casey Affleck, Laurence Fishburne, Emily Beecham', 'An astronaut struggles to maintain his grip on reality aboard a possibly fatally compromised mission to Saturn''s moon, Titan.', 'https://image.tmdb.org/t/p/w500/e6cCBe7DQOn9OFdFJ0eyVwSC8hR.jpg', null, null),
  ('As Above, So Below', 2014, true, 'R', 'John Erick Dowdle', '2014-08-29'::date, '93 min', 'Horror, Mystery, Thriller', 'John Erick Dowdle, Drew Dowdle', 'Perdita Weeks, Ben Feldman, Edwin Hodge', 'Miles of twisting catacombs lie beneath the streets of Paris, the eternal home to countless souls. When a team of explorers ventures into the uncharted maze of bones, they uncover the dark secret that lies within this city of the dead. A journey into madness and terror, As Above, So Below reaches deep into the human psyche to reveal the personal demons that come back to haunt us all.', 'https://image.tmdb.org/t/p/w500/oJZSajKLJkoTOzSZQN2ZwRnPwHZ.jpg', null, null),
  ('Alien: Romulus', 2024, true, 'R', 'Fede Alvarez', '2024-08-16'::date, '119 min', 'Horror, Sci-Fi, Thriller', 'Dan O''Bannon, Ronald Shusett, Fede Alvarez', 'Cailee Spaeny, David Jonsson, Archie Renaux', 'While scavenging the deep ends of a derelict space station, a group of young space colonists come face to face with the most terrifying life form in the universe.', 'https://image.tmdb.org/t/p/w500/2uSWRTtCG336nuBiG8jOTEUKSy8.jpg', 'Alien/Predator', null),
  ('House of Wax', 2005, true, 'R', 'Jaume Collet-Serra', '2005-05-06'::date, '113 min', 'Horror, Thriller', 'Charles Belden, Chad Hayes, Carey W. Hayes', 'Chad Michael Murray, Paris Hilton, Elisha Cuthbert', 'Six friends are on their way to a football game. They decide to camp out for the night and continue driving the next day. The next day the friends find that they''re having car troubles, so two of the friends accept a stranger''s ride into a small town named Ambrose. The main attraction in Ambrose is the House of Wax. Except something is not right in this town, the wax figures are so realistic and the whole town is deserted - except for two murderous twin brothers. The six friends must fight to survive and escape from being the next exhibits in the House of Wax.', 'https://image.tmdb.org/t/p/w500/aCLSgw1DaqkRvosYc3YUttBTtpT.jpg', null, null),
  ('Nope', 2022, true, 'R', 'Jordan Peele', '2022-07-22'::date, '130 min', 'Horror, Mystery, Sci-Fi', 'Jordan Peele', 'Daniel Kaluuya, Keke Palmer, Brandon Perea', 'The residents of a lonely gulch in inland California bear witness to an uncanny and chilling discovery.', 'https://image.tmdb.org/t/p/w500/AcKVlWaNVVVFQwro3nLXqPljcYA.jpg', null, null),
  ('Get Out', 2017, true, 'R', 'Jordan Peele', '2017-02-24'::date, '104 min', 'Horror, Mystery, Thriller', 'Jordan Peele', 'Daniel Kaluuya, Allison Williams, Bradley Whitford', 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family''s overly accommodating behavior as nervous attempts to deal with their daughter''s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.', 'https://image.tmdb.org/t/p/w500/tFXcEccSQMf3lfhfXKSU9iRBpa3.jpg', null, null),
  ('Final Destination', 2000, true, 'R', 'James Wong', '2000-03-17'::date, '98 min', 'Horror, Thriller', 'Glen Morgan, James Wong, Jeffrey Reddick', 'Devon Sawa, Ali Larter, Kerr Smith', 'Alex is boarding a plane to France on a school trip, when he suddenly gets a premonition that the plane will explode. Shortly after Alex, a group of students, and his teacher are thrown off the plane, to their horror, the plane does in fact explode. Alex must now work out Death''s plan, as each of the survivors falls victim. Whilst trying to prevent the next death, Alex must also dodge the FBI, who believe that he caused the explosion.', 'https://image.tmdb.org/t/p/w500/1mXhlQMnlfvJ2frxTjZSQNnA9Vp.jpg', null, null),
  ('Final Destination 2', 2003, true, 'R', 'David R. Ellis', '2003-01-31'::date, '90 min', 'Horror, Thriller', 'J. Mackye Gruber, Eric Bress, Jeffrey Reddick', 'A.J. Cook, Ali Larter, Tony Todd', 'Whilst heading onto the highway, Kimberly Corman has a vision of a huge car accident. Bringing the traffic to a halt, Kimberly is horrified when the accident actually happens. Kimberly links the occurrence with a similar event that occurred one year ago, on the same date that she had her premonition: the Flight 180 disaster. After speaking with Clear Rivers, the only remaining survivor of the Flight 180 disaster, Kimberly discovers that Death''s pattern has been disturbed, meaning everyone who was originally supposed to die will now be killed in separate freak accidents. Kimberly and the remaining survivors must work with Clear to try and stop Death from repeating its process.', 'https://image.tmdb.org/t/p/w500/dg6Tf98InieJSClSKQJTQevYWmB.jpg', null, null),
  ('Final Destination 3', 2006, true, 'R', 'James Wong', '2006-02-10'::date, '93 min', 'Horror, Thriller', 'Glen Morgan, James Wong, Jeffrey Reddick', 'Mary Elizabeth Winstead, Ryan Merriman, Kris Lemche', 'When Wendy Christensen has a vision of an accident on a roller coaster, resulting in her and her friends'' deaths, she instantly begins to panic and gets off the ride, causing some of her friends to get off as well. The remaining friends, including Wendy''s boyfriend, are stuck on the roller coaster and find themselves involved in the accident. With Death waiting around the corner, Wendy and Kevin Fischer must try and work out Death''s plan, before they and the remaining survivors end up dead.', 'https://image.tmdb.org/t/p/w500/p7ARuNKUGPGvkBiDtIDvAzYzonX.jpg', null, null),
  ('The Final Destination', 2009, true, 'R', 'David R. Ellis', '2009-08-28'::date, '82 min', 'Horror, Thriller', 'Eric Bress, Jeffrey Reddick', 'Nick Zano, Krista Allen, Andrew Fiscella', 'While watching a car race at McKinley Speedway, Nick O''Bannon has a premonition of a car crash that will result in many casualties, including several people that are in the audience. Nick convinces his girlfriend Lori, along with his friends Hunt and Janet to leave. A security guard named George Lanter, along with a racist named Carter, a mother and her two sons, and several other people follow Nick out. Shortly after they leave, Nick''s premonition comes true. When survivors start dying, Nick, his friends, and George must try to find the remaining survivors and save them from Death before it is too late.', 'https://image.tmdb.org/t/p/w500/5vxXrr1MqGsT4NNeRITpfDnl4Rq.jpg', null, null),
  ('Final Destination 5', 2011, true, 'R', 'Steven Quale', '2011-08-12'::date, '92 min', 'Horror, Thriller', 'Eric Heisserer, Jeffrey Reddick', 'Nicholas D''Agosto, Emma Bell, Arlen Escarpeta', 'While on a business retreat, Sam has a premonition that he, his co-workers, boss, and several other people will die in a horrific bridge collapse. When his premonition ends, he tries to make everyone get off the bus. Only some of his co-workers, along with his boss, leave. Shortly after, the bridge collapses. Everyone thinks that they are safe until the survivors start dying. It is now up to Sam to try to find a way to prevent anyone else from dying before it is too late.', 'https://image.tmdb.org/t/p/w500/Akx1Po4ZLetOWfYJhQf75tbhTtK.jpg', null, null),
  ('Guardians of the Galaxy Vol. 3', 2023, true, 'PG-13', 'James Gunn', '2023-05-05'::date, '150 min', 'Action, Adventure, Comedy', 'James Gunn, Jim Starlin, Stan Lee', 'Chris Pratt, Chukwudi Iwuji, Bradley Cooper', 'Still reeling from the loss of Gamora, Peter Quill rallies his team to defend the universe and one of their own - a mission that could mean the end of the Guardians if not successful.', 'https://image.tmdb.org/t/p/w500/r2J02Z2OpNTctfOSN1Ydgii51I3.jpg', null, null),
  ('Ant-Man And The Wasp Quantumania', 2023, true, 'PG-13', 'Peyton Reed', '2023-02-17'::date, '124 min', 'Action, Adventure, Comedy', 'Jeff Loveness, Stan Lee, Larry Lieber', 'Paul Rudd, Evangeline Lilly, Michael Douglas', 'The further adventures of Ant-Man and the Wasp.', 'https://image.tmdb.org/t/p/w500/qnqGbB22YJ7dSs4o6M7exTpNxPz.jpg', null, null),
  ('Doctor Strange In The Multiverse Of Madness', 2022, true, 'PG-13', 'Sam Raimi', '2022-05-06'::date, '126 min', 'Action, Adventure, Fantasy', 'Michael Waldron, Stan Lee, Steve Ditko', 'Benedict Cumberbatch, Elizabeth Olsen, Chiwetel Ejiofor', 'After the events of Avengers: Endgame, Dr. Stephen Strange continues his research on the Time Stone. But an old friend turned enemy seeks to destroy every sorcerer on Earth, messing with Strange''s plan, causing him to unleash an unspeakable evil', 'https://image.tmdb.org/t/p/w500/ddJcSKbcp4rKZTmuyWaMhuwcfMz.jpg', null, null),
  ('Black Panther Wakanda Forever', 2022, true, 'PG-13', 'Ryan Coogler', '2022-11-11'::date, '161 min', 'Action, Adventure, Drama', 'Ryan Coogler, Joe Robert Cole, Stan Lee', 'Letitia Wright, Lupita Nyong''o, Danai Gurira', 'The people of Wakanda fight to protect their home from intervening world powers as they mourn the death of King T''Challa.', 'https://image.tmdb.org/t/p/w500/sv1xJUazXeYqALzczSZ3O6nkH75.jpg', null, null),
  ('Shang-Chi And The Legend Of The Ten Rings', 2021, true, 'PG-13', 'Destin Daniel Cretton', '2021-09-03'::date, '132 min', 'Action, Adventure, Fantasy', 'Dave Callaham, Destin Daniel Cretton, Andrew Lanham', 'Simu Liu, Awkwafina, Tony Leung Chiu-wai', 'Shang-Chi, the master of weaponry-based Kung Fu, is forced to confront his past after being drawn into the Ten Rings organization.', 'https://image.tmdb.org/t/p/w500/d08HqqeBQSwN8i8MEvpsZ8Cb438.jpg', null, null),
  ('Eternals', 2021, true, 'PG-13', 'Chloé Zhao', '2021-11-05'::date, '156 min', 'Action, Adventure, Fantasy', 'Chloé Zhao, Patrick Burleigh, Ryan Firpo', 'Gemma Chan, Richard Madden, Angelina Jolie', 'Following the events of Avengers: Endgame (2019), an unexpected tragedy forces the Eternals, ancient aliens who have been living on Earth in secret for thousands of years, out of the shadows to reunite against mankind''s most ancient enemy, the Deviants.', 'https://image.tmdb.org/t/p/w500/lFByFSLV5WDJEv3KabbdAF959F2.jpg', null, null),
  ('The Marvels', 2023, true, 'PG-13', 'Nia DaCosta', '2023-11-10'::date, '105 min', 'Action, Adventure, Fantasy', 'Nia DaCosta, Megan McDonnell, Elissa Karasik', 'Brie Larson, Teyonah Parris, Iman Vellani', 'Carol Danvers gets her powers entangled with those of Kamala Khan and Monica Rambeau, forcing them to work together to save the universe.', 'https://image.tmdb.org/t/p/w500/9GBhzXMFjgcZ3FdR9w3bUMMTps5.jpg', null, null),
  ('Insomnia', 2002, true, 'R', 'Christopher Nolan', '2002-05-24'::date, '118 min', 'Drama, Mystery, Thriller', 'Hillary Seitz, Nikolaj Frobenius, Erik Skjoldbjærg', 'Al Pacino, Robin Williams, Hilary Swank', 'In Nightmute, Alaska, seventeen year old resident Kay Connell is found murdered. As a favor to the local Nightmute police chief, two Los Angeles Robbery Homicide police detectives, Will Dormer and Hap Eckhart, are called in to assist in the investigation. Although renowned in the police world, both Dormer and Eckhart are facing some professional issues back in Los Angeles. In Nightmute, Dormer has a major case of insomnia due to a combination of the incessant midnight sun and from a secret he is carrying. This insomnia is causing him to be delusional. Something he is not dreaming about is that the murderer has contacted him, informing him all about the murder and the fact that he knows everything that is going on with Dormer. They begin a symbiotic relationship in keeping secrets for each individual''s benefit. But ambitious young local detective, Ellie Burr, might piece the story together on her own.', 'https://image.tmdb.org/t/p/w500/riVXh3EimGO0y5dgQxEWPRy5Itg.jpg', null, null),
  ('Memento', 2000, true, 'R', 'Christopher Nolan', '2001-05-25'::date, '113 min', 'Mystery, Thriller', 'Christopher Nolan, Jonathan Nolan', 'Guy Pearce, Carrie-Anne Moss, Joe Pantoliano', 'Memento chronicles two separate stories of Leonard, an ex-insurance investigator who can no longer build new memories, as he attempts to find the murderer of his wife, which is the last thing he remembers. One story line moves forward in time while the other tells the story backwards revealing more each time.', 'https://image.tmdb.org/t/p/w500/fKTPH2WvH8nHTXeBYBVhawtRqtR.jpg', null, null),
  ('Dunkirk', 2017, true, 'PG-13', 'Christopher Nolan', '2017-07-21'::date, '106 min', 'Action, Drama, History', 'Christopher Nolan', 'Fionn Whitehead, Barry Keoghan, Mark Rylance', 'May/June 1940. Four hundred thousand British and French soldiers are hole up in the French port town of Dunkirk. The only way out is via sea, and the Germans have air superiority, bombing the British soldiers and ships without much opposition. The situation looks dire and, in desperation, Britain sends civilian boats in addition to its hard-pressed Navy to try to evacuate the beleaguered forces. This is that story, seen through the eyes of a soldier amongst those trapped forces, two Royal Air Force fighter pilots, and a group of civilians on their boat, part of the evacuation fleet.', 'https://image.tmdb.org/t/p/w500/b4Oe15CGLL61Ped0RAS9JpqdmCt.jpg', null, null),
  ('The Dark Knight', 2008, true, 'PG-13', 'Christopher Nolan', '2008-07-18'::date, '152 min', 'Action, Crime, Drama', 'Jonathan Nolan, Christopher Nolan, David S. Goyer', 'Christian Bale, Heath Ledger, Aaron Eckhart', 'Set within a year after the events of Batman Begins (2005), Batman, Lieutenant James Gordon, and new District Attorney Harvey Dent successfully begin to round up the criminals that plague Gotham City, until a mysterious and sadistic criminal mastermind known only as "The Joker" appears in Gotham, creating a new wave of chaos. Batman''s struggle against The Joker becomes deeply personal, forcing him to "confront everything he believes" and improve his technology to stop him. A love triangle develops between Bruce Wayne, Dent, and Rachel Dawes.', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', null, null),
  ('The Dark Knight Rises', 2012, true, 'PG-13', 'Christopher Nolan', '2012-07-20'::date, '164 min', 'Action, Drama, Thriller', 'Jonathan Nolan, Christopher Nolan, David S. Goyer', 'Christian Bale, Tom Hardy, Anne Hathaway', 'Despite his tarnished reputation after the events of The Dark Knight (2008), in which he took the rap for Dent''s crimes, Batman feels compelled to intervene to assist the city and its Police force, which is struggling to cope with Bane''s plans to destroy the city.', 'https://image.tmdb.org/t/p/w500/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg', null, null),
  ('The Prestige', 2006, true, 'PG-13', 'Christopher Nolan', '2006-10-20'::date, '130 min', 'Drama, Mystery, Sci-Fi', 'Jonathan Nolan, Christopher Nolan, Christopher Priest', 'Christian Bale, Hugh Jackman, Scarlett Johansson', 'In the end of the nineteenth century, in London, Robert Angier, his beloved wife Julia McCullough, and Alfred Borden are friends and assistants of a magician. When Julia accidentally dies during a performance, Robert blames Alfred for her death, and they become enemies. Both become famous and rival magicians, sabotaging the performance of the other on the stage. When Alfred performs a successful trick, Robert becomes obsessed trying to disclose the secret of his competitor with tragic consequences.', 'https://image.tmdb.org/t/p/w500/bdN3gXuIZYaJP7ftKK2sU0nPtEA.jpg', null, null),
  ('Dune Part Two', 2024, true, 'PG-13', 'Denis Villeneuve', '2024-03-01'::date, '166 min', 'Action, Adventure, Drama', 'Denis Villeneuve, Jon Spaihts, Frank Herbert', 'Timothée Chalamet, Zendaya, Rebecca Ferguson', 'Duke Paul Atreides joins the Fremen and begins a spiritual and martial journey to become Muad''dib, while trying to prevent the horrible but inevitable future he''s witnessed: a Holy War in his name, spreading throughout the known universe.', 'https://image.tmdb.org/t/p/w500/1pdfLvkbY9ohJlCjQH2CZjjYVvJ.jpg', null, null),
  ('Dune', 2021, true, 'PG-13', 'Denis Villeneuve', '2021-10-22'::date, '155 min', 'Action, Adventure, Drama', 'Jon Spaihts, Denis Villeneuve, Eric Roth', 'Timothée Chalamet, Rebecca Ferguson, Zendaya', 'A mythic and emotionally charged hero''s journey, "Dune" tells the story of Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, who must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet''s exclusive supply of the most precious resource in existence-a commodity capable of unlocking humanity''s greatest potential-only those who can conquer their fear will survive.', 'https://image.tmdb.org/t/p/w500/d5NXSklXo0qyIYkgV94XAgMIckC.jpg', null, null),
  ('Terrifier', 2016, true, 'Unrated', 'Damien Leone', '2018-03-27'::date, '85 min', 'Horror, Thriller', 'Damien Leone', 'Jenna Kanell, Samantha Scaffidi, David Howard Thornton', 'A maniac named Art the Clown terrorizes two friends on Halloween and everyone who gets in his way.', 'https://image.tmdb.org/t/p/w500/fjXqhGmaeQpB73WerhrYU6HlyV5.jpg', null, null),
  ('X', 2022, false, 'R', 'Ti West', '2022-03-18'::date, '105 min', 'Horror, Mystery, Thriller', 'Ti West', 'Mia Goth, Jenna Ortega, Brittany Snow', 'Set in 1979, adult movie actors and a small film crew arrive to a farmhouse occupied by an elderly couple in the desolate Texas countryside to film an adult movie. As the day shifts to night, the visitors slowly realize that they are not safe, and are being targeted by a nearby enemy.', 'https://image.tmdb.org/t/p/w500/lopZSVtXzhFY603E9OqF7O1YKsh.jpg', null, null),
  ('Pearl', 2022, false, 'R', 'Ti West', '2022-09-16'::date, '103 min', 'Drama, Horror, Thriller', 'Ti West, Mia Goth', 'Mia Goth, David Corenswet, Tandi Wright', 'In 1918, a young woman on the brink of madness pursues stardom in a desperate attempt to escape the drudgery, isolation, and lovelessness of life on her parents'' farm.', 'https://image.tmdb.org/t/p/w500/z5uIG81pXyHKg7cUFIu84Wjn4NS.jpg', null, null),
  ('Jurassic Park', 1993, true, 'PG-13', 'Steven Spielberg', '1993-06-11'::date, '127 min', 'Action, Adventure, Sci-Fi', 'Michael Crichton, David Koepp', 'Sam Neill, Laura Dern, Jeff Goldblum', 'Huge advancements in scientific technology have enabled a mogul to create an island full of living dinosaurs. John Hammond has invited four individuals, along with his two grandchildren, to join him at Jurassic Park. But will everything go according to plan? A park employee attempts to steal dinosaur embryos, critical security systems are shut down and it now becomes a race for survival with dinosaurs roaming freely over the island.', 'https://image.tmdb.org/t/p/w500/bRKmwU9eXZI5dKT11Zx1KsayiLW.jpg', null, null),
  ('Jurassic World Dominion', 2022, true, 'PG-13', 'Colin Trevorrow', '2022-06-10'::date, '147 min', 'Action, Adventure, Sci-Fi', 'Emily Carmichael, Colin Trevorrow, Derek Connolly', 'Chris Pratt, Bryce Dallas Howard, Laura Dern', 'Four years after the destruction of Isla Nublar, dinosaurs now live--and hunt--alongside humans all over the world. This fragile balance will reshape the future and determine, once and for all, whether human beings are to remain the apex predators on a planet they now share with history''s most fearsome creatures.', 'https://image.tmdb.org/t/p/w500/jbAvCACjLf1ZG0unB2tdmx5HAf1.jpg', null, null),
  ('Star Trek: The Motion picture', 1979, true, 'G', 'Robert Wise', '1979-12-08'::date, '143 min', 'Adventure, Mystery, Sci-Fi', 'Gene Roddenberry, Harold Livingston, Alan Dean Foster', 'William Shatner, Leonard Nimoy, DeForest Kelley', 'A massive alien spacecraft of enormous power destroys three powerful Klingon cruisers as it makes its way towards Federation space. Admiral James T. Kirk is ordered to take command of the USS Enterprise for the first time since her historic five-year mission. The Epsilon IX space station alerts the Federation, but they are also destroyed by the alien spacecraft. The only starship in range is the Enterprise, after undergoing a major overhaul in drydock orbiting Earth. Kirk rounds up the rest of his crew, and acquires some new members, and sets off to intercept the alien spacecraft. However, it has been three years since Kirk last went into deep space - is he up to the task of saving Earth?', 'https://image.tmdb.org/t/p/w500/wfiAfNwH6CMKxz4vRaW8CPTabtk.jpg', null, null),
  ('Star Trek II: The Wrath of Khan', 1982, true, 'PG', 'Nicholas Meyer', '1982-06-04'::date, '113 min', 'Action, Adventure, Sci-Fi', 'Gene Roddenberry, Jack B. Sowards, Harve Bennett', 'William Shatner, Leonard Nimoy, DeForest Kelley', 'It is the 23rd century. Admiral James T. Kirk is an instructor at Starfleet Academy and feeling old; the prospect of attending his ship, the USS Enterprise--now a training ship--on a two-week cadet cruise does not make him feel any younger. But the training cruise becomes a deadly serious mission when his nemesis Khan Noonien Singh--infamous conqueror from late 20th century Earth--appears after years of exile. Khan later revealed that the planet Ceti Alpha VI exploded, and shifted the orbit of the fifth planet as a Mars-like haven. He begins capturing Project Genesis, a top secret device holding the power of creation itself, and schemes the utter destruction of Kirk.', 'https://image.tmdb.org/t/p/w500/uPyLsKl8Z0LOoxeaFXsY5MxhR5s.jpg', null, null),
  ('Star Trek III: The Search for Spock', 1984, true, 'PG', 'Leonard Nimoy', '1984-06-01'::date, '105 min', 'Action, Adventure, Sci-Fi', 'Gene Roddenberry, Harve Bennett', 'William Shatner, Leonard Nimoy, DeForest Kelley', 'In the wake of Spock''s ultimate deed of sacrifice, Admiral Kirk and the Enterprise crew return to Earth for some essential repairs to their ship. When they arrive at Spacedock, they are shocked to discover that the Enterprise is to be decommissioned. Even worse, Dr. McCoy begins acting strangely and Scotty has been reassigned to another ship. Kirk is forced to steal back the Enterprise and head across space to the Genesis Planet to save Spock and bring him to Vulcan. Unbeknownst to them, the Klingons are planning to steal the secrets of the Genesis Device for their own deadly purpose.', 'https://image.tmdb.org/t/p/w500/yqEj0oPfKBMCz7YcCARHDgH7VFm.jpg', null, null),
  ('Star Trek IV: The Voyage Home', 1986, true, 'PG', 'Leonard Nimoy', '1986-11-26'::date, '119 min', 'Action, Adventure, Comedy', 'Gene Roddenberry, Leonard Nimoy, Harve Bennett', 'William Shatner, Leonard Nimoy, DeForest Kelley', 'The most acclaimed Star Trek adventure of all time with an important message. It is the 23rd century, and a mysterious alien probe is threatening Earth by evaporating the oceans and destroying the atmosphere. In their frantic attempt to save mankind, Admiral Kirk and his crew must time travel back to 1986 San Francisco where they find a world of punk, pizza and exact-change buses that are as alien to them as anything they have ever encountered in the far-off reaches of the galaxy. William Shatner and Leonard Nimoy return as Kirk and Spock, along with the entire Star Trek crew.', 'https://image.tmdb.org/t/p/w500/xY5TzGXJOB3L9rhZ1MbbPyVlW5J.jpg', null, null),
  ('Star Trek V: The Final Frontier', 1989, true, 'PG', 'William Shatner', '1989-06-09'::date, '107 min', 'Action, Adventure, Fantasy', 'Gene Roddenberry, William Shatner, Harve Bennett', 'William Shatner, Leonard Nimoy, DeForest Kelley', 'When the newly-christened starship Enterprise''s shakedown cruise goes poorly, Captain Kirk and crew put her into Spacedock for repairs. But an urgent mission interrupts their Earth-bound shore leave. A renegade Vulcan named Sybok has taken three ambassadors hostage on Nimbus III, the Planet of Galactic Peace. This event also attracts the attention of a Klingon captain who wants to make a name for himself and sets out to pursue the Enterprise. Sybok''s ragtag army captures the Enterprise and takes her on a journey to the center of the galaxy in search of the Supreme Being.', 'https://image.tmdb.org/t/p/w500/uiXr41VLYsuug3CZbFrKLSNahuZ.jpg', null, null),
  ('Star Trek VI: The Undiscovered Country', 1991, true, 'PG', 'Nicholas Meyer', '1991-12-06'::date, '110 min', 'Action, Adventure, Sci-Fi', 'Gene Roddenberry, Leonard Nimoy, Lawrence Konner', 'William Shatner, Leonard Nimoy, DeForest Kelley', 'After an explosion on their moon, the Klingons have an estimated 50 years before their ozone layer is completely depleted, and they all die. They have only one choice - to make peace with the Federation, which will mean an end to 70 years of conflict. Captain James T. Kirk and crew are called upon to help in the negotiations because of their experience with the Klingons. Peace talks don''t quite proceed, and Kirk and McCoy are convicted of assassinating the Klingon High Chancellor, and imprisoned on Rura Penthe, a snowy hard-labor prison camp. Will they manage to escape? And will there ever be peace with the Klingons?', 'https://image.tmdb.org/t/p/w500/tvTOJD7Gz668GLy2nNdLRQvpPsv.jpg', null, null),
  ('Star Trek Generations ', 1994, true, 'PG', 'David Carson', '1994-11-18'::date, '118 min', 'Action, Adventure, Mystery', 'Gene Roddenberry, Rick Berman, Ronald D. Moore', 'Patrick Stewart, William Shatner, Malcolm McDowell', 'In the late twenty-third century, the gala maiden voyage of the newly-christened U.S.S. Enterprise NCC-1701-B boasts such luminaries as Pavel Chekov, Montgomery Scott, and the legendary Captain James T. Kirk as guests. But her maiden voyage turns into a disaster as the unprepared starship is forced to rescue two transport ships from a mysterious energy ribbon. The Enterprise manages to save a handful of the ships'' passengers and barely succeeds out intact, but at the cost of Captain Kirk''s life. Seventy-eight years later, Captain Jean-Luc Picard and the U.S.S. Enterprise NCC-1701-D crew find themselves at odds with renegade scientist Dr. Tolian Soran, who is destroying entire star systems. Only one man can help Picard stop Soran''s scheme, and he has been dead for seventy-eight years.', 'https://image.tmdb.org/t/p/w500/gh0ZZRwSmlzEZTIZee3ZCN9Jssx.jpg', null, null),
  ('Star Trek: First Contact', 1996, true, 'PG-13', 'Jonathan Frakes', '1996-11-22'::date, '111 min', 'Action, Adventure, Drama', 'Gene Roddenberry, Rick Berman, Brannon Braga', 'Patrick Stewart, Jonathan Frakes, Brent Spiner', 'In the twenty-fourth century, the crew of the U.S.S. Enterprise NCC-1701-E has been ordered to patrol the Romulan Neutral Zone by the Federation to avoid interference with their battle against the insidious Borg. Witnessing the loss of the battle, Captain Jean-Luc Picard ignores orders and takes command of the fleet engaging the Borg. But the Borg plan to travel back into the twenty-first century through a vortex with the intention to stop Earth''s first contact with an alien race (the Vulcans). Following the Borg sphere, Picard and his crew realize that they have taken over the Enterprise in order to carry out their mission. Their only chance to do away with the Borg and their seductive Queen is to make sure that Zefram Cochrane makes his famous faster-than-light travel to the stars.', 'https://image.tmdb.org/t/p/w500/iqhHe893Vcf07jNkNQ31tu85dKG.jpg', null, null),
  ('Star Trek: Insurrection', 1998, true, 'PG', 'Jonathan Frakes', '1998-12-11'::date, '103 min', 'Action, Adventure, Sci-Fi', 'Gene Roddenberry, Rick Berman, Michael Piller', 'Patrick Stewart, Jonathan Frakes, Brent Spiner', 'While on a mission to observe the peaceful Ba''ku race, Lieutenant Commander Data suddenly behaves as if having to fear for his existence. The immortal Ba''ku, whose planet offers regenerative radiation, and therefore incredible lifespans, live in harmony with nature and reject advanced technology. Their planet and their culture is secretly researched by the Federation associated with an alien race called the Son''a. But the Son''a intend to abduct the Ba''ku in order to take the planet for themselves and for the Starfleet officials who all would like to regenerate their bodies. But they did not think of the loyalty of Captain Jean-Luc Picard and the crew of the U.S.S. Enterprise NCC-1701-E to the Prime Directive.', 'https://image.tmdb.org/t/p/w500/xQCMAHeg5M9HpDIqanYbWdr4brB.jpg', null, null),
  ('Star Trek: Nemesis', 2002, true, 'PG-13', 'Stuart Baird', '2002-12-13'::date, '116 min', 'Action, Adventure, Sci-Fi', 'Gene Roddenberry, John Logan, Rick Berman', 'Patrick Stewart, Jonathan Frakes, Brent Spiner', 'After a joyous wedding between William Riker and Deanna Troi, Captain Picard and the Enterprise crew stumble upon a positronic signature which results in a prototype version of the android Data. Then the Enterprise is invited to Romulus to negotiate a peace treaty with the Romulans by their new leader, Praetor Shinzon. However, Shinzon is revealed to be a clone of Picard who was raised on Remus, a slave planet to the Romulans. Later on, Picard discovers that this peace treaty was nothing more than a set-up on account of the fact that Shinzon needs Picard in order to survive. But little do the Enterprise crew know that Shinzon also plans to do away with the Federation by unleashing a weapon that could destroy a whole planet.', 'https://image.tmdb.org/t/p/w500/cldAwhvBmOv9jrd3bXWuqRHoXyq.jpg', null, null),
  ('Enemy', 2013, true, 'R', 'Denis Villeneuve', '2014-02-06'::date, '91 min', 'Drama, Mystery, Thriller', 'José Saramago, Javier Gullón', 'Jake Gyllenhaal, Mélanie Laurent, Sarah Gadon', 'Adam Bell is a Toronto area History college professor. He is a rather somber man, largely because he is stuck in a routine, which includes a relationship with his live-in girlfriend, Mary. While watching a rental movie, he spots an actor in a bit part that looks like him. He becomes obsessed with finding out about this double of his. He learns that the actor''s stage name is Daniel Saint Claire, whose legal name is Anthony Claire. Claire is a Toronto based actor with only a few on-screen credits, and is married to a woman named Helen who is currently several months pregnant. Adam then becomes obsessed with meeting Claire, who he learns upon first sighting that they look exactly the same, from the facial hair to a scar each has, but Claire who outwardly is more "put together" than Adam. Their lives become intertwined as Claire himself ends up becoming obsessed with Adam, but in a slightly different way.', 'https://image.tmdb.org/t/p/w500/vf40tyDRKZsBmaLsYeopzfFLzLx.jpg', null, null),
  ('Incendies', 2010, true, 'R', 'Denis Villeneuve', '2011-04-22'::date, '131 min', 'Drama, Mystery, War', 'Wajdi Mouawad, Denis Villeneuve, Valérie Beaugrand-Champagne', 'Lubna Azabal, Mélissa Désormeaux-Poulin, Maxim Gaudette', 'A mother''s last wishes send twins Jeanne and Simon on a journey to the Middle East in search of their tangled roots. Adapted from Wajdi Mouawad''s acclaimed play, Incendies tells the powerful and moving tale of two young adults'' voyage to the core of deep-rooted hatred, never-ending wars and enduring love.', 'https://image.tmdb.org/t/p/w500/yH6DAQVgbyj72S66gN4WWVoTjuf.jpg', null, null),
  ('Sicario', 2015, true, 'R', 'Denis Villeneuve', '2015-10-02'::date, '121 min', 'Action, Crime, Drama', 'Taylor Sheridan', 'Emily Blunt, Josh Brolin, Benicio Del Toro', 'Kate Macer leads a Phoenix based kidnap response unit for the FBI. Following Kate''s team leading a raid on a known drug den in nearby Chandler, Kate is recruited to work on a special ops team led by Matt Graver of the CIA, he who is on special assignment for the Department of Defense. They recruited her because they wanted someone with tactical procedures knowledge. Outwardly, the team''s mission, which works behind a Delta Force team as its primary gun power as required, is to decapitate a Mexican drug cartel by capturing or dismembering the workings of the main players, cartel head Manuel Díaz, his second in command Guillermo Díaz (Manuel''s brother), and drug lord Fausto Alarcón. Kate agrees to the assignment as she feels the work of this team would be more effective in stopping the drug trade in the US than the piecemeal work of her current kidnap response unit. The third on the team is a mysterious Hispanic or Latino man Kate only knows as Alejandro, and who she does not fully trust as she can tell that he is suffering from a very traumatic past. When Kate and the team arrive in El Paso for their first mission, Kate learns that the team''s workings are not all they appear on the surface - many of the proceedings which would not be considered above board or legal - despite the end goal being as she knows it to be. Still largely in the dark and only given information on a need to know basis, Kate decides to stick it out with the team if only to discover all that she is not told while still believing in the end goal. She may have changing or at least mixed emotions as she learns more and more about what is going on, including the specific reason why she was recruited.', 'https://image.tmdb.org/t/p/w500/lz8vNyXeidqqOdJW9ZjnDAMb5Vr.jpg', null, null),
  ('Prisoners', 2013, true, 'R', 'Denis Villeneuve', '2013-09-20'::date, '153 min', 'Crime, Drama, Mystery', 'Aaron Guzikowski', 'Hugh Jackman, Jake Gyllenhaal, Viola Davis', 'How far would you go to protect your family? Keller Dover is facing every parent''s worst nightmare. His six-year-old daughter, Anna, is missing, together with her young friend, Joy, and as minutes turn to hours, panic sets in. The only lead is a dilapidated RV that had earlier been parked on their street. Heading the investigation, Detective Loki arrests its driver, Alex Jones, but a lack of evidence forces his release. As the police pursue multiple leads and pressure mounts, knowing his child''s life is at stake the frantic Dover decides he has no choice but to take matters into his own hands. But just how far will this desperate father go to protect his family?', 'https://image.tmdb.org/t/p/w500/jsS3a3ep2KyBVmmiwaz3LvK49b1.jpg', null, null),
  ('Spider-Man', 2002, true, 'PG-13', 'Sam Raimi', '2002-05-03'::date, '121 min', 'Action, Adventure, Sci-Fi', 'Stan Lee, Steve Ditko, David Koepp', 'Tobey Maguire, Kirsten Dunst, Willem Dafoe', 'Based on Marvel Comics'' superhero character, this is a story of Peter Parker who is a nerdy high-schooler. He was orphaned as a child, bullied by jocks, and can''t confess his crush for his stunning neighborhood girl Mary Jane Watson. To say his life is "miserable" is an understatement. But one day while on an excursion to a laboratory a runaway radioactive spider bites him... and his life changes in a way no one could have imagined. Peter acquires a muscle-bound physique, clear vision, ability to cling to surfaces and crawl over walls, shooting webs from his wrist ... but the fun isn''t going to last. An eccentric millionaire Norman Osborn administers a performance enhancing drug on himself and his maniacal alter ego Green Goblin emerges. Now Peter Parker has to become Spider-Man and take Green Goblin to the task... or else Goblin will kill him. They come face to face and the war begins in which only one of them will survive at the end.', 'https://image.tmdb.org/t/p/w500/gh4cZbhZxyTbgxQPxD0dOudNPTn.jpg', null, null),
  ('Spider-Man 2', 2004, true, 'PG-13', 'Sam Raimi', '2004-06-30'::date, '127 min', 'Action, Adventure, Sci-Fi', 'Stan Lee, Steve Ditko, Alfred Gough', 'Tobey Maguire, Kirsten Dunst, Alfred Molina', 'Peter Parker is an unhappy man: after two years of fighting crime as Spider-Man, his life has begun to fall apart. The girl he loves is engaged to someone else, his grades are slipping, he cannot keep any of his jobs, and on top of it, the newspaper Daily Bugle is attacking him viciously, claiming that Spider-Man is a criminal. He reaches the breaking point and gives up the crime fighter''s life, once and for all. But after a failed fusion experiment, eccentric and obsessive scientist Dr. Otto Octavius is transformed into super villain Doctor Octopus, Doc Ock for short, having four long tentacles as extra hands. Peter guesses it might just be time for Spider-Man to return, but would he act upon it?', 'https://image.tmdb.org/t/p/w500/aGuvNAaaZuWXYQQ6N2v7DeuP6mB.jpg', null, null),
  ('Spider-Man 3', 2007, true, 'PG-13', 'Sam Raimi', '2007-05-04'::date, '139 min', 'Action, Adventure, Sci-Fi', 'Sam Raimi, Ivan Raimi, Alvin Sargent', 'Tobey Maguire, Kirsten Dunst, Topher Grace', 'Peter Parker has finally managed to piece together the once-broken parts of his life, maintaining a balance between his relationship with Mary-Jane and his responsibility as Spider-Man. But more challenges arise for our young hero. Peter''s old friend Harry Obsourne has set out for revenge against Peter; taking up the mantle of his late father''s persona as The New Goblin, and Peter must also capture Uncle Ben''s real killer, Flint Marko, who has been transformed into his toughest foe yet, the Sandman. All hope seems lost when suddenly Peter''s suit turns jet-black and greatly amplifies his powers. But it also begins to greatly amplify the much darker qualities of Peter''s personality that he begins to lose himself to. Peter has to reach deep inside himself to free the compassionate hero he used to be if he is to ever conquer the darkness within and face not only his greatest enemies, but also...himself.', 'https://image.tmdb.org/t/p/w500/qFmwhVUoUSXjkKRmca5yGDEXBIj.jpg', null, null),
  ('The Amazing Spider-Man 2', 2014, true, 'PG-13', 'Marc Webb', '2014-05-02'::date, '142 min', 'Action, Adventure, Sci-Fi', 'Alex Kurtzman, Roberto Orci, Jeff Pinkner', 'Andrew Garfield, Emma Stone, Jamie Foxx', 'We''ve always known that Spider-Man''s most important conflict has been within himself: the struggle between the ordinary obligations of Peter Parker and the extraordinary responsibilities of Spider-Man. But in The Amazing Spider-Man 2, Peter Parker finds that his greatest battle is about to begin. It''s great to be Spider-Man. For Peter Parker, there''s no feeling quite like swinging between skyscrapers, embracing being the hero, and spending time with Gwen. But being Spider-Man comes at a price: only Spider-Man can protect his fellow New Yorkers from the formidable villains that threaten the city. With the emergence of Electro, Peter must confront a foe far more powerful than he. And as his old friend, Harry Osborn, returns, Peter comes to realize that all of his enemies have one thing in common: Oscorp.', 'https://image.tmdb.org/t/p/w500/dGjoPttcbKR5VWg1jQuNFB247KL.jpg', null, null),
  ('Spider-Man: Across the Spider-Verse', 2023, true, 'PG', 'Joaquim Dos Santos, Kemp Powers, Justin K. Thompson', '2023-06-02'::date, '140 min', 'Animation, Action, Adventure', 'Phil Lord, Christopher Miller, Dave Callaham', 'Shameik Moore, Hailee Steinfeld, Brian Tyree Henry', 'Miles Morales returns for the next chapter of the Oscar®-winning Spider-Verse saga, an epic adventure that will transport Brooklyn''s full-time, friendly neighborhood Spider-Man across the Multiverse to join forces with Gwen Stacy and a new team of Spider-People to face off with a villain more powerful than anything they have ever encountered.', 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', null, null),
  ('X-Men', 2000, true, 'PG-13', 'Bryan Singer', '2000-07-14'::date, '104 min', 'Action, Adventure, Sci-Fi', 'Tom DeSanto, Bryan Singer, David Hayter', 'Patrick Stewart, Hugh Jackman, Ian McKellen', 'In a world where both Mutants and Humans fear each other, Marie, better known as Rogue, runs away from home and hitches a ride with another mutant, known as Logan, a.k.a. Wolverine. Professor Charles Xavier, who owns a school for young mutants, sends Storm and Cyclops to bring them back before it is too late. Magneto, who believes a war is approaching, has an evil plan in mind, and needs young Rogue to help him.', 'https://image.tmdb.org/t/p/w500/bRDAc4GogyS9ci3ow7UnInOcriN.jpg', null, null),
  ('X2', 2003, true, 'PG-13', 'Bryan Singer', '2003-05-02'::date, '134 min', 'Action, Sci-Fi, Thriller', 'Zak Penn, David Hayter, Bryan Singer', 'Patrick Stewart, Hugh Jackman, Halle Berry', 'Several months have passed since the X-Men defeated Magneto and imprisoned him in a seemingly impregnable plastic chamber. One day, a mutant by the name of Nightcrawler infiltrates the White House and attempts to assassinate the President, setting off a chain reaction of anti-mutant measures by the government. Meanwhile, Logan is trying to discover his past. As scientist named William Stryker discovers Professor X''s secret school and Cerebro, Magneto''s partner, Mystique, is planning to break her leader out of prison. But when Professor X''s school is attacked by Stryker''s forces, Logan, Rogue, Iceman, and a few are lucky to escape. Those who remain meet in Boston, where they form an uneasy alliance with Magneto to stop Stryker and rescue Professor X.', 'https://image.tmdb.org/t/p/w500/bWMw0FMsY8DICgrQnrTSWbzEgtr.jpg', null, null),
  ('X-Men: The Last Stand', 2006, true, 'PG-13', 'Brett Ratner', '2006-05-26'::date, '104 min', 'Action, Adventure, Sci-Fi', 'Simon Kinberg, Zak Penn', 'Patrick Stewart, Hugh Jackman, Halle Berry', 'When a "cure" is created, which apparently can turn any mutant into a "normal" human being, there is outrage amongst the mutant community. While some mutants do like the idea of a "cure", including Rogue, many mutants find that there shouldn''t be a "cure". Magneto, who still believes a war is coming, recruits a large team of mutants to take down Warren Worthington II and his "cure". Might seem easy for the X-Men to stop, but Magneto has a big advantage, which Wolverine doesn''t have. Jean Grey has returned, and joined with Magneto. The Dark Phoenix has woken within her, which has the ability to destroy anything in her way, even if that "anything" is an X-Man.', 'https://image.tmdb.org/t/p/w500/a2xicU8DpKtRizOHjQLC1JyCSRS.jpg', null, null),
  ('X-Men Origins: Wolverine', 2009, true, 'PG-13', 'Gavin Hood', '2009-05-01'::date, '107 min', 'Action, Sci-Fi', 'David Benioff, Skip Woods', 'Hugh Jackman, Liev Schreiber, Ryan Reynolds', 'Two mutant brothers, Logan and Victor, born two hundred years ago, suffer childhood trauma and have only each other to depend on. Basically, they''re fighters and killers, living from war to war throughout U.S. history. In modern times, a U.S. Colonel, Stryker, recruits them and other mutants as commandos. Logan quits and becomes a logger, falling in love with a local teacher. When Logan refuses to rejoin Stryker''s crew, the Colonel sends the murderous Victor. Logan now wants revenge.', 'https://image.tmdb.org/t/p/w500/yj8LbTju1p7CUJg7US2unSBk33s.jpg', null, null),
  ('The Wolverine', 2013, true, 'PG-13', 'James Mangold', '2013-07-26'::date, '126 min', 'Action, Sci-Fi', 'Mark Bomback, Scott Frank', 'Hugh Jackman, Will Yun Lee, Tao Okamoto', 'In modern day Japan, Wolverine is out of his depth in an unknown world as he faces his ultimate nemesis in a life-or-death battle that will leave him forever changed. Vulnerable for the first time and pushed to his physical and emotional limits, he confronts not only lethal samurai steel but also his inner struggle against his own near-immortality, emerging more powerful than we have ever seen him before.', 'https://image.tmdb.org/t/p/w500/t2wVAcoRlKvEIVSbiYDb8d0QqqS.jpg', null, null),
  ('Dark Phoenix', 2019, true, 'PG-13', 'Simon Kinberg', '2019-06-07'::date, '113 min', 'Action, Adventure, Sci-Fi', 'Simon Kinberg', 'James McAvoy, Michael Fassbender, Jennifer Lawrence', 'The X-Men. Protectors of peace. Jean Grey is one of the most beloved X-Men. But when a mission goes wrong, Jean is exposed to a dark and ancient power. This power has destroyed everything it comes in contact with, until her. Now that this power is becoming unstable, she releases it with destruction and anger. Now that this foreign power is consuming her, and the world is threatened, the X-Men have to face an important truth: they must save either the world, or their friend who threatens it.', 'https://image.tmdb.org/t/p/w500/cCTJPelKGLhALq3r51A9uMonxKj.jpg', null, null),
  ('The New Mutants', 2020, true, 'PG-13', 'Josh Boone', '2020-08-28'::date, '94 min', 'Action, Horror, Mystery', 'Josh Boone, Knate Lee', 'Maisie Williams, Anya Taylor-Joy, Charlie Heaton', 'After a near-death experience during a strange tornado, Danielle Moonstar awakens in an abandoned research facility run by the mysterious Dr Cecilia Reyes. There, Dr Reyes introduces Dani to four other equally uncommon teenagers: Illyana Rasputin, Rahne Sinclair, Sam Guthrie, and Roberto da Costa, who wants to keep them safe and sound until they learn how to be in full control of their extraordinary abilities. However, even though the exceptional team of traumatised inmates believes that they''re being treated and cared for, before long, they all start to experience horrifying hallucinations. But, this institution was supposed to be a safe place. Are they patients or prisoners?', 'https://image.tmdb.org/t/p/w500/xiDGcXJTvu1lazFRYip6g1eLt9c.jpg', null, null),
  ('The Shawshank Redemption', 1994, true, 'R', 'Frank Darabont', '1994-10-14'::date, '142 min', 'Drama', 'Stephen King, Frank Darabont', 'Tim Robbins, Morgan Freeman, Bob Gunton', 'Chronicles the experiences of a formerly successful banker as a prisoner in the gloomy jailhouse of Shawshank after being found guilty of a crime he did not commit. The film portrays the man''s unique way of dealing with his new, torturous life; along the way he befriends a number of fellow prisoners, most notably a wise long-term inmate named Red.', 'https://image.tmdb.org/t/p/w500/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', null, null),
  ('The Matrix Resurrections', 2021, true, 'R', 'Lana Wachowski', '2021-12-22'::date, '148 min', 'Action, Sci-Fi', 'Lana Wachowski, David Mitchell, Aleksandar Hemon', 'Keanu Reeves, Carrie-Anne Moss, Yahya Abdul-Mateen II', 'Return to a world of two realities: one, everyday life; the other, what lies behind it. To find out if his reality is a construct, to truly know himself, Mr. Anderson will have to choose to follow the white rabbit once more.', 'https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg', null, null),
  ('The Animatrix', 2003, true, 'Unrated', 'Peter Chung, Andrew R. Jones, Yoshiaki Kawajiri, Takeshi Koike, Mahiro Maeda, Kôji Morimoto, Shin''ic', '2003-03-21'::date, '100 min', 'Animation, Action, Sci-Fi', 'Lilly Wachowski (screenplay "The Matrix"), Lana Wachowski (screenplay "The Matrix"), Lilly Wachowski, Lana Wachowski, Yoshiaki Kawajiri, Kôji Morimoto, Shin''ichirô Watanabe, Peter Chung', 'James Arnold Taylor, Julia Fletcher, Dwight Schultz', 'Anthology of nine short anime (Japanese animation) films tied in to the 1999 blockbuster "The Matrix" and its sequels. "Final Flight of the Osiris": The crew of the hovercraft Osiris attempt to warn their city of an imminent attack. "The Second Renaissance, Parts 1 & 2": The story behind the war between man and the machines, how mankind scorched the sky, and the creation of the Matrix. "Kid''s Story": A teenager is contacted by Neo, and manages to escape the Matrix. "Program": Two warriors battle in a samurai training simulation when one decides to betray his crewmates and re-enter the Matrix. "World Record": A champion sprinter manages to break free of the Matrix by sheer physical effort during a record attempt. "Beyond": A young girl searching for her cat discovers a haunted house caused by a glitch in the system. "A Detective Story": Private investigator Ash tracks a hacker named Trinity through the looking glass. "Matriculated": A group of humans capture a machine scout and insert it into a ''human matrix''.', 'https://image.tmdb.org/t/p/w500/g52SOsTvdjzY8oPIn5znLJMzLHG.jpg', null, null),
  ('The Nun II', 2023, true, 'R', 'Michael Chaves', '2023-09-08'::date, '110 min', 'Horror, Mystery, Thriller', 'Ian Goldberg, Richard Naing, Akela Cooper', 'Taissa Farmiga, Jonas Bloquet, Storm Reid', '1956 in France, a priest is horribly murdered. An evil is spreading. Once again, Sister Irene comes face-to-face with Valak, the demon nun.', 'https://image.tmdb.org/t/p/w500/5gzzkR7y3hnY8AD1wXjCnVlHba5.jpg', null, null),
  ('The Conjuring: The Devil Made Me Do It', 2021, true, 'R', 'Michael Chaves', '2021-06-04'::date, '112 min', 'Horror, Mystery, Thriller', 'David Leslie Johnson-McGoldrick, James Wan, Chad Hayes', 'Patrick Wilson, Vera Farmiga, Ruairi O''Connor', 'A chilling story of terror, murder and unknown evil that shocked even experienced real-life paranormal investigators Ed and Lorraine Warren. One of the most sensational cases from their files, it starts with a fight for the soul of a young boy, then takes them beyond anything they''d ever seen before, to mark the first time in U.S. history that a murder suspect would claim demonic possession as a defense.', 'https://image.tmdb.org/t/p/w500/rQfX2xx8TUoNvyk892yKWNikJaM.jpg', null, null),
  ('Battle for the Planet of the Apes', 1973, true, 'G', 'J. Lee Thompson', '1973-06-15'::date, '93 min', 'Action, Sci-Fi', 'Pierre Boulle, Paul Dehn, John William Corrington', 'Roddy McDowall, Claude Akins, Natalie Trundy', 'After conquering the oppressive humans in "Conquest for the Planet of the Apes", Caesar must now keep the peace among the humans and apes. Gorilla General Aldo views things differently, and tries to cause an ape civil war. In the meantime, other human survivors learn of the ape city, and decide they want to take back civilization for themselves, thus setting the stage of warring ape factions and humans.', 'https://image.tmdb.org/t/p/w500/dP5dYjLp5p2CG103cJMio4Nj29d.jpg', null, null),
  ('Beneath the Planet of the Apes', 1970, true, 'G', 'Ted Post', '1970-05-26'::date, '95 min', 'Action, Adventure, Sci-Fi', 'Paul Dehn, Mort Abrahams, Pierre Boulle', 'James Franciscus, Kim Hunter, Maurice Evans', 'Brent is an American astronaut, part of a team sent to locate missing fellow American astronaut, George Taylor. Following Taylor''s known flight trajectory, the search and rescue team crash lands on an unknown planet much like Earth in the year 3955, with Brent being the only survivor of the team. What Brent initially does not know, much like Taylor didn''t initially know when he landed here before Brent, is that he has landed back on Earth in the future, in the vicinity of what was New York City. Brent finds evidence that Taylor has been on the planet. In Brent''s search for Taylor, he finds that the planet is run by a barbaric race of English speaking apes, whose mission is in part to annihilate the human race. Brent eventually locates some of those humans, who communicate telepathically and who live underground to prevent detection by the apes. These humans, who are in their own way as barbaric as the apes, want in turn to protect their species. Brent has to figure out a way to save himself under the circumstances, which may be more difficult to accomplish in the battle between the dominant species on this planet.', 'https://image.tmdb.org/t/p/w500/szHCeYwi4ubewuYnlnz0YGqWnQC.jpg', null, null),
  ('Escape from the Planet of the Apes', 1971, true, 'G', 'Don Taylor', '1971-07-09'::date, '98 min', 'Action, Sci-Fi', 'Paul Dehn, Pierre Boulle', 'Roddy McDowall, Kim Hunter, Bradford Dillman', 'Following the events in "Beneath the Planet of the Apes", Cornelius and Zira flee back through time to 20th Century Los Angeles, where they face fear and persecution similar to what Taylor and Brent suffered in the future, and discover the origins of the stream of events that will shape their world.', 'https://image.tmdb.org/t/p/w500/AnbLVdUEroTfHTUVAJCxkL4R0IH.jpg', null, null),
  ('Conquest of the Planet of the Apes', 1972, true, 'PG', 'J. Lee Thompson', '1972-06-30'::date, '88 min', 'Action, Sci-Fi', 'Paul Dehn, Pierre Boulle', 'Roddy McDowall, Don Murray, Ricardo Montalban', 'Cornelius and Zira''s son Caesar leads apes to revolution in this installment of the apes saga. Dogs and cats have been wiped out by a plague and now apes are household pets that are treated like slaves. Caesar has the intelligence to fight this oppression.', 'https://image.tmdb.org/t/p/w500/lZ1pUxJCO14ObrhDuxTBuYm0tjN.jpg', null, null),
  ('Planet of the Apes', 1968, true, 'G', 'Franklin J. Schaffner', '1968-04-03'::date, '112 min', 'Adventure, Sci-Fi', 'Michael Wilson, Rod Serling, Pierre Boulle', 'Charlton Heston, Roddy McDowall, Kim Hunter', 'Taylor and two other astronauts come out of deep hibernation to find that their ship has crashed. Escaping with little more than clothes they find that they have landed on a planet where men are pre-lingual and uncivilized while apes have learned speech and technology. Taylor is captured and taken to the city of the apes after damaging his throat so that he is silent and cannot communicate with the apes.', 'https://image.tmdb.org/t/p/w500/2r9iKnlSYEk4daQadsXfcjHfIjQ.jpg', null, null),
  ('Planet of the Apes', 2001, true, 'PG-13', 'Tim Burton', '2001-07-27'::date, '120 min', 'Action, Adventure, Sci-Fi', 'Pierre Boulle, William Broyles Jr., Lawrence Konner', 'Mark Wahlberg, Helena Bonham Carter, Tim Roth', 'It is the year 2029: Astronaut Leo Davidson boards a pod cruiser on a Space Station on a rescue and recovery mission. But an abrupt detour through a space time wormhole lands him on a strange planet where talking apes rule over the human race. With the help of a sympathetic chimpanzee activist named Ari and a small band of human rebels, Leo leads the effort to evade the advancing Gorilla Army led by General Thade and his most trusted warrior Attar. Now the race is on to reach a sacred temple within the planet''s Forbidden Zone to discover the shocking secrets of mankind''s past - and the key to its future.', 'https://image.tmdb.org/t/p/w500/eEsOgbgKXMvI2FEw1WENamVXi41.jpg', null, null),
  ('War for the Planet of the Apes', 2017, true, 'PG-13', 'Matt Reeves', '2017-07-14'::date, '140 min', 'Action, Adventure, Drama', 'Mark Bomback, Matt Reeves, Rick Jaffa', 'Andy Serkis, Woody Harrelson, Steve Zahn', 'Caesar and his apes are forced into a deadly conflict with an army of humans led by a ruthless Colonel. After the apes suffer unimaginable losses, Caesar wrestles with his darker instincts and begins his own mythic quest to avenge his kind. As the journey finally brings them face to face, Caesar and the Colonel are pitted against each other in an epic battle that will determine the fate of both their species and the future of the planet.', 'https://image.tmdb.org/t/p/w500/mMA1qhBFgZX8O36qPPTC016kQl1.jpg', null, null),
  ('Blade Runner', 1982, true, 'R', 'Ridley Scott', '1982-06-25'::date, '117 min', 'Action, Drama, Sci-Fi', 'Hampton Fancher, David Webb Peoples, Philip K. Dick', 'Harrison Ford, Rutger Hauer, Sean Young', 'In the early twenty-first century, the Tyrell Corporation, during what was called the Nexus phase, developed robots, called "replicants", that were supposed to aid society, the replicants which looked and acted like humans. When the superhuman generation Nexus 6 replicants, used for dangerous off-Earth endeavors, began a mutiny on an off-Earth colony, replicants became illegal on Earth. Police units, called "blade runners", have the job of destroying - or in their parlance "retiring" - any replicant that makes its way back to or created on Earth, with anyone convicted of aiding or assisting a replicant being sentenced to death. It''s now November, 2019 in Los Angeles, California. Rick Deckard, a former blade runner, is called out of retirement when four known replicants, most combat models, have made their way back to Earth, with their leader being Roy Batty. One, Leon Kowalski, tried to infiltrate his way into the Tyrell Corporation as an employee, but has since been able to escape. Beyond following Leon''s trail in hopes of finding and retiring them all, Deckard believes part of what will help him is figuring out what the replicants wanted with the Tyrell Corporation in trying to infiltrate it. The answer may lie with Tyrell''s fail-safe backup mechanism. Beyond tracking the four, Deckard faces a possible dilemma in encountering a fifth replicant: Rachael, who works as Tyrell''s assistant. The issue is that Dr. Elden Tyrell is experimenting with her, to provide her with fake memories so as to be able to better control her. With those memories, Rachael has no idea that she is not human. The problem is not only Rachael''s assistance to Deckard, but that he is beginning to develop feelings for her.', 'https://image.tmdb.org/t/p/w500/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg', null, null),
  ('1941', 1979, true, 'PG', 'Steven Spielberg', '1979-12-14'::date, '118 min', 'Action, Comedy, War', 'Robert Zemeckis, Bob Gale, John Milius', 'John Belushi, Dan Aykroyd, Treat Williams', 'Hysteria grips California in the wake of the bombing of Pearl Harbor. An assorted group of defenders attempt to make the coast defensible against an imagined Japanese invasion, in this big budget, big cast comedy. Members of a Japanese submarine crew scout out the madness, along with a Captain in Germany''s Kreigsmarine (Navy).', 'https://image.tmdb.org/t/p/w500/52Bn5yC6IHQuVxPUza3Q6RZCZTu.jpg', null, null),
  ('E.T. the Extra-Terrestrial', 1982, false, 'PG', 'Steven Spielberg', '1982-06-11'::date, '115 min', 'Adventure, Family, Sci-Fi', 'Melissa Mathison', 'Henry Thomas, Drew Barrymore, Peter Coyote', 'After a gentle alien becomes stranded on Earth, the being is discovered and befriended by a young boy named Elliott. Bringing the extraterrestrial into his suburban California house, Elliott introduces E.T., as the alien is dubbed, to his brother and his little sister, Gertie, and the children decide to keep its existence a secret. Soon, however, E.T. falls ill, resulting in government intervention and a dire situation for both Elliott and the alien.', 'https://image.tmdb.org/t/p/w500/an0nD6uq6byfxXCfk6lQBzdL2J1.jpg', null, null),
  ('Twilight Zone: The Movie', 1983, false, 'PG', 'Joe Dante, John Landis, George Miller', '1983-06-24'::date, '101 min', 'Horror, Sci-Fi', 'John Landis, George Clayton Johnson, Richard Matheson', 'Dan Aykroyd, Albert Brooks, Vic Morrow', 'Prologue: a driver has a big surprise with his passenger. Segment 1 ("Time Out"): a bigot hates Jews, Black and Asians. One day he will live in World War II, be hunted down by the KKK and get attacked in the Vietnam War and feel the effects of his hatred. Segment 2 ("Kick the Can"): In a nursing home, the elder inhabitants learn that their minds can keep them young. Segment 3 ("It''s a Good Life"): a traveler hits a boy in a bicycle with her car and takes the boy home. Soon she learns that the powerful boy brought her home indeed. Segment 4 ("Nightmare at 20,000 feet"): a writer is scared to fly and soon he sees a monstrous creature destroying the airplane engines during a stormy night.', 'https://image.tmdb.org/t/p/w500/sDWARc5aYTUKE8Y2FIGVgWXuI4K.jpg', null, null),
  ('The Color Purple', 1985, false, 'PG-13', 'Steven Spielberg', '1986-02-07'::date, '154 min', 'Drama', 'Menno Meyjes, Alice Walker', 'Danny Glover, Whoopi Goldberg, Oprah Winfrey', 'This film follows the life of Celie, a young black girl growing up in the early 1900''s. The first time we see Celie, she is 14 - and pregnant - by her father. We stay with her for the next 30 years of her tough life...', 'https://image.tmdb.org/t/p/w500/6bvxkcTAXyqxGRwo38mxw92D6Xr.jpg', null, null),
  ('Empire of the Sun', 1987, false, 'PG', 'Steven Spielberg', '1987-12-25'::date, '153 min', 'Drama, War', 'Tom Stoppard, J.G. Ballard, Menno Meyjes', 'Christian Bale, John Malkovich, Miranda Richardson', 'Based on J. G. Ballard''s autobiographical novel, tells the story of a boy, James Graham, whose privileged life is upturned by the Japanese invasion of Shanghai, December 8, 1941. Separated from his parents, he is eventually captured, and taken to Soo Chow confinement camp, next to a captured Chinese airfield. Amidst the sickness and food shortages in the camp, Jim attempts to reconstruct his former life, all the while bringing spirit and dignity to those around him.', 'https://image.tmdb.org/t/p/w500/gEaCzjwHoPgyQFcwHql7o5YLHAU.jpg', null, null),
  ('Always', 1989, true, 'PG', 'Steven Spielberg', '1989-12-22'::date, '122 min', 'Drama, Fantasy, Romance', 'Jerry Belson, Dalton Trumbo, Frederick Hazlitt Brennan', 'Richard Dreyfuss, Holly Hunter, Brad Johnson', 'Pete Sandich and buddy Al Yackey are daredevil aerial forest-fire fighters. Pete finds True Love with Dorinda but won''t give up the job. When he takes one risk too many, Dorinda faces deep grief and cannot easily put her life back together.', 'https://image.tmdb.org/t/p/w500/wh0WItAFrw3m66mDMlCCuXQwfMW.jpg', null, null),
  ('Hook', 1991, false, 'PG', 'Steven Spielberg', '1991-12-11'::date, '142 min', 'Adventure, Comedy, Family', 'J.M. Barrie, James V. Hart, Nick Castle', 'Dustin Hoffman, Robin Williams, Julia Roberts', 'Peter Pan (Robin Williams) has grown up to be a cut-throat merger and acquisitions lawyer, and is married to Wendy''s (Dame Maggie Smith''s) granddaughter, Moira (Caroline Goodall). Captain James Hook (Dustin Hoffman) kidnaps his children, Jack (Charlie Korsmo) and Maggie (Amber Scott), and Peter returns to Neverland with Tinkerbell (Julia Roberts). With the help of her and the Lost Boys, he must remember how to be Peter Pan again in order to save his children by battling with Captain Hook once again.', 'https://image.tmdb.org/t/p/w500/a6rB1lGXoGms7gWxRfJneQmAjNV.jpg', null, null),
  ('Schindler''s List', 1993, false, 'R', 'Steven Spielberg', '1994-02-04'::date, '195 min', 'Biography, Drama, History', 'Thomas Keneally, Steven Zaillian', 'Liam Neeson, Ralph Fiennes, Ben Kingsley', 'Oskar Schindler is a vain and greedy German businessman who becomes an unlikely humanitarian amid the barbaric German Nazi reign when he feels compelled to turn his factory into a refuge for Jews. Based on the true story of Oskar Schindler who managed to save about 1100 Jews from being gassed at the Auschwitz concentration camp, it is a testament to the good in all of us.', 'https://image.tmdb.org/t/p/w500/sF1U4EUQS8YHUYjNl3pMGNIQyr0.jpg', null, null),
  ('Amistad', 1997, true, 'R', 'Steven Spielberg', '1997-12-25'::date, '155 min', 'Biography, Drama, History', 'David Franzoni', 'Djimon Hounsou, Matthew McConaughey, Anthony Hopkins', 'Amistad is the name of a slave ship travelling from Cuba to the U.S. in 1839. It is carrying a cargo of Africans who have been sold into slavery in Cuba, taken on board, and chained in the cargo hold of the ship. As the ship is crossing from Cuba to the U.S., Cinque (Djimon Hounsou), who was a tribal leader in Africa, leads a mutiny and takes over the ship. They continue to sail, hoping to find their way back to Africa. Instead, they are misdirected and when they reach the United States, they are imprisoned as runaway slaves. They don''t speak a word of English, and it seems like they are doomed to die for killing their captors when an abolitionist lawyer decides to take their case, arguing that they were free citizens of another country and not slaves at all. The case finally gets to the Supreme Court, where John Quincy Adams (Sir Anthony Hopkins) makes an impassioned and eloquent plea for their release.', 'https://image.tmdb.org/t/p/w500/6QqNyIHKow0jngiQgTNBOBrLILM.jpg', null, null),
  ('Saving Private Ryan', 1998, false, 'R', 'Steven Spielberg', '1998-07-24'::date, '169 min', 'Drama, War', 'Robert Rodat', 'Tom Hanks, Matt Damon, Tom Sizemore', 'Opening with the Allied invasion of Normandy on 6 June 1944, members of the 2nd Ranger Battalion under Cpt. Miller fight ashore to secure a beachhead. Amidst the fighting, two brothers are killed in action. Earlier in New Guinea, a third brother is KIA. Their mother, Mrs. Ryan, is to receive all three of the grave telegrams on the same day. The United States Army Chief of Staff, George C. Marshall, is given an opportunity to alleviate some of her grief when he learns of a fourth brother, Private James Ryan, and decides to send out 8 men (Cpt. Miller and select members from 2nd Rangers) to find him and bring him back home to his mother...', 'https://image.tmdb.org/t/p/w500/uqx37cS8cpHg8U35f9U5IBlrCV3.jpg', null, null),
  ('A.I. Artificial Intelligence', 2001, true, 'PG-13', 'Steven Spielberg', '2001-06-29'::date, '146 min', 'Adventure, Drama, Sci-Fi', 'Brian Aldiss, Ian Watson, Steven Spielberg', 'Haley Joel Osment, Jude Law, Frances O''Connor', 'In the not-so-far future the polar ice caps have melted and the resulting rise of the ocean waters has drowned all the coastal cities of the world. Withdrawn to the interior of the continents, the human race keeps advancing, reaching the point of creating realistic robots (called mechas) to serve them. One of the mecha-producing companies builds David, an artificial kid which is the first to have real feelings, especially a never-ending love for his "mother", Monica. Monica is the woman who adopted him as a substitute for her real son, who remains in cryo-stasis, stricken by an incurable disease. David is living happily with Monica and her husband, but when their real son returns home after a cure is discovered, his life changes dramatically.', 'https://image.tmdb.org/t/p/w500/8MZSGX5JORoO72EfuAEcejH5yHn.jpg', null, null),
  ('Catch Me If You Can', 2002, false, 'PG-13', 'Steven Spielberg', '2002-12-25'::date, '141 min', 'Biography, Crime, Drama', 'Frank Abagnale Jr., Stan Redding, Jeff Nathanson', 'Leonardo DiCaprio, Tom Hanks, Christopher Walken', 'A true story about Frank Abagnale Jr. who, before his 19th birthday, successfully conned millions of dollars worth of checks as a Pan Am pilot, doctor, and legal prosecutor. An FBI agent makes it his mission to put him behind bars. But Frank not only eludes capture, he revels in the pursuit.', 'https://image.tmdb.org/t/p/w500/sdYgEkKCDPWNU6KnoL4qd8xZ4w7.jpg', null, null),
  ('The Terminal', 2004, false, 'PG-13', 'Steven Spielberg', '2004-06-18'::date, '128 min', 'Comedy, Drama, Romance', 'Andrew Niccol, Sacha Gervasi, Jeff Nathanson', 'Tom Hanks, Catherine Zeta-Jones, Chi McBride', 'Victor Navorski reaches JFK airport from a politically unstable country. Due to collapse of his government, his papers are no longer valid in the airport, and hence he is forced to stay in the airport until the war cools down. He makes the airport his home and develops a friendship with the people who work there until he can leave.', 'https://image.tmdb.org/t/p/w500/cPB3ZMM4UdsSAhNdS4c7ps5nypY.jpg', null, null),
  ('Beverly Hills Cop Axel F', 2024, true, 'R', 'Mark Molloy', '2024-07-03'::date, '118 min', 'Action, Comedy, Crime', 'Will Beall, Tom Gormican, Kevin Etten', 'Eddie Murphy, Joseph Gordon-Levitt, Taylour Paige', 'Axel Foley returns to Beverly Hills after his daughter''s life is threatened for a family reunion that includes old pals John Taggart and Billy Rosewood to uncover a conspiracy.', 'https://image.tmdb.org/t/p/w500/zszRKfzjM5jltiq8rk6rasKVpUv.jpg', null, null),
  ('War of the Worlds', 2005, false, 'PG-13', 'Steven Spielberg', '2005-06-29'::date, '117 min', 'Action, Adventure, Sci-Fi', 'Josh Friedman, David Koepp, H.G. Wells', 'Tom Cruise, Dakota Fanning, Tim Robbins', 'An ordinary man has to protect his children against alien invaders in this science fiction action film freely adapted from the classic story by H.G. Wells. Ray Ferrier (Tom Cruise) is a dockworker living in New Jersey, divorced from his first wife Mary Ann (Miranda Otto) and estranged from his two children Rachel and Robbie (Dakota Fanning and Justin Chatwin), of whom he has custody on weekends. On one such visitation, looking after the kids becomes a little more difficult when, after a series of strange lighting storms hit his neighborhood, Ray discovers that a fleet of death-ray robotic spaceships have emerged nearby, part of the first wave of an all-out alien invasion of the Earth. Transporting his children from New York to Boston in an attempt to find safety at Mary Ann''s parents'' house, Ray must learn to become the protector and provider he never was in marriage.', 'https://image.tmdb.org/t/p/w500/6Biy7R9LfumYshur3YKhpj56MpB.jpg', null, null),
  ('Munich', 2005, false, 'R', 'Steven Spielberg', '2006-01-06'::date, '164 min', 'Action, Drama, History', 'Tony Kushner, Eric Roth, George Jonas', 'Eric Bana, Daniel Craig, Marie-Josée Croze', 'After Black September''s assassination of Israeli athletes at the Munich Olympics in 1972, Prime Minister Golda Meir okays a covert operation to hunt down and kill all involved. A team of five gathers in Switzerland led by Avner, a low-level Mossad techie whose father was a war hero and whose wife is pregnant. It''s an expendable team, but relying on paid informants, they track and kill several in Europe and Lebanon. They must constantly look over their shoulders for the CIA, KGB, PLO, and their own sources. As the body count mounts -- with retribution following retribution -- so do questions, doubts, and sleepless nights. Loyalties blur. What does it mean to be a Jew?', 'https://image.tmdb.org/t/p/w500/iUekaw96QLInZpsNwRTlRKrZgwm.jpg', null, null),
  ('The Adventures of Tintin', 2011, true, 'PG', 'Steven Spielberg', '2011-12-21'::date, '107 min', 'Animation, Action, Adventure', 'Hergé, Steven Moffat, Edgar Wright', 'Jamie Bell, Andy Serkis, Daniel Craig', 'Having bought a model ship, the Unicorn, for a pound off a market stall Tintin is initially puzzled that the sinister Mr. Sakharine should be so eager to buy it from him, resorting to murder and kidnapping Tintin - accompanied by his marvellous dog Snowy - to join him and his gang as they sail to Morocco on an old cargo ship. Sakharine has bribed the crew to revolt against the ship''s master, drunken Captain Haddock, but Tintin, Snowy and Haddock escape, arriving in Morocco at the court of a sheikh, who also has a model of the Unicorn. Haddock tells Tintin that over three hundred years earlier his ancestor Sir Francis Haddock was forced to scuttle the original Unicorn when attacked by a piratical forebear of Sakharine but he managed to save his treasure and provide clues to its location in three separate scrolls, all of which were secreted in models of the Unicorn. Tintin and Sakharine have one each and the villain intends to use the glass-shattering top Cs of operatic soprano the Milanese Nightingale to secure the third. With aid from bumbling Interpol agents the Thompson Twins our boy hero, his dog and the captain must prevent Sakharine from obtaining all three scrolls to fulfil the prophesy that only the last of the Haddocks can discover the treasure''s whereabouts.', 'https://image.tmdb.org/t/p/w500/fQZ3sLR1Fi63NMsNRbjm9q5qODJ.jpg', null, null),
  ('War Horse', 2011, false, 'PG-13', 'Steven Spielberg', '2011-12-25'::date, '146 min', 'Action, Adventure, Drama', 'Lee Hall, Richard Curtis, Michael Morpurgo', 'Jeremy Irvine, Emily Watson, David Thewlis', 'On the outbreak of the First World War, Albert''s beloved horse ''Joey'' is sold to the Cavalry by his Father. After being sent to France, in a bid to survive, Joey has an unexpected journey across war torn Europe. Albert enlists in the British Army, and is wounded during the Battle of the Somme. Whilst recovering in Hospital, he learns of a Horse, found in no mans land.', 'https://image.tmdb.org/t/p/w500/3aRHhvvngFPJFy5uAjo7GVr3PhL.jpg', null, null),
  ('Lincoln', 2012, false, 'PG-13', 'Steven Spielberg', '2012-11-16'::date, '150 min', 'Biography, Drama, History', 'Tony Kushner, Doris Kearns Goodwin', 'Daniel Day-Lewis, Sally Field, David Strathairn', 'In 1865, as the American Civil War winds inexorably toward conclusion, U.S. president Abraham Lincoln endeavors to achieve passage of the landmark constitutional amendment which will forever ban slavery from the United States. However, his task is a race against time, for peace may come at any time, and if it comes before the amendment is passed, the returning southern states will stop it before it can become law. Lincoln must, by almost any means possible, obtain enough votes from a recalcitrant Congress before peace arrives and it is too late. Yet the president is torn, as an early peace would save thousands of lives. As the nation confronts its conscience over the freedom of its entire population, Lincoln faces his own crisis of conscience -- end slavery or end the war.', 'https://image.tmdb.org/t/p/w500/5KeUqW6DpVtf8G9VMuI2l0XIPCo.jpg', null, null),
  ('Bridge of Spies', 2015, false, 'PG-13', 'Steven Spielberg', '2015-10-16'::date, '142 min', 'Drama, History, Thriller', 'Matt Charman, Ethan Coen, Joel Coen', 'Tom Hanks, Mark Rylance, Alan Alda', 'In the cold war, a lawyer, James B. Donovan is recruited by the CIA and involved in an intense negotiation mission to release and exchange a CIA U-2 spy-plane pilot, Francis G. Powers. The pilot was arrested alive after his plane was shot down by the Soviet Union during a mission and stays in the company of a KGB intelligence officer, Rudolf Abel, who was arrested for espionage in the US.', 'https://image.tmdb.org/t/p/w500/fmOOjHAQzxr0c1sfcY4qkiSRBH6.jpg', null, null),
  ('The BFG', 2016, false, 'PG', 'Steven Spielberg', '2016-07-01'::date, '117 min', 'Adventure, Family, Fantasy', 'Melissa Mathison, Roald Dahl', 'Mark Rylance, Ruby Barnhill, Penelope Wilton', 'Ten-year-old Sophie is in for the adventure of a lifetime when she meets the Big Friendly Giant. Naturally scared at first, the young girl soon realizes that the twenty-four-foot behemoth is actually quite gentle and charming. As their friendship grows, Sophie''s presence attracts the unwanted attention of Bloodbottler, Fleshlumpeater, and other giants. After travelling to London, Sophie and the BFG must convince Queen Elizabeth to help them get rid of all of the bad giants once and for all.', 'https://image.tmdb.org/t/p/w500/vssXmCrfCiARkQ0512oG0wjh2h9.jpg', null, null),
  ('The Post', 2017, false, 'PG-13', 'Steven Spielberg', '2018-01-12'::date, '116 min', 'Biography, Drama, History', 'Liz Hannah, Josh Singer', 'Meryl Streep, Tom Hanks, Sarah Paulson', 'When American military analyst, Daniel Ellsberg, realizes to his disgust the depths of the US government''s deceptions about the futility of the Vietnam War, he takes action by copying top-secret documents that would become the Pentagon Papers. Later, Washington Post owner, Kay Graham, is still adjusting to taking over her late husband''s business when editor Ben Bradlee discovers the New York Times has scooped them with an explosive expose on those papers. Determined to compete, Post reporters find Ellsberg himself and a complete copy of those papers. However, the Post''s plans to publish their findings are put in jeopardy with a Federal restraining order that could get them all indicted for Contempt. Now, Kay Graham must decide whether to back down for the safety of her paper or publish and fight for the Freedom of the Press. In doing so, Graham and her staff join a fight that would have America''s democratic ideals in the balance.', 'https://image.tmdb.org/t/p/w500/h4XG3g6uMMPIBPjAoQhC2QIMdkl.jpg', null, null),
  ('Scream 4', 2011, false, 'R', 'Wes Craven', '2011-04-15'::date, '111 min', 'Horror, Mystery', 'Kevin Williamson', 'Neve Campbell, Courteney Cox, David Arquette', 'Sidney Prescott, now the author of a self-help book, returns home to Woodsboro on the last stop of her book tour. There she reconnects with Sheriff Dewey and Gale, who are now married, as well as her cousin Jill and her Aunt Kate. Unfortunately, Sidney''s appearance also brings about the return of Ghostface, putting Sidney, Gale, and Dewey, along with Jill, her friends, and the whole town of Woodsboro in danger.', 'https://image.tmdb.org/t/p/w500/tcrI37K98TVopLbcZBa55mWhLT1.jpg', null, null),
  ('West Side Story', 2021, false, 'PG-13', 'Steven Spielberg', '2021-12-10'::date, '156 min', 'Crime, Drama, Musical', 'Tony Kushner, Arthur Laurents', 'Ansel Elgort, Rachel Zegler, Ariana DeBose', 'Manhattan, Upper West Side, 1957. Against the backdrop of the decaying tenements in the San Juan Hill neighbourhood and the constant threat of the wrecking ball, two warring gangs--tough Riff''s Jets and swaggering Bernardo''s Puerto Rican Sharks--fight for supremacy. Now, with a once-and-for-all, winner-takes-all rumble on the cards, an unexpected whirlwind romance at the high-school dance between former Jet brawler Tony and Bernardo''s delicate little sister María sets the stage for an all-out turf war. But what''s a gang without its territory? Above all, when the future is uncertain, what''s hope without love?', 'https://image.tmdb.org/t/p/w500/yfz3IUoYYSY32tkb97HlUBGFsnh.jpg', null, null),
  ('The Fabelmans', 2022, false, 'PG-13', 'Steven Spielberg', '2022-11-23'::date, '151 min', 'Drama', 'Steven Spielberg, Tony Kushner', 'Michelle Williams, Gabriel LaBelle, Paul Dano', 'Growing up in post-World War II era Arizona, young Sammy Fabelman aspires to become a filmmaker as he reaches adolescence, but soon discovers a shattering family secret and explores how the power of films can help him see the truth.', 'https://image.tmdb.org/t/p/w500/h7llKkqkkJtJrTOaDLuVeUYDQ7I.jpg', null, null),
  ('The Hunger Games', 2012, false, 'PG-13', 'Gary Ross', '2012-03-23'::date, '142 min', 'Action, Adventure, Sci-Fi', 'Gary Ross, Suzanne Collins, Billy Ray', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth', 'In a dystopian future, the totalitarian nation of Panem is divided into 12 districts and the Capitol. Each year two young representatives from each district are selected by lottery to participate in The Hunger Games. Part entertainment, part brutal retribution for a past rebellion, the televised games are broadcast throughout Panem. The 24 participants are forced to eliminate their competitors while the citizens of Panem are required to watch. When 16-year-old Katniss'' young sister, Prim, is selected as District 12''s female representative, Katniss volunteers to take her place. She and her male counterpart, Peeta, are pitted against bigger, stronger representatives, some of whom have trained for this their whole lives.', 'https://image.tmdb.org/t/p/w500/yXCbOiVDCxO71zI7cuwBRXdftq8.jpg', null, null),
  ('The Hunger Games: Catching Fire', 2013, false, 'PG-13', 'Francis Lawrence', '2013-11-22'::date, '146 min', 'Action, Adventure, Sci-Fi', 'Simon Beaufoy, Michael Arndt, Suzanne Collins', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth', 'Twelve months after winning the 74th Hunger Games, Katniss Everdeen and her partner Peeta Mellark must go on what is known as the Victor''s Tour, wherein they visit all the districts, but before leaving, Katniss is visited by President Snow who fears that Katniss defied him a year ago during the games when she chose to die with Peeta. With both Katniss and Peeta declared the winners, it is fueling a possible uprising. He tells Katniss that while on tour she better try to make sure that she puts out the flames or else everyone she cares about will be in danger.', 'https://image.tmdb.org/t/p/w500/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg', null, null),
  ('The Hunger Games: Mockingjay Part 1', 2014, false, 'PG-13', 'Francis Lawrence', '2014-11-21'::date, '123 min', 'Action, Adventure, Sci-Fi', 'Peter Craig, Danny Strong, Suzanne Collins', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth', 'With the Games destroyed, Katniss Everdeen, along with Gale, Finnick and Beetee, end up in the so thought "destroyed" District 13. Under the leadership of President Coin and the advice of her friends, Katniss becomes the "Mockingjay", the symbol of rebellion for the districts of Panem.', 'https://image.tmdb.org/t/p/w500/4FAA18ZIja70d1Tu5hr5cj2q1sB.jpg', null, null),
  ('The Hunger Games: Mockingjay Part 2', 2015, false, 'PG-13', 'Francis Lawrence', '2015-11-20'::date, '137 min', 'Action, Adventure, Sci-Fi', 'Peter Craig, Danny Strong, Suzanne Collins', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth', 'After young Katniss Everdeen agrees to be the symbol of rebellion, the Mockingjay, she tries to return Peeta to his normal state, tries to get to the Capitol, and tries to deal with the battles coming her way...but all for her main goal: assassinating President Snow and returning peace to the Districts of Panem. As her squad starts to get smaller and smaller, will she make it to the Capitol? Will she get revenge on Snow or will her target change? Will she be with her "Star-Crossed Lover," Peeta, or her long-time friend, Gale? Deaths, bombs, bow and arrows, a love triangle, hope... What will happen?', 'https://image.tmdb.org/t/p/w500/lImKHDfExAulp16grYm8zD5eONE.jpg', null, null),
  ('The Hunger Games: The Ballad of Songbirds & Snakes', 2023, false, 'PG-13', 'Francis Lawrence', '2023-11-17'::date, '157 min', 'Action, Adventure, Drama', 'Michael Lesslie, Michael Arndt, Suzanne Collins', 'Rachel Zegler, Tom Blyth, Viola Davis', 'Coriolanus Snow at age 18, years before he would become the tyrannical President of Panem. Young Coriolanus is handsome and charming, and though the Snow family has fallen on hard times, he sees a chance for a change in his fortunes when he is chosen to be a mentor for the Tenth Hunger Games. only to have his elation dashed when he is assigned to mentor the girl tribute from impoverished District 12.', 'https://image.tmdb.org/t/p/w500/lrkOYL5GBTFW9cgs9RlojxAcZZF.jpg', null, null),
  ('Scream', 1996, false, 'R', 'Wes Craven', '1996-12-20'::date, '111 min', 'Horror, Mystery', 'Kevin Williamson', 'Neve Campbell, Courteney Cox, David Arquette', 'A year after her mother''s death, Sidney Prescott (Neve Campbell) and her friends started experiencing some strange phone calls. They later learned the calls were coming from a crazed serial killer, in a white faced mask and a large black robe, looking for revenge. His phone calls usually consist of many questions, the main one being: What''s your favorite scary movie? Along with much scary movie trivia, ending with bloody pieces of innocent lives scattered around the small town of Woodsboro.', 'https://image.tmdb.org/t/p/w500/lr9ZIrmuwVmZhpZuTCW8D9g0ZJe.jpg', null, null),
  ('Scream 2', 1997, false, 'R', 'Wes Craven', '1997-12-12'::date, '120 min', 'Horror, Mystery', 'Kevin Williamson', 'Neve Campbell, Courteney Cox, David Arquette', 'Two years after the events of Scream, Sidney Prescott and Randy are attending Windsor college. They are trying to get on with their lives...Until a new Ghostface killing spree begins. With the help of Dewey and Gale, Sidney must find out who''s behind the murders. As the body count goes up, the list of suspects goes down.', 'https://image.tmdb.org/t/p/w500/dORlVasiaDkJXTqt9bdH7nFNs6C.jpg', null, null),
  ('Scream 3', 2000, false, 'R', 'Wes Craven', '2000-02-04'::date, '116 min', 'Horror, Mystery', 'Kevin Williamson, Ehren Kruger', 'David Arquette, Neve Campbell, Courteney Cox', 'A new film is currently in production, and a killer is on the loose. The murders draw a reporter, ex-cop, and young woman to the set of the movie inspired by their life. They soon find out that they are dealing with a trilogy, and in a trilogy...anything can happen.', 'https://image.tmdb.org/t/p/w500/qpH8ToZVlFD1bakL04LkEKodyDI.jpg', null, null),
  ('Death of a Unicorn', 2025, true, 'R', 'Alex Scharfman', '2025-03-28'::date, '107 min', 'Comedy, Fantasy, Horror', 'Alex Scharfman', 'Jenna Ortega, Paul Rudd, David Pasquesi', 'A father and daughter accidentally hit and kill a unicorn while en route to a weekend retreat, where his billionaire boss seeks to exploit the creature''s miraculous curative properties.', 'https://image.tmdb.org/t/p/w500/xWlF2i51zUq7BUq4iJte1g9NyIM.jpg', null, null),
  ('Scream ', 2022, false, 'R', 'Matt Bettinelli-Olpin, Tyler Gillett', '2022-01-14'::date, '114 min', 'Horror, Mystery, Thriller', 'James Vanderbilt, Guy Busick, Kevin Williamson', 'Neve Campbell, Courteney Cox, David Arquette', 'Like the original movie 25 years ago, a cute teenage girl is at home alone when the phone rings. A man wants to play a game with her. With the threat of killing her best friend, Tara''s forced to play along. She barely survives the ghost face masked intruder''s stabbing. Her 5 year older sister, Sam(antha), who left home at 18 due to mental problems, Sam''s boyfriend and Tara''s high school friends visit her at the hospital. Later on in a bar, a guy provokes the friends and is later attacked outside in the parking lot by Ghostface. Sam receives a call from him at the hospital and then he unsuccessfully attacks her. She later reveals family secrets to her sister. Sam contacts one of the original victims, Dewey, for help. He warns two other original victims, Sidney Prescott and Gale Weathers, about Ghostface being back. Who is Ghostface? How many more must die?', 'https://image.tmdb.org/t/p/w500/1m3W6cpgwuIyjtg5nSnPx7yFkXW.jpg', null, null),
  ('Scream VI', 2023, false, 'R', 'Matt Bettinelli-Olpin, Tyler Gillett', '2023-03-10'::date, '122 min', 'Horror, Mystery, Thriller', 'James Vanderbilt, Guy Busick, Kevin Williamson', 'Courteney Cox, Melissa Barrera, Jenna Ortega', 'The survivors of the Ghostface killings leave Woodsboro behind and start a fresh chapter in New York City.', 'https://image.tmdb.org/t/p/w500/wDWwtvkRRlgTiUr6TyLSMX8FCuZ.jpg', null, null),
  ('I Am Number Four', 2011, false, 'PG-13', 'D.J. Caruso', '2011-02-18'::date, '111 min', 'Action, Adventure, Sci-Fi', 'Alfred Gough, Miles Millar, Marti Noxon', 'Alex Pettyfer, Timothy Olyphant, Dianna Agron', 'Extraordinary teen John Smith (Pettyfer) is a fugitive on the run from ruthless enemies sent to destroy him. Changing his identity, moving from town to town with his guardian Henri (Olyphant), John is always the new kid with no ties to his past. In the small Ohio town he now calls home, John encounters unexpected, life-changing events - his first love (Agron), powerful new abilities and a connection to the others who share his incredible destiny.', 'https://image.tmdb.org/t/p/w500/2NrP3h3GEsrPXX60bmjKuYWAvl9.jpg', null, null),
  ('Real Steel', 2011, false, 'PG-13', 'Shawn Levy', '2011-10-07'::date, '127 min', 'Action, Drama, Sci-Fi', 'John Gatins, Dan Gilroy, Jeremy Leven', 'Hugh Jackman, Evangeline Lilly, Dakota Goyo', 'In the near future when people become uninterested in boxing and similar sports, a new sport is created - Robot boxing wherein robots battle each other while being controlled by someone. Charlie Kenton, a former boxer who''s trying to make it in the new sport, not only doesn''t do well, he is very deeply in the red. When he learns that his ex, mother of his son Max, dies, he goes to figure out what to do with him. His ex''s sister wants to take him in but Charlie has first say in the matter. Charlie asks her husband for money so he can buy a new Robot in exchange for turning Max over to them. He takes Max for the summer. And Max improves his control of his robot. But when the robot is destroyed, they go to a scrap yard to get parts. Max finds an old generation robot named Atom and restores him. Max wants Atom to fight but Charlie tells him he won''t last a round. However, Atom wins. And it isn''t long before Atom is getting major bouts. Max gets Charlie to teach Atom how to fight, and the father and son bond strenghtens.', 'https://image.tmdb.org/t/p/w500/4GIeI5K5YdDUkR3mNQBoScpSFEf.jpg', null, null),
  ('Ghostbusters ', 1984, true, 'PG', 'Ivan Reitman', '1984-06-08'::date, '105 min', 'Action, Comedy, Fantasy', 'Dan Aykroyd, Harold Ramis, Rick Moranis', 'Bill Murray, Dan Aykroyd, Sigourney Weaver', 'Peter Venkman, Ray Stantz and Egon Spengler work at Columbia University. where they delve into the paranormal and fiddle with many unethical experiments on their students. As they are kicked out of the University, they really understand the paranormal and go into business for themselves. Under the new snazzy business name of ''Ghostbusters'', and living in the old firehouse building they work out of, they are called to rid New York City of paranormal phenomenon at everyone''s whim. - for a price. They make national press as the media reports the Ghostbusters are the cause of it all. Thrown in jail by the EPA, the mayor takes a chance and calls on them to help save the city. Unbeknownst to all, a long dead Gozer worshiper (Evo Shandor) erected a downtown apartment building which is the cause of all the paranormal activity. They find out the building could resurrect the ancient Hittite god, Gozer, and bring an end to all of humanity. Who are you gonna call to stop this terrible world-ending menace?', 'https://image.tmdb.org/t/p/w500/7E8nLijS9AwwUEPu2oFYOVKhdFA.jpg', null, null),
  ('Ghostbusters II', 1989, true, 'PG', 'Ivan Reitman', '1989-06-16'::date, '108 min', 'Action, Comedy, Fantasy', 'Dan Aykroyd, Harold Ramis', 'Bill Murray, Dan Aykroyd, Sigourney Weaver', 'Having lost their status and credibility five years after covering New York City with marshmallow in Ghostbusters (1984), the once-famous band of spirit-hunters find themselves struggling to keep afloat, working odd jobs. However, when Dana Barrett and her baby, Oscar, have yet another terrifying encounter with the paranormal, it''s up to Peter Venkman and his fearless team of supernatural crime-fighters to save the day. Now, once more, humanity is in danger, as rivers of slimy psycho-reactive ectoplasm, and the dreadful manifestation of the evil sixteenth-century tyrant, Vigo the Carpathian, threaten to plunge the entire city into darkness unless the selfless Ghostbusters take action. Can they save the world for the second time?', 'https://image.tmdb.org/t/p/w500/yObYPMA58DnTMvJooFW7GG6jWAt.jpg', null, null),
  ('Ghostbusters: Afterlife', 2021, true, 'PG-13', 'Jason Reitman', '2021-11-19'::date, '124 min', 'Adventure, Comedy, Fantasy', 'Gil Kenan, Jason Reitman, Ivan Reitman', 'Carrie Coon, Paul Rudd, Finn Wolfhard', 'When a single mom and her two kids arrive in a small town, they begin to discover their connection to the original Ghostbusters and the secret legacy their grandfather left behind.', 'https://image.tmdb.org/t/p/w500/sg4xJaufDiQl7caFEskBtQXfD4x.jpg', null, null),
  ('Ghostbusters: Frozen Empire', 2024, true, 'PG-13', 'Gil Kenan', '2024-03-22'::date, '115 min', 'Adventure, Comedy, Fantasy', 'Gil Kenan, Jason Reitman, Ivan Reitman', 'Paul Rudd, Carrie Coon, Finn Wolfhard', 'When the discovery of an ancient artifact unleashes an evil force, Ghostbusters new and old must join forces to protect their home and save the world from a second ice age.', 'https://image.tmdb.org/t/p/w500/e1J2oNzSBdou01sUvriVuoYp0pJ.jpg', null, null),
  ('Star Trek: Section 31', 2025, true, 'PG-13', 'Olatunde Osunsanmi', '2025-01-24'::date, '95 min', 'Action, Adventure, Drama', 'Craig Sweeny, Bo Yeon Kim, Erika Lippoldt', 'Michelle Yeoh, Omari Hardwick, Sam Richardson', 'In Star Trek: Section 31, Emperor Philippa Georgiou joins a secret division of Starfleet tasked with protecting the United Federation of Planets, and must face the sins of her past.', 'https://image.tmdb.org/t/p/w500/fNu6P4jYU55Cb3CC2SndtAKvois.jpg', null, null),
  ('Ghostbusters', 2016, true, 'PG-13', 'Paul Feig', '2016-07-15'::date, '117 min', 'Action, Comedy, Fantasy', 'Katie Dippold, Paul Feig, Ivan Reitman', 'Melissa McCarthy, Kristen Wiig, Kate McKinnon', 'Paranormal researcher Abby Yates and physicist Erin Gilbert are trying to prove that ghosts exist in modern society. When strange apparitions appear in Manhattan, Gilbert and Yates turn to engineer Jillian Holtzmann for help. Also joining the team is Patty Tolan, a lifelong New Yorker who knows the city inside and out. Armed with proton packs and plenty of attitude, the four women prepare for an epic battle as more than 1,000 mischievous ghouls descend on Times Square.', 'https://image.tmdb.org/t/p/w500/wJmWliwXIgZOCCVOcGRBhce7xPS.jpg', null, null),
  ('Friday the 13th', 1980, false, 'R', 'Sean S. Cunningham', '1980-05-09'::date, '95 min', 'Horror, Mystery, Thriller', 'Victor Miller, Ron Kurz', 'Betsy Palmer, Adrienne King, Jeannine Taylor', 'In 1957, a young boy named Jason drowns in a lake near Camp Crystal Lake. The next year, two counselors are murdered. In 1980, a descendant of the original owners reopens Camp Crystal Lake with some counselors'' help. The counselors gets killed one by one by a mysterious person. Could it be Jason, out for revenge?', 'https://image.tmdb.org/t/p/w500/uGGpnWHOmWTARVN9wbC1nPxNgps.jpg', null, null),
  ('Friday the 13th Part 2', 1981, false, 'R', 'Steve Miner', '1981-05-01'::date, '87 min', 'Horror, Mystery, Thriller', 'Ron Kurz, Victor Miller, Sean S. Cunningham', 'Betsy Palmer, Amy Steel, John Furey', 'Months after Alice beheaded psycho killer/mother Pamela Voorhees at Camp Crystal Lake, survivor Alice is still traumatized because of the murders. But there is one problem: Mrs. Voorhees'' son Jason never drowned and died, so he saw Alice behead Mrs. Voorhees. Jason finds Alice soon and murders her. Five years later, a camp counselor-in-training program begins at Packanack Lodge, right near Camp Crystal Lake. As teenagers in the program start snooping around Camp Crystal Lake, they start getting killed violently one by one.', 'https://image.tmdb.org/t/p/w500/92rGctBMTv4uaSlIBVnhz01kRWL.jpg', null, null),
  ('Friday the 13th Part 3', 1982, false, 'R', 'Steve Miner', '1982-08-13'::date, '95 min', 'Horror, Thriller', 'Martin Kitrosser, Carol Watson, Victor Miller', 'Dana Kimmell, Tracie Savage, Richard Brooker', 'Jason Voorhees, having barely survived a wound to his shoulder from his own machete, is back to revenge on all that visit "his" woods. A new group of friends come over to party at an area close to the campsite. This time, Jason will be stronger than ever, and getting a hockey mask from one of those friends.', 'https://image.tmdb.org/t/p/w500/9kukTSlgFgXnQGdpcHvHcpTDiUc.jpg', null, null),
  ('Friday the 13th: The Final Chapter', 1984, false, 'R', 'Joseph Zito', '1984-04-13'::date, '91 min', 'Horror, Thriller', 'Victor Miller, Ron Kurz, Martin Kitrosser', 'Erich Anderson, Judie Aronson, Peter Barton', 'After being stabbed in the head by Chris Higgins. Jason Vorhees is believed to be dead and is taken to a Hospital for an Autopsy. However, He is Alive and kills a Doctor and a Nurse and is loose once more. He Returns to Camp Crystal Lake where Young Boy Tommy Jarvis lives with his Mother and Older Sister. A Group of Teenagers move in to a House next door to the Jarvis House. Jason begins killing the Teenagers and kills Tommy''s Mother. It''s now up to Tommy and His Older Sister to kill Jason and end his murderous rampage once and for all.', 'https://image.tmdb.org/t/p/w500/1J7zudfR3VLPwAf9lK5YPfSu0n6.jpg', null, null),
  ('Friday the 13th: A New Beginning', 1985, false, 'R', 'Danny Steinmann', '1985-03-22'::date, '92 min', 'Horror, Mystery, Thriller', 'Martin Kitrosser, David Cohen, Danny Steinmann', 'Melanie Kinnaman, John Shepherd, Anthony Barrile', 'Five years after killing the goalie hockey-masked killer Jason Voorhees, Tommy Jarvis has grown up in various mental hospitals unable to get over the nightmares about Jason''s return. When Tommy is sent to a rural halfway house in New Jersey for mentally disturbed teenagers, a series of grisly murders begin anew as another hockey-masked killer begins killing off all people at and around the residence. Has Jason returned from the dead to re-start his killing spree? Has Tommy decided to take over the reign of Jason, or has someone else?', 'https://image.tmdb.org/t/p/w500/ewnIs4aCuWnKQ13Eaj8f3ybrQc8.jpg', null, null),
  ('Friday the 13th Part VI: Jason Lives', 1986, false, 'R', 'Tom McLoughlin', '1986-08-01'::date, '86 min', 'Horror, Thriller', 'Tom McLoughlin, Victor Miller, Sean S. Cunningham', 'Thom Mathews, Jennifer Cooke, David Kagen', 'Tommy Jarvis returns to the graveyard to make sure Jason Voorhees is dead and accidentally brings him back to life. Now it''s up to Tommy to stop Jason''s mindless killing and put him back where he belongs.', 'https://image.tmdb.org/t/p/w500/6vdUpHvkspQonXBdWcLWW5ciEPJ.jpg', null, null),
  ('Friday the 13th: The New Blood', 1988, false, 'R', 'John Carl Buechler', '1988-05-13'::date, '88 min', 'Horror, Thriller', 'Daryl Haney, Manuel Fidello, Victor Miller', 'Terry Kiser, Jennifer Banko, John Otrin', 'After Jason Vorhees was chained to the Bottom of Camp Crystal Lake by Tommy Jarvis. A Young Telekinetic Girl known as Tina Shepherd accidentally killed her Father with her Powers at Crystal Lake. Years Later, Tina and Her Mother return to Camp Crystal Lake, Where Tina''s Doctor trys to manipulate her powers for his own evil plans. Tina then trys to ressurect Her Father but Accidentally Awakens Jason Instead. It''s now up to Tina to use her Powers to Stop Jason and Her Evil Doctor.', 'https://image.tmdb.org/t/p/w500/rUzk9Qnyz2FZGxHMBrq6DYIQZkO.jpg', null, null),
  ('Friday the 13th Part VIII: Jason Takes Manhattan', 1989, false, 'R', 'Rob Hedden', '1989-07-28'::date, '100 min', 'Adventure, Horror, Thriller', 'Rob Hedden, Victor Miller', 'Jensen Daggett, Kane Hodder, Todd Caldecott', 'Jason Voorhees is accidentally awakened from his watery grave and ends up stalking a ship full of graduating high-school students headed to Manhattan, New York.', 'https://image.tmdb.org/t/p/w500/6ezOsZ9UzqGnbDokaatxdOWP6e9.jpg', null, null),
  ('Jason Goes To Hell', 1993, false, 'R', 'Adam Marcus', '1993-08-13'::date, '87 min', 'Fantasy, Horror, Thriller', 'Jay Huguely, Adam Marcus, Dean Lorey', 'John D. LeMay, Kari Keegan, Kane Hodder', 'The secret of Jason''s evil is revealed. It is up to the last remaining descendant of the Voorhees family to stop Jason before he becomes immortal and unstoppable. This is the final (?) battle to end Jason''s reign of terror forever.', 'https://image.tmdb.org/t/p/w500/Aacq05foqiWdXqetFv02HBvMoJy.jpg', null, null),
  ('Jason X', 2001, false, 'R', 'James Isaac', '2002-04-26'::date, '92 min', 'Action, Horror, Sci-Fi', 'Todd Farmer, Victor Miller', 'Kane Hodder, Lexa Doig, Jeff Geddis', 'In the Year 2008, Jason Vorhees is cryogenically frozen in a Government Facility in Camp Crystal Lake, along with scientist Rowan. Many centuries later, in the year 2455, Earth is uninhabitable, and humans have moved to another planet known as Earth II. However, a team of students awakens both him and Rowan on a spaceship known as the Grendel. Jason begins killing the students and crew of the ship. Along the way, he is upgraded to Uber Jason. It''s now up to Rowan and the surviving students to stop Jason, this time on a spaceship.', 'https://image.tmdb.org/t/p/w500/ggOND0hfoE0f3K857joSzEeIchb.jpg', null, null),
  ('Freddy vs. Jason', 2003, false, 'R', 'Ronny Yu', '2003-08-15'::date, '97 min', 'Action, Horror', 'Wes Craven, Victor Miller, Damian Shannon', 'Robert Englund, Ken Kirzinger, Kelly Rowland', 'It''s been nearly ten years since Freddy Krueger terrorized people in the dreams, and the towns folk want to keep him erased from their memory. Freddy still has one more plan on getting back to Elm Street. He resurrects Jason Voorhees and sends him off to kill. The more bodies which fall to the ground, the stronger in which Freddy becomes. This is until, Freddy realizes that Jason isn''t going to step aside easily, and must be taken down himself.', 'https://image.tmdb.org/t/p/w500/f9ZASRUfl8Jlco7rgRx3ujPR0P7.jpg', null, null),
  ('Diamonds Are Forever', 1971, true, 'PG', 'Guy Hamilton', '1971-12-17'::date, '120 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Tom Mankiewicz, Ian Fleming', 'Sean Connery, Jill St. John, Charles Gray', 'James Bond''s mission is to find out who has been smuggling diamonds, which are not re-appearing. He adopts another identity in the form of Peter Franks. He joins up with Tiffany Case, and acts as if he is smuggling the diamonds, but everyone is hungry for these diamonds. He also has to avoid Mr. Wint and Mr. Kidd, the dangerous couple who do not leave anyone in their way. Ernst Stavro Blofeld isn''t out of the question. He may have changed his looks, but is he linked with the heist? And if he is, can Bond finally defeat his ultimate enemy.', 'https://image.tmdb.org/t/p/w500/uajiHcFX5sOhYB2tBuWkmizbtuU.jpg', null, null),
  ('Friday the 13th', 2009, false, 'R', 'Marcus Nispel', '2009-02-13'::date, '97 min', 'Horror, Mystery, Thriller', 'Victor Miller, Damian Shannon, Mark Swift', 'Jared Padalecki, Amanda Righetti, Derek Mears', 'A group of young adults set up tent near the abandoned summer camp where a series of gruesome murders are said to have taken place back in 1980. The perpetrator was a grieving mother, driven insane by the drowning of her child, Jason, whom she believed was neglected by the camp counselors. As legend has it, the last survivor of the attacks beheaded the woman. But then Jason came back, and now he is a vengeful and inexorable killer, wielding crossbows, swords, axes and other sharp instruments. The legend proves horribly true, as these campers quickly discover. Six weeks later, the brother of one of those campers distributes posters of his missing sister. The police believe she took off with her boyfriend; but he knows better. The brother crosses paths with an uptight young rich guy who is having his girlfriend and friends over at his parents'' cabin. The brother ends up at the cabin himself just before his sister''s attacker sets upon them all.', 'https://image.tmdb.org/t/p/w500/88wlJ4teYlck4hJ2bnlxBrAVh0m.jpg', null, null),
  ('Daredevil', 2003, true, 'PG-13', 'Mark Steven Johnson', '2003-02-14'::date, '103 min', 'Action, Crime', 'Mark Steven Johnson', 'Ben Affleck, Jennifer Garner, Colin Farrell', 'Fate deals young orphan Matt Murdock a strange hand when he is doused with hazardous waste. The accident leaves Matt blind but also gives him a heightened "radar sense" that allows him to "see" far better than any man. Years later Murdock has grown into a man and becomes a respected criminal attorney. But after he''s done his "day job" Matt takes on a secret identity as "The Man Without Fear," Daredevil, the masked avenger that patrols the neighborhood of Hell''s Kitchen and New York City to combat the injustice that he cannot tackle in the courtroom.', 'https://image.tmdb.org/t/p/w500/oCDBwSkntYamuw8VJIxMRCtDBmi.jpg', null, null),
  ('Fantastic Four: Rise of the Silver Surfer', 2007, true, 'PG', 'Tim Story', '2007-06-15'::date, '92 min', 'Action, Adventure, Fantasy', 'Don Payne, Mark Frost, John Turman', 'Ioan Gruffudd, Jessica Alba, Chris Evans', 'Everything seems to be going great for the Fantastic Four. Reed and Sue are finally getting married, and things couldn''t seem better. However, when the mysterious Silver Surfer crashes things, they learn that they will have to deal with an old foe, and the powerful planet eating Galactus.', 'https://image.tmdb.org/t/p/w500/1rxTraSO45jbvTrCeSvJ6RmOu1b.jpg', null, null),
  ('Venom: Let there be Carnage', 2021, true, 'PG-13', 'Andy Serkis', '2021-10-01'::date, '97 min', 'Action, Sci-Fi, Thriller', 'Kelly Marcel, Tom Hardy', 'Tom Hardy, Woody Harrelson, Michelle Williams', 'Eddie Brock struggles to adjust to his new life as the host of the alien symbiote Venom, which grants him super-human abilities in order to be a lethal vigilante. Brock attempts to reignite his career by interviewing serial killer Cletus Kasady, who becomes the host of the symbiote Carnage and escapes prison after a failed execution.', 'https://image.tmdb.org/t/p/w500/pzKsRuKLFmYrW5Q0q8E8G78Tcgo.jpg', null, null),
  ('Elektra', 2005, true, 'PG-13', 'Rob Bowman', '2005-01-14'::date, '97 min', 'Action, Adventure, Crime', 'Mark Steven Johnson, Frank Miller, Zak Penn', 'Jennifer Garner, Goran Visnjic, Will Yun Lee', 'In the ultimate battle between good and evil stands a warrior who makes the choice that tips the balance. A strong, mysterious and a deadly sexy action heroine - a lethal synthesis of grace and power. Not long after recovering from seemingly mortal wounds, Elektra has severed all ties with the world, living only for her next assignment. But in an unexpected turn of events, she is forced to make a decision that can take her life in a new direction - or destroy her. Key players in Elektra''s journey are Stick, a blind martial arts master responsible for Elektra''s "resurrection," and Mark Miller and Abby Miller, a father and daughter on the run from The Hand, a powerful syndicate whose members practice the dark version of the martial art Kimagure.', 'https://image.tmdb.org/t/p/w500/Z4dAOxjAHTUZO6DJ2WVAsxzwe3.jpg', null, null),
  ('Ghost Rider', 2007, true, 'PG-13', 'Mark Steven Johnson', '2007-02-16'::date, '110 min', 'Action, Fantasy, Thriller', 'Mark Steven Johnson', 'Nicolas Cage, Eva Mendes, Sam Elliott', 'When the motorcyclist Johnny Blaze finds that his father Barton Blaze has terminal cancer, he accepts a pact with Mephistopheles, giving his soul for the health of his beloved father. But the devil deceives him, and Barton dies in a motorcycle accident during an exhibition. Johnny leaves the carnival, his town, his friends, and his girlfriend Roxanne. Many years later, Johnny Blaze becomes a famous motorcyclist, who risks his life in his shows, and he meets Roxanne again, now a television reporter. However, Mephistopheles proposes Johnny to release his contract if he become the "Ghost Rider" and defeat his evil son Blackheart, who wants to possess one thousand evil souls and transform hell on Earth.', 'https://image.tmdb.org/t/p/w500/1pyU94dAY7npDQCKuxCSyX9KthN.jpg', null, null),
  ('Hulk', 2003, true, 'PG-13', 'Ang Lee', '2003-06-20'::date, '138 min', 'Action, Sci-Fi', 'Stan Lee, Jack Kirby, James Schamus', 'Eric Bana, Jennifer Connelly, Sam Elliott', 'Bruce is an ordinary Gamma expert who one day gets blasted with radiation and somehow survives. But in the process a monster was born. Now whenever he gets angry he grows bigger and stronger until he is no longer Bruce Banner. He becomes The Hulk', 'https://image.tmdb.org/t/p/w500/UllIft2jLSBaay3zQyMV4GNdfy.jpg', null, null),
  ('Morbius', 2022, true, 'PG-13', 'Daniel Espinosa', '2022-04-01'::date, '104 min', 'Action, Adventure, Horror', 'Matt Sazama, Burk Sharpless', 'Jared Leto, Matt Smith, Adria Arjona', 'Dangerously ill with a rare blood disorder, and determined to save others suffering his same fate, Dr. Morbius attempts a desperate gamble. What at first appears to be a radical success soon reveals itself to be a remedy potentially worse than the disease.', 'https://image.tmdb.org/t/p/w500/6JjfSchsU6daXk2AKX8EEBjO3Fm.jpg', null, null),
  ('Fantastic Four', 2005, true, 'PG-13', 'Tim Story', '2005-07-08'::date, '106 min', 'Action, Adventure, Fantasy', 'Mark Frost, Michael France, Stan Lee', 'Ioan Gruffudd, Michael Chiklis, Chris Evans', 'Four astronauts have their lives changed forever, when they end up being hit by a cloud of cosmic radiation. Reed Richards now has the ability to stretch his body like elastic. Sue Storm (Alba) is now the invisible woman. Johnny Storm becomes the human touch and Ben Grimm becomes the ''Thing'', a man made out of rock. But there is one problem. The journey''s sponsor, Victor Von Doom has also been affected and with full power, is a dangerous force which needs to be stopped, before it''s too late.', 'https://image.tmdb.org/t/p/w500/5qLP3JVg8NE3zdZd48lqhx7iN5Q.jpg', null, null),
  ('Fantastic Four', 2015, true, 'PG-13', 'Josh Trank', '2015-08-07'::date, '100 min', 'Action, Adventure, Sci-Fi', 'Jeremy Slater, Simon Kinberg, Josh Trank', 'Miles Teller, Kate Mara, Michael B. Jordan', 'FANTASTIC FOUR, a contemporary re-imagining of Marvel''s original and longest-running superhero team, centers on four young outsiders who teleport to an alternate and dangerous universe, which alters their physical form in shocking ways. Their lives irrevocably upended, the team must learn to harness their daunting new abilities and work together to save Earth from a former friend turned enemy.', 'https://image.tmdb.org/t/p/w500/cDroz5qSlP8xZ6tOpeYoPkBvKyL.jpg', null, null),
  ('Live and Let Die', 1973, true, 'PG', 'Guy Hamilton', '1973-06-27'::date, '121 min', 'Action, Adventure, Thriller', 'Tom Mankiewicz, Ian Fleming', 'Roger Moore, Yaphet Kotto, Jane Seymour', 'Several British agents have been murdered and James Bond is sent to New Orleans, to investigate these mysterious deaths. Mr. Big comes to his knowledge, who is self-producing heroin. Along his journeys he meets Tee Hee who has a claw for a hand, Baron Samedi the voodoo master and Solitaire a tarot card reader. Bond must travel to New Orleans, and deep into the Bayou.', 'https://image.tmdb.org/t/p/w500/39qkrjqMZs6utwNmihVImC3ghas.jpg', null, null),
  ('The Man with the Golden Gun', 1974, true, 'PG', 'Guy Hamilton', '1974-12-20'::date, '125 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Tom Mankiewicz, Ian Fleming', 'Roger Moore, Christopher Lee, Britt Ekland', 'Scaramanga is a hitman who charges one million dollars per job. He becomes linked to the death of a scientist working on a powerful solar cell, and James Bond is called in to investigate. As he tracks down Scaramanga, he realizes that he is highly respected by the killer, but will this prove to be an advantage in the final showdown?', 'https://image.tmdb.org/t/p/w500/xVkbKwGnBVNQ122GN5bCTMyPbWz.jpg', null, null),
  ('Punisher', 2008, false, 'R', 'Lexi Alexander', '2008-12-05'::date, '103 min', 'Action, Crime, Drama', 'Nick Santora, Art Marcum, Matt Holloway', 'Ray Stevenson, Dominic West, Julie Benz', 'Frank Castle, the ex-military man whose family was killed by criminals, who became a vigilante known as the Punisher, goes after a whole mob family and gets everyone except enforcer Billy Russoti. He tracks Russoti down and chases him into a vat that is used for crushing bottles. Frank turns on the crusher hoping it would take care of him but it doesn''t. He survives but sustains very severe injuries that even with plastic surgery his face looks like a jigsaw puzzle. So he decides to adopt the name Jigsaw. Frank who killed one of Russoti''s people who unknown to him is an undercover Fed, decides to pack it in. But when he learns Russoti didn''t die and is looking for the money he entrusted to the Fed and will go looking for it at his home which means his family is in danger. So Frank tries to save them. But Russoti wants revenge on Frank so he breaks out his brother who is so crazed that he is committed to an asylum, to deal with him. And also another Fed who''s a friend of the man Frank killed wants him too.', 'https://image.tmdb.org/t/p/w500/7rmA1HwYp2GKM85BL0cVwCaosGr.jpg', null, null),
  ('Ghost Rider: Spirit of Vengeance', 2011, true, 'PG-13', 'Mark Neveldine, Brian Taylor', '2012-02-17'::date, '96 min', 'Action, Fantasy, Thriller', 'Scott M. Gimple, Seth Hoffman, David S. Goyer', 'Nicolas Cage, Ciarán Hinds, Idris Elba', 'Johnny Blaze, a man who made a deal with the Devil who called himself Mephistopheles at the time (now Roarke), is on the run trying to make sure no-one is harmed by his alter ego, The Ghost Rider. He is approached by a Monk named Moreau who tells him that he can help be him free of the Rider, but first, he needs Johnny''s help to protect a boy, whom Roarke has plans for, to help him take human form.', 'https://image.tmdb.org/t/p/w500/fUJOWsjjE8u1r4YOLYe1RLYy7bm.jpg', null, null),
  ('Madame Web', 2024, true, 'PG-13', 'S.J. Clarkson', '2024-02-14'::date, '116 min', 'Action, Adventure, Sci-Fi', 'Matt Sazama, Burk Sharpless, Claire Parker', 'Dakota Johnson, Sydney Sweeney, Isabela Merced', 'Cassandra Webb is a New York metropolis paramedic who begins to demonstrate signs of clairvoyance. Forced to challenge revelations about her past, she needs to safeguard three young women from a deadly adversary who wants them des...', 'https://image.tmdb.org/t/p/w500/rULWuutDcN5NvtiZi4FRPzRYWSh.jpg', null, null),
  ('Akira', 1988, true, 'R', 'Katsuhiro Ôtomo', '1988-07-16'::date, '124 min', 'Animation, Action, Drama', 'Katsuhiro Ôtomo, Izô Hashimoto', 'Mitsuo Iwata, Nozomu Sasaki, Mami Koyama', '2019. 31 years after being destroyed during World War 3, Tokyo (now ''Neo-Tokyo'') has been rebuilt and is a thriving metropolis. Shotaro Kaneda is the leader of a biker gang. His friend Tetsuo is injured in an accident and taken to a top-secret government facility. He develops telekinetic powers but decides to use them for evil rather than good. He has the same powers as Akira, the force that destroyed Tokyo in 1988, and now it appears that history will repeat itself.', 'https://image.tmdb.org/t/p/w500/neZ0ykEsPqxamsX6o5QNUFILQrz.jpg', null, null),
  ('Dr. No', 1962, true, 'PG', 'Terence Young', '1962-10-10'::date, '110 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Johanna Harwood, Berkely Mather', 'Sean Connery, Ursula Andress, Bernard Lee', 'James Bond 007 is Britain''s top agent, and is on an exciting mission, to solve the mysterious murder of a fellow agent. The task sends him to Jamaica, where he joins forces with Quarrel and a loyal C.I.A. Agent, Felix Leiter. While dodging tarantulas, "fire breathing dragons", and a trio of assassins, known as "the three blind mice". Bond meets up with the beautiful Honey Ryder and goes face to face with the evil Dr. No.', 'https://image.tmdb.org/t/p/w500/9zCOLJmLNst0sCPZlkW1IRoH65E.jpg', null, null),
  ('From Russia with Love', 1963, true, 'PG', 'Terence Young', '1964-05-27'::date, '115 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Johanna Harwood, Ian Fleming', 'Sean Connery, Robert Shaw, Lotte Lenya', 'James Bond 007 is on the search for a Russian decoding machine, known as "Lektor". Bond needs to find this machine, before the evil S.P.E.C.T.R.E. organization discovers it. While being romantically linked with Russian girl, Tatiana Romanova, Bond sneaks his way around Istanbul, while each S.P.E.C.T.R.E. Agent tries to pick him off, including the over powering Donald "Red" Grant and ex K.G.B. Agent Rosa Klebb, who knows all of the tricks in the book, and even possesses an incredible poison tipped shoe.', 'https://image.tmdb.org/t/p/w500/zx4V17FP8oclNvOpTgs2iCCtiYk.jpg', null, null),
  ('Goldfinger', 1964, true, 'Approved', 'Guy Hamilton', '1965-01-09'::date, '110 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Paul Dehn, Ian Fleming', 'Sean Connery, Gert Fröbe, Honor Blackman', 'James Bond (Sir Sean Connery) is back and his next mission takes him to Fort Knox, where Auric Goldfinger (Gert Fröbe) and his henchman are planning to raid Fort Knox and obliterate the world economy. To save the world once again, Bond will need to become friends with Goldfinger, dodge killer hats, and avoid Goldfinger''s personal pilot, the sexy Pussy Galore (Honor Blackman). She might not have feelings for Bond, but will 007 help her change her mind?', 'https://image.tmdb.org/t/p/w500/knGY8IxwAKXiWXsPbYbhQWqiQCK.jpg', null, null),
  ('Thunderball', 1965, true, 'Approved', 'Terence Young', '1965-12-22'::date, '130 min', 'Action, Adventure, Thriller', 'Richard Maibaum, John Hopkins, Jack Whittingham', 'Sean Connery, Claudine Auger, Adolfo Celi', 'James Bond continues on his fourth mission, with his aim to recover 2 stolen warheads. They''ve been taken by the SPECTRE organisation, and the world''s held hostage as Bond heads to Nassau, Bahamas. Here, he meets Domino and is forced into a thrilling confrontation with SPECTRE agent Emil Largo on-board his boat, the Disco Volante.', 'https://image.tmdb.org/t/p/w500/wCc4qllaTDsQN8zgGkAgQrKO6N9.jpg', null, null),
  ('Casino Royale', 1967, true, 'Approved', 'Val Guest, Ken Hughes, John Huston', '1967-04-28'::date, '131 min', 'Comedy', 'Wolf Mankowitz, John Law, Michael Sayers', 'David Niven, Peter Sellers, Ursula Andress', 'After the death of M, Sir James Bond is called back out of retirement to stop SMERSH. In order to trick SMERSH and Le Chiffre, Bond thinks up the ultimate plan. That every agent will be named James Bond. One of the Bonds, whose real name is Evelyn Tremble is sent to take on Le Chiffre in a game of baccarat, but all the Bonds get more than they can handle.', 'https://image.tmdb.org/t/p/w500/9wdw5H018bgIM8bK2HuDvh8BwOh.jpg', null, null),
  ('You Only Live Twice', 1967, true, 'PG', 'Lewis Gilbert', '1967-06-13'::date, '117 min', 'Action, Adventure, Thriller', 'Harold Jack Bloom, Roald Dahl, Ian Fleming', 'Sean Connery, Akiko Wakabayashi, Mie Hama', 'During the height of the Cold War, the United States and the Soviet Union lose one spacecraft each after they are both seemingly swallowed whole by a second unidentified spacecraft. The two superpowers are quick to blame one another for the disappearances, causing tensions to skyrocket. The United Kingdom has an alternate theory regarding the disappearances however, a theory involving Japan, and sends their number one spy, James Bond, to investigate there. With the help of the Japanese Secret Service, he uncovers a plot far more sinister than anyone could have ever imagined.', 'https://image.tmdb.org/t/p/w500/fdRbvRcEXcf2rC4ghLFZzCWPSmB.jpg', null, null),
  ('On Her Majesty''s Secret Service', 1969, true, 'PG', 'Peter R. Hunt', '1969-12-19'::date, '142 min', 'Action, Adventure, Thriller', 'Simon Raven, Richard Maibaum, Ian Fleming', 'George Lazenby, Diana Rigg, Telly Savalas', 'George Lazenby steps into the role of James Bond and is sent on his first mission. For help with Marc-Ange Draco (Gabriele Ferzetti), he must become very close friends with his daughter, Teresa "Tracy" (Dame Diana Rigg), and heads off to hunt down Ernst Stavro Blofeld (Telly Savalas) one more time. This takes him to Switzerland, where he must pose as Sir Hilary Bray to find out the secret plan of Blofeld. The facility is covered with Blofeld''s guards, as well as his henchwoman, Irma Bunt (Ilse Steppat). What does Blofeld have in mind this time? Can Bond keep up this act for much longer? Are any Bond Girls safe?', 'https://image.tmdb.org/t/p/w500/m3KfbxvqaiAvRJ6MpguA3GuLdDQ.jpg', null, null),
  ('Heretic', 2024, true, 'R', 'Scott Beck, Bryan Woods', '2024-11-08'::date, '111 min', 'Horror, Thriller', 'Scott Beck, Bryan Woods', 'Hugh Grant, Sophie Thatcher, Chloe East', 'Two young religious women are drawn into a game of cat-and-mouse in the house of a strange man.', 'https://image.tmdb.org/t/p/w500/fr96XzlzsONrQrGfdLMiwtQjott.jpg', null, null),
  ('The Spy Who Loved Me', 1977, true, 'PG', 'Lewis Gilbert', '1977-08-03'::date, '125 min', 'Action, Adventure, Thriller', 'Christopher Wood, Richard Maibaum, Ian Fleming', 'Roger Moore, Barbara Bach, Curd Jürgens', 'James Bond is back again and his new mission is to find out how a Royal Navy Polaris submarine holding sixteen nuclear warheads simply disappeared while on patrol. Bond joins Major Anya Amasova and takes on a a web-handed mastermind, known as Karl Stromberg, as well as his henchman Jaws, who has a mouthful of metal teeth. Bond must track down the location of the missing submarine before the warheads are fired.', 'https://image.tmdb.org/t/p/w500/cOm2ULaB4luYEjxlI53tW6jWLyJ.jpg', null, null),
  ('Moonraker', 1979, true, 'PG', 'Lewis Gilbert', '1979-06-29'::date, '126 min', 'Action, Adventure, Sci-Fi', 'Christopher Wood, Ian Fleming, Gerry Anderson', 'Roger Moore, Lois Chiles, Michael Lonsdale', 'James Bond is back for another mission and this time, he is blasting off into space. A spaceship travelling through space is mysteriously hijacked and Bond must work quickly to find out who was behind it all. He starts with the rockets creators, Drax Industries and the man behind the organization, Hugo Drax. On his journey he ends up meeting Dr. Holly Goodhead and encounters the metal-toothed Jaws once again.', 'https://image.tmdb.org/t/p/w500/6LrJdXNmu5uHOVALZxVYd44Lva0.jpg', null, null),
  ('For Your Eyes Only', 1981, true, 'PG', 'John Glen', '1981-06-26'::date, '127 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Michael G. Wilson, Ian Fleming', 'Roger Moore, Carole Bouquet, Topol', 'After disposing of a familiar looking face, Bond is sent to recover a communication device, known as an A.T.A.C., which went down with a British spy ship as it sunk. Bond must hurry though, as the Russians are also out for this device. On his travels, he also meets Melina Havelock, whose parents were brutally murdered. Bond also encounters Aristotle Kristatos and Milos Colombo. Each of them are accusing the other of having links with with the Russians. Bond must team up with Melina, solve who the true ally is, and find the A.T.A.C. before it''s too late.', 'https://image.tmdb.org/t/p/w500/rIbhuS2xBHDYWAriFxLABlK2LZV.jpg', null, null),
  ('Never Say Never Again', 1983, true, 'PG', 'Irvin Kershner', '1983-10-07'::date, '134 min', 'Action, Adventure, Thriller', 'Kevin McClory, Jack Whittingham, Ian Fleming', 'Sean Connery, Kim Basinger, Klaus Maria Brandauer', 'S.P.E.C.T.R.E. Agents under the command of Ernst Blofeld infiltrate a U.S. Air Force base situated in the U.K. and steal two Tomahawk cruise missiles. When N.A.T.O. is held ransom, the British re-activate their "00" Agents and send James Bond to recapture the warheads and kill Blofeld.', 'https://image.tmdb.org/t/p/w500/zhoAL4o1STGgLbLxJ9r1ijfyHC9.jpg', null, null),
  ('Octopussy', 1983, true, 'PG', 'John Glen', '1983-06-10'::date, '131 min', 'Action, Adventure, Thriller', 'George MacDonald Fraser, Richard Maibaum, Michael G. Wilson', 'Roger Moore, Maud Adams, Louis Jourdan', 'James Bond''s next mission sends him to the circus. A British Agent was murdered and found holding onto a priceless Fabergé egg. Kamal Kahn buys the egg at an auction, but Bond becomes suspicious when Kahn meets up with Russian General Orlov. Bond soon finds out that Kahn''s and Orlov''s plan is to blow-up a nuclear device on a U.S. Air Force Base. Bond teams up with a circus group, which are headed by the beautiful Octopussy, who is also close friend of Kahn.', 'https://image.tmdb.org/t/p/w500/yoosZitM9igSk3Sd0sBXIhKlAh1.jpg', null, null),
  ('A View to a Kill', 1985, true, 'PG', 'John Glen', '1985-05-24'::date, '131 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Michael G. Wilson, Ian Fleming', 'Roger Moore, Christopher Walken, Tanya Roberts', 'James Bond has one more mission. Bond returns from his travels in the U.S.S.R. with a computer chip. This chip is capable of withstanding a nuclear electromagnetic pulse that would otherwise destroy a normal chip. The chip was created by Zorin Industries, and Bond heads off to investigate its owner, Max Zorin. Zorin may only seem like an innocent man, but is really planning to set off an earthquake in San Andreas, which will wipe out all of Silicon Valley. As well as Zorin, Bond must also tackle May Day and equally menacing companion of Zorin, while dragging Stacy Sutton along for the ride.', 'https://image.tmdb.org/t/p/w500/arJF829RP9cYvh0NU70dC5TtXSa.jpg', null, null),
  ('The Living Daylights', 1987, true, 'PG', 'John Glen', '1987-07-31'::date, '130 min', 'Action, Adventure, Thriller', 'Richard Maibaum, Michael G. Wilson, Ian Fleming', 'Timothy Dalton, Maryam d''Abo, Jeroen Krabbé', 'James Bond 007''s mission is to firstly, organise the defection of a top Soviet general. When the general is re-captured, Bond heads off to find why an ally of General Koskov was sent to murder him. Bond''s mission continues to take him to Afghanistan, where he must confront an arms dealer known as Brad Whitaker. Everything eventually reveals its self to Bond.', 'https://image.tmdb.org/t/p/w500/1oRlmWX9hewpn2B44wawBjHd7dx.jpg', null, null),
  ('Licence to Kill', 1989, true, 'PG-13', 'John Glen', '1989-07-14'::date, '133 min', 'Action, Adventure, Thriller', 'Michael G. Wilson, Richard Maibaum, Ian Fleming', 'Timothy Dalton, Robert Davi, Carey Lowell', 'James Bond is on possibly his most brutal mission yet. Bond''s good friend, Felix Leiter, is left near death, by drug baron Franz Sanchez. Bond sets off on the hunt for Sanchez, but not everyone is happy. MI6 does not feel Sanchez is their problem and strips Bond of his license to kill making Bond more dangerous than ever. Bond gains the aid of one of Leiter''s friends, known as Pam Bouvier and sneaks his way into the drug factories, which Sanchez owns. Will Bond be able to keep his identity secret, or will Sanchez see Bond''s true intentions?', 'https://image.tmdb.org/t/p/w500/daIeOHe0M5HsSt2eP67ajapWgtr.jpg', null, null),
  ('GoldenEye', 1995, true, 'PG-13', 'Martin Campbell', '1995-11-17'::date, '130 min', 'Action, Adventure, Thriller', 'Ian Fleming, Michael France, Jeffrey Caine', 'Pierce Brosnan, Sean Bean, Izabella Scorupco', 'When a deadly satellite weapon system falls into the wrong hands, only Agent James Bond 007 (Pierce Brosnan) can save the world from certain disaster. Armed with his licence to kill, Bond races to Russia in search of the stolen access codes for "GoldenEye", an awesome space weapon that can fire a devastating electromagnetic pulse toward Earth. But 007 is up against an enemy who anticipates his every move: a mastermind motivated by years of simmering hatred. Bond also squares off against Xenia Onatopp (Famke Janssen), an assassin who uses pleasure as her ultimate weapon.', 'https://image.tmdb.org/t/p/w500/z0ljRnNxIO7CRBhLEO0DvLgAFPR.jpg', null, null),
  ('Tomorrow Never Dies', 1997, true, 'PG-13', 'Roger Spottiswoode', '1997-12-19'::date, '119 min', 'Action, Adventure, Thriller', 'Bruce Feirstein, Ian Fleming', 'Pierce Brosnan, Jonathan Pryce, Michelle Yeoh', 'Agent James Bond 007 (Pierce Brosnan) is on a mission which includes a media tycoon, his former lover and a Chinese Agent. Elliot Carver (Jonathan Pryce) wants to complete his global media empire, but in order for this to work, he must achieve broadcasting rights in China. Carver wants to start up World War III by starting a confrontation over British and Chinese waters. Bond gains the help of Wai Lin (Michelle Yeoh) on his quest to stop him, but how will Bond feel when he meets up with his former lover, Paris (Teri Hatcher), who is now Carver''s wife.', 'https://image.tmdb.org/t/p/w500/gZm002w7q9yLOkltxT76TWGfdZX.jpg', null, null),
  ('The World Is Not Enough', 1999, true, 'PG-13', 'Michael Apted', '1999-11-19'::date, '128 min', 'Action, Adventure, Thriller', 'Neal Purvis, Robert Wade, Bruce Feirstein', 'Pierce Brosnan, Sophie Marceau, Robert Carlyle', 'James Bond (Pierce Brosnan) is back. An oil tycoon is murdered in MI6, and Bond is sent to protect his daughter. Renard (Robert Carlyle), who has a bullet lodged in his brain from a previous Agent, is secretly planning the destruction of a pipeline. Bond gains a hand from research scientist Dr. Christmas Jones (Denise Richards), who witnesses the action which happens when Bond meets up with Renard, but Bond becomes suspicious about Elektra King (Sophie Marceau), especially when Bond''s boss, M (Dame Judi Dench) goes missing. Bond must work quickly to prevent Renard from destroying Europe.', 'https://image.tmdb.org/t/p/w500/wCb2msgoZPK01WIqry24M4xsM73.jpg', null, null),
  ('Wolfs', 2024, true, 'R', 'Jon Watts', '2024-09-27'::date, '108 min', 'Crime, Thriller', 'Jon Watts', 'George Clooney, Brad Pitt, Amy Ryan', 'Two rival fixers cross paths when they''re both called in to help cover up a prominent New York official''s misstep. Over one explosive night, they''ll have to set aside their petty grievances and their egos to finish the job.', 'https://image.tmdb.org/t/p/w500/vOX1Zng472PC2KnS0B9nRfM8aaZ.jpg', null, null),
  ('Die Another Day', 2002, true, 'PG-13', 'Lee Tamahori', '2002-11-22'::date, '133 min', 'Action, Adventure, Thriller', 'Ian Fleming, Neal Purvis, Robert Wade', 'Pierce Brosnan, Halle Berry, Rosamund Pike', 'Pierce Brosnan gives one last mission as James Bond 007. Starting off in North Korea, Bond is betrayed and captured. Fourteen months later, Bond is set free, but traded for Zao (Rick Yune) who was captured by MI6. When back in his world, Bond sets off to track down Zao. Bond gets caught up in yet another scheme which sends him to millionaire Gustav Graves (Toby Stephens). Another MI6 Agent known as Miranda Frost (Rosamund Pike) is also posing as a friend of Graves. Bond is invited to a presentation held by Graves about a satellite found in space which can project a huge laser beam. Bond must stop this madman with a fellow American Agent, known as Jinx Johnson (Halle Berry). While Bond tries to stop Graves and Zao, will he finally reveal who betrayed him?', 'https://image.tmdb.org/t/p/w500/bZmGqOhMhaLn8AoFMvFDct4tbrL.jpg', null, null),
  ('Casino Royale', 2006, true, 'PG-13', 'Martin Campbell', '2006-11-17'::date, '144 min', 'Action, Adventure, Thriller', 'Neal Purvis, Robert Wade, Paul Haggis', 'Daniel Craig, Eva Green, Judi Dench', 'James Bond (Daniel Craig) goes on his first mission as a 00. Le Chiffre (Mads Mikkelsen) is a banker to the world''s terrorists. He is participating in a poker game at Montenegro, where he must win back his money, in order to stay safe amongst the terrorist market. The boss of MI6, known simply as "M" (Dame Judi Dench) sends Bond, along with Vesper Lynd Eva Green) to attend this game and prevent Le Chiffre from winning. Bond, using help from Felix Leiter (Jeffrey Wright), Rene Mathis (Giancarlo Giannini), and having Vesper pose as his partner, enters the most important poker game in his already dangerous career. But if Bond defeats Le Chiffre, will he and Vesper Lynd remain safe?', 'https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg', null, null),
  ('Quantum of Solace', 2008, true, 'PG-13', 'Marc Forster', '2008-11-14'::date, '106 min', 'Action, Adventure, Mystery', 'Paul Haggis, Neal Purvis, Robert Wade', 'Daniel Craig, Olga Kurylenko, Mathieu Amalric', 'Is there solace in revenge? James Bond (Daniel Craig) and M (Dame Judi Dench) sniff a shadowy international network of power and corruption reaping billions. As Bond pursues the agents of an assassination attempt on M, all roads lead to Dominic Greene (Mathieu Amalric), a world-renowned developer of green technology. Greene, a nasty piece of work, is intent on securing a barren area of Bolivia in exchange for helping a strongman stage a coup there. The C.I.A. looks the other way, and only Bond, with help from a retired spy and a mysterious beauty, stands in Greene''s way. M wonders if she can trust Bond, or if vengeance possesses him. Can anyone drawn to Bond live to tell the tale?', 'https://image.tmdb.org/t/p/w500/e3DXXLJHGqMx9yYpXsql1XNljmM.jpg', null, null),
  ('Skyfall', 2012, true, 'PG-13', 'Sam Mendes', '2012-11-09'::date, '143 min', 'Action, Adventure, Thriller', 'Neal Purvis, Robert Wade, John Logan', 'Daniel Craig, Javier Bardem, Naomie Harris', 'When James Bond''s (Daniel Craig''s) latest assignment goes gravely wrong and Agents around the world are exposed, MI6 is attacked, forcing (M Dame Judi Dench) to relocate the agency. These events cause her authority and position to be challenged by Gareth Mallory (Ralph Fiennes), the new Chairman of the Intelligence and Security Committee. With MI6 now compromised from both inside and out, M is left with one ally she can trust: Bond. 007 takes to the shadows, aided only by field agent, Miss Eve Moneypenny (Naomie Harris), following a trail to the mysterious Tiago Rodriguez, a.k.a. Raoul Silva (Javier Bardem), whose lethal and hidden motives have yet to reveal themselves.', 'https://image.tmdb.org/t/p/w500/d0IVecFQvsGdSbnMAHqiYsNYaJT.jpg', null, null),
  ('No Time to Die', 2021, true, 'PG-13', 'Cary Joji Fukunaga', '2021-10-08'::date, '163 min', 'Action, Adventure, Thriller', 'Neal Purvis, Robert Wade, Cary Joji Fukunaga', 'Daniel Craig, Ana de Armas, Rami Malek', 'Bond has left active service and is enjoying a tranquil life in Jamaica. His peace is short-lived when his old friend Felix Leiter from the CIA turns up asking for help. The mission to rescue a kidnapped scientist turns out to be far more treacherous than expected, leading Bond onto the trail of a mysterious villain armed with dangerous new technology.', 'https://image.tmdb.org/t/p/w500/iUgygt3fscRoKWCV1d0C7FbM9TP.jpg', null, null),
  ('Joker: Folie a Deux', 2024, true, 'R', 'Todd Phillips', '2024-10-04'::date, '138 min', 'Crime, Drama, Musical', 'Scott Silver, Todd Phillips, Bob Kane', 'Joaquin Phoenix, Lady Gaga, Brendan Gleeson', 'Struggling with his dual identity, failed comedian Arthur Fleck meets the love of his life, Harley Quinn, while incarcerated at Arkham State Hospital.', 'https://image.tmdb.org/t/p/w500/if8QiqCI7WAGImKcJCfzp6VTyKA.jpg', null, null),
  ('Futurama: Bender''s Big Score', 2007, true, 'Not Rated', 'Dwayne Carey-Hill', '2007-11-27'::date, '88 min', 'Animation, Comedy, Romance, Sci-Fi', 'Matt Groening (created by), Matt Groening (developed by), David X. Cohen (developed by), Ken Keeler (teleplay by), Ken Keeler (story by), David X. Cohen (story by)', 'Billy West, Katey Sagal, John DiMaggio, Tress MacNeille', 'Planet Express sees a hostile takeover and Bender falls into the hands of criminals where he is used to fulfill their schemes.', 'https://image.tmdb.org/t/p/w500/bmVE90IHvx4uXQgtbRtu4RyMWpt.jpg', null, null),
  ('Futurama: The Beast with a Billion Backs', 2008, true, 'Not Rated', 'Peter Avanzino', '2008-06-24'::date, '90 min', 'Animation, Comedy, Romance, Sci-Fi', 'Matt Groening (created by), Matt Groening (developed by), David X. Cohen (developed by), Eric Kaplan (teleplay by), Eric Kaplan (story by), David X. Cohen (story by)', 'Billy West, Katey Sagal, John DiMaggio, Tress MacNeille', 'The Planet Express crew must work to fix rips between their universe and another inhabited by a planet-sized, tentacle alien which soon takes over the Earth and uses it''s ability to control Fry to command an entire religion which takes over and convinces the inhabitants of Earth to abandon the Earth to live in a pseudo-heaven, leaving the robots of the world to inherit the planet.', 'https://image.tmdb.org/t/p/w500/2BW6JAW4wo7t5wD3WVfoijzosvt.jpg', null, null),
  ('Futurama: Bender''s Game', 2008, true, 'Not Rated', 'Dwayne Carey-Hill', '2008-11-04'::date, '88 min', 'Animation, Action, Adventure, Comedy, Fantasy, Sci-Fi', 'Matt Groening (created by), Matt Groening (developed by), David X. Cohen (developed by), Eric Horsted (teleplay by), Michael Rowe (teleplay by), Eric Kaplan (teleplay by), David X. Cohen (teleplay by), Patric M. Verrone (teleplay by), Eric Horsted (story by), David X. Cohen (story by)', 'Billy West, Katey Sagal, John DiMaggio, Tress MacNeille', 'The Planet Express crew get trapped in a fantasy world.', 'https://image.tmdb.org/t/p/w500/bx8OVOBn5WP9TJJuOpRzyMCdzzb.jpg', null, null),
  ('Futurama: Into the Wild Green Yonder', 2009, true, 'Not Rated', 'Peter Avanzino', '2009-02-24'::date, '89 min', 'Animation, Comedy, Sci-Fi', 'Matt Groening (created by), Matt Groening (developed by), David X. Cohen (developed by), Ken Keeler (teleplay by), Ken Keeler (story by), David X. Cohen (story by), Ken Keeler', 'Billy West, Katey Sagal, John DiMaggio, Tress MacNeille', 'Dark forces older than time itself are on the attack, hell-bent on stopping the dawn of a wondrous new green age. Don''t you hate when that happens? Even more shocking: Bender''s in love with a married fembot, and Leela''s on the run from the law - Zapp Brannigan''s law! Fry is the last hope of the universe, recruited for an ultra-top-secret mission. Could this be the end of the Planet Express crew forever? Say it ain''t so, meatbag!', 'https://image.tmdb.org/t/p/w500/oL6SymcxQE6TN9KrrbdyhlulnEG.jpg', null, null),
  ('Dogma', 1999, true, 'R', 'Kevin Smith', '1999-11-12'::date, '130 min', 'Adventure, Comedy, Drama', 'Kevin Smith', 'Ben Affleck, Matt Damon, Linda Fiorentino', 'An abortion clinic worker with a special heritage is enlisted to prevent two angels from reentering Heaven and thus undoing the fabric of the universe. Along the way, she is aided by two prophets, Jay and Silent Bob. With the help of Rufus, the 13th Apostle, they must stop those who stand in their way and prevent the angels from entering Heaven.', 'https://image.tmdb.org/t/p/w500/dXXhveI3VO51C3VNzNrxYl2xbST.jpg', null, null),
  ('Terrifier 3', 2024, true, 'Not Rated', 'Damien Leone', '2024-10-11'::date, '125 min', 'Horror', 'Damien Leone', 'Lauren LaVera, David Howard Thornton, Antonella Rose', 'Art the Clown is set to unleash chaos on the unsuspecting residents of Miles County as they peacefully drift off to sleep on Christmas Eve.', 'https://image.tmdb.org/t/p/w500/ju10W5gl3PPK3b7TjEmVOZap51I.jpg', null, null),
  ('A Quiet Place: Part II', 2020, true, 'PG-13', 'John Krasinski', '2021-05-28'::date, '97 min', 'Drama, Horror, Sci-Fi', 'John Krasinski, Bryan Woods, Scott Beck', 'Emily Blunt, Millicent Simmonds, Cillian Murphy', 'With the newly acquired knowledge of the seemingly invulnerable creatures'' weakness, grief-stricken Evelyn Abbott finds herself on her own, with two young teens, a defenceless newborn son, and with no place to hide. Now, 474 days after the all-out alien attack in A Quiet Place (2018), the Abbotts summon up every last ounce of courage to leave their now-burned-to-the-ground farm and embark on a peril-laden quest to find civilization. With this in mind, determined to expand beyond the boundaries, the resilient survivors have no other choice but to venture into eerily quiet, uncharted hostile territory, hoping for a miracle. But, this time, the enemy is everywhere.', 'https://image.tmdb.org/t/p/w500/4q2hz2m8hubgvijz8Ez0T2Os2Yv.jpg', null, null),
  ('A Quiet Place Day One', 2024, true, 'PG-13', 'Michael Sarnoski', '2024-06-28'::date, '99 min', 'Drama, Horror, Sci-Fi', 'Michael Sarnoski, John Krasinski, Bryan Woods', 'Lupita Nyong''o, Joseph Quinn, Alex Wolff', 'A young woman named Sam finds herself trapped in New York City during the early stages of an invasion by alien creatures with ultra-sensitive hearing.', 'https://image.tmdb.org/t/p/w500/hU42CRk14JuPEdqZG3AWmagiPAP.jpg', null, null),
  ('Carry-On', 2024, true, 'PG-13', 'Jaume Collet-Serra', '2024-12-13'::date, '119 min', 'Action, Crime, Drama', 'T.J. Fixman', 'Taron Egerton, Jason Bateman, Sofia Carson', 'A mysterious traveler blackmails a young TSA agent into letting a dangerous package slip through security and onto a Christmas Eve flight.', 'https://image.tmdb.org/t/p/w500/sjMN7DRi4sGiledsmllEw5HJjPy.jpg', null, null),
  ('Fantastic Beasts: The Crimes of Grindelwald', 2018, true, 'PG-13', 'David Yates', '2018-11-16'::date, '134 min', 'Adventure, Family, Fantasy', 'J.K. Rowling', 'Eddie Redmayne, Katherine Waterston, Dan Fogler', 'In an effort to thwart Grindelwald''s plans of raising pure-blood wizards to rule over all non-magical beings, Albus Dumbledore enlists his former student Newt Scamander, who agrees to help, though he''s unaware of the dangers that lie ahead. Lines are drawn as love and loyalty are tested, even among the truest friends and family, in an increasingly divided wizarding world.', 'https://image.tmdb.org/t/p/w500/fMMrl8fD9gRCFJvsx0SuFwkEOop.jpg', 'Wizarding World', null),
  ('Fantastic Beasts: The Secrets of Dumbledore', 2022, true, 'PG-13', 'David Yates', '2022-04-15'::date, '142 min', 'Adventure, Fantasy', 'J.K. Rowling, Steve Kloves', 'Eddie Redmayne, Jude Law, Ezra Miller', 'Professor Albus Dumbledore knows the powerful Dark wizard Gellert Grindelwald is moving to seize control of the wizarding world. Unable to stop him alone, he entrusts Magizoologist Newt Scamander to lead an intrepid team of wizards, witches and one brave Muggle baker on a dangerous mission, where they encounter old and new beasts and clash with Grindelwald''s growing legion of followers. But with the stakes so high, how long can Dumbledore remain on the sidelines? (Warner Bros media release)', 'https://image.tmdb.org/t/p/w500/3c5GNLB4yRSLBby0trHoA1DSQxQ.jpg', 'Wizarding World', null),
  ('28 Days Later', 2002, true, 'R', 'Danny Boyle', '2003-06-27'::date, '113 min', 'Drama, Horror, Sci-Fi', 'Alex Garland', 'Cillian Murphy, Naomie Harris, Christopher Eccleston', 'Animal activists invade a laboratory with the intention of releasing chimpanzees that are undergoing experimentation, infected by a virus -a virus that causes rage. The naive activists ignore the pleas of a scientist to keep the cages locked, with disastrous results. Twenty-eight days later, our protagonist, Jim, wakes up from a coma, alone, in an abandoned hospital. He begins to seek out anyone else to find London is deserted, apparently without a living soul. After finding a church, which had become inhabited by zombie like humans intent on his demise, he runs for his life. Selena and Mark rescue him from the horde and bring him up to date on the mass carnage and horror as all of London tore itself apart. This is a tale of survival and ultimately, heroics, with nice subtext about mankind''s savage nature.', 'https://image.tmdb.org/t/p/w500/sQckQRt17VaWbo39GIu0TMOiszq.jpg', null, 'Alex Garland'),
  ('28 Weeks Later', 2007, true, 'R', 'Juan Carlos Fresnadillo', '2007-05-11'::date, '100 min', 'Horror, Sci-Fi', 'Rowan Joffe, Juan Carlos Fresnadillo, Enrique López Lavigne', 'Jeremy Renner, Rose Byrne, Robert Carlyle', 'Six challenging months after the horrific events of 28 Days Later... (2002), when the unstoppable Rage Virus decimated the entire city of London, the U.S. Army has restored order and is repopulating the quarantined city. However, after the first wave of returning refugees, an unsuspecting carrier of the highly transmittable pathogen enters the dead city, and unknowingly re-ignites the spread of the deadly infection. Indeed, the virus is not yet dead, and this time, it is more dangerous than ever. Will the nightmare begin again?', 'https://image.tmdb.org/t/p/w500/oix0aNv1lvW3nUGspUyvSIBlpbs.jpg', null, null),
  ('28 Years Later', 2025, false, 'R', 'Danny Boyle', '2025-06-20'::date, '115 min', 'Horror, Thriller', 'Danny Boyle, Alex Garland', 'Jack O''Connell, Aaron Taylor-Johnson, Ralph Fiennes', 'A group of survivors of the rage virus lives on a small island. When one of the group leaves the island on a mission into the mainland, he discovers secrets, wonders, and horrors that have mutated not only the infected but other s...', 'https://image.tmdb.org/t/p/w500/mIg1qCkVxnAlM2TK3RUF0tdEXlE.jpg', null, 'Alex Garland'),
  ('Challengers', 2024, true, 'R', 'Luca Guadagnino', '2024-04-26'::date, '131 min', 'Comedy, Drama, Romance', 'Justin Kuritzkes', 'Mike Faist, Josh O''Connor, Zendaya', 'Tashi, a former tennis prodigy turned coach, transformed her husband into a champion. But to overcome a recent losing streak and redeem himself, he''ll need to face off against his former best friend and Tashi''s ex-boyfriend.', 'https://image.tmdb.org/t/p/w500/H6vke7zGiuLsz4v4RPeReb9rsv.jpg', null, null),
  ('Beverly Hills Cop', 1984, true, 'R', 'Martin Brest', '1984-12-05'::date, '105 min', 'Action, Comedy, Crime', 'Daniel Petrie Jr., Danilo Bach', 'Eddie Murphy, Judge Reinhold, John Ashton', 'After the murder of his childhood friend, the slick Detroit detective, Axel Foley, heads to sunny Beverly Hills, on a one-man mission to ferret out the killer and bring him to justice. Before long, Axel and his unorthodox methods unearth the lucrative drug operation of the powerful local crime kingpin, Victor Maitland; however, Foley, too, will find himself in deep trouble, as Lieutenant Andrew Bogomil wants him out of town. Now, Axel will have to team up with Detectives, John Taggart, and Billy Rosewood, to shed light on the thick conspiracy, and finish what he has started. Will Foley''s total disregard for proper procedure bear fruit?', 'https://image.tmdb.org/t/p/w500/eBJEvKkhQ0tUt1dBAcTEYW6kCle.jpg', null, null),
  ('Beverly Hills Cop II', 1987, true, 'R', 'Tony Scott', '1987-05-20'::date, '103 min', 'Action, Comedy, Crime', 'Danilo Bach, Daniel Petrie Jr., Eddie Murphy', 'Eddie Murphy, Judge Reinhold, Jürgen Prochnow', 'Three years after the events in Beverly Hills Cop (1984), the street-wise Detroit detective, Axel Foley, invades the posh city once more, after the assassination attempt on Captain Andrew Bogomil. Against the backdrop of a seemingly endless string of violent and well-orchestrated smash-and-grab robberies known as the "Alphabet Crimes", Detectives Billy Rosewood and John Taggart struggle to solve the case; nevertheless, in vain. Now, a lethally beautiful hitwoman linked to an international arms trafficking ring is the mysterious and elusive prime suspect. Can the brazen and sassy Axel and his partners solve this thorny case, too?', 'https://image.tmdb.org/t/p/w500/egDakU8O5yUwpUJP9IMAUVtIDll.jpg', null, null),
  ('Beverly Hills Cop III', 1994, true, 'R', 'John Landis', '1994-05-25'::date, '104 min', 'Action, Comedy, Crime', 'Danilo Bach, Daniel Petrie Jr., Steven E. de Souza', 'Eddie Murphy, Jon Tenney, Joey Travolta', 'After a botched attempt to make a bust in a Detroit chop shop, the effectively unorthodox police officer, Axel Foley, once more, finds himself in sunny Beverly Hills, hot on the trail of an elusive gang of cold-blooded killers. There--with the aid of old friends, Serge; the recently promoted, Billy Rosewood, and his partner, Jon Flint--Axel sniffs out the criminals'' hideout which is nestled right under everyone''s nose: in Southern California''s bustling theme park, WonderWorld. Now, all that''s left to do is to convince the people and the police that the park''s impeccable chief of security, Ellis DeWald, is a ruthless villain; and that the immaculate amusement park is, in reality, a graceful and impenetrable facade for a sinister operation. How hard can it be?', 'https://image.tmdb.org/t/p/w500/7vIpCkgGEfk5LZwm78nMxswLJRH.jpg', null, null),
  ('Dredd', 2012, true, 'R', 'Pete Travis', '2012-09-21'::date, '95 min', 'Action, Crime, Sci-Fi', 'John Wagner, Carlos Ezquerra, Alex Garland', 'Karl Urban, Olivia Thirlby, Lena Headey', 'The future America is an irradiated waste land. On its East Coast, running from Boston to Washington DC, lies Mega City One - a vast, violent metropolis where criminals rule the chaotic streets. The only force of order lies with the urban cops called "Judges" who possess the combined powers of judge, jury and instant executioner. Known and feared throughout the city, Dredd is the ultimate Judge, challenged with ridding the city of its latest scourge - a dangerous drug epidemic that has users of "Slo-Mo" experiencing reality at a fraction of its normal speed. During a routine day on the job, Dredd is assigned to train and evaluate Cassandra Anderson, a rookie with powerful psychic abilities thanks to a genetic mutation. A heinous crime calls them to a neighborhood where fellow Judges rarely dare to venture - a 200 storey vertical slum controlled by prostitute turned drug lord Ma-Ma and her ruthless clan. When they capture one of the clan''s inner circle, Ma-Ma overtakes the compound''s control center and wages a dirty, vicious war against the Judges that proves she will stop at nothing to protect her empire. With the body count climbing and no way out, Dredd and Anderson must confront the odds and engage in the relentless battle for their survival.', 'https://image.tmdb.org/t/p/w500/wLx65gtGVnUFCxceHWGszcruCZj.jpg', null, 'Alex Garland'),
  ('Men', 2022, true, 'R', 'Alex Garland', '2022-05-20'::date, '100 min', 'Drama, Fantasy, Horror', 'Alex Garland', 'Jessie Buckley, Rory Kinnear, Paapa Essiedu', 'A young woman goes on a solo vacation to the English countryside following the death of her ex-husband.', 'https://image.tmdb.org/t/p/w500/jo1Kv3P3UgDVk7JnUFr2Cl8WWUM.jpg', null, 'Alex Garland'),
  ('Never Let Me Go', 2010, true, 'R', 'Mark Romanek', '2010-10-15'::date, '103 min', 'Drama, Romance', 'Alex Garland, Kazuo Ishiguro', 'Keira Knightley, Carey Mulligan, Andrew Garfield', 'As children, Ruth, Kathy and Tommy spend their childhood at a seemingly idyllic English boarding school. As they grow into young adults, they find that they have to come to terms with the strength of the love they feel for each other, while preparing themselves for the haunting reality that awaits them.', 'https://image.tmdb.org/t/p/w500/8F0r5ng9Fp60OhzQfR5v33fppq.jpg', null, 'Alex Garland'),
  ('The Menu', 2022, false, 'R', 'Mark Mylod', '2022-11-18'::date, '107 min', 'Comedy, Horror, Thriller', 'Seth Reiss, Will Tracy', 'Ralph Fiennes, Anya Taylor-Joy, Nicholas Hoult', 'A young couple travels to a remote island to eat at an exclusive restaurant where the chef has prepared a lavish menu, with some shocking surprises.', 'https://image.tmdb.org/t/p/w500/fPtUgMcLIboqlTlPrq0bQpKK8eq.jpg', null, null),
  ('Glass Onion', 2022, true, 'PG-13', 'Rian Johnson', '2022-12-23'::date, '139 min', 'Comedy, Crime, Drama', 'Rian Johnson', 'Daniel Craig, Edward Norton, Kate Hudson', 'Tech billionaire Miles Bron invites his friends for a getaway on his private Greek island. When someone turns up dead, Detective Benoit Blanc is put on the case.', 'https://image.tmdb.org/t/p/w500/vDGr1YdrlfbU9wxTOdpf3zChmv9.jpg', null, null),
  ('8mm', 1999, true, 'R', 'Joel Schumacher', '1999-02-26'::date, '123 min', 'Crime, Drama, Mystery', 'Andrew Kevin Walker', 'Nicolas Cage, Joaquin Phoenix, James Gandolfini', 'A small, seemingly innocuous plastic reel of film leads surveillance specialist Tom Welles down an increasingly dark and frightening path. With the help of the streetwise Max, Welles relentlessly follows a bizarre trail of evidence to determine the fate of a complete stranger. As his work turns into obsession, he drifts farther and farther away from his wife, family and simple life as a small-town private eye.', 'https://image.tmdb.org/t/p/w500/mhr9xRpjOBqlBjgDwtiOx6FsLvV.jpg', null, null),
  ('Wicked', 2024, false, 'PG', 'Jon M. Chu', '2024-11-22'::date, '160 min', 'Fantasy, Musical, Romance', 'Winnie Holzman, Dana Fox, Gregory Maguire', 'Cynthia Erivo, Ariana Grande, Jeff Goldblum', 'A vivid reimagining of the classic The Wizard of Oz, Wicked spotlights the untold stories of Oz''s most famous (or infamous) characters, namely the Wicked Witch of the West and her unlikely friend, Glinda the Good Witch. The show follows green-skinned star Elphaba from birth to college and through the life-changing events which eventually label her "wicked," introducing spoiled rich girl Glinda, local prince and heartthrob Fiyero and even the Wizard of Oz himself, a troubled man very unlike the one you may remember. As Elphaba, a passionate political activist if there ever was one, fights injustice and seeks to undo the mistakes of the past, dark secrets and personal tragedies shape the history of Oz, paying homage to the classic Wizard of Oz story while simultaneously changing fans'' understanding of it forever. A cautionary tale about love, friendship and trust, Wicked effortlessly reveals that there are indeed two sides to every story.', 'https://image.tmdb.org/t/p/w500/xDGbZ0JJ3mYaGKy4Nzd9Kph6M9L.jpg', null, null),
  ('Gladiator', 2000, true, 'R', 'Ridley Scott', '2000-05-05'::date, '155 min', 'Action, Adventure, Drama', 'David Franzoni, John Logan, William Nicholson', 'Russell Crowe, Joaquin Phoenix, Connie Nielsen', 'Maximus is a powerful Roman general, loved by the people and the aging Emperor, Marcus Aurelius. Before his death, the Emperor chooses Maximus to be his heir over his own son, Commodus, and a power struggle leaves Maximus and his family condemned to death. The powerful general is unable to save his family, and his loss of will allows him to get captured and put into the Gladiator games until he dies. The only desire that fuels him now is the chance to rise to the top so that he will be able to look into the eyes of the man who will feel his revenge.', 'https://image.tmdb.org/t/p/w500/ty8TGRuvJLPUmAR1H1nRIsgwvim.jpg', null, null),
  ('Gladiator II', 2024, true, 'R', 'Ridley Scott', '2024-11-22'::date, '148 min', 'Action, Adventure, Drama', 'David Franzoni, Peter Craig, David Scarpa', 'Paul Mescal, Denzel Washington, Pedro Pascal', 'After his home is conquered by the tyrannical emperors who now lead Rome, Lucius is forced to enter the Colosseum and must look to his past to find strength to return the glory of Rome to its people.', 'https://image.tmdb.org/t/p/w500/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg', null, null),
  ('Bodies Bodies Bodies', 2022, true, 'R', 'Halina Reijn', '2022-08-12'::date, '94 min', 'Comedy, Horror, Mystery', 'Sarah DeLappe, Kristen Roupenian', 'Amandla Stenberg, Maria Bakalova, Myha''la', 'When a group of rich 20-somethings plan a hurricane party at a remote family mansion, a party game turns deadly.', 'https://image.tmdb.org/t/p/w500/hSuTjDmqRdy7Dii8ymnF2WILTeP.jpg', null, null),
  ('Moana 2', 2024, true, 'PG', 'David G. Derrick Jr., Jason Hand, Dana Ledoux Miller', '2024-11-27'::date, '100 min', 'Animation, Adventure, Comedy', 'Jared Bush, Dana Ledoux Miller, Bek Smith', 'Auli''i Cravalho, Dwayne Johnson, Hualalai Chung', 'After receiving an unexpected call from her wayfinding ancestors, Moana must journey to the far seas of Oceania and into dangerous, long-lost waters for an adventure unlike anything she''s ever faced.', 'https://image.tmdb.org/t/p/w500/aLVkiINlIeCkcZIzb7XHzPYgO6L.jpg', null, null),
  ('Transformers: Revenge of the Fallen', 2009, true, 'PG-13', 'Michael Bay', '2009-06-24'::date, '149 min', 'Action, Adventure, Sci-Fi', 'Ehren Kruger, Roberto Orci, Alex Kurtzman', 'Shia LaBeouf, Megan Fox, Josh Duhamel', 'A youth chooses manhood. The week Sam Witwicky starts college, the Decepticons make trouble in Shanghai. A presidential envoy believes it''s because the Autobots are around; he wants them gone. He''s wrong: the Decepticons need access to Sam''s mind to see some glyphs imprinted there that will lead them to a fragile object that, when inserted in an alien machine hidden in Egypt for centuries, will give them the power to blow out the sun. Sam, his girlfriend Mikaela Banes, and Sam''s parents are in danger. Optimus Prime and Bumblebee are Sam''s principal protectors. If one of them goes down, what becomes of Sam?', 'https://image.tmdb.org/t/p/w500/pLBb0whOzVDtJvyD4DPeQyQNOqp.jpg', null, null),
  ('Transformers: Dark of the Moon', 2011, true, 'PG-13', 'Michael Bay', '2011-06-29'::date, '154 min', 'Action, Adventure, Sci-Fi', 'Ehren Kruger', 'Shia LaBeouf, Rosie Huntington-Whiteley, Tyrese Gibson', 'Autobots Bumblebee, Ratchet, Ironhide, Mirage (aka Dino), Wheeljack (aka Que) and Sideswipe led by Optimus Prime, are back in action taking on the evil Decepticons, who are eager to avenge their recent defeat. The Autobots and Decepticons become involved in a perilous space race between the United States and Russia to reach a hidden Cybertronian spacecraft on the moon and learn its secrets, and once again Sam Witwicky has to go to the aid of his robot friends. The new villain Shockwave is on the scene while the Autobots and Decepticons continue to battle it out on Earth.', 'https://image.tmdb.org/t/p/w500/28YlCLrFhONteYSs9hKjD1Km0Cj.jpg', null, null),
  ('Transformers: Age of Extinction', 2014, true, 'PG-13', 'Michael Bay', '2014-06-27'::date, '165 min', 'Action, Adventure, Sci-Fi', 'Ehren Kruger', 'Mark Wahlberg, Nicola Peltz Beckham, Jack Reynor', 'After the battle between the Autobots and Decepticons that leveled Chicago, humanity thinks that all alien robots are a threat. So Harold Attinger, a CIA agent, establishes a unit whose sole purpose is to hunt down all of them. But it turns out that they are aided by another alien robot who is searching for Optimus Prime. Cade Yeager, a "robotics expert", buys an old truck and upon examining it, he thinks it''s a Transformer. When he powers it up, he discovers it''s Optimus Prime. Later, men from the unit show up looking for Optimus. He helps Yeager and his daughter Tessa escape but are pursued by the hunter. They escape and Yeager learns from technology he took from the men that a technology magnate and defense contractor named Joshua Joyce is part of what''s going on, so they go to find out what''s going on.', 'https://image.tmdb.org/t/p/w500/jyzrfx2WaeY60kYZpPYepSjGz4S.jpg', null, null),
  ('Transformers: The Last Knight', 2017, true, 'PG-13', 'Michael Bay', '2017-06-21'::date, '154 min', 'Action, Adventure, Sci-Fi', 'Art Marcum, Matt Holloway, Ken Nolan', 'Mark Wahlberg, Anthony Hopkins, Josh Duhamel', 'Optimus Prime finds his dead home planet, Cybertron, in which he comes to find he was responsible for its destruction. He finds a way to bring Cybertron back to life, but in order to do so, Optimus needs to find an artifact that is on Earth.', 'https://image.tmdb.org/t/p/w500/s5HQf2Gb3lIO2cRcFwNL9sn1o1o.jpg', null, null),
  ('Transformers: Rise of the Beasts', 2023, true, 'PG-13', 'Steven Caple Jr.', '2023-06-09'::date, '127 min', 'Action, Adventure, Sci-Fi', 'Joby Harold, Darnell Metayer, Josh Peters', 'Anthony Ramos, Dominique Fishback, Luna Lauren Velez', 'Set in the 1990s, Transformers: Rise of the Beasts will take audiences on an action-packed, globetrotting adventure as the Maximals, Predacons, and Terrorcons join the battle between the Autobots and Decepticons on Earth. Noah, a sharp young guy from Brooklyn, and Elena, an ambitious, talented artifact researcher, are swept up in the conflict as Optimus Prime and the Autobots face a terrifying new nemesis bent on their destruction named Scourge.', 'https://image.tmdb.org/t/p/w500/gPbM0MK8CP8A174rmUwGsADNYKD.jpg', null, null),
  ('Bumblebee', 2018, true, 'PG-13', 'Travis Knight', '2018-12-21'::date, '114 min', 'Action, Adventure, Sci-Fi', 'Christina Hodson', 'Hailee Steinfeld, Jorge Lendeborg Jr., John Cena', 'On Cybertron, the Autobots, led by Optimus Prime, are on the verge of losing the Great Cybertronian War to their enemies, the Decepticons, had begin making preparations to leave the planet. The Decepticons led by Shockwave, Soundwave and Starscream ambush them during the evacuation, and Optimus sends a young scout, B-127, to Earth in order to set up a base of operations where the Autobots can regroup. B-127 reaches Earth alone in 1987, crash-landing in California and disrupting a training exercise being conducted by Sector 7, a secret government agency that monitors extraterrestrial activity on Earth. Sector 7 agent Colonel Jack Burns presumes B-127 to be a hostile invader and attacks, driving B-127 into the forest, where he is then ambushed by the Decepticon Blitzwing. When B-127 refuses to reveal Optimus'' whereabouts, Blitzwing spitefully tears out his voice-box and damages his memory core. B-127 manages to destroy Blitzwing before collapsing from his wounds. Before entering stasis, B-127 scans and transforms into a yellow 1967 Volkswagen Beetle.', 'https://image.tmdb.org/t/p/w500/fw02ONlDhrYjTSZV8XO6hhU3ds3.jpg', null, null),
  ('Nosferatu', 2024, true, 'R', 'Robert Eggers', '2024-12-25'::date, '132 min', 'Fantasy, Horror, Mystery', 'Robert Eggers, Henrik Galeen, Bram Stoker', 'Lily-Rose Depp, Nicholas Hoult, Bill Skarsgård', 'A gothic tale of obsession between a haunted young woman and the terrifying vampire infatuated with her, causing untold horror in its wake.', 'https://image.tmdb.org/t/p/w500/5qGIxdEO841C0tdY8vOdLoRVrr0.jpg', null, null),
  ('Anora', 2024, true, 'R', 'Sean Baker', '2024-11-08'::date, '139 min', 'Comedy, Drama, Romance', 'Sean Baker', 'Mikey Madison, Paul Weissman, Yura Borisov', 'A young escort from Brooklyn meets and impulsively marries the son of a Russian oligarch. Once the news reaches Russia, her fairy tale is threatened as his parents set out for New York to get the marriage annulled.', 'https://image.tmdb.org/t/p/w500/cgXk2tNYhJZLXdBDO5DidAVzQ82.jpg', null, null),
  ('Transformers One', 2024, true, 'PG', 'Josh Cooley', '2024-09-20'::date, '104 min', 'Animation, Action, Adventure', 'Eric Pearson, Andrew Barrer, Gabriel Ferrari', 'Chris Hemsworth, Brian Tyree Henry, Scarlett Johansson', 'The untold origin story of Optimus Prime and Megatron, better known as sworn enemies, but who once were friends bonded like brothers who changed the fate of Cybertron forever.', 'https://image.tmdb.org/t/p/w500/iRCgqpdVE4wyLQvGYU3ZP7pAtUc.jpg', null, null),
  ('The Predator', 2018, true, 'R', 'Shane Black', '2018-09-14'::date, '107 min', 'Action, Adventure, Sci-Fi', 'Fred Dekker, Shane Black, Jim Thomas', 'Boyd Holbrook, Trevante Rhodes, Jacob Tremblay', 'From the outer reaches of space to the small-town streets of suburbia, the hunt comes home. Now, the universe''s most lethal hunters are stronger, smarter and deadlier than ever before, having genetically upgraded themselves with DNA from other species. When a young boy accidentally triggers their return to Earth, only a ragtag crew of ex-soldiers and a disgruntled science teacher can prevent the end of the human race.', 'https://image.tmdb.org/t/p/w500/a3eWGF6YPF7No5Rbtjc8QpDvz7l.jpg', 'Alien/Predator', null),
  ('Prey', 2022, true, 'R', 'Dan Trachtenberg', '2022-08-05'::date, '100 min', 'Action, Adventure, Horror', 'Patrick Aison, Dan Trachtenberg, Jim Thomas', 'Amber Midthunder, Dakota Beavers, Dane DiLiegro', 'Naru, a skilled warrior of the Comanche Nation, fights to protect her tribe against one of the first highly-evolved Predators to land on Earth.', 'https://image.tmdb.org/t/p/w500/2FKjLRt7oK1bRRIrxgWmthbBdFh.jpg', 'Alien/Predator', null),
  ('Avatar: The Way of Water', 2022, true, 'PG-13', 'James Cameron', '2022-12-16'::date, '192 min', 'Action, Adventure, Fantasy', 'James Cameron, Rick Jaffa, Amanda Silver', 'Sam Worthington, Zoe Saldana, Sigourney Weaver', 'Jake Sully lives with his newfound family formed on the extrasolar moon Pandora. Once a familiar threat returns to finish what was previously started, Jake must work with Neytiri and the army of the Na''vi race to protect their home.', 'https://image.tmdb.org/t/p/w500/t6HIqrRAclMCA60NsSmeqe9RmNV.jpg', null, null),
  ('2001: A Space Odyssey', 1968, true, 'G', 'Stanley Kubrick', '1968-05-12'::date, '149 min', 'Adventure, Sci-Fi', 'Stanley Kubrick, Arthur C. Clarke', 'Keir Dullea, Gary Lockwood, William Sylvester', '2001 is a story of evolution. Sometime in the distant past, someone or something nudged evolution by placing a monolith on Earth (presumably elsewhere throughout the universe as well). Evolution then enabled humankind to reach the moon''s surface, where yet another monolith is found, one that signals the monolith placers that humankind has evolved that far. Now a race begins between computers (HAL) and human (Bowman) to reach the monolith placers. The winner will achieve the next step in evolution, whatever that may be.', 'https://image.tmdb.org/t/p/w500/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg', null, null),
  ('Elysium', 2013, true, 'R', 'Neill Blomkamp', '2013-08-09'::date, '109 min', 'Action, Drama, Sci-Fi', 'Neill Blomkamp', 'Matt Damon, Jodie Foster, Sharlto Copley', 'In the year 2154, two classes of people exist: the very wealthy, who live on a pristine man-made space station called Elysium, and the rest, who live on an overpopulated, ruined Earth. Secretary Delacourt, a government official, will stop at nothing to enforce anti-immigration laws and preserve the luxurious lifestyle of the citizens of Elysium. That doesn''t stop the people of Earth from trying to get in by any means they can. When unlucky Max is backed into a corner, he agrees to take on a daunting mission that, if successful, will not only save his life but could bring equality to these polarized worlds.', 'https://image.tmdb.org/t/p/w500/uiiXHBd9oUrtUa4YqZiAoy05cRz.jpg', null, null),
  ('The Woman in the Yard', 2025, true, 'PG-13', 'Jaume Collet-Serra', '2025-03-28'::date, '88 min', 'Drama, Horror, Thriller', 'Sam Stefanak', 'Danielle Deadwyler, Okwui Okpokwasili, Peyton Jackson', 'A mysterious woman repeatedly appears in a family''s front yard, often delivering chilling warnings and unsettling messages, leaving them to question her identity, motives and the potential danger she might pose.', 'https://image.tmdb.org/t/p/w500/n0WS2TsNcS6dtaZKzxipyO7LuCJ.jpg', null, null),
  ('The Terminator', 1984, true, 'R', 'James Cameron', '1984-10-26'::date, '107 min', 'Action, Adventure, Sci-Fi', 'James Cameron, Gale Anne Hurd, William Wisher', 'Arnold Schwarzenegger, Linda Hamilton, Michael Biehn', 'Sent back from a dystopian 2029--where the cold machines have conquered the entire world--to 1984 Los Angeles, the indestructible cyborg-assassin known as the "Terminator" commences his deadly mission to kill humankind''s most important woman: the unsuspecting Sarah Connor. However, from the same war-torn post-apocalyptic future comes a battle-scarred defender--Kyle Reese, a brave soldier of the human Resistance Army--bent on stopping the cybernetic killer from eliminating the world''s last hope. But, the Terminator has no feelings, he doesn''t sleep, and above all, he won''t stop until he carries out his grim task. Does our future lie in our past?', 'https://image.tmdb.org/t/p/w500/hzXSE66v6KthZ8nPoLZmsi2G05j.jpg', null, null),
  ('Terminator 2: Judgement Day', 1991, true, 'R', 'James Cameron', '1991-07-03'::date, '137 min', 'Action, Adventure, Sci-Fi', 'James Cameron, William Wisher', 'Arnold Schwarzenegger, Linda Hamilton, Edward Furlong', 'Over 10 years have passed since the first machine called The Terminator tried to kill Sarah Connor and her unborn son, John. The man who will become the future leader of the human resistance against the Machines is now a healthy young boy. However, another Terminator, called the T-1000, is sent back through time by the supercomputer Skynet. This new Terminator is more advanced and more powerful than its predecessor and its mission is to kill John Connor when he''s still a child. However, Sarah and John do not have to face the threat of the T-1000 alone. Another Terminator (identical to the same model that tried and failed to kill Sarah Connor in 1984) is also sent back through time to protect them. Now, the battle for tomorrow has begun.', 'https://image.tmdb.org/t/p/w500/jFTVD4XoWQTcg7wdyJKa8PEds5q.jpg', null, null),
  ('Terminator 3: Rise of the Machines', 2003, true, 'R', 'Jonathan Mostow', '2003-07-02'::date, '109 min', 'Action, Sci-Fi', 'John Brancato, Michael Ferris, Tedi Sarafian', 'Arnold Schwarzenegger, Nick Stahl, Kristanna Loken', 'More than 10 years after ''Terminator 2'', John Connor now exists only as a drifter - living ''off the grid'', so no more Terminators from the future can hunt him down. Unfortunately, SkyNet does send another one back - and this one is called the T-X, even more powerful &amp; advanced than the dreaded T-1000. However, another CSM-101 Terminator is also sent back to protect John against the T-X. Now, Skynet is patiently assuming control of civilian computer systems, under the guise of a computer virus. John has also met his future wife, Kate Brewster, whose father - a U.S. Air Force General - is in charge of the military computer systems &amp; is leery of up linking SkyNet. However, when the SkyNet virus infects the U.S military computers &amp; leaves the country open to attack, the machines begin their horrific takeover. Soon a nuclear war will result - and the war against the machines will begin. Can the outdated CSM-101 Terminator eliminate the highly advanced T-X - or will a darker future await man following the nuclear attack?', 'https://image.tmdb.org/t/p/w500/vvevzdYIrk2636maNW4qeWmlPFG.jpg', null, null),
  ('Terminator Salvation', 2009, false, 'PG-13', 'McG', '2009-05-21'::date, '115 min', 'Action, Adventure, Sci-Fi', 'John Brancato, Michael Ferris', 'Christian Bale, Sam Worthington, Anton Yelchin', 'In 2003, in the Longview State Correctional Facility, the criminal Marcus Wright is on death row, and is convinced by the cancerous Dr. Serena Kogan to donate his body to her research and he accepts. In 2018, after an unsuccessful attack to a Skynet facility, only John Connor survives, but he discovers that Skynet is developing the powerful new model T-800. Out of the blue, Marcus appears naked and with amnesia in the location. Marcus befriends the teenager Kyle Reese and the girl Star who help him to survive the lethal machines and they travel together in a Jeep. Meanwhile the resistance discovers a signal that might turn-off the machines and John offers to test it. When Kyle is captured by a machine and brought to the Skynet headquarters, Marcus decides to help the youngster and heads to Skynet; on the way, he saves Blair Williams who suggests to him that he should meet John Connor first. But Marcus steps on a mine and is submitted to surgery, when a secret about his origins is disclosed.', 'https://image.tmdb.org/t/p/w500/gw6JhlekZgtKUFlDTezq3j5JEPK.jpg', null, null),
  ('Terminator Dark Fate', 2019, false, 'R', 'Tim Miller', '2019-11-01'::date, '128 min', 'Action, Adventure, Sci-Fi', 'David S. Goyer, Justin Rhodes, Billy Ray', 'Linda Hamilton, Arnold Schwarzenegger, Mackenzie Davis', 'A young female Mexican worker, Dani Ramos, is hunted down by a virtually indestructible terminator from the future called a REV-9. However, she is protected by an enhanced human named Grace who is also from the future. They flee from the unstoppable terminator and, out of the blue, Sarah Connor helps them on the road. All three head to Laredo, Texas, where Grace has the coordinates of a possible support and where they meet a T-800 who is living in an isolated location with his family. The group teams up to try to destroy the REV-9.', 'https://image.tmdb.org/t/p/w500/vqzNJRH4YyquRiWxCCOH0aXggHI.jpg', null, null),
  ('Everything Everywhere All at Once', 2022, true, 'R', 'Daniel Kwan, Daniel Scheinert', '2022-04-08'::date, '139 min', 'Action, Adventure, Comedy', 'Daniel Kwan, Daniel Scheinert', 'Michelle Yeoh, Stephanie Hsu, Jamie Lee Curtis', 'A middle-aged Chinese immigrant is swept up into an insane adventure in which she alone can save existence by exploring other universes and connecting with the lives she could have led.', 'https://image.tmdb.org/t/p/w500/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', null, null),
  ('Companion', 2025, true, 'R', 'Drew Hancock', '2025-01-31'::date, '97 min', 'Sci-Fi, Thriller', 'Drew Hancock', 'Sophie Thatcher, Jack Quaid, Lukas Gage', 'A billionaire''s death sets off a chain of events for Iris and her friends during a weekend trip to his lakeside estate.', 'https://image.tmdb.org/t/p/w500/oCoTgC3UyWGfyQ9thE10ulWR7bn.jpg', null, null),
  ('Transcendence', 2014, true, 'PG-13', 'Wally Pfister', '2014-04-18'::date, '119 min', 'Action, Drama, Sci-Fi', 'Jack Paglen', 'Johnny Depp, Rebecca Hall, Morgan Freeman', 'Dr. Will Caster (Johnny Depp) is the foremost researcher in the field of Artificial Intelligence, working to create a sentient machine that combines the collective intelligence of everything ever known with the full range of human emotions. His highly controversial experiments have made him famous, but they have also made him the prime target of anti-technology extremists who will do whatever it takes to stop him. However, in their attempt to destroy Will, they inadvertently become the catalyst for him to succeed-to be a participant in his own transcendence. For his wife Evelyn (Rebecca Hall) and best friend Max Waters (Paul Bettany), both fellow researchers, the question is not if they can...but if they should. Their worst fears are realized as Will''s thirst for knowledge evolves into a seemingly omnipresent quest for power, to what end is unknown. The only thing that is becoming terrifyingly clear is there may be no way to stop him.', 'https://image.tmdb.org/t/p/w500/qmOKJWl3wnXDcLhjtJHnCCCvAiO.jpg', null, null),
  ('Captain America: Brave New World', 2025, true, 'PG-13', 'Julius Onah', '2025-02-14'::date, '118 min', 'Action, Adventure, Sci-Fi', 'Rob Edwards, Malcolm Spellman, Dalan Musson', 'Anthony Mackie, Harrison Ford, Danny Ramirez', 'Sam Wilson, the new Captain America, finds himself in the middle of an international incident and must discover the motive behind a nefarious global plan.', 'https://image.tmdb.org/t/p/w500/pzIddUEMWhWzfvLI3TwxUG2wGoi.jpg', null, null),
  ('Until Dawn', 2025, true, 'R', 'David F. Sandberg', '2025-04-25'::date, '103 min', 'Drama, Horror', 'Blair Butler, Gary Dauberman', 'Ella Rubin, Michael Cimino, Odessa A''zion', 'A group of friends trapped in a time loop, where mysterious foes chase and kill them in gruesome ways, must survive until dawn to escape it.', 'https://image.tmdb.org/t/p/w500/bLY5yN4MKVynZ2HMZWElTOGBgBe.jpg', null, null),
  ('Drop', 2025, true, 'PG-13', 'Christopher Landon', '2025-04-11'::date, '95 min', 'Drama, Mystery, Thriller', 'Jillian Jacobs, Chris Roach', 'Meghann Fahy, Brandon Sklenar, Violett Beane', 'A widowed mother''s first date in years takes a terrifying turn when she''s bombarded with anonymous threatening messages on her phone during their upscale dinner, leaving her questioning if her charming date is behind the harassment.', 'https://image.tmdb.org/t/p/w500/hSQPSW8aLjsMBfwqGjgJ6HozTkp.jpg', null, null),
  ('The Monkey', 2025, true, 'R', 'Osgood Perkins', '2025-02-21'::date, '98 min', 'Horror', 'Osgood Perkins, Stephen King', 'Theo James, Tatiana Maslany, Christian Convery', 'When twin brothers Bill and Hal find their father''s old monkey toy in the attic, a series of gruesome deaths start. The siblings decide to throw the toy away and move on with their lives, growing apart over the years.', 'https://image.tmdb.org/t/p/w500/yYa8Onk9ow7ukcnfp2QWVvjWYel.jpg', null, null),
  ('Borderlands', 2024, true, 'PG-13', 'Eli Roth', '2024-08-09'::date, '101 min', 'Action, Adventure, Comedy', 'Eli Roth, Joe Abercrombie', 'Cate Blanchett, Kevin Hart, Edgar Ramírez', 'Lilith, an infamous outlaw with a mysterious past, reluctantly returns to her home planet of Pandora to find the missing daughter of the universe''s most powerful S.O.B., Atlas. Lilith forms an alliance with an unexpected team - Roland, a former elite mercenary, now desperate for redemption; Tiny Tina, a feral pre-teen demolitionist; Krieg, Tina''s musclebound, rhetorically challenged protector; Tannis, the scientist with a tenuous grip on sanity; and Claptrap, a persistently wiseass robot. These unlikely heroes must battle alien monsters and dangerous bandits to find and protect the missing girl, who may hold the key to unimaginable power. The fate of the universe could be in their hands - but they''ll be fighting for something more: each other.', 'https://image.tmdb.org/t/p/w500/4JGoZu1ZKFpMJTWAP35PCfkMgu8.jpg', null, null),
  ('The Electric State', 2025, true, 'PG-13', 'Anthony Russo, Joe Russo', '2025-03-14'::date, '125 min', 'Action, Adventure, Comedy', 'Christopher Markus, Stephen McFeely, Simon Stålenhag', 'Chris Pratt, Millie Bobby Brown, Woody Harrelson', 'An orphaned teen hits the road with a mysterious robot to find her long-lost brother, teaming up with a smuggler and his wisecracking sidekick.', 'https://image.tmdb.org/t/p/w500/sI2NiMU8o65hmIMY0JI9CjJ0p7f.jpg', null, null),
  ('Rosemary''s Baby', 1968, true, 'R', 'Roman Polanski', '1968-06-12'::date, '137 min', 'Drama, Horror', 'Ira Levin, Roman Polanski', 'Mia Farrow, John Cassavetes, Ruth Gordon', 'Desiring to start their family, young Catholic homemaker Rosemary Woodhouse and her struggling-actor husband Guy move into The Bramford: New York City''s iconic building that brims with unpleasant stories of obscure dwellers and ghastly occurrences. The young couple is soon befriended by their eccentric next-door neighbors, Roman and Minnie and Castevet; shortly afterward, Rosemary gets pregnant. However, little by little--as the inexperienced mother becomes systematically cut off from her circle of friends--alarming hints of a sinister, well-planned conspiracy start to emerge, enfolding timid Rosemary in a shroud of suspicion and mental agony. Why is everyone so conveniently eager to help? And why is Guy allowing it?', 'https://image.tmdb.org/t/p/w500/uYgvlHceRFjAFbsNeMInYcLZLUb.jpg', null, null),
  ('Apartment 7A', 2024, true, 'R', 'Natalie Erika James', '2024-09-27'::date, '107 min', 'Horror, Thriller', 'Natalie Erika James, Christian White, Skylar James', 'Julia Garner, Dianne Wiest, Kevin McNally', 'A struggling young dancer finds herself drawn in by dark forces when a peculiar, well-connected older couple promise her a shot at fame.', 'https://image.tmdb.org/t/p/w500/uipHKJHY1nNEQyprXjfNzH0GIOF.jpg', null, null),
  ('Sinners', 2025, true, 'R', 'Ryan Coogler', '2025-04-18'::date, '137 min', 'Action, Drama, Horror', 'Ryan Coogler', 'Michael B. Jordan, Miles Caton, Saul Williams', 'Trying to leave their troubled lives behind, twin brothers return to their hometown to start again, only to discover that an even greater evil is waiting to welcome them back.', 'https://image.tmdb.org/t/p/w500/qTvFWCGeGXgBRaINLY1zqgTPSpn.jpg', null, null),
  ('Caddo Lake', 2024, true, 'PG-13', 'Logan George, Celine Held', '2024-10-10'::date, '103 min', 'Drama, Mystery, Sci-Fi', 'Celine Held, Logan George', 'Dylan O''Brien, Eliza Scanlen, Caroline Falk', 'When an 8-year-old girl disappears on Caddo Lake, a series of past deaths and disappearances begin to link together, altering a broken family''s history.', 'https://image.tmdb.org/t/p/w500/sv1IoM6xlCdAoOzUmgB9XTnADC.jpg', null, null),
  ('Mickey 17', 2025, true, 'R', 'Bong Joon Ho', '2025-03-07'::date, '137 min', 'Adventure, Comedy, Fantasy', 'Bong Joon Ho, Edward Ashton', 'Robert Pattinson, Steven Yeun, Michael Monroe', 'During a human expedition to colonize space, Mickey 17, a so-called "expendable" employee, is sent to explore an ice planet.', 'https://image.tmdb.org/t/p/w500/edKpE9B5qN3e559OuMCLZdW1iBZ.jpg', null, null),
  ('Novocaine', 2025, true, 'R', 'Dan Berk, Robert Olsen', '2025-03-14'::date, '110 min', 'Action, Comedy, Thriller', 'Lars Jacobson', 'Jack Quaid, Amber Midthunder, Ray Nicholson', 'When the girl of his dreams is kidnapped, a man incapable of feeling physical pain turns his rare condition into an unexpected advantage in the fight to rescue her.', 'https://image.tmdb.org/t/p/w500/xmMHGz9dVRaMY6rRAlEX4W0Wdhm.jpg', null, null),
  ('A Star is Born', 2018, true, 'R', 'Bradley Cooper', '2018-10-05'::date, '136 min', 'Drama, Music, Romance', 'Eric Roth, Bradley Cooper, Will Fetters', 'Lady Gaga, Bradley Cooper, Sam Elliott', 'Seasoned musician Jackson Maine (Bradley Cooper) discovers-and falls in love with-struggling artist Ally (Gaga). She has just about given up on her dream to make it big as a singer - until Jack coaxes her into the spotlight. But even as Ally''s career takes off, the personal side of their relationship is breaking down, as Jack fights an ongoing battle with his own internal demons.', 'https://image.tmdb.org/t/p/w500/wrFpXMNBRj2PBiN4Z5kix51XaIZ.jpg', null, null),
  ('Final Destination: Bloodlines', 2025, true, 'R', 'Zach Lipovsky, Adam B. Stein', '2025-05-16'::date, '110 min', 'Horror', 'Guy Busick, Lori Evans Taylor, Jon Watts', 'Kaitlyn Santa Juana, Teo Briones, Rya Kihlstedt', 'Plagued by a recurring violent nightmare, a college student returns home to find the one person who can break the cycle and save her family from the horrific fate that inevitably awaits them.', 'https://image.tmdb.org/t/p/w500/6WxhEvFsauuACfv8HyoVX6mZKFj.jpg', null, null),
  ('Caveat', 2020, true, 'Not Rated', 'Damian Mc Carthy', '2021-06-05'::date, '88 min', 'Horror, Mystery, Thriller', 'Damian Mc Carthy', 'Ben Caplan, Johnny French, Leila Sykes', 'A lone drifter, Isaac suffering from partial memory loss accepts a job from his old landlord Barrett, to look after his niece Olga, a psychologically troubled woman living in an abandoned house on an isolated island. When Barrett convinces Isaac to confine his movements to the house and leaves the two of them alone, a game of cat and mouse ensues with Isaac fighting to survive amid the terrifying resurgence of his own memory.', 'https://image.tmdb.org/t/p/w500/nbug05AceVU8PMXIONDFxMRtq54.jpg', null, null),
  ('Dr. Horrible''s Sing-Along Blog', 2008, true, 'TV-PG', 'N/A', '2008-07-15'::date, '55S min', 'Short, Comedy, Musical', 'N/A', 'Neil Patrick Harris, Nathan Fillion, Felicia Day', 'Dr. Horrible, an aspiring supervillain with his own video blog, is attempting to join the prestigious Evil League of Evil (led by the legendary "thoroughbred of sin", Bad Horse), but his plans are usually foiled by the egotistical superhero Captain Hammer. Horrible''s life is thrown for a loop when he falls in love with Penny, a beautiful and optimistic advocate for the homeless he meets at the laundromat, a situation which complicates itself even further when Penny begins dating the boorish, oafish Hammer after he apparently saves her life. Faced with the task of impressing the League, can Horrible overcome his own incompetence to ruin the day, kill the hero, and still get the girl?', 'https://image.tmdb.org/t/p/w500/Ag9FEOTyldtvhOo9qCmb2jqgbhY.jpg', null, null),
  ('The Lego Movie 2', 2019, false, 'PG', 'Mike Mitchell', '2019-02-08'::date, '107 min', 'Animation, Adventure, Comedy', 'Phil Lord, Christopher Miller, Matthew Fogel', 'Chris Pratt, Elizabeth Banks, Will Arnett', 'It''s been five years since everything was awesome and the citizens are facing the huge new threat of Lego Duplo, invaders from outer space, wrecking everything faster than they can rebuild.', 'https://image.tmdb.org/t/p/w500/QTESAsBVZwjtGJNDP7utiGV37z.jpg', null, null),
  ('The Conjuring: Last Rites', 2025, true, 'R', 'Michael Chaves', '2025-09-05'::date, '135 min', 'Horror, Mystery, Thriller', 'Ian Goldberg, Richard Naing, David Leslie Johnson-McGoldrick', 'Vera Farmiga, Patrick Wilson, Elliot Cowan', 'Paranormal investigators Ed and Lorraine Warren take on one last terrifying case involving mysterious entities they must confront.', 'https://image.tmdb.org/t/p/w500/byWgphT74ClOVa8EOGzYDkl8DVL.jpg', null, null),
  ('Major League', 1989, true, 'R', 'David S. Ward', '1989-04-07'::date, '107 min', 'Comedy, Sport', 'David S. Ward', 'Tom Berenger, Charlie Sheen, Corbin Bernsen', 'Rachel Phelps is the new owner of the Cleveland Indians baseball team. However, her plans for the team are rather nefarious. She wants to move the team to Miami for the warmer climate and a new stadium. To justify the move, the team has to lose, and lose badly. So she assembles the worst possible team she can. Among these are a past-his-prime catcher with bad knees, a shrewd but past-his-prime pitcher, a young tearaway pitcher (and felon) with a 100 mph fastball but absolutely no control, a third baseman who is too wealthy and precious to dive, a voodoo-loving slugger who can''t hit a curve ball and an energetic-but-naive lead off hitter and base-stealer who can''t keep the ball on the ground. Against the odds, and after the inevitable initial failures, they iron out some of their faults and start to win, much to Ms Phelps'' consternation.', 'https://image.tmdb.org/t/p/w500/ypUedY9zX4nGGf1lQv1UGc8PhPA.jpg', null, null),
  ('The Gorge', 2025, true, 'PG-13', 'Scott Derrickson', '2025-02-14'::date, '127 min', 'Action, Adventure, Horror', 'Zach Dean', 'Miles Teller, Anya Taylor-Joy, Sigourney Weaver', 'Two operatives are appointed to posts in guard towers on opposite sides of a classified gorge.', 'https://image.tmdb.org/t/p/w500/7iMBZzVZtG0oBug4TfqDb9ZxAOa.jpg', null, null),
  ('Don''t Worry Darling', 2022, true, 'R', 'Olivia Wilde', '2022-09-23'::date, '123 min', 'Drama, Mystery, Thriller', 'Katie Silberman, Carey Van Dyke, Shane Van Dyke', 'Florence Pugh, Harry Styles, Chris Pine', 'While her husband leaves home every day to work in a top secret facility, a young 1950s housewife begins to question her life when she notices strange behavior from the other wives in the neighborhood.', 'https://image.tmdb.org/t/p/w500/jOqxKIOC92BVyinYO1Fm73XY7Tc.jpg', null, null),
  ('Jurassic World: Rebirth', 2025, true, 'PG-13', 'Gareth Edwards', '2025-07-02'::date, '133 min', 'Action, Adventure, Sci-Fi', 'David Koepp, Michael Crichton', 'Scarlett Johansson, Mahershala Ali, Jonathan Bailey', 'Five years post-Jurassic World: Dominion (2022), an expedition braves isolated equatorial regions to extract DNA from three massive prehistoric creatures for a groundbreaking medical breakthrough.', 'https://image.tmdb.org/t/p/w500/1RICxzeoNCAO5NpcRMIgg1XT6fm.jpg', null, null),
  ('Colossal', 2016, true, 'R', 'Nacho Vigalondo', '2017-04-21'::date, '109 min', 'Comedy, Drama, Fantasy', 'Nacho Vigalondo', 'Anne Hathaway, Jason Sudeikis, Austin Stowell', 'Gloria (Anne Hathaway) is an out-of-work girl who, after getting kicked out of her apartment by her boyfriend, is forced to leave her life in New York and move back to her hometown. When news reports surface that a giant creature is destroying Seoul, South Korea, Gloria gradually comes to the realization that she is somehow connected to this far-off phenomenon. As events begin to spin out of control, Gloria must determine why her seemingly insignificant existence has such a colossal effect on the fate of the world.', 'https://image.tmdb.org/t/p/w500/4VOyofBd1pexblxtDZYtYIk7NI4.jpg', null, null),
  ('Batman', 1989, false, 'PG-13', 'Tim Burton', '1989-06-23'::date, '126 min', 'Action, Adventure', 'Bob Kane, Sam Hamm, Warren Skaaren', 'Michael Keaton, Jack Nicholson, Kim Basinger', 'Gotham City. Crime boss Carl Grissom (Jack Palance) effectively runs the town but there''s a new crime fighter in town - Batman (Michael Keaton). Grissom''s right-hand man is Jack Napier (Jack Nicholson), a brutal man who is not entirely sane... After falling out between the two Grissom has Napier set up with the Police and Napier falls to his apparent death in a vat of chemicals. However, he soon reappears as The Joker and starts a reign of terror in Gotham City. Meanwhile, reporter Vicki Vale (Kim Basinger) is in the city to do an article on Batman. She soon starts a relationship with Batman''s everyday persona, billionaire Bruce Wayne.', 'https://image.tmdb.org/t/p/w500/cij4dd21v2Rk2YtUQbV5kW69WB2.jpg', null, null),
  ('Batman Returns', 1992, false, 'PG-13', 'Tim Burton', '1992-06-19'::date, '126 min', 'Action, Crime, Fantasy', 'Bob Kane, Daniel Waters, Sam Hamm', 'Michael Keaton, Danny DeVito, Michelle Pfeiffer', 'In the sewers of gotham city to the rooftops of the gotham city the penguin wants to know where he came from well in his villain ways catwoman plans to kill rich man of gotham max shreak but as he battles with millionaire Bruce Wayne both ladies men have their own secrets Bruce Wayne is back as Bat man trying to stop the penguin Max is helping penguin steal gotham city while selina Kyle/catwoman tries to help penguin not knowing her man murder target also her murder is helping him but all four men have their goals taking gotham from crime winning gotham city assassination for two men and more money to be gotham citys number one rich man.', 'https://image.tmdb.org/t/p/w500/jKBjeXM7iBBV9UkUcOXx3m7FSHY.jpg', null, null),
  ('Dumb Money', 2023, true, 'R', 'Craig Gillespie', '2023-09-29'::date, '105 min', 'Biography, Comedy, Drama', 'Lauren Schuker Blum, Rebecca Angelo, Ben Mezrich', 'Paul Dano, Pete Davidson, Vincent D''Onofrio', 'A regular guy sinks his life savings into the stock of videogame store GameStop and starts posting about it. When his social posts start blowing up and a stock tip becomes a movement, everyone gets rich, until the billionaires fig...', 'https://image.tmdb.org/t/p/w500/e9u7luSxFKOZgPTB9XHFnPArGdP.jpg', null, null),
  ('Superman', 2025, true, 'PG-13', 'James Gunn', '2025-07-11'::date, '129 min', 'Action, Adventure, Sci-Fi', 'James Gunn, Jerry Siegel, Joe Shuster', 'David Corenswet, Rachel Brosnahan, Nicholas Hoult', 'Superman must reconcile his alien Kryptonian heritage with his human upbringing as reporter Clark Kent. As the embodiment of truth, justice and the human way he soon finds himself in a world that views these as old-fashioned.', 'https://image.tmdb.org/t/p/w500/ldyfo0BKmz5rWtJJKCvwaNS4cJT.jpg', null, null),
  ('The Big Short', 2015, true, 'R', 'Adam McKay', '2015-12-23'::date, '130 min', 'Biography, Comedy, Drama', 'Charles Randolph, Adam McKay, Michael Lewis', 'Christian Bale, Steve Carell, Ryan Gosling', 'Three separate but parallel stories of the U.S mortgage housing crisis of 2005 are told. Michael Burry, an eccentric ex-physician turned one-eyed Scion Capital hedge fund manager, has traded traditional office attire for shorts, bare feet and a Supercuts haircut. He believes that the US housing market is built on a bubble that will burst within the next few years. Autonomy within the company allows Burry to do largely as he pleases, so Burry proceeds to bet against the housing market with the banks, who are more than happy to accept his proposal for something that has never happened in American history. The banks believe that Burry is a crackpot and therefore are confident in that they will win the deal. Jared Vennett with Deutschebank gets wind of what Burry is doing and, as an investor believes he too can cash in on Burry''s beliefs. An errant telephone call to FrontPoint Partners gets this information into the hands of Mark Baum, an idealist who is fed up with the corruption in the financial industry. Baum and his associates, who work at an arms length under Morgan Stanley, decide to join forces with Vennett despite not totally trusting him. In addition to Burry''s information, they further believe that most of the mortgages are overrated by the bond agencies, with the banks collating all the sub-prime mortgages under AAA packages. Charlie Geller and Jamie Shipley, who are minor players in a $30 million start-up garage company called Brownfield, get a hold of Vennett''s prospectus on the matter. Wanting in on the action but not having the official clout to play, they decide to call an old "friend", retired investment banker Ben Rickert, to help out. All three of these groups work on the premise that the banks are stupid and don''t know what''s going on, while for them to win, the general economy has to lose, which means the suffering of the general investor who trusts the financial institutions. That latter aspect may not sit well with Baum. Some of these assumptions may be incorrect and may be far more manipulative than they could have ever imagined, which in turn may throw curves into the process.', 'https://image.tmdb.org/t/p/w500/scVEaJEwP8zUix8vgmMoJJ9Nq0w.jpg', null, null),
  ('Mission: Impossible – The Final Reckoning', 2025, true, 'PG-13', 'Christopher McQuarrie', '2025-05-23'::date, '169 min', 'Action, Adventure, Thriller', 'Bruce Geller, Christopher McQuarrie, Erik Jendresen', 'Tom Cruise, Hayley Atwell, Ving Rhames', 'Hunt and the IMF pursue a dangerous AI called the Entity that''s infiltrated global intelligence. With governments and a figure from his past in pursuit, Hunt races to stop it from forever changing the world.', 'https://image.tmdb.org/t/p/w500/z53D72EAOxGRqdr7KXXWp9dJiDe.jpg', null, null),
  ('Weapons', 2025, true, 'R', 'Zach Cregger', '2025-08-08'::date, '128 min', 'Horror, Mystery', 'Zach Cregger', 'Julia Garner, Josh Brolin, Alden Ehrenreich', 'When all but one child from the same class mysteriously vanish on the same night at exactly the same time, a community is left questioning who or what is behind their disappearance.', 'https://image.tmdb.org/t/p/w500/cpf7vsRZ0MYRQcnLWteD5jK9ymT.jpg', null, null),
  ('Barbarian', 2022, true, 'R', 'Zach Cregger', '2022-09-09'::date, '102 min', 'Horror, Mystery, Thriller', 'Zach Cregger', 'Georgina Campbell, Bill Skarsgård, Justin Long', 'A woman staying at an Airbnb discovers that the house she has rented is not what it seems.', 'https://image.tmdb.org/t/p/w500/idT5mnqPcJgSkvpDX7pJffBzdVH.jpg', null, null),
  ('Eenie Meanie', 2025, true, 'R', 'Shawn Simmons', '2025-08-22'::date, '106 min', 'Action, Comedy, Drama', 'Shawn Simmons', 'Samara Weaving, Karl Glusman, Andy Garcia', 'A reformed teenage getaway driver is dragged back into her unsavory past when a former employer offers her a chance to save the life of her chronically unreliable ex-boyfriend.', 'https://image.tmdb.org/t/p/w500/12Va3oO3oYUdOd75zM57Nx1976a.jpg', null, null),
  ('Kpop Demon Hunters', 2025, true, 'PG', 'Chris Appelhans, Maggie Kang', '2025-06-20'::date, '95 min', 'Animation, Action, Adventure', 'Danya Jimenez, Hannah McMechan, Maggie Kang', 'Arden Cho, May Hong, Ji-young Yoo', 'A world-renowned K-Pop girl group balance their lives in the spotlight with their secret identities as demon hunters.', 'https://image.tmdb.org/t/p/w500/zT7Lhw3BhJbMkRqm9Zlx2YGMsY0.jpg', null, null),
  ('Bring Her Back', 2025, true, 'R', 'Danny Philippou, Michael Philippou', '2025-05-30'::date, '104 min', 'Horror, Mystery', 'Danny Philippou, Bill Hinzman', 'Billy Barratt, Sally Hawkins, Mischa Heywood', 'A brother and sister uncover a terrifying ritual at the secluded home of their new foster mother.', 'https://image.tmdb.org/t/p/w500/1Q3GlCXGYWELifxANYZ5OVMRVZl.jpg', null, null),
  ('Bullet Train', 2022, true, 'R', 'David Leitch', '2022-08-05'::date, '127 min', 'Action, Comedy, Thriller', 'Zak Olkewicz, Kôtarô Isaka', 'Brad Pitt, Joey King, Aaron Taylor-Johnson', 'Trained killer Ladybug wants to give up the life but is pulled back in by his handler Maria Beetle in order to collect a briefcase on a bullet train heading from Tokyo to Morioka. On board are fellow assasins Kimura, the Prince, Tangerine, and Lemon. Once on board the five assasins discover that their objectives are all connected.', 'https://image.tmdb.org/t/p/w500/j8szC8OgrejDQjjMKSVXyaAjw3V.jpg', null, null),
  ('Him', 2025, true, 'R', 'Justin Tipping', '2025-09-19'::date, '96 min', 'Horror, Sport', 'Zack Akers, Skip Bronkie, Justin Tipping', 'Marlon Wayans, Tyriq Withers, Julia Fox', 'A young athlete descends into a world of terror when he''s invited to train with a legendary champion whose charisma curdles into something darker.', 'https://image.tmdb.org/t/p/w500/ce6wANgLoSV16Q1H3v0b6yjFOVs.jpg', null, null),
  ('The Voyeurs', 2021, true, 'R', 'Michael Mohan', '2021-09-10'::date, '116 min', 'Drama, Mystery, Romance', 'Michael Mohan', 'Sydney Sweeney, Justice Smith, Ben Hardy', 'Pippa and Thomas move into their dream apartment, they notice that their windows look directly into the apartment opposite - inviting them to witness the volatile relationship of the attractive couple across the street. But when they attempt to anonymously intercede in their lives, they unwittingly set in motion a chain of events that will lead to disaster.', 'https://image.tmdb.org/t/p/w500/8Y4XOIWhpOvSOEn8XrxbkH9yAXO.jpg', null, null),
  ('Together', 2025, true, 'R', 'Michael Shanks', '2025-07-30'::date, '102 min', 'Horror, Romance', 'Michael Shanks', 'Dave Franco, Alison Brie, Damon Herriman', 'Years into their relationship, Tim and Millie find themselves at a crossroads as they move to the country. With tensions already flaring, an encounter with an unnatural force threatens to corrupt their lives, their love and their ...', 'https://image.tmdb.org/t/p/w500/m52XidzKx94bKlToZfEXUnL3pdy.jpg', null, null),
  ('One Battle After Another', 2025, true, 'R', 'Paul Thomas Anderson', '2025-09-26'::date, '161 min', 'Action, Crime, Drama', 'Paul Thomas Anderson, Thomas Pynchon', 'Teyana Taylor, Leonardo DiCaprio, Regina Hall', 'When their evil enemy resurfaces after 16 years, a group of ex-revolutionaries reunite to rescue the daughter of one of their own.', 'https://image.tmdb.org/t/p/w500/m1jFoahEbeQXtx4zArT2FKdbNIj.jpg', null, null),
  ('Night Always Comes', 2025, true, 'R', 'Benjamin Caron', '2025-08-15'::date, '108 min', 'Crime, Drama, Thriller', 'Willy Vlautin, Sarah Conradt', 'Vanessa Kirby, Jennifer Jason Leigh, Zack Gottsagen', 'Risking everything to secure a future for herself and her brother, Lynette sets out on a dangerous odyssey, confronting her own dark past over the course of one propulsive night.', 'https://image.tmdb.org/t/p/w500/1jDo1nG7rtjaaQGpr6e73x9i9Xp.jpg', null, null),
  ('The Lost Bus', 2025, true, 'R', 'Paul Greengrass', '2025-10-03'::date, '130 min', 'Biography, Drama, History', 'Brad Ingelsby, Paul Greengrass, Lizzie Johnson', 'Matthew McConaughey, America Ferrera, Yul Vazquez', 'A wayward school bus driver and a dedicated school teacher battle to save 22 children from a terrifying inferno.', 'https://image.tmdb.org/t/p/w500/zpygCOYY1DPBkeUsrrznLRN5js5.jpg', null, null),
  ('The Long Walk', 2025, true, 'R', 'Francis Lawrence', '2025-09-12'::date, '108 min', 'Horror, Sci-Fi, Thriller', 'JT Mollner, Stephen King', 'Cooper Hoffman, David Jonsson, Garrett Wareing', 'A group of teenage boys compete in an annual contest known as "The Long Walk," in which they must maintain a certain walking speed or get shot.', 'https://image.tmdb.org/t/p/w500/wobVTa99eW0ht6c1rNNzLkazPtR.jpg', null, null),
  ('Frankenstein', 2025, true, 'R', 'Guillermo del Toro', '2025-11-07'::date, '149 min', 'Drama, Fantasy, Horror', 'Guillermo del Toro, Mary Shelley', 'Oscar Isaac, Jacob Elordi, Christoph Waltz', 'Dr. Victor Frankenstein, a brilliant but egotistical scientist, brings a creature to life in a monstrous experiment that ultimately leads to the undoing of both the creator and his tragic creation.', 'https://image.tmdb.org/t/p/w500/g4JtvGlQO7DByTI6frUobqvSL3R.jpg', null, null),
  ('RiffTrax Live: MST3K Reunion', 2016, true, 'N/A', 'N/A', '2016-06-28'::date, '141 min', 'Comedy', 'Trace Beaulieu, Frank Conniff, Bill Corbett, John Gleaves (collaborating writer), Joel Hodgson, Bridget Jones, Conor Lastowka, Kevin Murphy, Michael J. Nelson, Mary Jo Pehl, Jonah Ray, Sean Thomason', 'Michael J. Nelson, Kevin Murphy, Bill Corbett, Joel Hodgson', 'Mike, Kevin and Bill were joined on stage by their MST3K colleagues at the State Theatre in Minneapolis to bring it back to their roots in an MST3K cast reunion the likes of which have never been seen before!', 'https://image.tmdb.org/t/p/w500/4oRuNpDU9hE8dZvTkUgyE62VwkO.jpg', null, null),
  ('Enemy of the State', 1998, true, 'R', 'Tony Scott', '1998-11-20'::date, '132 min', 'Action, Thriller', 'David Marconi', 'Will Smith, Gene Hackman, Jon Voight', 'Robert Clayton Dean (Will Smith) is a mild-mannered lawyer who works in Washington, D.C. He is on the trail of a kingpin named Paulie Pintero (Tom Sizemore). Meanwhile, a politician named Thomas Brian Reynolds (Jon Voight) is negotiating with Representative Phillip Hammersley (Jason Robards, Jr.) about a new surveillance system with satellites. But, Hammersley declines; Reynolds has Hammersley killed, but the murder is caught on tape, and the taper is chased by Reynolds'' team of N.S.A. Agents. The guy must ditch the tape, so he plants it on Dean (unbeknownst to Dean). Then, the N.S.A. decides to get into Dean''s life. That is when Dean''s life began to fall apart all around him, with his wife and job both gone. Dean wants to find out what is going on. Then, he meets a man named "Brill" (Gene Hackman), who tells him that Dean has something that the government wants. Dean and Brill formulate a plan to get Dean''s life back and turn the tables on Reynolds.', 'https://image.tmdb.org/t/p/w500/x9pXrMKLsBGGOFyyZ0Gwt9YpVub.jpg', null, null),
  ('Don''t Look Up', 2021, true, 'R', 'Adam McKay', '2021-12-24'::date, '138 min', 'Comedy, Drama, Sci-Fi', 'Adam McKay, David Sirota', 'Leonardo DiCaprio, Jennifer Lawrence, Meryl Streep', 'Kate Dibiasky (Jennifer Lawrence), an astronomy grad student, and her professor Dr. Randall Mindy (Leonardo DiCaprio) make an astounding discovery of a comet orbiting within the solar system. The problem - it''s on a direct collision course with Earth. The other problem? No one really seems to care. Turns out warning mankind about a planet-killer the size of Mount Everest is an inconvenient fact to navigate. With the help of Dr. Oglethorpe (Rob Morgan), Kate and Randall embark on a media tour that takes them from the office of an indifferent President Orlean (Meryl Streep) and her sycophantic son and Chief of Staff, Jason (Jonah Hill), to the airwaves of The Daily Rip, an upbeat morning show hosted by Brie (Cate Blanchett) and Jack (Tyler Perry). With only six months until the comet makes impact, managing the 24-hour news cycle and gaining the attention of the social media obsessed public before it''s too late proves shockingly comical - what will it take to get the world to just look up?.', 'https://image.tmdb.org/t/p/w500/th4E1yqsE8DGpAseLiUrI60Hf8V.jpg', null, null),
  ('Triangle', 2009, true, 'R', 'Christopher Smith', '2009-10-16'::date, '99 min', 'Fantasy, Mystery, Sci-Fi', 'Christopher Smith', 'Melissa George, Joshua McIvor, Jack Taylor', 'When Jess sets sail on a yacht with a group of friends, she cannot shake the feeling that there is something wrong. Her suspicions are realized when the yacht hits a storm and the group is forced to board a passing ocean liner to get to safety, a ship Jess is convinced she''s been on before. The ship appears deserted, the clock on board has stopped, but they are not alone... Someone is intent on hunting them down, one by one. And Jess unknowingly holds the key to end the terror.', 'https://image.tmdb.org/t/p/w500/cRlMrbc4Iof7vN0ZqHwJnMBYBLi.jpg', null, null),
  ('Southland Tales', 2006, true, 'R', 'Richard Kelly', '2007-12-07'::date, '145 min', 'Comedy, Drama, Mystery', 'Richard Kelly', 'Dwayne Johnson, Sarah Michelle Gellar, Seann William Scott', 'Southland Tales is an ensemble piece set in the futuristic landscape of Los Angeles on July 4, 2008, as it stands on the brink of social, economic and environmental disaster. Boxer Santaros is an action star who''s stricken with amnesia. His life intertwines with Krysta Now, an adult film star developing her own reality television project, and Ronald Taverner, a Hermosa Beach police officer who holds the key to a vast conspiracy.', 'https://image.tmdb.org/t/p/w500/thGIvfayC2aIS6V8je6w0DmJn4z.jpg', null, null),
  ('Now You See Me', 2013, true, 'PG-13', 'Louis Leterrier', '2013-05-31'::date, '115 min', 'Crime, Mystery, Thriller', 'Ed Solomon, Boaz Yakin, Edward Ricourt', 'Jesse Eisenberg, Common, Mark Ruffalo', 'Four magicians each answer a mysterious summons to an obscure address with secrets inside. A year later, they are the Four Horsemen, big time stage illusionists who climax their sold-out Las Vegas show with a bank apparently robbed for real. This puts F.B.I. Agents Dylan Rhodes and Interpol Agent Alma Dray on the case to find out how they did it. However, this mystery proves to be difficult to solve, even with the insights of professional illusion exposer Thaddeus Bradley. What follows is a bizarre investigation where nothing is what it seems to be, with illusions, dark secrets, and hidden agendas galore as all involved are reminded of a great truth in this puzzle: the closer you look, the less you see.', 'https://image.tmdb.org/t/p/w500/tWsNYbrqy1p1w6K9zRk0mSchztT.jpg', null, null),
  ('Now You See Me 2', 2016, true, 'PG-13', 'Jon M. Chu', '2016-06-10'::date, '129 min', 'Action, Adventure, Comedy', 'Ed Solomon, Peter Chiarelli, Boaz Yakin', 'Jesse Eisenberg, Mark Ruffalo, Woody Harrelson', 'One year after outwitting the F.B.I. and winning the public''s adulation with their Robin Hood-style magic spectacles, The Four Horsemen resurface for a comeback performance in hopes of exposing the unethical practices of a tech magnate. The man behind their vanishing act is none other than Walter Mabry, a tech prodigy who threatens the Horsemen into pulling off their most impossible heist yet. Their only hope is to perform one last unprecedented stunt to clear their names and reveal the mastermind behind it all.', 'https://image.tmdb.org/t/p/w500/A81kDB6a1K86YLlcOtZB27jriJh.jpg', null, null),
  ('Tron Ares', 2025, true, 'PG-13', 'Joachim Rønning', '2025-10-10'::date, '119 min', 'Action, Adventure, Sci-Fi', 'Steven Lisberger, Bonnie MacBird, David DiGilio', 'Jared Leto, Greta Lee, Jeff Bridges', 'A highly sophisticated program, Ares, is sent from the digital world into the real world on a dangerous mission.', 'https://image.tmdb.org/t/p/w500/chpWmskl3aKm1aTZqUHRCtviwPy.jpg', null, null),
  ('Ready or Not', 2019, true, 'R', 'Matt Bettinelli-Olpin, Tyler Gillett', '2019-08-21'::date, '95 min', 'Action, Comedy, Horror', 'Guy Busick, R. Christopher Murphy', 'Samara Weaving, Adam Brody, Mark O''Brien', 'All of us have made certain efforts so our in-laws will like us, but Grace is going to have to give it her all if she wants to fit in with her brand new husband''s wealthy dynasty, who require her to follow a brutal tradition: for the bride to try to survive her wedding night while the rest of them hunt her down. The class struggle stuff hits the proverbial fan in this extremely black satire starring a brilliant Samara Weaving and including an uncommonly perverse Andie MacDowell.', 'https://image.tmdb.org/t/p/w500/oJD9KQFoObZmxAS1je56SIFVNJt.jpg', null, null)
)
insert into public.movies (
  user_id,
  title,
  year_released,
  downloaded,
  rated,
  director,
  date_released,
  runtime,
  genre,
  writers,
  actors,
  plot,
  poster_url,
  franchise_id,
  collection_id
)
select
  target_user.user_id,
  source.title,
  source.year_released,
  source.downloaded,
  source.rated,
  source.director,
  source.date_released,
  source.runtime,
  source.genre,
  source.writers,
  source.actors,
  source.plot,
  source.poster_url,
  franchise.id,
  collections.id
from target_user
cross join source
left join public.franchise franchise
  on franchise.user_id = target_user.user_id
  and source.franchise_name is not null
  and lower(franchise.name) = lower(source.franchise_name)
left join public.collections collections
  on collections.user_id = target_user.user_id
  and source.collection_name is not null
  and lower(collections.name) = lower(source.collection_name)
where not exists (
  select 1
  from public.movies existing
  where existing.user_id = target_user.user_id
    and lower(existing.title) = lower(source.title)
    and existing.year_released = source.year_released
);

commit;

